window.CHAI_DATA=window.CHAI_DATA||{};CHAI_DATA["26761859"]={"book":{"id":26761859,"title":"精要主义","author":"[英] 格雷戈·麦吉沃恩 (Greg McKeown)","translator":"邵信芳","publisher":"浙江人民出版社","pubdate":"2016-4-1","isbn":"9787213072291","tags":["个人管理","思维方式","时间管理","自我管理","生活方式","管理","思维","心理学"],"memCount":22},"np":1,"pb":[34],"idx":[{"i":17448,"t":"想清楚当下重要的是什么？","l":"TF2-3","c":"小福泥","g":1,"p":1},{"i":15630,"t":"如何利用精要主义的思维和方法，告别拥挤的混乱状态，做更少，但做得更好？","l":"TF2-4","c":"clund","g":1,"p":1},{"i":10915,"t":"让你战胜拖延症，不费力气的三个技巧","l":"TF1-2","c":"南妃","g":1,"p":1},{"i":10645,"t":"专注于当下的三步法","l":"TF2-3","c":"盈盈","g":1,"p":1},{"i":9756,"t":"使用“假设还不曾拥有”的方法克服禀赋效应带来的影响","l":"TF2-2","c":"我叫刘军","g":0,"p":1},{"i":8904,"t":"如何成为精要主义","l":"TF2-4","c":"天一","g":1,"p":1},{"i":8802,"t":"找到当下最重要的一件事情","l":"TF2-3","c":"天一","g":1,"p":1},{"i":8666,"t":"如何活在当下","l":"TF2-3","c":"天一","g":1,"p":1},{"i":8448,"t":"如何运用“小胜法”更好地实现目标","l":"TF2-3","c":"Josie-琼绚","g":1,"p":1},{"i":8022,"t":"三步法扫除“最慢行进者”，快速达成目标","l":"TF2-2","c":"佐江","g":1,"p":1},{"i":7921,"t":"如何克服禀赋效应带来的影响","l":"TF2-2","c":"我叫刘军","g":0,"p":1},{"i":7854,"t":"如何努力才会有成效","l":"TF3-3","c":"绚绚","g":1,"p":1},{"i":7026,"t":"MVP，最低可行性产品","l":"TF2-2","c":"叶子","g":1,"p":1},{"i":6518,"t":"三步扫除“最慢进行者”","l":"TF1-1","c":"涂毓敏","g":1,"p":1},{"i":4268,"t":"创造全新的刺激事件来触发重要常规的执行","l":"TF2-3","c":"王丽","g":1,"p":1},{"i":4012,"t":"禀赋效应陷阱-放弃就是最大的赢","l":"TF1-1","c":"张溶冰","g":1,"p":1},{"i":3575,"t":"怎样设置工作与生活的界限，免受他人事务烦扰","l":"TF2-4","c":"胡奇伟","g":1,"p":1},{"i":3574,"t":"通过低风险的方法排除不重要的事件，精简自己的工作和生活","l":"TF2-3","c":"胡奇伟","g":1,"p":1},{"i":3305,"t":"精要主义者如何轻松应对工作与生活呢？","l":"TF2-1","c":"果莉","g":1,"p":1},{"i":3183,"t":"逆向试行","l":"TF2-3","c":"胡奇伟","g":1,"p":1},{"i":2924,"t":"怎样设置工作与生活的界线，从而免受他人事务烦扰","l":"TF2-4","c":"胡奇伟","g":1,"p":1},{"i":2699,"t":"设置缓冲期的窍门","l":"TF1-1","c":"木年槿","g":1,"p":1},{"i":2559,"t":"警惕！你的大部分时间也许都在瞎忙！","l":"TF3-1","c":"陈宏玉","g":1,"p":1},{"i":2397,"t":"学会优雅的说“不”","l":"TF2-4","c":"Lizzy","g":1,"p":1},{"i":2395,"t":"改变坏习惯","l":"TF2-3","c":"Lizzy","g":1,"p":1},{"i":2394,"t":"克服禀赋效应","l":"TF2-2","c":"Lizzy","g":1,"p":1},{"i":1662,"t":"面对目标，如何迈出第一步，并坚持下去","l":"TF2-2","c":"抗抗","g":1,"p":1},{"i":1581,"t":"关注当下，从最重要的开始","l":"TF1-1","c":"钱彩虹","g":1,"p":1},{"i":1509,"t":"在工作和生活中，从小处着手，鼓励进步，庆祝小胜","l":"TF1-2","c":"潇潇","g":1,"p":1},{"i":1508,"t":"设置缓冲区使自己保持头脑理智清醒","l":"TF1-1","c":"潇潇","g":1,"p":1},{"i":1447,"t":"面对机会，进行选择是应遵循的三条最低标准+三条极端标准","l":"TF2-1","c":"抗抗","g":1,"p":1},{"i":1255,"t":"关注真正重要的事情","l":"TF3-3","c":"Emma","g":0,"p":1},{"i":799,"t":"Get 精要，远离杂乱无章的人生！","l":"TF2-3","c":"阿花","g":1,"p":1},{"i":725,"t":"放弃也是一种勇气，前进就是一种胜利","l":"TF2-4","c":"存在","g":1,"p":1}],"ms":[{"id":17448,"topic":"想清楚当下重要的是什么？","learn_goal":"","remark":"主张人们应该专注于最重要的事情，摒弃那些琐碎而无意义的事物。它提出了一个核心理念，即“更少但更好”。在当今社会，我们每天都面临着大量的信息和选择，这使得我们很难确定哪些事情是真正重要的，哪些事情是应该优先处理的。","level":"TF2-3","duration":25,"status":30,"type":0,"chaishujia":{"username":"小福泥","city":""},"club":{"name":"北京紫禁之巅分舵","city":"北京市"},"prologue":"\u003cp>\u003cstrong>【技能点】分组\u003c/strong>\u003cbr>为了便于待会学习时讨论、分享，我们先分一下组,线上一组，线下一组总共分为两组。\u003c/p>\u003cp>\u003cstrong>【技能点】设定学习目标\u003c/strong>\u003c/p>\u003cp>那今天跟着我完成RIA现场学习后，大家能够运用精要主义，在同一时间段，想清楚自己当下最重要的事情？\u003c/p>\u003cp>\u003cstrong>【技能点】FAB介绍法，能够清晰辨别出F、A、B\u003c/strong> \u003c/p>\u003cp>\u003cstrong>F:特征，核心是“书”，用于满足好奇心。\u003c/strong>\u003c/p>\u003cp>《精要主义》致力于帮助个人和企业摒弃琐碎，直抵精要（如何应对拥挤不堪的工作与生活）。作者格雷格·麦基恩是《华尔街日报》畅销书作家，《哈佛商业评论》杂志最受欢迎的专栏作家之一。\u003c/p>\u003cp>\u003cstrong>A:优势，重点是“比较”，用于建立安全感\u003c/strong>\u003c/p>\u003cp>与其他书相比，本书提供了清晰的实践步骤和方法，用简单图文清晰表达，通过大量生动实例和故事使理念更易于理解和吸收。\u003c/p>\u003cp>\u003cstrong>B:利益，强调的是“你（学习者）”用于引发兴趣\u003c/strong>\u003c/p>\u003cp>\u003cstrong>B1：指这本书给学习者带来的好处\u003c/strong> \u003c/p>\u003cp>这本书为那些感到生活混乱无序，工作效率不高的人，以及想要简化生活方式的人提供了实用的策略和建议 \u003c/p>\u003cp>\u003cstrong>B2：指接下来的这个片段给学习者带来的好处\u003c/strong>\u003c/p>\u003cp>本片段是精要主的第要素十五专注，当下最重要的是什么。\u003c/p>\u003cp>而通过今天的片段学习，让你能够不念过去，不畏将来，专注当下，当下最重要的是什么。\u003c/p>\u003cp>接下来请大家阅读我为大家准备的原书片段，这个片段选自《精要主义》电子书第P381-383页给大家一分钟时间阅读，完毕之后请举手示意我。\u003c/p>","ratings_count":1,"texts":[{"id":21627,"quote":"\u003cp>想清楚当下最重要的是什么？\u003c/p>\u003cp>最近，我在纽约向一个领导团队讲了整整一天的精要主义。我尽情享受了这一天，并自始至终感受着当下。但当我回到房间酒店的时候，我突然感到自己被拉向了四面八方。身边每一样东西都在提醒着我应该做的一切：查看电子邮件，听留言，读一本自己觉得有必要读的书，从现在开始花几个星期准备一个报告，把这一天的经历触发的有意思的想法记录下来，以及其他事情。让我觉得不堪重负的，倒不仅仅是事情的数量，而是在同一时刻很多事情都争着抢着要被优先完成的这种压力，对此我再熟悉不过了。焦虑和紧张让我停了下来。我跪下来，闭上眼睛，问自己：“当下重要的是什么？”沉思片刻后，我明白了，在知道当下重要的是什么之前，重要的是搞清楚“当下重要的是什么”这个理念！\u003c/p>\u003cp>我站了起来，开始整理。我把所有散乱地堆在我身边的东西收了起来，放到该放的位置上去，免得它们分散我的注意力，也免得我每次经过时，它们迫使我按它们的吩咐去做。我关掉了手机。别人没办法给我发短信，这让我如释重负。我打开笔记本记录下这一天，这让我收起了心。我用铅笔给脑海中出现的所有事情列了一个清单。为了明确任务，我问自己：“你要做些什么才能平静地睡去？”我决定，第一重要的事是跟妻子和孩子们联系。接下来要做的就是能让次日早上的头几个小时尽可能轻松一些的事情：安排好叫醒服务和房内早餐，把幻灯片拷到电脑上，熨好衬衣。我划掉了当时并不重要的事情。\u003c/p>\u003cp>当你面临很多很多的任务，以至于不知该从何下手的时候，停下来，深呼吸。投入到当下，问问自己此时此刻最重要的是什么——不是明天最重要的是什么，甚至不是一小时后最重要的是什么。如果不确定，那就把所有争抢你注意力的事情都列出来，然后划掉所有此时此刻不重要的事情。\u003c/p>","explains":"\u003cp>清晰的看到左边的图，为非精要主义：把有限的精力和时间分散在不同的事情上。\u003c/p>\u003cp>而精要主义是：同一时间只专注于一件事情。\u003c/p>\u003cp>（What）\u003cstrong>在同一时间段，想清楚自己当下最重要的事情？\u003c/strong>\u003c/p>\u003cp>（why）在面对生活和工作中的大量任务时，当下什么都想要。导致什么都做不好，比如：狗熊掰玉米，不能三心二意，想要拥有得越多就会失去得越多。当我们往往无法有效识别和区分哪些事情是真正重要的，哪些事情是次要的。很容易将时间和精力分散在琐碎、无意义的事务上，导致无法专注于真正重要的事情。比如在工作中面对大量任务时，思绪比较混乱，遭受工作效率不高，到下班的点无法准时下班，还要在公司加班。\u003c/p>\u003cp>（How）\u003c/p>\u003cp>用于在面临大量任务时确定当下最重要的事情：\u003c/p>\u003cp>1、\u003cstrong>清晰思考。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>（1）深呼吸：深呼吸并投入到当下\u003c/strong>\u003c/p>\u003cp>（2）\u003cstrong>整理自己：关闭自己社交软件，避免被外界的噪音和杂念所干扰。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>2、列清单：列出所有争抢注意力的事情。\u003c/strong>如果我们对“当下重要的是什么”感到不确定，那么把所有争抢我们注意力的事情都列出来。这有助于我们更清楚地看到所有的任务和责任，从而更容易决定优先级。\u003c/p>\u003cp>3、\u003cstrong>划掉\u003c/strong>：\u003cstrong>划掉所有此时此刻不重要的事情。\u003c/strong>在列出的清单上，要勇敢地划掉那些在当前情境下不重要的事情。这有助于我们专注于真正重要的事情，避免被琐碎的事务分散注意力。\u003c/p>\u003cp>4、\u003cstrong>定计划并有序执行：\u003c/strong>在任务清单中，找到当前最重要、最需要关注的任务。为当下最重要的任务制定详细的执行计划，包括时间安排、资源分配等。全身心地投入到任务中去，专注执行，直到任务完成。在执行过程中，保持灵活性和适应性，根据实际情况及时调整计划。\u003c/p>\u003cp>这四个步骤构成了一个简单而有效的过程，帮助我们在面临大量任务时，明确并专注于当下最重要的事情。\u003c/p>\u003cp>细化步骤 \u003c/p>\u003cp>（例子）讲一个我的例子，之前在银行工作需要出差去石家庄，给公司办理放贷款业务，晚上回到酒店时，感觉自己需要做很多事情，思考着万一贷款批不下来怎么办，放贷结束后需要怎么写贷后报告。需要把审核岗有问题得事情如何记录下来，万一我的部门经理与审核岗起争执我该如何处理等等。想着去看放款审核资料。还需要当时感觉自己脑袋要炸了。为了第二天办理业务顺利，\u003c/p>\u003cp>通过今天学习精要主义在同一时间段，如何想清楚当下重要的一件事。\u003c/p>\u003cp>\u003cstrong>1清晰思考。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>（1）深呼吸：深呼吸并投入到当下\u003c/strong>\u003c/p>\u003cp>（3）\u003cstrong>整理自己：关闭自己社交软件，避免被外界的噪音和杂念所干扰。\u003c/strong>\u003c/p>\u003cp>2、\u003cstrong>列清单：列出所有争抢注意力的事情。贷款业务遇到问题怎么办，贷后报告、审核有问题如何处理、起争执我改如何处理，如何更好的休息、业务更好的办理\u003c/strong>\u003c/p>\u003cp>3、\u003cstrong>划掉\u003c/strong>：\u003cstrong>划掉所有此时此刻不重要的事情。贷款业务遇到问题怎么办，贷后报告、审核有问题如何处理、起争执我改如何处理\u003c/strong>\u003c/p>\u003cp>4、\u003cstrong>定计划并有序执行：最重要的事情是保证充足的睡眠，为第二天办理业务顺利进行，我做出如下计划，先给家人报平安，收拾一下明天去审核的资料，\u003c/strong>安排好叫醒服务。\u003c/p>\u003cp>（why好处）\u003c/p>\u003cp>通过上述方法以帮助人们分清轻重缓急，优先处理当下最重要的事项。同时，它也有助于减少无效的努力和加班，提高工作效率，使人们能够更好地平衡工作和生活。\u003c/p>\u003cp>\u003cstrong> (\u003c/strong>where)\u003c/p>\u003cp>适用在面临大量任务时，很焦虑先做那件事情，无从下手的场景。\u003c/p>\u003cp>（预防异议）\u003c/p>\u003cp>你可能会说，实际上，同时做两件事情轻而易举：比如洗碗的时候听收音乐，边吃边聊，一面收拾书桌一面琢磨上哪儿吃中饭，一边发着短信一边看电视等等。\u003c/p>\u003cp>我们没法做的是同时专注于两件事情。精要主义观点并非是主张同一时间只能做一件事情。\u003c/p>\u003cp>而是同一时间只专注于一件事情。\u003c/p>","interaction":"\u003cp>\u003cstrong>【技能点】【A3】场景设计。\u003c/strong>\u003c/p>\u003cp>【A3】之场景设计：我们刚刚学习了精要主义找到当下最重要的事情的四个步骤。现在一起做一个演练。请大家认真听一下要演练的场景：\u003c/p>\u003cp>小王是一个经常出差的审计，去其他企业审核公司账务，忙碌了一天晚上回到酒店时，感觉自己需要做很多事情，思考着之前未完成的工作如何进展，一边思考几个月需要完成报告。需要思考如何应对企业人员前后说话不一致，又焦虑下班后如何去考证。事情堆积在一块让小王觉得压力很大。\u003c/p>\u003cp>向自己朋友李姐诉苦\u003c/p>\u003cp>【A3】之小组讨论：现在，请每两人一组，一位扮演小王，一位扮演李姐，李姐是如何运用今天学到的精要主义找到当下最重要的事情来倾听小张的困惑。\u003c/p>\u003cp>演练时间7分钟，7分钟后，我会选一位扮演小王，一位扮演李姐，大家一起听听他们是怎么样演练的。\u003c/p>\u003cp>【A3】之角色扮演：\u003c/p>\u003cp>现在我们请这组小伙伴来演练\u003c/p>\u003cp>一对学习者的分享：（3分钟）\u003c/p>\u003cp>小王：\u003c/p>\u003cp>李姐真是我要摆烂了，我不想干了\u003c/p>\u003cp>李姐：怎么怎么回事，\u003c/p>\u003cp>小王：最近事情赶事情，然后弄得我压力太大的，不知道该怎么办。\u003c/p>\u003cp>李姐：先不要想这些事情，首先先深呼吸。深呼吸三次\u003c/p>\u003cp>小王：呼~吸~呼~吸~呼~吸~\u003c/p>\u003cp>李姐：这么忙，咱们先把需要做的事情列一个清单。\u003c/p>\u003cp>小王：最近飞来飞去，然后到处到公司去做审计。业务对接的这些人也是说话不一致，没有准谱，然后回到从早上忙到晚回到家里边回回到酒店之后，想的就是几个月之后可能还需要去提交一个一份报告，然后那个考证的这件事情一直还都没有推进。这么说，事情确实蛮多的！马上要做的，下班后要做的还有后面要做几个月之后要交的工作报告。\u003c/p>\u003cp>李姐：要不先列一个优先级。\u003c/p>\u003cp>小王：我是觉得公司的事肯定得先忙，毕竟是吃饭的活，对接人，说话前后不一致是必须要解决的，必须得给他们拉空对齐一下，然后这个。几个月完成报告的事情先缓一缓，等到手头的事忙完了之后再聚焦在这件事情上去做一个解决。然后考证的事就只能依赖于业余了，到时候就是工资的事全都不管，直接做这个考试准备，这样分配一下的话可能会好一点。\u003c/p>\u003cp>李姐：现在这个顺序非常明确了，刚才我们来确定一下当下就是现在我们要做的一个最重要的事情。\u003c/p>\u003cp>刚才你说的这个说法，这个你明天是要面对的这个企业，这个说法不一致，跟他们进行审计工作的这个事情。是不是咱们先在脑子里面先过一下，是不是这样话，那其他的其他一些事项。我建议再给他划掉一个，在当前我们暂时不需要考虑。然后你觉得多长时间把这个事情再考虑考虑做完你就可以睡觉了。\u003c/p>\u003cp>小王：我现在已经列了一份可行的计划，要不然就今天就先到这。那就好好的睡上一大觉。\u003c/p>\u003cp>【结语】\u003c/p>\u003cp>感谢两位小伙伴在表演的时候也用到了刚学习的精要主义，找到当下最重要的一件事的五步骤。\u003c/p>\u003cp>引用“行禅师”的一句话：生活只在当下。如果放弃当下，你将无法细致深入地过好生活中的每一刻。\u003c/p>\u003cp>这就是我今天分享，到此结束，谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":true}}],"created_at":1711459903000,"updated_at":1713257357000,"ria":true},{"id":15630,"topic":"如何利用精要主义的思维和方法，告别拥挤的混乱状态，做更少，但做得更好？","learn_goal":"","remark":"宣传语: 现在生活节奏越来越快，内卷越来越严重，我们要做的事情也越来越多，我们的精力负荷也越来越超载，从而容易让自己的工作和生活陷入一种拥挤不堪的混乱状态中而无法自拔，我们迫切需要找到解脱之术。","level":"TF2-4","duration":60,"status":29,"type":0,"chaishujia":{"username":"clund","city":"武汉市"},"club":{"name":"武汉珞珈分舵","city":"武汉"},"prologue":"\u003cp> \u003cstrong>一、自我介绍及分组\u003c/strong>\u003c/p>\u003cp>大家好，感谢大家来参加我的拆书练级活动。我是陈慧云，现从事知识服务咨询方面的工作，如果用三个标签，我可以这样来介绍自己，1、职业上：自由的知识服务工作者。2、生活哲学方面：自律的斯多葛主义者。价值观取向：自省的保守主义者。今天我参加的是L3-1级别的拆书学习，为了更好的促进大家的学习和互动讨论，我们要分组讨论，但因为今天的人不多，我们就形成一个学习小组就好了……\u003c/p>\u003cp> \u003cstrong>二、场景法介绍书籍及目标设定\u003c/strong>\u003c/p>\u003cp>今天我跟大家分享的书籍是《精要主义》，那为什么我要跟大家分享这本书呢？\u003c/p>\u003cp>【\u003cstrong>场景法介绍图书\u003c/strong>】\u003c/p>\u003cp>F:《精要主义》》是一本介绍如何有效进行自我管理并提高效率的一本书，就是叫你如何“做更少，但更好”的致用类书籍。作者把这种思维和方法叫做精要主义。\u003c/p>\u003cp>A:那为什么我要给大家讲讲这本书？因为现代人面临的一个很大问题生活陷入一种拥挤不堪的混乱状态.相比于类似《断舍离》这样偏重家居事务操作的 书籍，《精要主义》提供了从底层逻辑到方法论的工作和生活全套解决方案，相比而言更具系统性和全面性。\u003c/p>\u003cp>精要主义主张只做该做的事情,做更少，但更好。倡导“在合适的时机，以恰当的方式，追求合适的事情”。助你摆脱无意义的多数，专注有意义的少数，成就有意义、有目的的人生。\u003c/p>\u003cp>B1对于那些想要从拥挤不堪的混乱和焦虑的生活状态中解脱，想要重新掌控自己的健康、幸福与快乐的人来说，这是一本必读之作。\u003c/p>\u003cp>B2:今天我要给大家分享的是书中的两个重要章节。让大家知道精要主义的思维，以及精要主义的实践方法，相信一定会给大家带来启发和收益。\u003c/p>\u003cp>我希望各位在跟随我完成本次RIA现场学习后，学习者能够知道什么是精要主义的思维方式，（拆页1）并在此基础上，能掌握精要主义的方法和步骤，能将其应用于自己的日常工作和生活中。（拆页2）\u003c/p>","ratings_count":1,"texts":[{"id":19693,"quote":"\u003cp> 拆页1——精要主义者的核心思维模式\u003c/p>\u003cp>精要主义者的核心思维模式：时间与精力只用于有意义的事\u003c/p>\u003cp>这部分概述了我们试图躲避的三种现实，没有它们，精要思维就毫无意义或无从谈起。\u003c/p>\u003cp>1、选择：我们可以选择如何支配自己的精力和时间。若无选择，讨论权衡取舍就没有意义。\u003c/p>\u003cp>2、甄别：几乎一切都是噪声，只有少数事情价值非凡。正因为如此，我们应该费时费心地去辨别什么才是最重要的。有些事情比其他事重要得多，因此费力找到它们是磨刀不误砍柴工。\u003c/p>\u003cp>3、取舍：我们不能什么都有，也不能什么都做。如果可以的话，我们就大可不必评估和淘汰各种选项。一旦接受了取舍的现实，就不要再问：“我怎样才能完成这一切？”而是要问一个更加诚实的问题：“我要解决的问题是什么？”\u003c/p>\u003cp>只有理解了这些，我们才能像精要主义者那样思考。一旦彻底接受并理解了它们，那么本书中所提供的很多方法在我们的生活和工作中就会变得自然而然，并成为一种本能。\u003c/p>","explains":"\u003cp>\u003cstrong>I便签\u003c/strong>\u003c/p>\u003cp>【what】\u003c/p>\u003cp>本拆页给我们讲了精要主义的核心思维方式：\u003cstrong>选择、甄别、取舍。\u003c/strong>\u003c/p>\u003cp>【why】\u003c/p>\u003cp>那么为什么我们要掌握精要主义这样的思维方式呢？\u003c/p>\u003cp>因为精要主义是一种反人性本能的思维方式，人类在进化的过程的早期，都是面临的资源不足的问题，所以贪婪就成为了人的本性，但贪多嚼不烂。所以我们才要懂得选择做和不做，判断该做和不该做，聚焦重要，舍去更多无意义的事情。\u003c/p>\u003cp>如果我们不这样做，不懂得选择和取舍，试想，如果你选了一条不适合自己的路，你就拼命也可能一事无成，而且不懂舍弃，有可能将自己压垮。\u003c/p>\u003cp>所谓，选择大于努力，人生的智慧就是要懂得选择和取舍，少就是多，只有做得越少，才能做到越好。\u003c/p>\u003cp>【how】\u003c/p>\u003cp>那如何利用掌握精要主义者的核心思维模式呢，一个有三个步骤：\u003c/p>\u003cp>\u003cstrong>1、选择：\u003c/strong>开放的心态，对任何事物都保留主动选择权，这是成为精要主义者的大前提\u003c/p>\u003cp>\u003cstrong>2、甄别\u003c/strong>：判断的能力，能甄别判断事情的价值意义的大小，这是成为精要主义者的小前提\u003cstrong>。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>3、取舍：\u003c/strong>舍九取一的信念，果断摒弃那些不重要无意义的事情，将精力专注在少而重要的事情上。\u003c/p>\u003cp>【where】\u003c/p>\u003cp>精要主义思维适用于那些没有清晰的人生愿景、规划和目标，不懂得选择和取舍，且在工作和生活中陷入忙碌和迷茫的人。\u003c/p>\u003cp>但如果你目标非常明确，非常懂得选择和取舍，且工作状态和精力负荷都不过载，那就不用刻意专注于探讨精要主义思维。\u003c/p>\u003cp>\u003cstrong>【异议预防】\u003c/strong>\u003c/p>\u003cp>可能有些人说，我就是没有选择啊。如果不能自主选择，讨论精要思维就没有意义。比方说，大学新生要参加军训，无法自由支配自己的时间和动作行为，在这种情况下，精要主义就无从谈起。\u003c/p>\u003cp>可能也有人说，小孩子才做选择题，成人都想要，我就是不想舍弃呀。你要知道，有舍才有得，选择本质上是一种放弃，人的精力有限，你只能专注在少数几件事情上，才可能成功。就像打井，只有持续深钻一个领域，才能出水。\u003c/p>\u003cp>\u003cstrong>【案例分享】\u003c/strong>\u003c/p>\u003cp>我在南方工作多年，有不错的职位和薪水，但是孩子在武汉上学，相隔两地，家庭和工作始终无法兼顾和取舍，一方面又不愿意放弃在南方多年工作打下的基础和大几十万的年薪，另一方面又深知孩子成长过程中父亲的陪伴和关爱不可或缺，让自己疲惫不堪。2019年，母亲也因为我们关爱不周延误治疗而导致肾衰竭，在这种情况下，才让我意识到，家庭永远是最重要的，才促使我下定决心，做出主动选择，毅然放弃南方的工作回到武汉另谋发展。\u003c/p>","interaction":"\u003cp>\u003cstrong>A便签\u003c/strong>\u003c/p>\u003cp>A1:\u003c/p>\u003cp>大家回想一下自己的过往经历，有没有跟我先前类似的经历和体验，因为不懂选择不懂甄别不愿放弃而让自己生活陷入拥挤疲惫和焦虑中的例子，当时你是怎么做的？如果时光可以倒流，你坐时光穿梭机回到当初，按照选择-甄别-取舍的精要主义思维方式，你会如何应对？\u003c/p>\u003cp>请大家思考2分钟，两分钟后我邀请一个小伙伴来做分享。\u003c/p>\u003cp>A2:\u003c/p>\u003cp>但是今天不一样了，我们学习了精要主义的思维，我们的思维和做法可能较以往有不同。\u003c/p>\u003cp>请大家联系下自己的工作和生活实际，大家有哪些感觉精力负荷超载，需要用精要主义思维寻求解决的事情，参照精要主义选择甄别取舍的核心思维，你会如何思考并从哪方面寻求解决？\u003c/p>\u003cp>请注意，只需要说明你要用精要主义思维解决的事项，和你大致的思考步骤，具体该怎么做，我们后面的章节在讲。\u003c/p>\u003cp>请大家先在评论区讨论三分钟，三分钟后，我会邀请一位小伙伴做对应的分享。\u003c/p>\u003cp>好，感谢大家的积极参与。\u003c/p>\u003cp>\u003cstrong>【互动答疑】\u003c/strong>\u003c/p>\u003cp>关于理解精要主义思维模式，还有那些我没有讲清楚，需要我再次来澄清，\u003c/p>\u003cp>或者大家有什么问题，需要跟我来探讨的？\u003c/p>\u003cp>请直接开麦发言，谢谢！\u003c/p>\u003cp>徐一一：\u003c/p>\u003cp>我是一个宝妈，一方面我想照顾好孩子和家庭，另一方面我也想经营自己的事业，比如开一个瑜伽馆，一度非常纠结……\u003c/p>\u003cp>我：如果按照精要主义选择、甄别和取舍三步曲，你会怎么考虑这件事情？\u003c/p>\u003cp>徐一一：\u003c/p>\u003cp> 1、\u003cstrong>选择：\u003c/strong>目前我有两个选项，照顾家庭和经营事业，如果要在家庭和事业二者之间做一个选择的话，我认为是前者。\u003c/p>\u003cp>2、\u003cstrong>甄别\u003c/strong>：我曾经也做了尝试，我只是喜欢瑜伽，其实并不善于经营，\u003c/p>\u003cp>3、\u003cstrong>取舍：\u003c/strong>通过甄别，我发现经营瑜伽浪费了大量的时间，不能有充足的时间来照顾孩子，所以，我给自己做减法，安排好照顾孩子的时间，再空闲时间再去做其他的事情和学习，让自己充实起来。\u003c/p>\u003cp>\u003cstrong>【总结启下】\u003c/strong>\u003c/p>\u003cp>精要主义的道理都懂，可能大家都很关心怎么直奔主题，想找到如何做到精要主义，不过我个人认为，对一种反直觉本能的思想观念，只有在思想上有深刻认知，我们才能在行动上有所改变。\u003c/p>\u003cp>至于如何才能践行精要主义，请大家继续跟我学习第二个拆页。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":19709,"quote":"\u003cp>践行这些方法要遵循以下3个简单的步骤。\u003c/p>\u003cp>\u003cstrong>1、探索：区分无意义的多数和有意义的少数\u003c/strong>\u003c/p>\u003cp>精要主义的一个悖论就是，相比非精要主义者，精要主义者实际上会探索更多的选项。尽管非精要主义者致力于什么都做或者几乎什么都做，但并未经过实际探索；而精要主义者在真正行动之前会系统地探索和评估多个选项，因为他们会在一两个大的设想或项目上大干一场，所以一开始就会慎重地探索更多的选项，来确保自己做出的选择是正确的。\u003c/p>\u003cp>通过运用更加严格的标准，我们能够挖掘出大脑中复杂的搜索引擎。如果我们搜索“一个好机会”，会找到很多页的搜索结果。但如果我们可以进行高级搜索并且问3个问题：令我深受启发的是什么？我特别擅长的是什么？在这世上能满足我重大需求的是什么？自然就不会有那么多搜索结果页需要查看了。但这正是练习的重点所在。我们不是要找过多的好事情去做，而是寻找个人贡献峰值的所在：重要的事情，恰当的方式，合适的时间。\u003c/p>\u003cp>精要主义者在探索上面花了尽可能多的时间，倾听、辩论、质问、思考。但并不是探索完就结束了，探索的最终目的是从无意义的多数里识别出有意义的少数。\u003c/p>\u003cp>\u003cstrong>2、排除：摆脱无意义的多数\u003c/strong>\u003c/p>\u003cp>我们很多人答应一些事情，是因为要急于取悦别人或者让自己不同凡响。然而，说“不”才是实现个人贡献峰值的关键所在。彼得·德鲁克曾说：“说‘不’可以让人变得高效，因为说‘不’的人会说‘这不是我的事’。”\u003c/p>\u003cp>排除非精要之事意味着要对有些人说“不”，并且是经常性说“不”。这意味着要将那些社会期待拒之门外，要做到这一点极需勇气和同情。因此，淘汰非精要之事不仅是心智的训练，也是情感的训练，比如必要的时候对社会压力说“不”。\u003c/p>\u003cp>考虑到取舍的现实性，我们不能选择什么都做。真正的问题不是我们怎样才能做到这一切，而是谁来决定我们做什么和不做什么。记住，当我们丧失选择权的时候，别人会替我们作出选择。所以，要么慎重地选择有所不为，要么不由自主，任人摆布。\u003c/p>\u003cp>本书这一部分提供一种淘汰非精要之事的方法，让我们赢得时间去做真正重要的事。只有这样我们才能建立一种平台，尽可能地使执行变得毫不费力。\u003c/p>\u003cp>\u003cstrong>3、执行：让有意义的少数做起来毫不费力\u003c/strong>\u003c/p>\u003cp>不管是要完成一项工作任务，还是要迈向事业的新台阶，抑或是要为伴侣安排一个生日聚会，我们往往都会觉得执行的过程充满了困难和阻力，必须硬着头皮强迫自己去“完成”。精要方法却截然不同。不是逼着自己去执行，而是把时间省下来创造一种方法，用来扫除障碍，使任务执行起来变得尽可能轻松自如。\u003c/p>\u003cp>探索，排除，执行并不是呈周期性循环的独立事件，若我们能持续运用，就能获得越来越多的收益。\u003c/p>","explains":"\u003cp>\u003cstrong>I便签\u003c/strong>\u003c/p>\u003cp>【what】\u003c/p>\u003cp>本拆页给我们讲了精要主义行动的三个步骤：1、\u003cstrong>探索，2、排除  3、行动\u003c/strong>\u003c/p>\u003cp>【why】\u003c/p>\u003cp>那为什么践行精要主义内，我们知道，物理学上有个著名的热力学第二定律--熵增定律，就是说万事万物都会一定走向无序和混乱，这是不可逆的。\u003c/p>\u003cp>不这么做的坏处，如果我们不引起重视，进行“反熵增”的话，我们的人生一定会疲惫不堪，我们会陷入诸事缠绕中无法自拔，越忙越茫。严重时甚至引发心理健康问题。就像现在患上焦虑症和抑郁症的人越来越多。\u003c/p>\u003cp>如果我们想要过高质量的生活和可掌控的人生，就一定要践行精要主义，聚焦少数重要的事情上，才可能过上幸福的生活。\u003c/p>\u003cp>【how】\u003c/p>\u003cp>那如何做一个精要主义者，原文说是有三个步骤：但有些步骤有信息的整合，为了更便于大家理解和执行，我将具体步骤拆分为五步\u003c/p>\u003cp>1、\u003cstrong>想象：\u003c/strong>想象更多的可能性，列出所有的潜在选项。\u003c/p>\u003cp>\u003cstrong>2、探索：\u003c/strong>尽可能对所列出的选项探索实践，不断试错\u003c/p>\u003cp>3、\u003cstrong>区分：\u003c/strong>在探索的基础上，区分出哪些是有意义的（少数）和无意义的（多数）\u003c/p>\u003cp>4、\u003cstrong>排除：\u003c/strong>将多数无意义的选项排除，只保留少数有意义的选项\u003c/p>\u003cp>\u003cstrong>5、执行：\u003c/strong>聚焦于少数有意义的事，坚决执行。\u003c/p>\u003cp>【where】\u003c/p>\u003cp>那精要主义是不是任何情况下，都要实行精要主义做减法呢？答案是不一定的。\u003c/p>\u003cp>假如你现在对生活的状态非常满意，感觉精力充沛，能量满满，而且工作经常处于心流中，就不需要刻意实行精要主义。\u003c/p>\u003cp>但如果你感觉时间精力严重不够用，人陷入那种拥挤不堪的混乱和焦虑，就要考虑实行将要主义做减法了。\u003c/p>\u003cp>\u003cstrong>【异议预防】\u003c/strong>\u003c/p>\u003cp>这里可能有一个关键点，需要跟大家指出来。有人说，精要主义不就是做减法，少就是多吗？那我从在做的诸多事情中，挑几件重要的 事情来做不就行了吗？干嘛要搞得那么麻烦。精要主义奉行的是一种成长性思维，而不是固定型思维，没有人天然的擅长什么事，人的方向和能力都是探索培养出来的。要先做加法，再做减法，先要尽可能的探索尽可能多的选项，广泛试错，探索人生更多的可能性，然后再排除不合适选项，这样的探索才让人生充满意义。\u003c/p>\u003cp>\u003cstrong>【案例分享】\u003c/strong>\u003c/p>\u003cp>我减脂的经历。\u003c/p>\u003cp>今年初，因为疫情大幅减少了户外运动，以及没有控制饮食，加上春节期间的暴饮暴食，我体重激增，一度达到了150斤。我想这样下去不行，就想着启动减脂计划。但减脂的理论和方法很多，就算是大家通常说的管住嘴，迈开腿也有很多不同的做法。我是这样做的。\u003c/p>\u003cp>1、想象：我充分发挥想象，并找了所有能找到的关于减肥的方法，把他都列出来。\u003c/p>\u003cp>2、探索：我按列出来的那几种方法，用一周的时间，做了探索尝试。\u003c/p>\u003cp>3、区分：经过探索，我知道那些适合我，那些不适合我，并将重要性做了排序。\u003c/p>\u003cp>4、排除：经过区分，我排除了生酮饮食法，健身房力量练习等不适合我的方法\u003c/p>\u003cp>5、执行：我执行的是地中海饮食+Keep内脏脂肪减脂训练2组相结合的方式执行\u003c/p>\u003cp>结果，在2个月的时间内，减脂10斤，减脂取得初步成效。\u003c/p>","interaction":"\u003cp> A  便签\u003c/p>\u003cp>A3【场景设计】\u003c/p>\u003cp>我们刚刚学习了践行精要主义的五部曲，想象-探索-区分-排除-执行，光说不练假把式，我们要学以致用，我们现在来一起做一个小练习。\u003c/p>\u003cp>在做的都是终身学习者，我们来到拆书帮当然是为了得到成长。但是，所谓学海无涯，我们我们要学习的东西太多，阅读、沟通、写作、亲子、运动、职场、理财……也经常容易陷入学习的焦虑中，请大家在一周时间内，按照我们今天学习到的精要主义探索--排除-执行的三步曲，来重新规划自己的学习和成长计划……\u003c/p>\u003cp>请大家讨论5分钟，五分钟后，我将邀请小伙伴来根据精要主义五步曲做分享\u003c/p>\u003cp>……\u003c/p>\u003cp>A2【学习应用】\u003c/p>\u003cp>请大家刚刚按照我刚刚给定的场景和条件，就是说你有很多东西和内容想学习，请按照精要主义五部曲的做法，谈谈未来你该如何践行精要主义，下面我有请大家做一下分享：\u003c/p>\u003cp>徐一一：\u003c/p>\u003cp>我经常参加各种学习，我想探讨的内容是个人成长方面，我想成为更好的自己，那么，如何我才能成为最好的自己？\u003c/p>\u003cp>按照精要主义五步区，我可以这样思考：\u003c/p>\u003cp>1、想象：\u003c/p>\u003cp>成长的范围很广，我想象到的有，美食、健身、运动、阅读、演讲、很多都想学。\u003c/p>\u003cp>2、探索：\u003c/p>\u003cp>经过探索，我选择了三项长期的成长项目\u003c/p>\u003cp> 1、运动，2、阅读，3、演讲。\u003c/p>\u003cp>3、区分：\u003c/p>\u003cp>经过探索，我知道那些喜欢，那些不喜欢，我喜欢的是：在头马学习演讲，提升自信和表达力，在拆书帮学习拆书法，提高阅读效率。\u003c/p>\u003cp>4、排除：\u003c/p>\u003cp>排除了美食、营养、其他等项目\u003c/p>\u003cp>5、执行：\u003c/p>\u003cp>每周参加头马会议练习演讲，每个月参加2次拆书帮练级。\u003c/p>\u003cp>\u003cstrong>【互动答疑】\u003c/strong>\u003c/p>\u003cp>我们刚刚分享了践行精要主义的五个步骤想象-探索-区分-排除-执行，我不确定有无跟大家讲清楚，大家还有什么疑问要我澄清或提出探讨的吗？请直接开麦提问，或在互动区留言，我会一一作答。\u003c/p>\u003cp>学员的提问……\u003c/p>\u003cp>徐媛媛：我有一个疑问，通过刚才的分享，我们实施精要主义的有个前提，都是知道自己要什么？如果我不知道自己要什么怎么办？\u003c/p>\u003cp>我的解答：那我们就要回到精要主义的前提：选择。即使你不知道自己要什么，先列举自己可能有的选项，进行探索。并在探索的过程中不断进行探索和行动。\u003c/p>\u003cp>徐一一：我感觉很多内容都连不上，这是怎么回事？\u003c/p>\u003cp>我的解答：我们学习新知，一定要关联旧知，过去发生了什么不重要，更重要的是我们要面对未来。\u003c/p>\u003cp>徐媛媛：精要主义和极简主义和断舍离的区别是什么？\u003c/p>\u003cp>三者有相通之处，相对而言，精要主义既有理论指导和实践的方法论和工具，有更好的体系，可能更适合当下的我们。\u003c/p>\u003cp>\u003cstrong>【总结陈词】\u003c/strong>\u003c/p>\u003cp>总结：精要主义不仅是一种做事的思维和方法，而应该成为当下我们的一种生活哲学，特别在当下生活节奏和压力越来越大，内卷越来越严重的现在，奉行精要主义的价值观和方法论，让我们告别 拥挤不堪的混乱，掌控内心的安静和幸福。谢谢大家\u003c/p>\u003cp>希望今天的拆书分享能给大家带来一些思考和启发。\u003c/p>\u003cp>我今天的拆书分享到此结束，感谢大家的积极参与和配合，谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1681809559000,"updated_at":1684159624000,"ria":true},{"id":10915,"topic":"让你战胜拖延症，不费力气的三个技巧","learn_goal":"","remark":"如果，你是个拖延症患者，常常把重要的事拖延到DDL，最后不得不降低质量，为此烦恼不已…\n\n如果你发现年初的flag基本倒了，希望自己能有所转变…\n\n如果你处于希望自己能有所成，但又很难坚持的矛盾状态…\n\n那建议你一定要来现场拆书，今天的拆书主题：让你战胜拖延症，不费力气的三个技巧 ，简短的**希望能大家带来小小启发。","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"南妃","city":"深圳"},"club":{"name":"深圳智行分舵","city":"深圳"},"prologue":"\u003cp>【开场白+分组】 30秒 \u003c/p>\u003cp>大家好，我是南非，那么我们在正式的主题分享之前，先来做一个分组，因为大潘是观察家，所以他就不参加我们的分组，那我们这三个小伙伴可以做成一组，再凑近一点，这样就凑近一点好不好，然后我们这三个伙伴是一组，然后上面三台小伙伴就凑近一点。\u003c/p>\u003cp>【图书介绍】1分钟\u003c/p>\u003cp>那我们就接下来我们就开始我们的分享，首先，来介绍一下我们今天待拆的书籍是精要主义，这本书的作者是格雷戈•麦吉沃恩，那他被誉为21世纪的史蒂芬科维，就是我们非常熟知的，高效的七个人士的那个书的作者，所以她是非常有成就的，那她有三个标签。第一个标签就是她就是精要主义，这个理念的一个提出者、领导者，那第二个标签就是他是《华尔街日报》非常畅销的畅销书作家，第三个标签是它是全球世界经济的一个青年扭领袖，那这本书呢，主要是讲了一个精要主义者，但他的思维模式，然后在这本书里面把它转换成了一个系统的程序，就把这种思维模式系统化了，这本书也受到了非常多大咖的推荐，比如说推特的创始人，还有巴菲特就是都推荐这本书，所以我们看一下今天能够能够给大家带来一些什么。\u003c/p>","ratings_count":1,"texts":[{"id":14812,"quote":"\u003cp>接下来呢，我想请大家带着一个问题来阅读原文片段就是年底了，你的目标完成了几个呢？那可能可以是关于你个人成长，也是工作，家庭都可以。那如果是用今天学习的一个片段，能不能帮助你明年活出更多姿多彩的一个你。好，那接下来用一分钟左右的时间阅读一下原文片段，并带着一个问题进行一个思考，如果阅读完的小伙伴可以抬头示意我一下，看完的小伙伴可以抬头示意我一下都看完了吗？\u003c/p>\u003cp>拆书主题：让你战胜拖延症，鼓励小胜的三部曲\u003c/p>\u003cp>拆解图书：《精要主义》\u003c/p>\u003cp>拆书时长：10-15分钟\u003c/p>\u003cp>我们可以选择。我们既可以下工夫建设种制度，让执行精要之事不费力气，也可以听命于一种制度，哪怕它实际上只会让执行要事变得困难重重。沃德的肯定票制度属于前者，它取得了很好的效果。在为人生设计制度的时候，我们也可以将同样的原则运用到自己所面临的选择中去。\u003c/p>\u003cp>我和妻子安娜试着在我们的子女教育机制中运用这样的理念。我们曾一度很担心家里的屏幕时间究竟多到了什么样的程度。在对电视、电脑、平板电脑和智能手机的轮番使用中，孩子们的时间就这样轻易浪费在了意义不大的娱乐活动中。我们试图改变他们的习惯，但是正如你能想象到的那样，我们遇到了阻力。不管什么时候.我们要关电视或者想要限制他们的屏幕时间，孩子们总是抱怨不休。作为父母，我们必须有意识地管理这种状况。这让我们不得不放下重要的事情。\u003c/p>\u003cp>因此，我们采用了一种代币制度。每周开始，孩子们可以领到10个代币。每个代币可以30分钟的屏幕时间，或者在周末的时候换50美分，总共加起来是每周5美元或者5个小时的屏幕时间。如果哪个孩子读书30分钟，他或她就可以赚到一个额外的代币，也可以换成屏幕时间或者钱。结果简直不可思议:一夜之间，屏幕时间下降了90％，读书时间上升了同样的百分比而且我们必须投入到管理中的努力越来越。也就是说，不重要的活动显著减少而有意义的活动显著增加。当初只不过投入了一点点努力来建设一种机制，而现在它顺利无阻地发挥着效用。\u003c/p>\u003cp>在家里和在工作中，我们都可以建立这样要素十三进步，小胜的价值的机制。关键在于，要从小处着手，鼓励进步，庆祝小胜。以下是一些技巧。\u003c/p>\u003cp>\u003cbr> \u003cstrong>1.关注最低可行性进步\u003c/strong>\u003c/p>\u003cp>在硅谷流行着“完成比完美更重要”的理念。这并不是让大家去制造垃圾。其中的思想，在我看来就是不要在不重要的事情上虚掷光阴，而是要把事情做成。在企业界，这种想法被表述为创造一种“最低可行性产品”( Minimal Viable Product)。它指的是:“对目标客户有用且有价值的尽可能简单的产品是什么?”\u003c/p>\u003cp>同样，我们也可以采取“最低可行性进步”( Minimal Viable Progress)的方法。问问自己:“对于我们努力要完成的重要任务，有用且有价值的最小进步是什么?”我在本书的写作中就采用了这种方法。比如，当我还在探索阶段的时候，在动笔(或敲打键盘)之前，我会在 Itwitter上面分享一个小小的想法(我的最低可行性产品)。如果能够在那上面引起共鸣,我就会给《哈佛商业评论》写一篇博客文章。通过这种只需要花费很少精力的迭代过程，我能够知道应该在什么地方搭建座桥梁，让自己所思考的事情和同別人生活最相关的事情之间建立起联系。\u003c/p>\u003cp>皮克斯动画工作室把这个方法用在了他们的电影中。这些电影的创作不是开始于脚本，而是开始于情节串联图板，或者叫做连环漫画版电影。他们尝试各种想法，并观察哪些有效，在小范围内进行数百次实验。然后，做出一个影片放映给小规模人群看，以便提前获得反馈。这样，他们就可以用尽可能少的投入，获得尽可能快的长进。皮克斯动画工作室的首席创意官迪士尼幻想工程的首席创意顾问约輸拉塞特( John Lasseter)说:“实际上，我们不是在完成电影，而是在发行电影。\u003c/p>\u003cp>\u003cbr> \u003cstrong>2.做最低可行性准备\u003c/strong>\u003c/p>\u003cp>应对一个重要目标或一个最后期限，有两种截然对立的方法。一种是早动手，小步前进;另一种是晚动手，一日千里。“而大”意味着要在最后一刻完成全部，通宵加班，把它做完。“早而小”意味着以尽可能少的时间投入，尽可能早地开始。\u003c/p>\u003cp>你只要在一个项目或任务到期前两周仅仅投入10分钟时间，就不用在最后时刻花大把时间焦头烂额地仓促赶工了。有了目标或者期限，就问问自己:“我此刻能够做的最低可行性准备是什么?\u003c/p>\u003cp>有一位领导者，他非常善于发表激动人心的演说。他解释说自己的秘诀就是在演说的6个月前就开始为这些鸿篇阔论做准备。不是准备整个讲稿，只是开始而已。如果未来几个星期或几个月内你有一个重大报告要做，那么你现在就打开文件，花4分钟时间，想到什么就写什么。然后，关闭文件。不要超过4分钟。开始就够了。\u003c/p>\u003cp>一位在纽约的同事有一种很简单的方法任何时她安排了会议或者有电话要打.就会很精确地花15秒钟备忘一下那个会议的主题。这样在开会那天早上，当她坐下来准备发言要点的时候，可以参考这个备忘录。她不需要规划整个会议的议程，只要花几秒钟提前准备，就会大有收益。\u003c/p>\u003cp>\u003cbr> \u003cstrong>3.直观地嘉奖进步\u003c/strong>\u003c/p>\u003cp>你记不记得，在你5岁的时候，学校组织了场募捐活动?你记得那个用来直观地展示学校向目标迈进的大温度计吗?你是否记得，看到温度计一天天上升时，心情多么激动，多么欢欣鼓舞?或者，你的父母给你准备了一个星形图，每次你吃了菠菜，或按时睡觉，或打扫了房间，你就能得到一颗星星，然后很快你就不用什么激励物也在做这些事情了。\u003c/p>\u003cp>直观地看到自己正在朝着目标进步，会产生一种巨大的力量。不管是在家里，还是在单位里，不要不屑于把这样的方法运用到你自己的重要目标上。\u003c/p>\u003cp>相较于设定庞大的、高远的和不现实的目标，从小处着手，奖励进步，才能成就更多。作为一种额外奖励，这种明确地强化成功的行为，能让我们在过程中收获更多的快乐和满足。\u003cbr> \u003cbr> \u003c/p>","explains":"\u003cp>好，那我先来就这个片段，今天分享一下我的见解，那么首先精要的事情我们可以理解为是对自己很重要的一些事情，那在日常生活中，我们很多人都会有这样一个困扰，就是本来你想回家去学一下习，刚刚结束了工作，觉得很累了，但是实际上你一回到家就是刷手机睡觉了。那还有一种情况就是把你明明有一个方案，老板要你出，结果你一直推到，老板说你怎么还没交，然后你临时赶了一把，我们经常把一些很重要的事情就这样子慢慢的延后了，直到突然发现哦，惨了，我什么都没有做成，我今天没有成长哦，大家怎么成长的都这么快，这个时候你很难挽回了，你只能再往前走，那么怎么去避免这样的情况再发生呢？我们可以用今天的这个拆页片段鼓励小胜的三步法来帮助我们把一些庞大的目标，或者说我们想要做的事情去往小了落地，从小处着手去关注一些小的成果，然后从一些小的动作，然后去直观的奖励自己的一些小的进步，这样子帮助自己能够走在自己真正想要走的大路上。好。那么具体来说要怎么做呢？\u003c/p>\u003cp>首先第一步就是小成果，那什么叫做小成果，就是你要去关注这件事情，你可以做成的有价值有意义的最小最简单的成果是什么？比如说你要输出一个年终汇报的一个PPT，那你其实你要输出这个目标，你你可以先做什么？比如说第一个就是你其实可以先做一个思维导图，这就是他的一个小成果。\u003c/p>\u003cp>那第二步就是一个轻动作，轻动作就是你做越重要的事情，你反而要越早开始，这样子一动就轻的时候，你就更轻松的可以一直做这件事情，就比如说我们要写一篇专业的文章，那你其实可以好早三个月之前你就去开始看相关的文章，去学习其他的别人是怎么写的，然后你就开始写大纲，然后慢慢的每一天只写一小段，再丰富，这样子，这个动作就很轻，你就容易坚持。\u003c/p>\u003cp>第三步是直观奖，奖是奖励的奖，直观奖是什么呢，就是你要很直观的把你的进度展示出来，这样子这个展示的过程就是你奖励自己，自己奖励自己的一个过程，那比如说我们可以做一个月历表，就是贴在墙上，你每做完一个，你就这样子打个对勾，它其实就是在不断的奖励我们自己的一个过程，好，那这就是鼓励小胜的三步法。那么鼓励小胜的三步法非常适用于我们在工作中，生活中去处理一些，对我们来说很重要的事情，让我们更轻松的去完成一些我们想要去做的事情。\u003c/p>","interaction":"\u003cp>A1激活经验 5分钟\u003c/p>\u003cp>好，那接下来呢我想请大家去讨论一下，就是在过去的一年中你有哪些目标是想完成，但是因为各种事情是没有完成的，大概3~5分钟去讨论一下，好，那我们就按照刚刚的小组，就你在这一年中由哪些事情是白想做的，但是因为你推了，然后又不想做，各种推延，好，我们用3~5分钟的时间去进行一个简单的分享，每个人就一句话，每个人就讲一讲自己的来，按照刚刚小组。\u003c/p>\u003cp>\u003cem>学习者小牛说：\u003c/em>\u003c/p>\u003cp>\u003cem>我没有完成的任务是个考试，就是我没有完成原因是因为我之前在盐田和坪山的工作过，是从6月份的时候才调过来，之前一直再连贯的看书，后来到一个新环境就中断了。然后就是突然中断，所以后面就没做了。\u003c/em>\u003c/p>\u003cp>\u003cem>拆书家反馈\u003c/em>\u003c/p>\u003cp>“因为你没有做一个表格去管自己之前做了多少，然后你没有去打对勾的那种。”\u003c/p>\u003cp>“我之前是按单天算的，一天要看几个小时。”\u003c/p>\u003cp>“你换了环境之后你还有吗？”\u003c/p>\u003cp>“换了环境，因为环境的原因，可能环境比较吵杂，或者其他原因就一直想克服，当时睡眠也不太好，然后就比较憔悴，然后我当时也没有解决以后就有点儿算了”\u003c/p>\u003cp>“嗯嗯了解了解，那我们先请小牛回去，像小牛案例里面说他换了环境，她很累了，所以他后面就没有再做，其实，他可以说去放轻自己的动作，他不需要做很多，你可以减半，但是你要把这个习惯坚持下来，就你当时是可以就是不需要按照原来的计划做的那么重。因为你换了环境，其实你是需要精力去适应他的，所以你其实是可以去减半，甚至只完成1/10，1/5你都可以，对，因为你要从长远的时间去看这个动作。”\u003c/p>\u003cp>【A2分步催化应用】 3分钟\u003c/p>\u003cp>\u003cstrong>技能点：拆书家给出最简单的【A2】指令，让学习者自己写A2便签。\u003c/strong>\u003c/p>\u003cp>对，所以按照这个来看的话，你其实当时就可以把动作做清的好，那接下来呢，我想请大家一起再用刚刚的片段回顾，看一下刚刚的片段，可以在你2021年给你的哪一个目标可以带来，就是怎么帮你实现哪一个目标好不好，大家在纸上写一下，用一分钟左右的时间写一下，具体写一下你希望大概什么时候完成，什么时候用，能够帮助你完成什么目标，怎么用，我们写目标的时候要注意一下smart就是你这个目标能不能执行落地下去，所以我们一定要确定好自己是在什么时间用，然后就是完成自己的哪一个目标，哪一项任务想做成哪一件事情怎么用。大家写完之后，我们可以请一位小伙伴上来分享一下，看一下其他小伙伴是怎么用的。来我看吴哥写的差不多了。我们请吴哥下来做一个简单的分享，好不好用一分钟左右的时间，大概是在什么时间用，怎么用用，在什么目标上。\u003c/p>\u003cp>学习者吴鸽：\u003c/p>\u003cp>\u003cem>去年的目标是要把买的英语网课听完，但其实只听了不到10%，嗯，然后决定今年继续把那个课要听完，然后计划的是每天就听一节课，然后要给那个课程做一个计划表，然后听完一节课打个勾，然后到我的成果更加直观，然后希望我能尽快听完那个课。\u003c/em>\u003c/p>\u003cp>吴鸽的这个计划做的非常标准，就是他非常落地，我一听就知道，我要怎么做，而且他不是很重，所以就更能坚持。所以我们看到自己的目标的时候，往往要去看长远，他不是说我一天要去读多少本书，一个月要读多少本书，而是说你在整个人生长河里面，你要做成哪些事情，你希望往哪方面走，好，那以上就是我带来的鼓励小胜的三步法，谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1610208227000,"updated_at":1610970286000,"ria":true},{"id":10645,"topic":"专注于当下的三步法","learn_goal":"","remark":"你有没有过那样的一瞬间，脑海突然充斥着很多。同一时刻很多事情都争着抢着要被优先完成的这种压力，让你感觉不堪负重。怎么缓解这种压力呢？\n\n活在当下，做当下最重要的事情。","level":"TF2-3","duration":25,"status":30,"type":0,"chaishujia":{"username":"盈盈","city":"深圳"},"club":{"name":"深圳智荟分舵","city":"深圳"},"prologue":"\u003cp>大家好，我是盈盈，今天给大家拆解的片段选自《精要主义》。\u003c/p>\u003cp>F:《精要主义》的作者是麦吉沃恩，被誉为21世纪的史蒂芬.柯维，本书从探索、排除、执行三个方面讲述了精要主义的生活方式。\u003c/p>\u003cp>A:和其他个人管理类图书相比，本书不是强调时间和精力管理的方法，而是根据实际情况，主动选择，精简生活。\u003c/p>\u003cp>B1：在读完本书后，大家可以学会给生活做减法，从琐碎的事情中脱离出来，做更少但更好的事情，。 \u003c/p>\u003cp>B2跟随我完成本次学习后，学习者能够在事务繁忙时,运用专注当下5步法，快速调整好状态,专注当下最重要的事情。\u003c/p>","ratings_count":1,"texts":[{"id":14511,"quote":"\u003cp>\u003cstrong>1.想清楚当下最重要的是什么\u003c/strong>\u003c/p>\u003cp>最近，我在纽约向一个领导团队讲了整整一天的精要主义。我尽情享受了这一天，并自始至终感受着当下。但当我回到房间酒店的时候，我突然感到自己被拉向了四面八方。身边每一样东西都在提醒着我应该做的一切：查看电子邮件，听留言，读一本自己觉得有必要读的书，从现在开始花几个星期准备一个报告，把这一天的经历触发的有意思的想法记录下来，以及其他事情。让我觉得不堪重负的，倒不仅仅是事情的数量，而是在同一时刻很多事情都争着抢着要被优先完成的这种压力，对此我再熟悉不过了。焦虑和紧张让我停了下来。我跪下来，闭上眼睛，问自己：“当下重要的是什么？”沉思片刻后，我明白了，在知道当下重要的是什么之前，重要的是搞清楚“当下重要的是什么”这个理念！\u003c/p>\u003cp>我站了起来，开始整理。我把所有散乱地堆在我身边的东西收了起来，放到该放的位置上去，免得它们分散我的注意力，也免得我每次经过时，它们迫使我按它们的吩咐去做。我关掉了手机。别人没办法给我发短信，这让我如释重负。我打开笔记本记录下这一天，这让我收起了心。我用铅笔给脑海中出现的所有事情列了一个清单。为了明确任务，我问自己：“你要做些什么才能平静地睡去？”我决定，第一重要的事是跟妻子和孩子们联系。接下来要做的就是能让次日早上的头几个小时尽可能轻松一些的事情：安排好叫醒服务和房内早餐，把幻灯片拷到电脑上，熨好衬衣。我划掉了当时并不重要的事情。\u003c/p>\u003cp>当你面临很多很多的任务，以至于不知该从何下手的时候，停下来，深呼吸。投入到当下，问问自己此时此刻最重要的是什么——不是明天最重要的是什么，甚至不是一小时后最重要的是什么。如果不确定，那就把所有争抢你注意力的事情都列出来，然后划掉所有此时此刻不重要的事情。\u003c/p>","explains":"\u003cp>今天给大家分享的内容是关于提升专注力，活在当下的方法。\u003c/p>\u003cp>在工作和生活中，相信大家都有过这样的时刻，同一时间很多事情都想要去做。\u003c/p>\u003cp>比如：下班回家后，想看点书充实一下自己，或者写点总结，记录下有些异常的今天，洗洗衣服收拾收拾家务，又或者是做做运动减减肚子。有家有娃的朋友们，还要和孩子进行下亲子活动。\u003c/p>\u003cp>明明一直想给自己创造一个轻松积极的环境，可是这么些事情，就像是一个雪球，越滚越大，让人疲惫。\u003c/p>\u003cp>如何缓解这种焦虑，摆脱这种情形呢？专注当下。\u003c/p>\u003cp>\u003cstrong>如何去做呢？有5个步骤：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>1. 扫除外部杂物。具体做法：把东西归置收纳好，或者干脆换一个没有杂物地方，让自己能清净。 \u003c/strong>\u003c/p>\u003cp>\u003cstrong>2. 清空大脑。在清单上列出此刻正在扰乱你思绪的所有事项。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>3. 划掉不重要的事情。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>4. 把未来的要做事情挪到另一页清单。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>5. 挑出你此刻觉得最重要的事情，就做这一件。\u003c/strong>\u003c/p>\u003cp>WHY 为什么要这样做呢？\u003c/p>\u003cp>扫除干扰项，把外物收拾整齐，就不会被它吸引注意力。比如，之前我的书桌上放着镜子、茶具。我写字时，就会看看两眼，或者摆弄下。现在好了，把东西收起来，我的眼中就只有书本了\u003c/p>\u003cp>清空大脑，把事情从大脑里面抽出来。\u003c/p>\u003cp>将未来想要做的事情记录在另一张清单上，让你专注于当下，又可以当做是一个提醒，以便将来需要时能够有记录。\u003c/p>\u003cp>可以看到在我们生活中效率比较高或者是看起来比较成功的人，他们做事是有重点的。人的精力是有限的。这样可以花费主要精力在最有回报的事情上，事倍功半。\u003c/p>\u003cp>比如，有一次，我准备要和领导汇报月度的销售回款数据，领导是这样分析数据的，先把数字汇总归类，把销售数据多的客户先挑出来，重点分析大客户。\u003c/p>\u003cp>不这么做的坏处：\u003c/p>\u003cp>很多人总想着要事事俱到，但是往往事事都做不好。\u003c/p>\u003cp>就像我们常见的例子。左手画圆，右手画方，能画下吧？能。但是比较下，你画的这两个图形没有你专注画一个图形时候好看。\u003c/p>\u003cp>A2 上周我下班之后，突然感觉自己心静不下来，好多任务呀，如果再这样下去，我可能会焦虑，什么都干不好。\u003c/p>\u003cp>于是，我给自己找个清静的环境，找了一家咖啡馆，\u003c/p>\u003cp>只拿了一张A4纸，一只铅笔。\u003c/p>\u003cp>我列出所有当下影响我思考的东西：\u003c/p>\u003cp>1.准备拆页。\u003c/p>\u003cp>2.准备旅行的物资。\u003c/p>\u003cp>3.周报。\u003c/p>\u003cp>4.工作的代办项。\u003c/p>\u003cp>我想到工作上的事情完全可以上班时候做，旅行物资也不着急，只有拆页这件事情是当下最重要的，所以，我专注在此事情上，明确目标是交付拆书表。\u003c/p>\u003cp>只用了1个小时，就确定了拆页和大纲，这可是史无前例的呀。\u003c/p>\u003cp>预防异议：我们这里不是说不能同时做两件事情，只是说做两件事你不可能都专注。一次只做一件事情，会提升专注力。比如，你可以洗碗的时候听歌，或者是跑步时看综艺节目，毕竟跑步这种事情，可太无聊了。\u003c/p>\u003cp>适用范围：在工作和学习中，需要专注力比较强的场景，像是娱乐时可以不用。\u003c/p>","interaction":"\u003cp>A3 问题\u003c/p>\u003cp>请大家思考以下的场景，运用专注当下5步骤去帮助下面的小伙伴找到学习方法。\u003c/p>\u003cp>琳琳是个一个10岁孩子的宝妈，同时她也是一个职场达人。一天，她上了一天的班，拖着疲惫的身体回到家，虽然离开了工作的场景，但是心里一点也没有放松，想着：明天的方案汇报还没有收尾，领导又得要催了；周末策划的亲子出游，行李还没准备好呢？小女儿最近情绪有点不好，要花点时间和她聊聊天。网易云上的课程快要过期了，得抓紧时间看看呢。洗衣篮里丢着一家子换洗的衣服，沙发上、书桌上都堆满了孩子的玩具，书本。\u003c/p>\u003cp>请大家进行角色扮演，一个人是琳琳好朋友，一个人是琳琳，通过对话的形式，运用专注当下的5步骤，帮助琳琳解决混乱的情景，回到当下。\u003c/p>\u003cp>帅帅：符号，来来来，我给你说点事，我跟你说，最近好烦、好焦虑，你看我明天方案没完成，领导肯定要催我，我现在心里好累。这周木要带孩子出去玩，行李还没准备好。我那小宝，最近一直再闹，我还想和他聊聊天。网易云有个课程，也快过期了。洗衣篮上都是一家人换洗的衣服，好烦呀。\u003c/p>\u003cp>符号：不要着急，我们先找个地方坐下来，好好聊聊，最近在拆书帮，正好最近听到朋友分享一个方法。\u003c/p>\u003cp>1. 列出最重要的事情。方案、周末亲子出游、小孩需要安排、网易云课程、洗衣篮的衣服、沙发上玩具和书本。那现在我们做一个排序，挑出你此刻觉得最重要的事情，现在不需要立马处理的？划掉。\u003c/p>\u003cp>帅帅:方案是明天做的，周末出行，网易云要过期了，但是有几天的时间。\u003c/p>\u003cp>符号：那我们把未来要做的事情先划掉，剩下356，哪项是此刻最需要做的\u003c/p>\u003cp>帅帅：衣服可以直接丢洗衣机和处理孩子玩具，顺便在整理过程跟孩子聊聊天，\u003c/p>\u003cp>符号：所以我们先洗衣服，然后和女儿一起整理书本，和女儿进行亲子沟通。\u003c/p>\u003cp>帅帅：对，这样子差不多清晰了。\u003c/p>\u003cp>符号：这个就跟我们在拆书帮学的知识一样了\u003c/p>\u003cp>1. 扫除外部杂物。\u003c/p>\u003cp>2. 清空大脑，在清单上列出此刻正在扰乱你思绪的所有事项。\u003c/p>\u003cp>3. 划掉不重要的事情。\u003c/p>\u003cp>4. 把未来的要做事情写到另一页清单，\u003c/p>\u003cp>5. 挑出你此刻觉得最重要的事情，一次做一件事情。\u003c/p>\u003cp>恭喜你获得新的技能。\u003c/p>\u003cp>盈盈：感谢符号的分享，最后纠正一个点，第二步是列出所有的事情。在听完帅帅和符号的分享，我发现原来琳琳是可以如此轻松的，晚上可以有时间和孩子进行亲子沟通。\u003c/p>\u003cp>结语：生活总是被缤纷的事情打扰，专注变成很难的事情。今天的方法让大家学会专注于一件事情，专注于当下，专注于享受生活，专注于更有意义的事情。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1605696025000,"updated_at":1606307081000,"ria":true},{"id":9756,"topic":"使用“假设还不曾拥有”的方法克服禀赋效应带来的影响","learn_goal":"","remark":"学会使用“假设还不曾拥有”的方法克服禀赋效应带来的影响","level":"TF2-2","duration":20,"status":30,"type":0,"chaishujia":{"username":"我叫刘军","city":"天津市"},"club":{"name":"北京城市之光分舵","city":"北京市"},"prologue":"\u003cp>大家好，我是刘军。欢迎各位和我一起共赴今天的拆书之路。\u003c/p>\u003cp>【学习目标】\u003c/p>\u003cp>在跟随我完成今天的现场学习后，希望各位学会使用“假设还不曾拥有”的方法克服禀赋效应带来的影响。\u003c/p>\u003cp>【FAB介绍图书】\u003c/p>\u003cp>F：今天要拆的这本书是《精要主义》的。作者是被誉为“21世纪史蒂芬•柯维”的英国人格雷戈•麦吉沃恩，他是精要主义的提出者、倡导者和领导者，本书主要内容为读者将自己打造成一名精要主义者提供的思路和方法。\u003c/p>\u003cp>A：这本书排在豆瓣2016年度读书榜单经营管理类图书第八名。相比其他同类书籍，书中对概念的提炼、理论和实践的结合做的都非常到位，案例也更为详实丰富。\u003c/p>\u003cp>B：你是否感到自己总是忙忙碌碌却效率低下？你是否觉得自己的时间总是被别人的安排打乱？你是否觉得自己一直在奔波，却总是到不了任何地方？这本书介绍了精要主义者的思维模式，并将这种模式转化为一种系统化的程序，助你摆脱无意义的多数行为，专注有意义的少数生活，成就你的有意义、有目的的人生。\u003c/p>","ratings_count":1,"texts":[{"id":13600,"quote":null,"explains":"\u003cp>【what】\u003c/p>\u003cp>拆页内容主要为我们介绍了克服禀赋效应的方法。禀赋效应是指当个人一旦拥有某项物品，他对该物品价值的评价要比未拥有之前大大增加。就是到我手里的东西感觉比之前更值钱。\u003c/p>\u003cp>【why】\u003c/p>\u003cp>对多数人来说，比起“得不到”及“已失去”的，更珍贵的是“即将失去”的东西。做个调研哈：不用的东西舍不得扔；股票跌了不忍心抛掉，总相信它会涨；对象不怎么合适，自己却不愿意分手；买回来的东西，即使别人指出种种缺点，也总是试图用各种优点来说服别人……至少有过上面一种经历的伙伴举个手。\u003cbr>谢谢。从有这么多举手的伙伴来看，大家或多或少都受到过禀赋效应的影响。而禀赋效应带来的副作用，往往让我们变得拖拖拉拉，盲目自信、患得患失或是不够理智。\u003c/p>\u003cp>【提出不这么做的坏处、举反例说明】\u003c/p>\u003cp>几年前，我花一千块钱买了个32寸电视放在以前的合租房里。半年后因为换工作而新租的房间配43寸电视，那个32寸的就没用了。搬家之时，合租室友想五百块买下那个电视，但我觉得电视才用了半年，还是99成新的，怎么也得卖八百，五百块钱亏就没卖。结果呢？直到现在，那台电视还在我衣柜顶上吃灰，闲鱼上挂到四百也还是无人问津，更亏！\u003c/p>\u003cp>【HOW】\u003c/p>\u003cp>拆页中为我们提供了应对禀赋效应的方法：假设我们手头没有，我们愿意付出多大代价去获得它。以此克服禀赋效应为我们带来的影响。\u003c/p>\u003cp>【反例转化正例】\u003c/p>\u003cp>其实想想看，如果室友说要买电视时，我不是追求想卖八百，而是问问自己：如果我没电视，我愿意花多少钱买他的呢？其实最多也就愿意花个五、六百。如此也就把电视卖给室友了。自己回收资金，室友也得到了实惠，一举两得。\u003c/p>\u003cp>【预防异议】\u003c/p>\u003cp>可能有伙伴会觉得那万一以后可能还用的上是不是？其实很多人都这样想，这件物品可能未来用的上，但是大家去衡量一下这个时间，可能是未来的半年、以年，或者两三年以后才用的上。其实未来要用的时候，往往会有其它的解决办法，而且效果可能更好。\u003c/p>","interaction":"\u003cp>A2【分布催化场景】\u003c/p>\u003cp>禀赋效应的影响经常出现在我们的生活中，拆迁时居民与政府补偿价格上的争执，是禀赋效应的体现；股价下跌时，持有者为了避免损失冒风险惜售，也是禀赋效应的体现；不会穿又不舍得扔的衣服、昂贵又无趣的演出，甚至是明明不爱还不肯放手的感情，都是相似的情况。你在生活中会涉及到哪个情境？请大家思考以下，把这个情景简单写在便签上。时间1分钟，一会我请位伙伴分享。\u003c/p>\u003cp>学习者案例分享：\u003c/p>\u003cp>史千军：我在闲鱼上挂着了耳机，其实给它们定价时，就可以用到今天的知识。\u003c/p>\u003cp>【分步催化运用】\u003c/p>\u003cp>OK，请各位再加工一下刚才的例子，说明在往后的时间里，你如何在刚才你想到的情境下克服禀赋效应带来的影响。你会问自己什么问题？请在小组内分享你的应用。\u003c/p>\u003cp>学习者案例分享：\u003c/p>\u003cp>史千军：今晚我回去就改价。我在闲鱼上一直挂着的8个二手耳机，很少有人买家问津，就是源于定价太高。我总想的是这耳机1800买的，我1600才愿意卖。晚上到家我会先问自己，如果是我现在买的话，我愿意花多少钱？答案应该是600，我就按600给他标价，来促成这些耳机尽快出手。\u003c/p>\u003cp>感谢大家参加今天的拆书活动，通过练习应用，我们已经学会使用“假设还不曾拥有”的方法克服禀赋效应带来的影响。也希望今天的活动能帮各位像开场说的那样，助你摆脱无意义的多数行为，专注有意义的少数生活，成就有意义、有目的的人生。谢谢大家。\u003c/p>","flags":{"r":false,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1586234370000,"updated_at":1587639252000},{"id":8904,"topic":"如何成为精要主义","learn_goal":"用清晰的标准选出对自己最有利的一项","remark":"有没有觉的你很认真很努力，结果却不理想，离你的预期差很远。如何做很少，得更多？如何才能事半功倍，实现你的最大峰值！如何成为精要主义，成为行业的专家。","level":"TF2-4","duration":60,"status":30,"type":0,"chaishujia":{"username":"天一","city":"绍兴"},"club":{"name":"杭州光明顶分舵","city":"杭州"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;【自我介绍】\r\n大家好！我是天一，天天进步，知行合一！我给自己的三个标签是：一个有爱的心灵设计师/传统企业主/学习促进者.\r\n【分组】为了便于大家更好的学习，我们分个小组，我们俩俩一组，leo和杜克一组，吴蔚和苓英一组，佳威和冠岚一组，石头和立新一组。\r\n【FAB图书介绍】\r\n今天我给大家带来是《精要主义》\r\nF:这是一本可以改变心智模式的书。作者是（英）格雷戈.麦吉沃恩，是个备受大众欢迎的撰稿人。书中讲解的是如何确定最重要的事，让精力聚焦在带给你最大回报的事务上，并且给出了具体的方法。\r\nA：本书多次登上纽约时报畅销排行榜，和其他书相比。本书逻辑简单清晰，只需要翻下目录，和几张小插图就可以掌握。书中每个点都辅助了生动，有趣，有哲理的故事，单独成篇也是足够的精彩。\r\nB1:在你的生活中，有没有感觉自己忙忙碌碌，却又效率低下？有没有觉得身边机会很多，也很努力，可最终，努力和回报不成正比！夲书让你懂得如何做最少，却事半功倍，让价值最大化！同时教会你做事如何做到一厘米宽，一公里深，如何成为行业的专家！\r\nB2:而通过今天的片段学习，让你能够有清晰的标准，找到能够产生价值最大化的重要事务，并且给出方法，使你在达成目标，实施的过程中变的轻而易举，真正实现做更少，但更好！\r\n【总学习目标】\r\n在面对选择时，能够通过三条普通标准+三条严格标准来区分和选择。接着，在执行的过程中，能够运用解决关键障碍的四个步骤，让执行过程更容易，协助目标的达成。\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","ratings_count":2,"texts":[{"id":12631,"quote":"\u003cp>接下来进入我们的\u003cstrong>R环节，阅读原文\u003c/strong>\u003c/p>\u003cp>请大家用1分钟的时间\u003cstrong>阅读一下原文片段\u003c/strong>，读完的小伙伴请给我一个示意。\u003c/p>\u003cp>\u003cstrong>主题\u003c/strong>:找出10%能给你价值最大化的事\u003c/p>\u003cp>摘自《精要主义》P124-125页\u003c/p>\u003cp>当机会向你走来时，不妨用以下这种简单、系统的流程来执行精挑细选的标准。第一步，把机会记下来。第二步，写下3条“最低标准”，如果这个机会要进入考虑范围的话，就必须达到这3条标准。第三步，写下3条理想的或“极端标准”，如果这个机会要被考虑的话，也必须满足这3条标准。按照这个流程，一旦这个机会不能满足第一组标准，那么答案很显然就是No。但是如果它不满足3条极端标准中的2条，答案依然是No。\u003c/p>","explains":"\u003cp>\u003cstrong>【R1-学习目标1】\u003c/strong>\u003c/p>\u003cp>通过现场RIA学习，学习者能够运用三条普通标准+三条严格标准，选择最有利于自己的一项。\u003c/p>\u003cp>管理大师德鲁克说：最笨的努力就是没有效率的勤奋。你忙忙碌碌了很久，却发现离你的期望相差太远，你百思不得其解，为什么同样的努力，结果却是完全不同？看完下面这张图你就明白了\r\n &nbsp; &nbsp; &nbsp; &nbsp;&nbsp; &nbsp;\u003c/p>\u003cp>精要主义把所有的精力放在一件重要的事情上，非精要主义把有限的时间和精力放在了不同的事情上。\u003c/p>\u003cp>精要主义有个最恰当的定义是：更少，但更好！如何才能做到精要主义呢？首先你得会区分什么才是你最重要的事情？什么才是那10%你做的很少，却可以回报最大化的事务。\u003c/p>\u003cp>\u003cstrong>【What\u003c/strong>:】\u003c/p>\u003cp>刚刚阅读的片断讲述的是面对需要选择或者做决策时，运用三条普通标准+三条严格标准，来进行选择。只有六条标准符合五条，这才算真正符合。\u003c/p>\u003cp>\u003cstrong>【Why】\u003c/strong>\u003c/p>\u003cp>在需要做决定时，如果没有标准去选择，会面临他人说什么就是什么，很容易人云亦云，一拍脑袋就决定，做出很多不理智或者是会后悔的决定。而如果有清晰的标准，选择的速度变快了，也能够选出对自己最有利的那一项。\u003c/p>\u003cp>\u003cstrong>【How】\u003c/strong>\u003c/p>\u003cp>如何用标准做选择？选出对你最有利的那项，有以下三个步骤\u003c/p>\u003cp>1.列出事项：你所面对的选择事件或者是机会是什么？如：我要买一个关于形体方面的微课\u003c/p>\u003cp>2.列出三条普通标准：什么是普通标准？最起码符合的条件是什么？或者说符合哪些基本的条件你才会选？如：1.导师气质好 &nbsp;2.自己心动 &nbsp; 3.100元以内\u003c/p>\u003cp>3.列出三条严格标准：什么是严格标准？最高要求是什么？或者理想状态应该符合哪些条件？如：1.不光是理论，要有行动步骤。2. 课程结束后有100天的打卡 &nbsp;3.不买会觉得后悔。\u003c/p>\u003cp>\u003cstrong>【不这么做的坏处】\u003c/strong>\u003c/p>\u003cp>通常情况下，大多数的伙伴，在面临选择时，都是凭感觉和一拍脑袋决定的，没有清晰的标准。做出的决定都是不理智的，很多时候会造成经济和精神上的伤害。\u003c/p>\u003cp>\u003cstrong>【举个例子】-反例\u003c/strong>\u003c/p>\u003cp>去年下半年，我在郑州投资两套房子，在选房的时候，自己没有去看房，只是看了对方给我的图片，盲目的相信对方，多损失了好几十万，很是后悔。\u003c/p>\u003cp>如果换作现在，再来选择投资买房，我会这样做\u003c/p>\u003cp>\u003cstrong>【正例】\u003c/strong>\u003c/p>\u003cp>第一步：列出事项：投资房子如何选？\u003c/p>\u003cp>第二步：三条普通标准：最低符合的条件是什么？1.一线或者强二线城市 &nbsp;2.市中心 &nbsp;3.地铁口不超过300米。（前提：选对中介，自己到现场看房）\u003c/p>\u003cp>第三步：三条严格标准：理想状态，最好能够符合什么条件？1.名校学区房 &nbsp; &nbsp;2.户型方正 &nbsp; 3.租金抵月供。\u003c/p>\u003cp>相信有了这些标准，选房也变得比较简单了。经济和精神上不会遭受损失。\u003c/p>\u003cp>\u003cstrong>【预防异议】\u003c/strong>\u003c/p>\u003cp>可能你会说，这么多的标准，太复杂了，有时候想都想不出来，要花费很多的时间，值得吗？磨刀不误砍柴工，精要主义在前期筛选时，会花费大量的时间，去制定标准，去调研，而一旦决定了，就不会后悔。会全力以赴去做到。因为方向正确，后期执行会更省力。一切都是为了更少，但更好，所以前期不能怕麻烦，很重要。\u003c/p>\u003cp>\u003cstrong>【where】\u003c/strong>\u003c/p>\u003cp>今天分享的选择标准，适合于选人，选物品或者是选择机会，适合于没有做决定前，需要考虑周全，慎重做选择的事项。对于一些临时起意或者是玩游戏，不注重结果时就不适合。\u003c/p>","interaction":"\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【A1:显像提问】\u003c/strong>\u003c/p>\u003cp>俗话说：光学不练假把式，现在是我们练的时候了\u003c/p>\u003cp>现在请小伙伴们回想一下，在过去的一个月里，你曾经面临什么样的场景需要选择？比如给孩子报辅导班，左右为难；买衣服不知道选哪件？犹豫不决。或者纠结是否换个工作？或者朋友推荐的项目犹豫要不要加入？在面对这些场景时，你是凭感觉决定的？还是有清晰的标准？想一件具体的事情，在小组分享，记得要有时间，地点，人物，情节，结果等要素。时间是2分钟。\u003c/p>\u003cp>现在请一个小伙伴上台来分享\u003c/p>\u003cp>石头： 选择包包要不要流通掉？两年前(时间），我（人物）买了个包包，当时买回来的时候挺开心的，可是基本上没有背过（情节）。要不要处理掉（事件）？当时挺纠结（结果）的，买回来几乎没有背过。\u003c/p>\u003cp>拆书家：你当时定了几个标准？\u003c/p>\u003cp>石头:我当时定了两个标准，不经常用它，朋友也需要它。可还是纠结，纠结的原因是买的时候价格比较贵。\u003c/p>\u003cp>\u003cstrong>【拆书家反馈】\u003c/strong>：我可以这样理解吗？当时你选择包包是否扔掉是有标准的，只是没有这么多，没有这么清晰，因此会纠结。我这样理解，对吗？\u003c/p>\u003cp>石头:对的。\u003c/p>\u003cp>谢谢学习者A的分享,谢谢，请坐下。我们接着往下走。\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003cbr>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【A1+:反思加工经验】\u003c/strong>\u003c/p>\u003cp>你上面想到的场景，如果再给你一次机会，运用今天的三条普通标准+三条严格标准，你会怎么选择？请大家在便签上写下具体的行动计划，记得要有目标，有明确的时间，有具体的做法。时间是2分钟，等一下会请一个小伙伴来分享。\u003c/p>\u003cp>石头：我可以分享吗？\u003c/p>\u003cp>拆书家：当然可以。\u003c/p>\u003cp>石头：（列出事项）关于包包要不要流通掉？\u003c/p>\u003cp>石头：如果让我重新来选择，我的标准是：1.超过半年（时间）不用 &nbsp;2.我不喜欢了，不心动了&nbsp; 3.我不用了（行为）\u003c/p>\u003cp>拆书家：这是你的普通标准是吗？\u003c/p>\u003cp>石头：是的，这是我的三条普通标准。\u003c/p>\u003cp>石头：我的三条严格标准是：1.三个月内不用 &nbsp; 2.是否占了我的空间 &nbsp; &nbsp; 3. &nbsp; 第三个条件我想不出 \u003c/p>\u003cp>来了。\u003c/p>\u003cp>\u003cstrong>【反馈.号召鼓掌】\u003c/strong>：想不出来没有关系的，六条标准符合五条就好了，因为有了更清晰的标准，选择就不再纠结了。谢谢石头的分享，我们把热烈的掌声送给她。\u003c/p>\u003cp>\u003cstrong>【R1总结】\u003c/strong>\u003c/p>\u003cp>第一个片段我们主要讲解的是精要主义通过三种普通标准+三条严格标准，选出那10%的能给你产生最大回报的重要之事。\u003c/p>\u003cp>\u003cstrong>【两个片段的过渡语】\u003c/strong>\u003c/p>\u003cp>现在，我们已经选出了那10%的选项，接下来是不是要去达成？要去行动？要去执行？\u003c/p>\u003cp>\u003cstrong>【简短互动】\u003c/strong>来拿出你的右手，拍拍自己的肩膀，和我一起说，我行动，我执行，我说到做到。\u003c/p>\u003cp>你真的去做了，可是你发现，在执行的过程中会有各种各样的问题发生。怎么办?进入我们的第二个片段，让你在执行过程中找出最关键的阻碍，让你的实现目标的路上更轻松些。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}},{"id":12632,"quote":"\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003cstrong>片断二\u003c/strong>\u003c/p>\u003ch2>\u003cp>【R2-学习目标】\u003c/p>\u003c/h2>\u003cp>运用解决障碍四步骤，找出关键问题并给出一个解决方案。\u003c/p>\u003ch2>\u003cp>【R2-阅读原书拆页】\u003c/p>\u003c/h2>\u003cp>请大家看下刚刚发下去的片段，时间是2分钟，看完的小伙伴请示意我一下。\u003c/p>\u003cp>摘自巜精要主义》第211-212页\u003c/p>\u003cp>主题:扫除，锁定你的最慢进行者\u003c/p>\u003cp>R:原文片断\u003c/p>\u003cp>在努力弄清楚这些话的含义的时候，他和他的儿子及一帮朋友进行了一次徒步旅行。作为童子军领袖，他负责在太阳下山之前，把所有男孩子都带到营地。但是，所有参加过这种旅行的人都知道，让一群小男孩都以同样的速度行进并不掉队，这实际上是很难的。艾利克斯很快就碰上了一个问题：有些童子军走得很快，而另一些却走得很慢。特别是一个叫赫比的小男孩，走得最慢。结果，走在队伍最前面的男孩和落伍的赫比之间，距离相差好几公里。\u003c/p>\u003cp>为了解决这个问题，起初艾利克斯用的办法是让走在前面的那些人停下来，等等落后的人。这办法让队伍在短时间内聚了起来，但是一旦又开始前行，同样的差距就再次形成。\u003c/p>\u003cp>因此，艾利克斯决定换一种方法。他把赫比放在这组人的前面，把其他孩子按速度进行排列：从最慢到最快。虽然，把走得最快的人放在队伍的最后面是违反常理的做法，但是这么做能让这群人开始以整齐划一的队列行进。每个男孩都可以跟上自己前面的那个男孩。这种方法的好处在于，他马上可以看到整个队伍的情况，男孩子们可以安全、同时到达营地。不利之处在于，这个队伍现在是以赫比的速度在前进，因此他们将会晚到。那么，艾利克斯该怎么办呢？\u003c/p>\u003cp>他找到的对策是，想尽一切办法为赫比减负。因为走得最慢的小孩恰恰在队伍的最前面，如果赫比每小时都能走快一米，整个队伍就能以同样的增速更快地到达营地。\u003c/p>\u003cp>这个发现对艾利克斯来说意义重大。赫比的任何一点加速，哪怕极其微小，也会对整个队伍的行进速度产生立竿见影的效果。因此，他把赫比背包里的东西（他随身带的多余的食物和用品）都拿了出来，并分给了队里的其他人。这种方法马上奏效，队伍行进速度立刻加快。他们最后提前到达了营地。\u003c/p>","explains":"\u003cp>看到小伙伴已经都看完了这个片段，进入我们的\u003cstrong>I环节。\u003c/strong>\u003c/p>\u003cp>非精要主义在遇到问题时，总想着把所有问题都解决，这个也要去解决，那个也要去处理，最终发现，每天忙的焦头烂额，问题还是一堆。\u003c/p>\u003cp>精要主义在解决问题时，首先找出关键问题，直捣黄龙，直至要害，有目的性的去解决\u003c/p>\u003cp>\u003cstrong>【What】\u003c/strong>\u003c/p>\u003cp>本片断讲述的是，在目标达成的过程中，出现了问题时，通过找出最关键的障碍并针对问题给出解决方案。\u003c/p>\u003cp>\u003cstrong>【Why】\u003c/strong>\u003c/p>\u003cp>如果没有针对核心的问题去解决，你可能就成为了救火队员，很忙很乱，没有重点，力不从心，最后很可能是吃力不讨好，根本问题也没有解决。也不可能实现价值最大化。\u003c/p>\u003cp>\u003cstrong>【意译案例】\u003c/strong>\u003c/p>\u003cp>王来身高1.73米，体重85公斤，最近谈了个女朋友，一切都很顺，到了谈婚论嫁的时候，可是女方要求，减掉20斤，再确定婚期。为了达成这个目标，王来决定天天跑步，减掉20斤，争取早日娶新娘子过门。可是他发现，才跑了3天，他就不想跑了，任谁去说，他都不想动。\u003c/p>\u003cp>过了几天，他想着或许是跑步没有人陪，坚持不下去，于是他加入一个跑团，跑了一星期，发现自己又不想跑了。短短的7天，还是没有能够达到减重的目的。\u003c/p>\u003cp>怎么办？为了娶媳妇，王来也是豁出去了，他办了张健身卡，还找了个私人教练，坚持了一个月，他发现还是没有效果。一点没有减轻。\u003c/p>\u003cp>王来静下心来想，怎么就减不下来呢，有一天，女朋友对他说，你天天晚饭吃这么多，并且无荤不下饭，吃完了就在那坐着，怎么可能减的下来，练也是白练。一句话惊醒梦中人，之前健身房私教也说过这个问题，不过他没有重视。原来最大的问题是晚饭吃得多，并且吃完就坐那不动。\u003c/p>\u003cp>找到了问题的根源，一切就好办多了。从那以后，王来下午4-5点会吃点水果，吃饭前喝一碗汤，吃饭时细嚼慢咽，控制食量，吃完在半小时内不能坐下，必须散步或者坐一些轻运动。再辅助私人教练的指导，加强练习，没到三个月，王来减掉了20斤，如愿把婚期提上了日程。\u003c/p>\u003cp>当你想达成目标，遇到障碍时，开始解决，在不断尝试的过程中，找到最佳的解决方案，文中是通过案例来讲解，步骤不是特别清晰，为此我总结\u003cstrong>细化了以下步骤\u003c/strong>\u003c/p>\u003cp>\u003cstrong>1.确定目标\u003c/strong>：你想要的结果是什么？目标要具体。如：上面的例子，王来的目标减重20斤，确定婚期。\u003c/p>\u003cp>\u003cstrong>2.找出障碍\u003c/strong>：找出一个关键性的障碍。怎么找？\u003c/p>\u003cp>问自己：只要解决了哪一个问题，其他问题都会得到改善或者是迎刃而解。如：王来选的是如何减掉20斤？\u003c/p>\u003cp>\u003cstrong>3.尝试方案：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>①行动\u003c/strong>：完成比完美更重要，想到一个办法就先动起来。如：跑步，先跑起来\u003c/p>\u003cp>\u003cstrong>②检查\u003c/strong>：检查行动方案是否能解决最关键的那个问题，如果不能，继续想办法，继续测试。如：跑步不行，跑团不行，健身房还是不行。\u003c/p>\u003cp>\u003cstrong>③发现\u003c/strong>：发现解决关键问题的最重要的信息。如：晚饭吃太多，没有节制，吃完一动不动。\u003c/p>\u003cp>\u003cstrong>4.执行方案\u003c/strong>：对重要信息进行剖析，找出最佳执行方案并且开始执行，达成目标。如：晚饭前一两个小时吃水果，饭前一碗汤，吃完半小时内不许坐下）\u003c/p>\u003cp>\u003cstrong>【不这么做的坏处】\u003c/strong>\u003c/p>\u003cp>通常情况下，大多数人是这样做的，头痛医头，脚痛医脚！哪里出问题解决哪里问题。可是很多时候，只是解决了表面的问题，这样的解决方案都是冶标不冶本，累个半死，也没有一个好的结果\u003c/p>\u003ch3>\u003cp>【举个例子】-反例\u003c/p>\u003c/h3>\u003cp>三个月前，仓库发现布被老鼠咬，刚开始想得是怎么抓老鼠，发现老鼠今天逮到一只，明天又又其他的来了，花了很多的时间和精力，最终还是没有能够彻底解决。\u003c/p>\u003cp>后来用了今天的四步骤，才把问题彻底解决了。怎么做？\u003c/p>\u003cp>\u003cstrong>【反例变正例】\u003c/strong>\u003c/p>\u003cp>1.确定目标：让仓库的布不再被破坏\u003c/p>\u003cp>2.找出障碍：最关键的问题是什么？怎么让老鼠在仓库消失？\u003c/p>\u003cp>3.尝试方案：刚开始把食物藏起来，没有用，后来买老鼠夹，三天后又无效。最后发现老鼠最怕的是猫。\u003c/p>\u003cp>4.执行方案：只要想办法搞一只猫来，这个问题就彻底解决了。后来仓库就养了只猫，老鼠再也不见了。\u003c/p>\u003cp>\u003cstrong>【预防异议】\u003c/strong>\u003c/p>\u003cp>可能你会说，就算这个问题解决了，还是会有其他问题发生的，你搞怎么复杂，有用吗？当然有用。精要主义处理问题不会浮于表面，要的是解决核心问题，连根拔起。另外，事情是永远处理不完的，只能是一件一件来，当你把前进路上最大的拦路虎解决了，在执行的过程中，就会变得容易多了。一切都是为了，做更少，但更好！\u003c/p>\u003ch3>\u003cp>【where】\u003c/p>\u003c/h3>\u003cp> 解决障碍四步骤，适合你用在实现目标的过程中，出现问题，遇到了困境时。如果一件事情没有目标，没有对你产生困扰，对你没有重要性，也就不需要用这个四步骤了。\u003c/p>","interaction":"\u003cp>\u003cstrong>&nbsp; I部分讲解完了，进入我们的演练环节A3\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【场景】\u003c/strong>\u003c/p>\u003cp>小丽在一家化妆品公司上班，她管理着公司的一个销售部门，这两月业绩不但没有上升，还掉了15%，老板找她谈话，她承诺三个月一定把销量提升30%。为了兑现承诺，开始想办法，分析销售数据，发现业绩拖后腿的是新调来的大学生小柯，小丽发现，只要能够把小柯的业绩稳定，业绩就可以上去了。\u003c/p>\u003cp>\u003cstrong>【R2-A3之小组讨论】\u003c/strong>\u003c/p>\u003cp>现在，请小伙伴们在小组讨论，一个扮演小丽，一个扮演小柯，小丽怎么样运用今天的解决障碍四步骤，帮助小柯找到业绩不好的最关键问题，提升业绩，并且给出解决方案。时间是5分钟\u003c/p>\u003ch3>\u003cp>【R2-A3之角色扮演】\u003c/p>\u003c/h3>\u003cp>好，时间到。\u003c/p>\u003cp>有没有哪组小伙伴愿意分享下，请上台来分享\u003c/p>\u003cp>\u003cstrong>【学习者分享】\u003c/strong>\u003c/p>\u003cp>确定目标：部门业绩提升30%\u003c/p>\u003cp>找出障碍：如何提升小柯的业绩\u003c/p>\u003cp>小丽：小柯，我们的部门业绩要提升30%，我看了一下，只要你努力一下，我们就可以达到了。\u003c/p>\u003cp>小柯：嗯，我也挺想努力的，就是不知道劲往哪里使？\u003c/p>\u003cp>小丽：那我们一起来看看困难点在哪里？\u003c/p>\u003cp>小柯：我觉得我对业务不太熟悉，对知识点不太了解。能不能有一些资料可以提供？\u003c/p>\u003cp>小丽：那我看下，我这里关于产品资料方面的，我提供给你。产品部的同事我也和\u003c/p>\u003cp> &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 你接洽下，你可以和她多学学。\u003c/p>\u003cp>小丽：一星期过去了，小柯你现在对产品熟悉点了吗？\u003c/p>\u003cp>小柯：我现在好点了，有些客户问我的问题能够回答的上来了。\u003c/p>\u003cp>小丽：反应在我们的业绩上有变化吗？\u003c/p>\u003cp>小柯：好一点，有一点提升。\u003c/p>\u003cp>小丽：你觉得这样的业绩提升够吗？\u003c/p>\u003cp>小柯：我觉得还不够，因为我发现我和客户沟通时，不知道怎么站在客户的角度去想问题。\u003c/p>\u003cp>小丽：你是说，对于客户的需求点，你在沟通时，不太会把握？\u003c/p>\u003cp>小柯：是的，我不太能够掌握。\u003c/p>\u003cp>小丽：那我找个对这方面比较熟悉的人来带带你？我有空时也来和你沟通下？\u003c/p>\u003cp>小柯：太好了，谢谢。\u003c/p>\u003cp>小丽：小柯，一个星期又过去了，你现在怎么样了？\u003c/p>\u003cp>小柯：我现在和客户沟通时比较能够抓住客户的心理了。\u003c/p>\u003cp>小丽：那现在业绩能达标了吗？你还有什么需求吗？\u003c/p>\u003cp>小柯：业绩有提升了，不过感觉还缺点火候，如果能够找一个业务比较厉害的和我一起，带着我，估计更好。\u003c/p>\u003cp>小丽：你是说，帮你找个师父来带你？\u003c/p>\u003cp>小柯：是的\u003c/p>\u003cp>小丽：那我去找王姐，你们一起搭档，王姐平常事情比较多，你帮她坐一些杂事，有重要客户沟&nbsp;通时，让王姐和你一起去谈，你也跟着多学习。\u003c/p>\u003cp>小柯：那太好了，这样我们团队的业绩一定可以提升。\u003c/p>\u003cp>拆书家：你们的最终执行方案是？\u003c/p>\u003cp>学习者：我们的最终执行方案是找个厉害的师父带着她，重要的客户帮她去谈。\u003c/p>\u003cp>【拆书家反馈】\u003c/p>\u003cp> 谢谢两位伙伴的分享。目标明确，找出了关键障碍，尝试不同的方法，也找到了最终的解决方案。谢谢两位伙伴的分享。\u003c/p>\u003ch2>\u003cp>R2-分享A2便签\u003c/p>\u003c/h2>\u003cp>刚才我们解决的是他人的问题，接下来回归我们自己 \u003c/p>\u003ch3>\u003cp>【R2分步催化一】\u003c/p>\u003c/h3>\u003cp>请小伙伴们回想下，在未来的一个月里，你会遇到哪些困惑的问题需要解决？比如孩子不肯好好吃饭，或者孩子因为玩游戏耽误学习，或者是客户所有条件都谈妥了，就是不肯付款。又或者，财务不批你的预算经费，有什么样的场景？在便签上写下关键词。时间是2分钟。\u003c/p>\u003cp>\u003cstrong>【R2分步催化二】\u003c/strong>现在，请结合上面故事的背景，运用今天学习的解决障碍四步骤，写下你的行动步骤，并在小组分享。时间是2分钟，等下我会邀请伙伴上台来分享。\u003c/p>\u003cp>温馨提醒：我知道伙伴们很有智慧，可能会有其他更好的办法，不过我们今天分享的知识点是这四个步骤，请大家用这四个步骤来规划你未来的运用。记得要有目标，时间截点，可被观测，可被衡量。\u003c/p>\u003cp>\u003cstrong>【学习者案例分享】\u003c/strong>\u003c/p>\u003cp>故事背景：和客户合作什么的都谈好了，客户就是不签单。\u003c/p>\u003cp>时间：下一周\u003c/p>\u003cp>吴蔚：（目标明确）让客户签单\u003c/p>\u003cp>吴蔚：（找出障碍）客户不肯签单\u003c/p>\u003cp>吴蔚：（尝试方案）价格方面，服务方面\u003c/p>\u003cp>吴蔚：（行动）去询问客户是不是嫌价格高了？（检查）发现价格是有问题。又问，服务上还有没有其他要求？（发现）发现价格和服务都有问题\u003c/p>\u003cp>拆书家：你发现哪个是最重要的？解决问题我们只能是一个一个来解决。\u003c/p>\u003cp>吴蔚：好的。（执行方案）我先去和客户确认好价格，等价格敲定了，再谈服务方面，一样一样&nbsp;来。\u003c/p>\u003cp>\u003cstrong>【拆书家反馈】\u003c/strong>\u003c/p>\u003cp>好，谢谢吴蔚的分享，用我们今天的解决障碍四步骤，妥妥的解决了客户不愿意签单的困扰。把热烈的掌声送给她！\u003c/p>\u003cp>\u003cstrong>【强有力的总结】\u003c/strong>\u003c/p>\u003cp>选择大于努力，通过三条普通标准和三条严格标准，找出10%的好机会，然后开始实施计划，在实施过程中，明确目标，坚定信念，当出现障碍时，找出关键问题，尝试用不同的方案去解决，找出最佳方案。你离目标就越来越近了。人生路漫漫，希望每个人都可以成为精要主义，做更少，但更好！实现自己的价值最大化！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1568960599000,"updated_at":1568961201000,"ria":true},{"id":8802,"topic":"找到当下最重要的一件事情","learn_goal":"通过现场RIA学习，学习者能够找出当下最重要的一件事","remark":"在面对多个任务，不知道如何处理，已经给自己造成困惑时，该做些什么？又如何做呢？","level":"TF2-3","duration":25,"status":30,"type":0,"chaishujia":{"username":"天一","city":"绍兴"},"club":{"name":"杭州光明顶分舵","city":"杭州"},"prologue":"【自我介绍】\r\n大家好，我是天一，天天进步，知行合一！我给自己的三个标签是，懂身心灵的房产教练/传统企业主/未来的学习促进者\r\n【学习目标】\r\n通过RIA现场学习，学习者在同一时间段，有多个事情需要处理时，能够运用重要事项四步骤”，找出当下最需要做的一件事。\r\n【分组】为了便于大家更好的学习，我们分个小组，央央老师和美女一组，思雯和永华妈妈一组，这边三个小伙伴一组。\r\n【介绍图书】\r\nF:这是一本可以改变心智模式的书。作者是 （英）格雷戈.麦吉沃恩，是个备受大众欢迎的撰稿人，也是《哈佛商业评论》受欢迎的专栏作家之一，他在斯坦福大学举办的“设计你的精要人生”的课程，价格非常昂贵，也一样备受青睐和追捧。\r\nA：这本书多次登上纽约时报畅销排行榜，和其他书相比。本书逻辑简单清晰，只需要翻下目录，和几张小插图就可以把握。书中每个点都辅助了生动，有趣，有哲理的故事，单独成篇也是足够的精彩。\r\nB1:在你的生活中，你有没有感到过心力交瘁？你有没有感觉自己忙忙碌碌，却又效率低下？你有没有觉得身边机会很多，你也很努力，可最终，你的努力和回报不成正比！夲书让你懂得如何做最少，事半功倍，实现你的最大价值！同时教会你如何做到一厘米宽，一公里深，如何成为行业的专家！\r\nB2:而通过今天的片段学习，让你能够不念过去，不畏将来，专注当下，只做当下最重要的一件事情","ratings_count":1,"texts":[{"id":12510,"quote":"\u003cp>书介绍完了，进入我们的R环节，阅读原文，请小伙伴看下手上的拆页，时间是两分钟，看完示意我一下\u003c/p>\u003cp>摘自《精要主义》P249-251页（250页是个插图，没有内容）\u003c/p>\u003cp>主题:如何找到当下最重要的一件事\u003c/p>\u003cp>最近，我在纽约向一个领导团队讲了整整一天的精要主义。我尽情享受了这一天，并自始至终感受着当下。但当我回到房间酒店的时候，我突然感到自己被拉向了四面八方。身边每一样东西都在提醒着我应该做的一切:查看电子邮件，听留言，读一本自己觉得有必要读的书，从现在开花几个星期准备一个报告，把这一天的经历触发的有意思的想法记录下来，以及其他事情。让我觉得不堪重负的，倒不仅仅是事情的数量，而是在同一时刻很多事情都争着抢着要被优先完成的这种压力，对此我再熟悉不过了。焦虑和紧张让我停了下来。我跪下来，闭上眼睛，\u003cstrong>问自己:“当下重要的是什么?\u003c/strong>沉思片刻后，我明白了，在知道当下重要的是什么之前，重要的是搞清楚“当\u003c/p>\u003cp>下重要的是什么”这个理念!\u003c/p>\u003cp>我站了起来，\u003cstrong>开始整理\u003c/strong>。我把所有散乱地堆在我身边的东西收了起来，放到该放的位置上去，免得它们分散我的注意力，也免得我每次经过时，它们迫使我按它们的吩附去做。\u003cstrong>我关掉了手机。\u003c/strong>别人没办法给我发短信，这让我如释重负。我打开笔记本记录下这一天，这让我收起了心。我用铅笔给脑海中出现的所有事情\u003cstrong>列了一个清单\u003c/strong>。为了明确任务，我问自己:“你要做些什么才能平静地睡去?”我决定，第一重要的事是跟妻子和孩子们联系。接下来要做的就是能让次日早上的头几个小时尽可能轻松一些的事情:安排好叫醒服务和房内早餐，把幻灯片拷到电脑上，熨好村衣。我划掉了当时并不重要的事情。\u003c/p>","explains":"\u003cp>看到小伙伴们都已经看完了片断，进入我们的I环节，\u003cstrong>重述原文\u003c/strong>\u003c/p>\u003cp>在讲解这个片段之前，先给大家看一张图。解释一下什么是精要主义，什么是非精要主义。\u003c/p>\u003cp>精要主义把所有的时间和精力放在一件事情上，聚焦。\u003c/p>\u003cp>非精要主义把有限的精力和时间分散在不同的事情上。\u003c/p>\u003cp>\u003cstrong>What\u003c/strong>\u003c/p>\u003cp>本片段讲述的是精要主义在同一时间段是如何做到，只专注做一件重要的事情。\u003c/p>\u003cp>\u003cstrong>why\u003c/strong>\u003c/p>\u003cp>为什么要专注？众所皆知，如果一个人做事情很专注，相对做起来比较容易，效率也会很高。相反，你做事情一心二用，心不在焉，效率就会非常的低下。\u003c/p>\u003cp>在专注这件事上，俩者的区别有哪些？大家可以看一下我手上的这张表格\u003c/p>\u003cp>精要主义对于你又有什么样的意义？精要主义能够让你把有限的时间和精力投入到你最重要的事情上，你做得很少，却能够让你实现价值最大化！\u003c/p>\u003cp>如何做到，像精要主义一样，在同一时间段只专注做一件重要的事情来提高工作效率？原文表达的不够清晰，我现在对它进行\u003cstrong>细化\u003c/strong>\u003c/p>\u003cp>\u003cstrong>1.\u003c/strong>\u003cstrong>停下来，深呼吸\u003c/strong>\u003cstrong>：\u003c/strong>\u003c/p>\u003cp>先停下手头的所有事情，通过一次或多次深呼吸，让自己静下来，建议可以先屏蔽掉一些干扰，比如把手机调成静音，把手机放远一些。\u003c/p>\u003cp>\u003cstrong>2.问自己:\u003c/strong>\u003c/p>\u003cp>当下最重要的是什么？还是想不出来，好乱，怎么办？没有关系，我们有第三步\u003c/p>\u003cp>\u003cstrong>3.列清单:\u003c/strong>\u003c/p>\u003cp>把你当下想做的事情全部写下来。我列出来还是找不到怎么办？进入第四步\u003c/p>\u003cp>\u003cstrong>4.做选择\u003c/strong>\u003c/p>\u003cp>怎么选？\u003c/p>\u003cp>问：哪些事情可以等等再做？把这些先全部划去，只留下一件当下要做的重要之事！\u003c/p>\u003cp>为了便于大家更好的理解，举个例子\u003c/p>\u003cp>最近一直在拆书，前天下午四点，因为预备表还没有改好，发现自己很焦虑，同时脑子里开始想着，要给儿子对试卷答案，要练瑜伽，要写每天的输出作业，五点前还有个穿衣搭配的社群要打卡，又想着做晚饭，所有的事情都向我拢来，感觉快炸了，当时，我发现我什么也做不了！\u003c/p>\u003cp>怎么办？我想到了精要主义如何找到当下最重要的一件事情的步骤，拿来即用\u003c/p>\u003cp>1.深呼吸：先让自己静下来，关注自己的念头！同时我把手机放得离我远点，不再让一条一条的微信干扰我\u003c/p>\u003cp>2.问自己:我问自己，此刻当下最重要的是什么？我发现我没法确定\u003c/p>\u003cp>3.列清单:我把脑子里想的要做的事全部列了出来。改预备表，给儿子对答案，练瑜珈，写故事课作业，社群打卡，做晚饭.\u003c/p>\u003cp>4做选择：:我问自己，哪些事情可以暂缓再做？选出来的就划掉，最后，只留下一件重要的事，改预备表半小时。\u003c/p>\u003cp>我发现，当我确定这件事情以后，我把手机设置了25分钟的番茄钟，在那半个小时里，我专心致志，不再焦虑。\u003c/p>\u003cp>\u003cstrong>预防异议\u003c/strong>\u003c/p>\u003cp>可能你会说，我同一时间段同时做两件事情，很轻松，比如边吃饭边看手机，边做家务边听微课，边开车边打电话，我为什么要这么麻烦，还要这么多的步骤，简直是浪费时间呀！\u003c/p>\u003cp>哪有提高效率？\u003c/p>\u003cp>我想说，亲爱滴，你们说的很对，这很正常，也是生活中常有的事情。这里我们分享的是，在同一时间段\u003cstrong>专注\u003c/strong>做一件\u003cstrong>重要\u003c/strong>事情，因为人是不可能在同一时间段\u003cstrong>同时专注\u003c/strong>做一件事情的。这正是精要主义和非精要主义的区别，做更少，但更好！因此，这很重要！\u003c/p>\u003cp>\u003cstrong>where\u003c/strong>\u003c/p>\u003cp>当你面对多个事情需要处理，很焦虑，同时又想让自己做事能专注，高效时，用上面的四步骤，找出你当下最重要的一件事情，非常的适用。\u003c/p>","interaction":"\u003cp>光学不练假把式，现在进入我们的\u003cstrong>A3\u003c/strong>，\u003cstrong>演练环节\u003c/strong>\u003c/p>\u003cp>现在我给大家设置一个场景，场景如下。\u003c/p>\u003cp>小王刚刚大学毕业，进入到一家公司做销售，发现自己要学的东西特别的多。需要熟悉公司产品的各种特性，价格。公司的各种销售政策，需要梳理公司给的意向客户的名单。每周一会有相关考核。\u003c/p>\u003cp>今天是周六，离星期一考核还有一两天的时间，快下班的时候，女朋友打电话要小王下班后陪着去看电影。小王答应了。放下电话的时候发现自己开始心神不宁，感觉好多事情没做完，一想到周一的考核，更焦虑了！\u003c/p>\u003cp>带队组长李姐走了过来，发现了小王的心神不宁，现在，小组开始角色扮演，一个扮演李姐，一个扮演小王，李姐如何通过今天的找出重要事项四步骤，帮助小王找到他当下最重要的一件事情！\u003c/p>\u003cp>现在，开始，小组讨论，等一下会请一组小伙伴站起来分享！看到小伙伴们都已经分享完了，现在有请一组小伙伴上台来分享。\u003c/p>\u003cp>李姐：小王，怎么了？都要下班了，看你好像有点心神不宁？\u003c/p>\u003cp>小王：我觉得事情挺多的，很烦，不知道做哪件？\u003c/p>\u003cp>李姐：我也经常这样，我教你一招好不好？\u003c/p>\u003cp>小王：好的。\u003c/p>\u003cp>李姐：\u003cstrong>（深呼吸\u003c/strong>）来，你先跟着我做深呼吸，做三次\u003c/p>\u003cp>小王：好，三次做完了。\u003c/p>\u003cp>李姐：（\u003cstrong>问自己\u003c/strong>）你问下自己，你现在什么是最重要的？\u003c/p>\u003cp>小王：我感觉都挺重要的，理不清头绪\u003c/p>\u003cp>李姐：\u003cstrong>（列清单\u003c/strong>）都挺重要？那这样，你拿一张纸，一支笔，先把你现在想做的全部写下来\u003c/p>\u003cp>小王：我写好了，事情挺多的，我感觉公司产品型号价格要理，因为是新公司，公司的政策要熟悉，客户的名单也挺多，我也需要去了解下。晚上还要陪女朋友看电影，我更烦了。\u003c/p>\u003cp>李姐：这么多的事情，哪些可以等等再做的?\u003c/p>\u003cp>小王：\u003cstrong>（做选择）\u003c/strong>资料是下星期一交，下周一再考核，我现在暂时不需要去弄。然后，女朋友已经是好久都没有陪她了，我想想工作永远都做不完，我想着今天晚上要陪我女朋友看电影，要不然，她要和我分手了。今天就先去陪女朋友看个电影吧！\u003c/p>\u003cp>李姐：好，那你现在心定下来了吗？\u003c/p>\u003cp>小王：是的，谢谢。我现在就去找女朋友，看电影去。\u003c/p>\u003cp>谢谢两位小伙伴的分享，非常的精彩。李姐也帮助小王找到了当下最重要的一件事。希望小伙伴们能够把今天的所学用于生活和工作中。我今天的拆书暂告一段落，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1567943333000,"updated_at":1567943333000,"ria":true},{"id":8666,"topic":"如何活在当下","learn_goal":"学习者能够运用重要事项四步骤，找出当下最重要的一件事","remark":"在你的生活中，你有没有感到过心力交瘁？你有没有感觉自己忙忙碌碌，却又效率低下？你有没有觉得身边机会很多，你也很努力，可最终，你的努力和回报不成正比！夲书让你懂得如何做最少，事半功倍，实现你的最大价值！同时教会你如何做到一厘米宽，一公里深，如何成为行业的专家","level":"TF2-3","duration":30,"status":29,"type":0,"chaishujia":{"username":"天一","city":"绍兴"},"club":{"name":"杭州光明顶分舵","city":"杭州"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;【自我介绍】\r\n大家好，我是天一，天天进步，知行合一！我给自己的三个标签是，懂身心灵的房产教练/传统企业主/未来的学习促进者\r\n【学习目标】\r\n通过RIA现场学习，学习者在同一时间段，有多个事情需要处理时，能够运用重要事项四步骤”，找出当下最需要做的一件事。\r\n【分组】为了便于大家更好的学习，我们分个小组，央央老师和美女一组，思雯和永华妈妈一组，这边三个小伙伴一组。\r\n【介绍图书】\r\nF:这是一本可以改变心智模式的书。作者是 （英）格雷戈.麦吉沃恩，是个备受大众欢迎的撰稿人，也是《哈佛商业评论》受欢迎的专栏作家之一，他在斯坦福大学举办的“设计你的精要人生”的课程，价格非常昂贵，也一样备受青睐和追捧。\r\nA：这本书多次登上纽约时报畅销排行榜，和其他书相比。本书逻辑简单清晰，只需要翻下目录，和几张小插图就可以把握。书中每个点都辅助了生动，有趣，有哲理的故事，单独成篇也是足够的精彩。\r\nB1:在你的生活中，你有没有感到过心力交瘁？你有没有感觉自己忙忙碌碌，却又效率低下？你有没有觉得身边机会很多，你也很努力，可最终，你的努力和回报不成正比！夲书让你懂得如何做最少，事半功倍，实现你的最大价值！同时教会你如何做到一厘米宽，一公里深，如何成为行业的专家！\r\nB2:而通过今天的片段学习，让你能够不念过去，不畏将来，专注当下，只做当下最重要的一件事情\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","ratings_count":1,"texts":[{"id":12353,"quote":"\u003cp>\u003cp>摘自《精要主义》P249-251页（250页是个插图，没有内容）\u003c/p>\u003cp>主题:如何找到当下最重要的一件事\u003c/p>\u003cp>最近，我在纽约向一个领导团队讲了整整一天的精要主义。我尽情享受了这一天，并自始至终感受着当下。但当我回到房间酒店的时候，我突然感到自己被拉向了四面八方。身边每一样东西都在提醒着我应该做的一切:查看电子邮件，听留言，读一本自己觉得有必要读的书，从现在开花几个星期准备一个报告，把这一天的经历触发的有意思的想法记录下来，以及其他事情。让我觉得不堪重负的，倒不仅仅是事情的数量，而是在同一时刻很多事情都争着抢着要被优先完成的这种压力，对此我再熟悉不过了。焦虑和紧张让我停了下来。我跪下来，闭上眼睛，\u003cstrong>问自己:“当下重要的是什么?\u003c/strong>沉思片刻后，我明白了，在知道当下重要的是什么之前，重要的是搞清楚“当\u003c/p>\u003cp>下重要的是什么”这个理念!\u003c/p>\u003cp>我站了起来，\u003cstrong>开始整理\u003c/strong>。我把所有散乱地堆在我身边的东西收了起来，放到该放的位置上去，免得它们分散我的注意力，也免得我每次经过时，它们迫使我按它们的吩附去做。\u003cstrong>我关掉了手机。\u003c/strong>别人没办法给我发短信，这让我如释重负。我打开笔记本记录下这一天，这让我收起了心。我用铅笔给脑海中出现的所有事情\u003cstrong>列了一个清单\u003c/strong>。为了明确任务，我问自己:“你要做些什么才能平静地睡去?”我决定，第一重要的事是跟妻子和孩子们联系。接下来要做的就是能让次日早上的头几个小时尽可能轻松一些的事情:安排好叫醒服务和房内早餐，把幻灯片拷到电脑上，熨好村衣。我划掉了当时并不重要的事情。\u003c/p>\u003c/p>","explains":"\u003cp>\u003cp>看到小伙伴们都已经看完了片断，进入我们的I环节，\u003cstrong>重述原文\u003c/strong>\u003c/p>\u003cp>在讲解这个片段之前，先给大家看一张图。解释一下什么是精要主义，什么是非精要主义。\u003c/p>\r\n &nbsp; &nbsp; &nbsp;\u003cp>精要主义把所有的时间和精力放在一件事情上，聚焦。\u003c/p>\u003cp>非精要主义把有限的精力和时间分散在不同的事情上。\u003c/p>\u003cp>\u003cstrong>What\u003c/strong>\u003c/p>\u003cp>本片段讲述的是精要主义在同一时间段是如何做到，只专注做一件重要的事情。\u003c/p>\u003cp>\u003cstrong>why\u003c/strong>\u003c/p>\u003cp>为什么要专注？众所皆知，如果一个人做事情很专注，相对做起来比较容易，效率也会很高。相反，你做事情一心二用，心不在焉，效率就会非常的低下。\u003c/p>\u003cp>在专注这件事上，俩者的区别有哪些？大家可以看一下我手上的这张表格\u003c/p>\u003cp>精要主义对于你又有什么样的意义？精要主义能够让你把有限的时间和精力投入到你最重要的事情上，你做得很少，却能够让你实现价值最大化！\u003c/p>\u003cp>如何做到，像精要主义一样，在同一时间段只专注做一件重要的事情来提高工作效率？原文表达的不够清晰，我现在对它进行\u003cstrong>细化\u003c/strong>\u003c/p>\u003cp>\u003cstrong>1.\u003c/strong>\u003cstrong>停下来，\u003c/strong>\u003cstrong>深呼吸\u003c/strong>\u003cstrong>：\u003c/strong>\u003c/p>\u003cp>先停下手头的所有事情，通过一次或多次深呼吸，让自己静下来，建议可以先屏蔽掉一些干扰，比如把手机调成静音，把手机放远一些。\u003c/p>\u003cp>\u003cstrong>2.问自己:\u003c/strong>\u003c/p>\u003cp>当下最重要的是什么？还是想不出来，好乱，怎么办？没有关系，我们有第三步\u003c/p>\u003cp>\u003cstrong>3.列清单:\u003c/strong>\u003c/p>\u003cp>把你当下想做的事情全部写下来。我列出来还是找不到怎么办？进入第四步\u003c/p>\u003cp>\u003cstrong>4.\u003c/strong>\u003cstrong>做选择\u003c/strong>\u003c/p>\u003cp>怎么选？\u003c/p>\u003cp>问：哪些事情可以等等再做？把这些先全部划去，只留下一件当下要做的重要之事！\u003c/p>\u003cp>为了便于大家更好的理解，举个例子\u003c/p>\u003cp>最近一直在拆书，前天下午四点，因为预备表还没有改好，发现自己很焦虑，同时脑子里开始想着，要给儿子对试卷答案，要练瑜伽，要写每天的输出作业，五点前还有个穿衣搭配的社群要打卡，又想着做晚饭，所有的事情都向我拢来，感觉快炸了，当时，我发现我什么也做不了！\u003c/p>\u003cp>怎么办？我想到了精要主义如何找到当下最重要的一件事情的步骤，拿来即用\u003c/p>\u003cp>1.深呼吸：先让自己静下来，关注自己的念头！同时我把手机放得离我远点，不再让一条一条的微信干扰我\u003c/p>\u003cp>2.问自己:我问自己，此刻当下最重要的是什么？我发现我没法确定\u003c/p>\u003cp>3.列清单:我把脑子里想的要做的事全部列了出来。改预备表，给儿子对答案，练瑜珈，写故事课作业，社群打卡，做晚饭.\u003c/p>\u003cp>4做选择：:我问自己，哪些事情可以暂缓再做？选出来的就划掉，最后，只留下一件重要的事，改预备表半小时。\u003c/p>\u003cp>我发现，当我确定这件事情以后，我把手机设置了25分钟的番茄钟，在那半个小时里，我专心致志，不再焦虑。\u003c/p>\u003cp>\u003cstrong>预防异议\u003c/strong>\u003c/p>\u003cp>可能你会说，我同一时间段同时做两件事情，很轻松，比如边吃饭边看手机，边做家务边听微课，边开车边打电话，我为什么要这么麻烦，还要这么多的步骤，简直是浪费时间呀！\u003c/p>\u003cp>哪有提高效率？\u003c/p>\u003cp>我想说，亲爱滴，你们说的很对，这很正常，也是生活中常有的事情。但这里我们分享的是，在同一时间段\u003cstrong>专注\u003c/strong>做一件\u003cstrong>重要\u003c/strong>事情，因为人是不可能在同一时间段\u003cstrong>同时专注\u003c/strong>做两件事情的。这正是精要主义和非精要主义的区别，做更少，但更好！因此，这很重要！\u003c/p>\u003cp>\u003cstrong>where\u003c/strong>\u003c/p>\u003cp>当你面对多个事情需要处理，很焦虑，同时又想让自己做事能专注，高效时，用上面的四步骤，找出你当下最重要的一件事情，非常的适用。\u003c/p>\u003c/p>","interaction":"\u003cp>\u003cp>光学不练假把式，现在进入我们的\u003cstrong>A3\u003c/strong>，\u003cstrong>演练环节\u003c/strong>\u003c/p>\u003cp>现在我给大家设置一个场景，场景如下。\u003c/p>\u003cp>小王刚刚大学毕业，进入到一家公司做销售，发现自己要学的东西特别的多。需要熟悉公司产品的各种特性，价格。公司的各种销售政策，需要梳理公司给的意向客户的名单。每周一会有相关考核。\u003c/p>\u003cp>今天是周六，离星期一考核还有一两天的时间，快下班的时候，女朋友打电话要小王下班后陪着去看电影。小王答应了。放下电话的时候发现自己开始心神不宁，感觉好多事情没做完，一想到周一的考核，更焦虑了！\u003c/p>\u003cp>带队组长李姐走了过来，发现了小王的心神不宁，现在，小组开始角色扮演，一个扮演李姐，一个扮演小王，李姐如何通过今天的找出重要事项四步骤，帮助小王找到他当下最重要的一件事情！\u003c/p>\u003cp>现在，开始，小组讨论，等一下会请一组小伙伴站起来分享！看到小伙伴们都已经分享完了，现在有请一组小伙伴上台来分享。\u003c/p>\u003cp>李姐：小王，怎么了？都下班了，怎么还不走？\u003c/p>\u003cp>小王：我觉得事情挺多的，很烦，不知道做哪件？\u003c/p>\u003cp>李姐：我也经常这样，我教你一招好不好？\u003c/p>\u003cp>小王：好的。\u003c/p>\u003cp>李姐：\u003cstrong>（深呼吸\u003c/strong>）来，你先跟着我做深呼吸，做三次\u003c/p>\u003cp>小王：好，三次做完了。\u003c/p>\u003cp>李姐：（\u003cstrong>问自己\u003c/strong>）你问下自己，你现在什么是最重要的？\u003c/p>\u003cp>小王：我感觉都挺重要的，理不清头绪\u003c/p>\u003cp>李姐：\u003cstrong>（列清单\u003c/strong>）都挺重要？那这样，你拿一张纸，一支笔，先把你现在想做的全部写下来\u003c/p>\u003cp>小王：我写好了，事情挺多的，我感觉公司产品型号价格要记，因为是新公司，公司的政策要熟悉，客户的名单也挺多，我也需要去了解分类。晚上还要陪女朋友看电影，我更烦了。\u003c/p>\u003cp>李姐：这么多的事情，哪些可以等等再做的?\u003c/p>\u003cp>小王：\u003cstrong>（做选择）\u003c/strong>资料是下星期一交，下周一再考核，我现在暂时不需要去弄。然后，女朋友已经好久都没有陪她了，想想工作永远都做不完，我想着今天晚上要陪我女朋友看电影，要不然，她要和我分手了。今天就先去陪女朋友看个电影吧！\u003c/p>\u003cp>李姐：好，那你现在心定下来了吗？\u003c/p>\u003cp>小王：是的，谢谢。我现在就去找女朋友，看电影去。\u003c/p>\u003cp>感谢两位小伙伴的分享，非常的精彩。我们把热烈的掌声送给他们。今天我们分享的是精要主义如何在同一时间段，怎么才能专注做一件事情。四步骤，1.停下来，深呼吸 2.问自己 &nbsp;3.列清单 4.做选择。希望小伙伴能够在生活和工作中用起来！今天我的拆书暂告一段落，谢谢大家！\u003c/p>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1566276112000,"updated_at":1567423852000,"ria":true},{"id":8448,"topic":"如何运用“小胜法”更好地实现目标","learn_goal":"通过列举进步行为、转换关注点、奖励进步制定实现目标的规则","remark":"2019年伊始，你有没有为自己工作和生活设立年度目标呢？为了完成这些目标，有人绞尽脑汁想要一步到位，却发现自己绕进了瞎忙的怪圈；也有人还没开始就发现\"太难了，坚持不下去了\"结果15年的flag原封不动的留到了今年。究竟怎么才能更好的坚持和实现目标呢？本周五，让我们一起来学习吧！","level":"TF2-3","duration":25,"status":30,"type":0,"chaishujia":{"username":"Josie-琼绚","city":"深圳"},"club":{"name":"深圳智荟分舵","city":"深圳"},"prologue":"自我介绍：大家好，我是今天的拆书家Josie琼绚，三个标签介绍下我自己，标签一、互联网小说运营；标签二、读书学习者；标签三，正在升级打怪的拆书家。为方便接下来的讨论和交流，先给大家分下组，2人一组\r\n我今天跟大家分享的拆页来自《精要主义》\r\nF 特征（核心是“书”，用于满足好奇心）\r\n这本书的作者是格雷戈·麦吉沃恩，他是精要主义的提出者、倡导者和领导者。这本书主要介绍了精要主义者的思维模式，并将这种模式转化为一种系统化的程序，帮助我们专注于重要的少数事情，实现更有意义、有目的的人生。\r\nA 优势（重点是“比较”，用于建立安全感）\r\n跟其他提倡精简的书籍比如说《极简主义》相比，这本书提出了更加彻底的精要主义思维：如果答案不是一个确定的YES，就是一个肯定的NO。从探索、排除、执行三个方面提出实用的方法和理论引导我们如何做得更少，但更好。\r\nB 利益（强调的是“学习者”的利益，用于引发兴趣）\r\nB1：如果你觉得自己总是忙忙碌碌却效率低下或者说自己的时间总是被别人的安排打乱等，读一读这本书可能会对你重新掌握自己的生活有所启发。\r\nB2：那我们今天学习的主题是用鼓励小胜的方法来助力实现目标。希望通过25分钟的现场学习，大家能够学会运用鼓励小胜的三步法：制定可行性进步列表+转换关注点+直观奖励进步来制定出帮助实现目标的规则。\r\n学习目标：通过今天的现场学习，学习者学会运用鼓励小胜的三步法：制定可行性进步列表+转换关注点+直观奖励进步来制定出帮助实现目标的规则","ratings_count":2,"texts":[{"id":12098,"quote":"\u003cp>\u003cstrong>鼓励小胜助力目标实现\u003c/strong>\u003c/p>\u003cp>多年来，里土满警察局就是默守着这些在所有地方的警务管理系统中核心的、长期存在的成规，同时也承受着典型的后果：高达65%的累犯率和呈螺旋式上升的青少年犯罪率。这种情况始终存在着，直到沃德.克拉彭( Ward Clapham)，一个年轻的、具有前瞻思维的新长官出现并挑战它们。他提出了质疑:为什么我们所有的警务工作都必须如此的被动、消极并且滞后于现实?如果我们不把精力仅仅集中在犯罪行为实施之后的犯人抓捕和进行更严酷的处罚上，而是用大量的资源和精力，将犯罪行为扼杀于其发生之前，那将产生什么样的结果?引用-句前英国首相托尼.布莱尔(Towy Blair) 的话来说，如果我们不仅对罪行强硬，而且对犯罪的原因也持强硬态度，那会如何?\u003c/p>\u003cp>就在这些问题之中，孕育出了\u003cstrong>“发放肯定票”\u003c/strong>的新颖想法。运用这种方法，警务人员不是专注于抓捕实施犯罪行为的年轻人，而是\u003cstrong>寻找做好事的年轻人\u003c/strong>，这些好事可以小到把垃圾丢到垃圾桶里而不随地乱扔，骑车时佩戴头盔，在指定地点滑滑板，或者按时到校等。通过给这些年青人发肯定票来表扬这些积极行为。这种票当然不像违章停车罚单那样是用来处罚的，而是可以换成些小小的\u003cstrong>奖励\u003c/strong>，比如免费观看电影或免费参加当地青少年中心的活动，这些健康有益的活动同时也具有防止年轻人在街上无所事事从而滋生事端的积极效果。\u003c/p>\u003cp>那么，里土满的这种非常规的方法对重新规划警务工作的作用如何?结果证明，效果好得令人惊讶。虽然没有产生立竿见影的效果，但是他们把这种方法当做长期战略来实施，十年以后，肯定票制度把累犯率从60%降到了8%。\u003c/p>","explains":"\u003cp>\u003cstrong>&nbsp; &nbsp; &nbsp; 不那么做的坏处1：\u003c/strong>\u003c/p>\u003cp>【引入+一般人怎么做】好的，看到很多小伙伴已经看完了。大家有没有在微信上见过一群人，他们的头像叫：不瘦十斤不换头像！当我们定了一个目标后，我们需要制定配套的规则来保证目标顺利实现。但是很多人会习惯于制定惩罚规则来强制自己或他人完成某些目标。\u003c/p>\u003cp>【个人案例】我年前参加了一个21天写作训练营，为了让大家保持每天写作的习惯，圈主制定的规则是每个人每天都要写一篇作文打卡，没有完成的就要在群里发红包。为了不被扣钱，很多参与的小伙伴即便写不出来也东拼西凑或者拿以前的文章凑数，最后结束的时候很多人都说没有实现最初提高写作能力的目标。\u003c/p>\u003cp>【这样做的后果】这种惩罚规则会让人产生很多内心的纠结、逃避和自我怀疑。事实上，我们也很少会见到说了不瘦十斤不换头像的人最后真的瘦了十斤的。\u003c/p>\u003cp>当我们想推动实现一个目标时，制定鼓励小胜的规则远比惩罚来的有效。\u003cstrong>（what)\u003c/strong>什么是鼓励小胜呢？，顾名思义就是指鼓励我们在实现目标过程中的每个小进步。惩罚的规则会让你做到，但不能保证做好，甚至可能会反弹，而鼓励小胜可以帮助我们实现良性的坚持，让我们真正的做好。具体到行动上主要包含三个步骤\u003cstrong>（HOW）\u003c/strong>：\u003c/p>\u003cp>1、\u003cstrong>制定目标的可行性进步列表：\u003c/strong>我们要先找出：对于我们努力想要完成的目标，有用而且有价值的每一个小进步是什么？这个过程需要我们对目标进行分解、排序，然后执行。\u003c/p>\u003cp>\u003cstrong>2、转变关注点：\u003c/strong>从否定和惩罚没有完成转变为肯定和鼓励已经实现的进步和人，关注实现目标过程中的每一个进步；\u003c/p>\u003cp>\u003cstrong>3、直观的奖励进步：\u003c/strong>奖励的设置可以帮助我们强化成功的行为，产生更积极的力量。根据进步的大小，我们可以制定不一样的奖励力度，比如看电影，放松或者参加其他活动等。\u003c/p>\u003cp>\u003cstrong>&nbsp; &nbsp; 不那么做的坏处2-转为正例：\u003c/strong>\u003c/p>\u003cp>&nbsp; 比如我前面提到的写作打卡活动，如果用鼓励小胜的方法，我可以这样来做：\u003c/p>\u003col>\u003cli>\u003cp>首先第一步，列出可行性进步列表，罗列对于写作训练营而言的重要进步，比如说完成作业、社区互动、听完每日音频、给优秀作业点评、输出笔记等，在按时间和重要性排序找到第一个可行性操作：听音频——输出笔记——社区互动——点评作业——完成作业；\u003c/p>\u003c/li>\u003cli>\u003cp>第二步我们需要转变关注点，从关注惩罚没有完成写作的人转为关注已经完成前面罗列的小进步的学员；\u003c/p>\u003c/li>\u003cli>\u003cp>第三步：直观奖励进步，根据进步的大小给予不同的奖励，比如完成听音频、社区互动等可以奖励积分或者学习币，坚持完成XX天作业打卡奖励返现或者作品推荐机会等等；\u003c/p>\u003c/li>\u003cli>\u003cp>\u003cstrong>预防异议&amp;适用边界：\u003c/strong>\u003c/p>\u003c/li>\u003c/ol>\u003cp>&nbsp; （预防异议）通过这种方式可以营造良好的学习氛围，帮助学员真正达到提高写作能力的目标。当然，这种模式并不是一日见效的,需要一段时间的坚持才能看到效果。（适用边界）这里所说的方法不仅可以用于推动团队目标实现，也同样适用于个人目标的实现。\u003c/p>","interaction":"\u003cp>为了让大家更好的巩固应用这个三步法，我今天准备了一个现场演练的小互动，场景是这样子的（大家可以看拆页背面）：\u003c/p>\u003cp>学习者现场演练：\u003c/p>\u003cp>角色：小真、小香\u003c/p>\u003cp>新年伊始，小真部门领导为了鼓励大家培养阅读习惯，提出在部门内举行“全民阅读”活动，每个人要在半年内读完10本书并输出读书笔记分享给同部门的小伙伴。领导把这个任务交给小真了，要求他制定出合理的活动规则来帮助实现目标。小真很为这件事烦恼，小香作为小真的好朋友，又刚刚学完鼓励小胜的三步法，请大家按照刚刚分好的小组，2人一组分角色扮演小真和小香，小真主要说自己的烦恼和担心，小香则要用今天的知识来帮助小真制定这个规则。给大家8分钟时间讨论，我们等下请一个小组来现场扮演一下。\u003c/p>\u003cp>……好的，有小组想现场演练一下吗？好的，我们邀请一下我们的“真香组合”\u003c/p>\u003cp>学习者A：小香啊，我们公司领导为了让我们文化氛围更好一些鼓励我们读书，还定了个目标，说半年内要读10本书。还把KPI加我这了，我不知道怎么去督促大家读书啊。\u003c/p>\u003cp>学习者B：我昨天学了一个办法，有点类似于分步正向激励的方法，你可以用这个方法试下\u003c/p>\u003cp>学习者A：怎么说？\u003c/p>\u003cp>学习者B：你们是180天要读10本书嘛，摊下来就是18天一本书，你可以和公司的同事一起列个更详细的计划，比如每天读20页书，9天读完半本书、15天读完1本书、3个月读完5本书试下这样子，也不要一直盯着没有读完的人，可以通过给达标小伙伴奖励的方式吸引他们，比较不容易引起逆反心理。\u003c/p>\u003cp>学习者A：你的意思是说每次达标就给他们奖励吗？我觉得也可以哦，我可以拉个读书微信群，第一次读完半本书的小伙伴，给他们一点奖励，读完1本书、5本书、10本书都给不同的奖励。\u003c/p>\u003cp>学习者B：没错啊，你说的这个方法就很适用啊，半年读10本书你们一定没有问题的！\u003c/p>\u003cp>学习者A：明白了，谢谢你啊，我马上回去试试。\u003c/p>\u003cp>好的，非常感谢莫念和张聪！在他们刚刚的角色扮演中，他们把半年读10本书这个任务进行了分解，每天20页，9天读完半本书等等，跟着又引导从督促没有看完的人变成奖励已经达成目标的同事，最后也提到根据任务强度给予不同的奖励，非常棒！\u003c/p>\u003cp>那我们今天的学习已经接近尾声了，今天我们学习了鼓励小胜三步法：制定可行性进步列表+转换关注点+直观奖励进步来制定出帮助实现目标的规则。新年伊始，希望大家都能制定出适合自己2019年目标实现的规则，我的分享到此结束，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1563606910000,"updated_at":1563606910000,"ria":true},{"id":8022,"topic":"三步法扫除“最慢行进者”，快速达成目标","learn_goal":"三步法扫除“最慢行进者”，快速达成目标","remark":"","level":"TF2-2","duration":20,"status":30,"type":0,"chaishujia":{"username":"佐江","city":"重庆市"},"club":{"name":"重庆山城分舵","city":"重庆市"},"prologue":"【学习目标】在跟随我完成本次RIA现场学习后，学习者能够在遇到需要发挥创造力去解决的棘手问题时，使用“扫除最慢行进者”的方法，找出“最慢行进者”，制定方案，解决问题，达成目标。\r\n自我介绍：大家好，我是佐江，目前是一名自由投资人，主要从事区块链投资、房地产投资和个人1对1投资辅导等工作。我今天要给大家拆解的片段来自《精要主义》。\r\n【F】这本《精要主义》的作者是格雷戈•麦吉沃恩，他被誉为21世纪的史蒂芬•柯维。这是一本时间管理类书籍，用“探索最重要的事”“排除不重要的事”“专注最重要的事”三个步骤，教会我们过“更少，但更好”精要人生。\r\n【A】 这本书长期占据美国亚马逊时间管理类图书第一名，是《华尔街日报》畅销书、《纽约时报》畅销书。股神巴菲特、硅谷创投教父彼得•蒂尔都推崇这本书。与其他时间管理类书籍相比，它专注于讲解如何选择、执行真正重要的事情，让你四两拨千斤，过上精要的人生。并且，书中的方法通俗易通，还有大量真实案例，学了马上就能使用。\r\n【B】 那么这本书对你有什么用呢？\r\n你是否总是忙忙碌碌却效率低下？这本书可以教你“做得更少，收效更高”的实用管理方法；\r\n你是否发现自己只擅长做琐碎小事？这本书可以教你精选出最重要事情的方法；\r\n你是否在面对棘手问题时，常常头大，抓不住重点？这本书可以教你找到问题的瓶颈（也就是“最慢行进者”），轻松搞定棘手问题。","ratings_count":1,"texts":[{"id":11603,"quote":"\u003cp>我今天给大家拆解的片段是三步扫除“最慢行进者”。【\u003cstrong>学习目标\u003c/strong>】在跟随我完成本次RIA现场学习后，你们能够在遇到需要发挥创造力去解决的棘手问题时，使用“扫除最慢行进者”的方法，找出“最慢行进者”，制定方案，解决问题，达成目标。下面请大家阅读片段，时间两分钟，读完请举手示意。谢谢！\u003c/p>\u003cp>片段：\u003c/p>\u003cp>\u003cstrong>三步扫除“最慢行进者”\u003c/strong>\u003c/p>\u003cp>亚里士多德谈到过三种形式的工作,但在现代社会中,我们倾向于只强调两种。第一种是理论性工作,其终极目标是探求真理;第二种是实践性工作,其目的是行动。但还有第三种:创制性工作(Poietical Work).哲学家马丁·海德格尔(Martin Heidegger)将创制描述为“展现”(Bringingforth)。这第三种类型的工作就是精要执行方式。\u003c/p>\u003cp>人们很少花时间认真考虑什么样的努力会产生成效,什么样的不会。但就算我们认真考虑了,也很容易认为执行意味着加法而不是减法。如果我们想要出售更多的产品,那么我们会增加销售人员。如果我们想要生产更多的产品,那么我们就会扩大生产。这种方法可以找到清晰的证据支持。然而,要改善效果,还有其他思路可循。\u003cstrong>精要主义者不关注需要增加哪些精力和资源\u003c/strong>\u003cstrong>,\u003c/strong>\u003cstrong>而是关注哪些限制和障碍需要连根拔起。\u003c/strong>那么,他们是怎么做的呢?\u003c/p>\u003cp>\u003cstrong>1.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; \u003c/strong>\u003cstrong>弄清核心目标\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>只有弄清了要达到的结果是什么,我们才能知道应该扫除的障碍是什么。如果不知道自己真正想要实现什么,所有的改变都是武断妄为。因此,不如问问自己:“如何知道自己已经成功了?”在本章,让我们假定你的目标是,在本周四下午2点之前,准备好一份15页的报告草案,并用电子邮件发给客户。注意:这结果非常精确,一点儿都不含糊。\u003c/p>\u003cp>\u003cstrong>2.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; \u003c/strong>\u003cstrong>锁定障碍\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>不要仓促上马,三思而后行。问问自己:“在我完成任务的道路上有哪些障碍?”“是什么阻碍着我完成任务?&quot;把这些障碍列一个清单。它们可能包括:缺乏必要的信息、精力不足 、追求完美。 “哪一个障碍扫除之后,其余的障碍会立刻消失?”根据这个问题,来给所有的障碍排列优先顺序。\u003c/p>\u003cp>在锁定你的“最慢行进者”时,需要记住的关键一点是:即便是一些&quot;有成效的”事情,比如为了获取信息而进行研究或者给别人发电子邮件,或是修改报告以求第一稿就达到完美,这些都可能是障碍。记住,要达成的目标是完成报告的草案。 任何延缓此目标执行的活动都是值得怀疑的。\u003c/p>\u003cp>妨碍重要目标实现的障碍多种多样。然而,在任何一个特定的时间,有且只有一个头等要事,如果主要障碍岿然不动的话,盲目扫除障碍不会产生任何效果。 以我们的任务为例,如果获取信息是你的主要障碍,你可以雇人替你做些研究,但前述报告的起草依然没有获得进展。 因此,正如艾利克斯最先修理了效率最低的那台机器,紧接着修理效率倒数第二低的那台,然后依此类推一样,不要试图一下子修好所有的机器,我们也应该一个一个地消除障碍物。\u003c/p>\u003cp>\u003cstrong>3.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; \u003c/strong>\u003cstrong>扫除障碍\u003c/strong>\u003c/p>\u003cp>如果你的“最慢行进者”是你追求报告的完美性,你有很多很多的想法能让报告更完善,但是在现在的情况下,你的核心目标是交上初稿。因此,要扫除障碍,你必须考虑“完成比完美更重要”,忘记“这报告必须完美”。允许自己不用对第一稿进行润色。主要障碍一扫除,这项工作的任何其他方面都会变得更容易。\u003c/p>\u003cp>“最慢行进者”甚至还可能是一个人——不管是在一个项目上给你开绿灯的老板,还是不批准预算的财务部门,抑或是一个不愿在签字栏里签字的客户。为了减少与他人的摩擦,你要采用 “用蜂蜜捕捉更多苍蝇” 的办法。给他发一封电子邮件,但不要问他是否已经为你做了X事(很显然,他没有做),而是去看看他,问问他:“你在做X事的时候碰到了什么障碍和困难,我该怎么帮你扫除这些障碍?”不要纠缠别人,而是要真诚地提供支持。这样做,你会比只发一封邮件然后提一个要求,得到更加热情的回复。\u003c/p>","explains":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>读完这个片段，大家可能还是没搞懂什么是“最慢行进者”。举个例子大家就清楚了。我们想要把一个木桶装满水，就必须先把最短的那个木板加长，然后再加长其他木板，才有可能把水装满。如果你不解决这个短板的问题，把其他木板加的再长也不可能把桶装满。这个短板就是我们的“最慢行进者”。\u003c/p>\u003cp>就像片段中讲得一样，在面对创造性问题的时候，如果我们能够优先找到并且扫除“最慢行进者”，就能高效解决问题。\u003c/p>\u003cp>那么具体如何做呢？\u003c/p>\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>HOW\u003c/strong>\u003cstrong>】三步法扫除“最慢行进者”方法如下：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第一步，明确目标。\u003c/strong>制定出明确的目标，这个目标要有可观察与衡量的标准。有了清晰的目标，我们就更容易判断出 “最慢行进者”，而不会陷在无关紧要的事情里。\u003c/p>\u003cp>\u003cstrong>第二步，锁定“最慢行进者”。\u003c/strong>列出目标实现过程可能遇到的障碍清单，根据目标判断出哪个才是“最慢行进者”。\u003c/p>\u003cp>\u003cstrong>第三步，扫除“最慢行进者”。就是找到解决“最慢行进者”的方案。\u003c/strong>通常，\u003cstrong>“最慢行进者”\u003c/strong>一扫除，问题就能轻松解决。\u003c/p>\u003cp>你也可以循环使用这种方法（把第二障碍当做最慢行进者），直到你认为目标达成变得轻松为止。\u003c/p>\u003cp>\u003cstrong>举个我自己的例子给大家示范一下：\u003c/strong>\u003c/p>\u003cp>以前我曾经给自己定下早起的目标，却没有做到。\u003c/p>\u003cp>学习了三步扫除“最慢行进者”之后，我是这样做的：\u003c/p>\u003cp>\u003cstrong>第一步，明确目标。\u003c/strong>我的目标是睡够7小时，并且第二天在6点之前起床。\u003c/p>\u003cp>\u003cstrong>第二步，锁定“最慢行进者”。\u003c/strong>列出晚睡、冬天冷、闹铃不够响等原因后，我根据目标（睡够7小时，6点之前起床）发现，晚睡才是\u003cstrong>“最慢行进者”。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第三步，扫除“最慢行进者”。\u003c/strong>我告诉自己早起学习比熬夜学习效率高很多，于是交押金给我太太，让她监督我在每晚11点之前睡觉。就这样，解决了晚睡这个“最慢行进者”，我轻松地实现了早起的目标。\u003c/p>\u003cp>\u003cstrong>【预防异议】\u003c/strong>有的伙伴会说，这个方法太麻烦了，反正有那么多障碍，我挨个解决不就好了吗，干嘛要花力气去选择最慢行进者。事实上，不这么做会更麻烦。因为在遇到棘手问题的时候，只有先解决最慢行进者，其他的问题才能往前推进，否则只会带来时间、精力的浪费。比如，我以前早起采取的方案就是多上几个闹铃，可能因为晚睡，往往听见闹铃响也起不来，或者根部听不见。上再多闹铃也决绝不了问题。总之，这个方法一开始做起来可能有点麻烦，但是很值。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","interaction":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>拆书家提问设计（逐字稿）：听完我的例子，请大家设想一下，在接下来的一个月，你最想解决什么需要发挥创造力的棘手问题，比如解决工作中的某个难题、养成一个对你来说很困难的习惯、解决一个拖延很久的重要问题…..请选择一个你本月最想解决的棘手问题，把它写在纸上。请在小组内轮流分享，你想解决的棘手问题是什么？这个问题的具体情况是什么？你为什么想要解决它？\u003c/p>\u003cp>\u003cstrong>3\u003c/strong>\u003cstrong>分钟后，我会请一个小伙伴起来分享自己的案例。\u003c/strong>\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>学习者案例记录：\u003c/p>\u003cp>雪莉：我想在最近一个月解决的问题是通过3-1的拆书，因为3-1我已经拆了4遍了还是，没过。我比较崩溃，我觉得自己已经很努力在修改了，观察家老是觉得我的拆解不符合要求。我想利用扫除最慢行进者的方法，来发现关键问题到底是什么，从而一举拆过3-1。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>拆书家提问设计（逐字稿）：刚才大家都分享了一个自己在接下来的一个月想要发挥创造力去解决的一个棘手问题。现在请你用三步扫除“最慢行进者”的方法，来规划出这个问题的解决方案。请写下具体的时间、地点、时间，以及具体的方法步骤，和可预期的结果。\u003c/p>\u003cp>\u003cstrong>5\u003c/strong>\u003cstrong>分钟后，我会请一个小伙伴起来分享自己的案例。\u003c/strong>\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>学习者案例记录：\u003c/p>\u003cp>李娟：我想要我想在最近一个月解决的问题是早睡，因为我总是睡得很晚，当身体已经很疲惫的时候还是不由自主玩手机，经常到两三点。这样我就会长痘痘，就不美了。\u003c/p>\u003cp>我准备这样使用三步扫除“最慢行进者”来解决问题：\u003c/p>\u003cp>\u003cstrong>第一步，明确目标。\u003c/strong>每晚10点前睡觉，睡够8小时，衡量标准是不因为睡眠不足而长痘。\u003c/p>\u003cp>\u003cstrong>第二步，锁定“最慢行进者”。\u003c/strong>我列出控制不住玩手机、白天喝咖啡、晚上睡不着等三个障碍后，我根据目标（每晚10点前睡觉，睡够8小时）发现，\u003cstrong>控制不住玩手机\u003c/strong>才是\u003cstrong>“最慢行进者”。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第三步，扫除“最慢行进者”。\u003c/strong>今天回家就上网搜索“满脸痘痘和油光”的女生图片，把它作为微信、微博、的背景和屏保图片。这样当我想在晚上玩手机的时候就会因为看到这些恐怖的照片而不敢玩了。\u003c/p>\u003cp>我相信通过这个方法，可以大大减少我晚上玩手机的时间，更容易做到早睡，从而成为不长痘的大美女。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1559104774000,"updated_at":1559104774000,"ria":true},{"id":7921,"topic":"如何克服禀赋效应带来的影响","learn_goal":"学习后，学习者能够使用假设还不曾拥有的方法克服禀赋效应的影响","remark":"","level":"TF2-2","duration":16,"status":29,"type":0,"chaishujia":{"username":"我叫刘军","city":"天津市"},"club":{"name":"北京城市之光分舵","city":"北京市"},"prologue":"【F】这本《精要主义》的作者是被誉为“21世纪史蒂芬•柯维”的英国人格雷戈•麦吉沃恩，他是精要主义的提出者、倡导者和领导者，本书主要为读者将自己打造成一名精要主义者提供思路和方法。\r\n【A】这本书排在豆瓣2016年度读书榜单中经营管理类图书第八名，曾荣获800-CEO-READ商业书籍大奖，被《华尔街日报》、《纽约时报》评为畅销书。\r\n【B】你是否感到自己总是忙忙碌碌却效率低下？你是否觉得自己的时间总是被别人的安排打乱？你是否觉得自己一直在奔波，却总是到不了任何地方？这本书介绍了精要主义者的思维模式，并将这种模式转化为一种系统化的程序，助你拜托无意义的多数，专注有意义的少数，成就有意义、有目的的人生。","ratings_count":1,"texts":[{"id":11470,"quote":null,"explains":"\u003cp>拆页内容主要为我们介绍了客服禀赋效应的方法。禀赋效应是指当个人一旦拥有某项物品，他对该物品价值的评价要比未拥有之前大大增加。\u003c/p>\u003cp>【预防异议】听上去不是很容易理解对不对？这是源于禀赋效应属于行为金融学中的一个理论分支。其实日常生活中我们经常会受到禀赋效应的影响，【举例说明】举个简单的例子大家就明白了：年关将至，大家在收拾自己衣物的时候是不是发现自己的衣柜里都有那么几件衣服或是一两双鞋子，是自己上次收拾时没舍得扔，还树雄心立大志后面要穿，但此时他还是原封不动的躺在那占你柜子的空间呢，这就是禀赋效应带来的影响：由于禀赋效应，人们要避免失去所拥有的东西，使人产生的“安于现状情结”。\u003c/p>\u003cp>拆页中为我们提供了应对禀赋效应的方法：假设我们手头没有，我们愿意付出多大代价去获得它，以此克服禀赋效应为我们带来的影响。\u003c/p>\u003cp>【举例说明】如果收拾衣柜时遇到不知道该留还是该扔的衣物时，停下来问问自己：如果没有这件衣服，在面对需要的季节或者场合时，你是不是愿意花钱买下它。这样的话，也许就不会再让那些不穿的衣物占领你衣柜里有限的空间了。\u003c/p>","interaction":"\u003cp>【分步催化1】禀赋效应的影响经常出现在我们的生活中，拆迁时居民与政府补偿价格上的争执，是禀赋效应的体现；股价下跌时，持有者为了避免损失冒风险惜售，也是禀赋效应的体现；不会穿又不舍得扔的衣服、昂贵又无趣的演出，甚至是明明不爱还不肯放手的感情，你在生活中会涉及到哪个情境？\u003c/p>\u003cp>史老师：我觉得我晚上要给我在闲鱼上挂着的耳机重新定价时，就可以用到今天的知识。\u003c/p>\u003cp>【分步催化2】请各位加工一下刚才的例子，说明在以后的日子中，你如何在刚才你想到的情境下克服禀赋效应带来的影响。请在小组内分享你的应用。\u003c/p>\u003cp>史老师：今晚我回去就改价。我在闲鱼上一直挂着的8个二手耳机，很少有人买家问津，就是源于定价太高。我总想的是这耳机1800买的，我1600才愿意卖。晚上到家我会先问自己，如果是我现在买的话，我愿意花多少钱？如果答案是600，我就按600给他标价，来促成这些耳机尽快出手。\u003c/p>","flags":{"r":false,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1558082897000,"updated_at":1558082897000},{"id":7854,"topic":"如何努力才会有成效","learn_goal":"在遇到阻碍时，能用“目标-障碍改进法”，找到最可能的障碍","remark":"","level":"TF3-3","duration":60,"status":30,"type":0,"chaishujia":{"username":"绚绚","city":"深圳"},"club":{"name":"深圳智荟分舵","city":"深圳"},"prologue":"\u003cp>大家好，我是二级拆书家绚绚，一个喜欢阅读的项目管理工程师。\u003c/p>\u003cp>今天我拆书的主题是：如何努力才会有成效。在接下来一小时的拆书里我们有两个学习目标：\u003c/p>\u003cp>学习目标1：学完后，在遇到阻碍时，能用“目标-障碍改进法”（澄清），找到（行为）最可能的障碍（界定），避免无用功。\u003c/p>\u003cp>学习目标2:&nbsp;在没有遇到阻碍时，能通过主动应战（澄清），解决（行为）可能产生的问题（界定）。\u003c/p>\u003cp>给学习者分组：3～4人一组。\u003c/p>\u003cp>【场景法介绍图书】\u003c/p>\u003cp>【场景】\u003c/p>\u003cp>我前段时间有点低落，每天忙忙碌碌的，上班做了好多领导交代的事情，到写绩效输出时却无从下手，每天下班回家都觉得很累，强撑着去运动看书，但体型没有什么变化，书看了也没记住，感觉很丧。 \u003c/p>\u003cp>【提问】\u003c/p>\u003cp>小伙伴们，你们有没有遇到类似的情况，明明付出了很多努力，却又一事无成？如果一直处于这样的状态下，会有什么样的影响？如何才能避免这种状态呢？\u003c/p>\u003cp>【影响】\u003c/p>\u003cp>（不自信、没输出等） 如果总是忙忙碌碌，却没有成果，我们就会不自信、没输出，压力很大，也可能会破罐子破摔，觉得努力无用，或干脆放弃努力。 \u003c/p>\u003cp>【解决】\u003c/p>\u003cp>今天我给大家重磅推荐《精要主义》一书，本书作者格雷戈·麦吉沃恩被誉为“21世纪的史蒂芬·柯维”,他教给我们做事的一种方式：更少，但更好，把精力集中在最重要的事务上，用20%的努力产生80%的成果。\u003c/p>\u003cp>给大家1min的时间先阅读一下拆页1，阅读完抬头示意我一下。&nbsp;\u003c/p>","ratings_count":3,"texts":[{"id":11378,"quote":"\u003cp>在努力弄清楚这些话的含义的时候,他和他的儿子及一帮朋友进行了次徒步旅行。作为童子军领袖,他\u003cstrong>负责在太阳下山之前\u003c/strong>\u003cstrong>,\u003c/strong>\u003cstrong>把所有男孩子都带到营地\u003c/strong>。但是,所有参加过这种旅行的人都知道,让一群小男孩都以同样的速度行进并不掉队,这实际上是很难的。\u003cstrong>艾利克斯很快就碰上了一个问题：有些童子军走得很快\u003c/strong>\u003cstrong>,\u003c/strong>\u003cstrong>而另一些却走得很慢。\u003c/strong>特别是\u003cstrong>一个叫赫比的小男孩\u003c/strong>\u003cstrong>,\u003c/strong>\u003cstrong>走得最慢\u003c/strong>。结果,走在队伍最前面的男孩和落伍的赫比之间,距离相差好几公里。\u003c/p>\u003cp>因此,艾利克斯决定换一种方法。他\u003cstrong>把赫比放在这组人的前面\u003c/strong>,把其他孩子按速度进行排列:从最慢到最快。虽然,把走得最快的人放在队伍的最后面是违反常理的做法,但是这么做能让这群人开始以整齐划一的队列行进。\u003c/p>\u003cp>\u003cstrong>他找到的对策是,\u003c/strong>\u003cstrong>想尽一切办法为赫比减负\u003c/strong>。因为\u003cstrong>走得最慢的小孩恰恰在队伍的最前面\u003c/strong>\u003cstrong>,\u003c/strong>\u003cstrong>如果赫比每小时都能走快一米,\u003c/strong>\u003cstrong>整个队伍就能以同样的增速更快地到达营地。\u003c/strong>\u003c/p>\u003cp>这个发现对艾利克斯来说意义重大。赫比的任何一点加速,哪怕极其微小,也会对整个队伍的行进速度产生立竿见影的效果。因此,他把赫比背包里的东西(他随身带的多余的食物和用品)都拿了出来,并分给了队里的其他人。这种方法马上奏效,队伍行进速度立刻加快。他们最后提前到达了营地。\u003c/p>","explains":"\u003cp>技能点：有I环节的互动，且拆书家能精准控场。\u003cbr> 【what】\u003cbr> 拆页中讲了一个什么故事？\u003cbr> （艾利克斯参加一次徒步旅行的故事。）\u003c/p>\u003cp>在这个故事中，艾利克斯是否清楚他的目标？他的目标是？\u003c/p>\u003cp>（清楚。在太阳落山前，把所有男孩子带到营地）\u003c/p>\u003cp>他遇到的问题是？\u003c/p>\u003cp>（小男孩的速度不一致。）\u003c/p>\u003cp>那他是想办法使小男孩的速度一致吗？\u003c/p>\u003cp>（不是）\u003c/p>\u003cp>他是怎么做的？\u003c/p>\u003cp>（找到速度最慢的那个小男孩，把他放到队伍的前面，并想办法提高最慢小男孩的速度）\u003c/p>\u003cp>为什么他不想办法使所有小男孩的速度一致？\u003c/p>\u003cp>（因为难度太大，不一定能完成）\u003c/p>\u003cp>好的，非常棒，大家已经把重点都说出来了，如果艾利克斯在遇到小男孩速度不一致的问题时，就想当然想办法使他们的速度一致，可能会事倍功半，甚至徒劳无功。他考虑到了这一点，所以采取了另一种方法。\u003c/p>\u003cp>【how】\u003c/p>\u003cp>通过对艾利克斯行为的解读，我们已经拆解出具体步骤了：\u003c/p>\u003cp>1、清楚最主要的目标（要达到的结果/具体/可量化/可实现/可执行）\u003c/p>\u003cp>2、找到最主要的障碍（列出可能的障碍，判断哪个的影响最大）\u003c/p>\u003cp>3、针对障碍做出改进\u003c/p>\u003cp>【反例】\u003c/p>\u003cp>举个例子，相信很多小伙伴都有跟我一样的困扰，买书如山倒，读书如抽丝，（笑~），我一直想把家里的书看完，为此还买了很多帮助阅读的书，结果就是未拆封的书又增加了好几本。\u003c/p>\u003cp>【正例】\u003c/p>\u003cp>后面我运用了拆页中的方法，成功解决了这个问题：\u003c/p>\u003cp>1、首先我思考了看书的目标，是有输出、能解决问题，表现为在平台上发表文章、回复问题，分享给朋友等。\u003c/p>\u003cp>2、找到最主要的障碍。我的障碍是：时间不够、书太多不知道读哪一本、没有输出的习惯等。将其排序，我发现最主要的障碍是没有输出的习惯。\u003c/p>\u003cp>3、针对障碍做出改进。我要解决没有输出习惯的问题，于是给自己定了硬性要求。即使是一天只读一页书，也要把书里的内容用自己的话在微信群、朋友圈或简书上发出来。只要给我带来收获，这本书就可以功成身退了，通过这种方式，我很快读完了家里的藏书。\u003c/p>\u003cp>【适用边界】\u003c/p>\u003cp>这种方法适用的前提是你愿意做出改变，如果你不愿意花时间去考虑什么样的努力会产生成效并行动，就不适用。\u003c/p>\u003cp>【预防异议】\u003c/p>\u003cp>可能有人会说，现实生活中，很难清楚的知道，哪一个因素是最主要的障碍。没错，刚开始的时候，辨别是很难的，尤其大部分人都习惯先做自己能做的，而不是提升目标进度的事。所以才需要我们刻意的去练习，去改变。\u003c/p>","interaction":"\u003cp>\u003cstrong>使用【\u003c/strong>\u003cstrong>A2\u003c/strong>\u003cstrong>】技能点环节指令清晰，涵盖了三级催化应用的技巧：\u003c/strong>\u003cstrong>1\u003c/strong>\u003cstrong>）学习者根据指令，设计出一个包含人物角色、有起因经过结果、有对话的故事。\u003c/strong>\u003c/p>\u003cp>知识在脑海中应用一遍，就相当于实际演练了一遍。\u003c/p>\u003cp>接下来请大家编写一个小剧本，要求用我们刚才讲到的三点。\u003c/p>\u003cp>可能是未来一个月的某天，你身边的朋友遇到一些困惑，他可能采取了错误的做法，也可能不知道从何下手，你会与他开展一场什么样的对话呢。\u003c/p>\u003cp>请设想一下那个场景，给你们5分钟写在纸上，只记关键字。（场景不限，需包含时间、地点、人物、对话过程）。待会请一位小伙伴上来分享。\u003c/p>\u003cp>学习者分享：\u003c/p>\u003cp>时间（未来的某天）：下个星期一\u003c/p>\u003cp>地点：咖啡厅\u003c/p>\u003cp>人物：西瓜和她朋友香蕉\u003c/p>\u003cp>背景：香蕉觉得自己皮肤不好，想要剁手SKII最新款的护肤品。\u003c/p>\u003cp>对话过程：\u003c/p>\u003cp>西瓜：你最近脸色不大好，是太累了吗？\u003c/p>\u003cp>香蕉：我最近皮肤不知道为什么长了好多痘痘，用了很多贵妇护肤品都没效，好心烦，SKII最新款的护肤品是我最后的希望了。\u003c/p>\u003cp>西瓜：你皮肤出问题了，你现在希望皮肤赶紧好起来是吧？（确定目标）\u003c/p>\u003cp>香蕉：那当然啦，我都要急得睡不着觉了。\u003c/p>\u003cp>西瓜：我记得你以前皮肤很好的，那时候你用的是SKII最新款的护肤品?\u003c/p>\u003cp>香蕉：不是，皮肤好的时候用什么护肤品都好，不过那时候我吃得好睡得好，皮肤当然没什么问题。\u003c/p>\u003cp>西瓜（注意到了重点）：嗯哼，你现在吃的睡的不好吗？\u003c/p>\u003cp>香蕉：吃得还行，睡倒是越来越晚了。基本没在12点前睡觉过。\u003c/p>\u003cp>西瓜：你觉的是护肤品的作用大还是睡眠好对皮肤的影响大？\u003c/p>\u003cp>香蕉：那当然是睡眠啊！\u003c/p>\u003cp>西瓜：那你现在觉得自己长痘的原因是什么？\u003c/p>\u003cp>香蕉：我睡得太晚了（确定主要障碍）\u003c/p>\u003cp>西瓜：关于这点，你有什么想法吗？\u003c/p>\u003cp>香蕉：我今晚10点钟就睡觉，设置手机到点自动关机，没有手机我就能很早睡觉了（针对障碍做出改进）\u003c/p>\u003cp>西瓜：加油！我明天等你的好消息～\u003c/p>\u003cp>我（回应）：&nbsp;好的，谢谢西瓜的精彩分享，我们可以看到，西瓜通过拆页中的方法，成功帮助朋友克服遇到的阻碍，灰常优秀！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":11379,"quote":"\u003cp>刚才我们讲到了当遇到阻碍时，我们可以怎么做。其实，与其每次救火，不如提前规避风险一劳永逸。接下来我们要学习，在遇到问题前，我们应该怎么做，如何才能防范于未然。接下来要进行拆页2的学习。在学习之前先给大家做个自测题。\u003cbr>\u003c/p>\u003cp>---------------------------\u003c/p>\u003cp>\u003cstrong>技能点：\u003c/strong>\u003cstrong>1min\u003c/strong>\u003cstrong>，量表清晰设置了多个选项，学习者通过自测可以了解在某一种情况下自己的表现。\u003c/strong>\u003cstrong>\u003cbr> \u003c/strong>拆书家设计提问（逐字稿）：在学习之前，先请大家花一分钟的时间做一个简短的测试，帮助大家后面更好的学习。\u003cbr> 以下有五道题，能够测试大家准备做事前的情况，请按照1~6分给自己打分，1代表完全不符合，6代表非常符合。请仔细阅读下题中的每一句话，根据自己的实际情况打分。\u003cbr> \u003cbr> \u003c/p>\u003cp>1、每次我都会根据目标来安排事情。\u003c/p>\u003cp>①&nbsp;&nbsp; ②&nbsp;&nbsp; ③&nbsp;&nbsp; ④&nbsp;&nbsp; ⑤&nbsp;&nbsp; ⑥\u003c/p>\u003cp>2、做事前，每次我都会先做计划。\u003c/p>\u003cp>①&nbsp;&nbsp; ②&nbsp;&nbsp; ③&nbsp;&nbsp; ④&nbsp;&nbsp; ⑤&nbsp;&nbsp; ⑥\u003c/p>\u003cp>3、做事前，每次我都会考虑至少两个困难点和可能的解决办法\u003c/p>\u003cp>①&nbsp;&nbsp; ②&nbsp;&nbsp; ③&nbsp;&nbsp; ④&nbsp;&nbsp; ⑤&nbsp;&nbsp; ⑥\u003c/p>\u003cp>4、我每次都能准确评估自己完成一件事情所需要的时间\u003c/p>\u003cp>①&nbsp;&nbsp; ②&nbsp;&nbsp; ③&nbsp;&nbsp; ④&nbsp;&nbsp; ⑤&nbsp;&nbsp; ⑥\u003c/p>\u003cp>5、我每次都会在估算任务完成所需的时间上多留一些时间，留有余量\u003c/p>\u003cp>①&nbsp;&nbsp; ②&nbsp;&nbsp; ③&nbsp;&nbsp; ④&nbsp;&nbsp; ⑤&nbsp;&nbsp; ⑥\u003c/p>","explains":"\u003cp>时间要求：1min\u003cbr> \u003c/p>\u003cp>看到很多小伙伴已经做完自测题了，我想请问一下，有没有分数在20分以上的小伙伴？（有两个人举手了）\u003cbr> 那有没有10分以下的？（也有一个人举手）\u003cbr> 这个自测题主要是测试大家做事的一个情况，20分以上，说明你会主动的提前做准备，减少可能产生的问题，大部分时间都有正产出。\u003c/p>\u003cp>10~20分，说明你在这方面有很大的提升空间。\u003c/p>\u003cp>分数在10分以下，恭喜你，你来对地方啦，等下我们就来学习如何做出针对性改进。\u003c/p>\u003cp>我看到有两位小伙伴20分以上，我们请一位小伙伴分享下，就是你得6分的那项，你是如何做的，有请瑜瑜。\u003cbr>\u003c/p>","interaction":"\u003cp>瑜瑜分享： 第一点我得了6分，比如说我去徒步，我就会提前一周做好计划。\u003c/p>\u003cp>我问：这样做的好处是什么？\u003c/p>\u003cp>瑜瑜：徒步过程会很顺利很省事，胸有成竹。\u003c/p>\u003cp>拆书家总结：好的，请把掌声给到瑜瑜。提前做好计划能确定接下来的一个行程和细节，让徒步更有组织，也更轻松。\u003c/p>\u003cp>现在大家对自己做事情的情况已经有了一定的了解，也知道自己的不足之处，接下来就让我们一起学习如何做出改进。给大家1分钟的时间阅读一下拆页2。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":11380,"quote":"\u003cp>非精要主义者在执行的时候,总是\u003cstrong>被动应战\u003c/strong>,率性而为。因为,他们总是在遭遇危机后才被动反应,而不是提前预测危机,所以就不得不采取应急之计——相当于把手指插进堤坝的漏洞,幻想整个大坝不会坍塌。由于擅长使用锤子,非精要主义者认为一切都是钉子。这样,他们用的力气越来越大,但结果却导致了更大的阻力和更多的挫折。的确,有些情况下,你给人的压力越大,他或她的反抗力也就越大。\u003c/p>","explains":"\u003cp>技能点：在未包含how拆页的【I】环节，涵盖了三级讲解引导的技巧：1）给出清晰的how，2）通过对比概念和匹配例子引出知识点逻辑、步骤和边界等。\u003cbr> 拆书家进行简短互动，并能精确控场。\u003cbr> 【what】\u003c/p>\u003cp>拆页中讲到了精要主义，在这里，我介绍一下精要主义，精要主义的本质在于排除最重要事务以外的一切，因为我们正在努力完成的事情中有太多是根本不该做的。\u003c/p>\u003cp>是什么使我们做了太多本来不该做的事情？\u003c/p>\u003cp>（被动应战，率性而为）\u003c/p>\u003cp>没错，在这里，我们对比一下被动应战与主动应战的概念。\u003c/p>\u003cp>【概念对比】\u003c/p>\u003cp>被动应战是指把选择权交给其他人或事，而主动应战是指提前考虑怎么做，占据主导权。\u003c/p>\u003cp>比如说，你今天上班，没想好要做什么，结果一会完成老板的指令，一会帮同事一个小忙，一天就过去了。这是主动应战还是被动应战？\u003c/p>\u003cp>显然是被动应战。因为主动权不在你手上，你不做出选择，就会有人替你做出选择。\u003c/p>\u003cp>比如说，你策划了一场出游，方案很完美，结果出行的时候，天降大雨，行程被迫取消，你前面的付出全部白费，这是主动应战还是被动应战？\u003c/p>\u003cp>显然是被动应战，因为你只考虑了一种可能性，当发生突发状况时就只能被动接受。\u003c/p>\u003cp>比如说，你总觉得自己20分钟就能到办公室，因为有一次，你从出门到打卡只用了20分钟，但实际上，没有30分钟是很难到办公室的，因为时间规划的紧张，总处于压力之下，还经常性迟到，这是主动应战还被动应战？\u003c/p>\u003cp>显然是被动应战。因掐点做事，一旦出现一点小意外，可能要额外付出极大的代价。\u003c/p>\u003cp>【how】\u003c/p>\u003cp>综上，主动应战要做到：\u003c/p>\u003cp>1.&nbsp; 根据目标选择自己要做的事情。\u003c/p>\u003cp>2.&nbsp; 提前做两种或两种以上的准备（顺利的情况，不顺利的情况）。\u003c/p>\u003cp>3.&nbsp; 多预留50%以上的时间。\u003c/p>\u003cp>【例子】\u003c/p>\u003cp>前面说到我上班做了很多事情，但到写绩效的时候，无法下笔，就是因为我没有做出自己的计划，领导安排一个指令，我就做一个，很多项目到一半的时候都停掉了，无法写入绩效。\u003c/p>\u003cp>接下来上班我会这么做：\u003c/p>\u003cp>1.&nbsp;&nbsp;&nbsp;&nbsp; 根据我下一个季度的绩效目标列出待办事项，选定一件事。如准备一个培训。\u003c/p>\u003cp>2.&nbsp;&nbsp;&nbsp;&nbsp; 做两手准备：\u003c/p>\u003cp>1）正常准备ppt和培训资料\u003c/p>\u003cp>2）针对大家可能提出的刁钻问题准备一个plan B 计划\u003c/p>\u003cp>3.&nbsp;&nbsp;&nbsp;&nbsp; 正常讲课时间时一小时，我会预留一个半小时的时间。\u003c/p>\u003cp>【适用边界】\u003c/p>\u003cp>这种方法适用的前提是你有比较充裕的时间来做准备，如果本身就时间不够，只能走一步看一步，那可能更多的要拼运气和应变能力。\u003c/p>\u003cp>（有学习者举手）\u003cbr> Josie：我有一个疑问，为什么要比预计时间多留50%？\u003cbr> 我（提问）：可以说一下你的主要疑惑点在哪里吗？（澄清问题）\u003cbr> Josie：我觉得50%有点多。\u003c/p>\u003cp>我（提问）：请问你平时制定目标都能按时完成吗？\u003c/p>\u003cp>Josie：大部分时候不能。\u003c/p>\u003cp>我（提问）：你觉得大概多多少的时间能完成。\u003c/p>\u003cp>Josie：20%或30%吧\u003c/p>\u003cp>我（提问）：如果比预计时间多30%你就一定能完成吗？\u003c/p>\u003cp>Josie：也不是，有时还会在这个基础上再超20%或30%。我明白了，50%是一个比较宽裕又比较保守的时间，但又不是确定的时间，是可以根据自己的实际情况调整的，是吗？\u003c/p>\u003cp>我（回复）：没错，你的理解完全正确。50%是我们建议的一个比较宽松的时间段，你们在实际应用的过程中可以根据自己的实际情况进行调整。\u003c/p>","interaction":"\u003cp>A3促动参与\u003c/p>\u003cp>（技能点：在未包含how拆页的【A3】环节指令清晰，学习者在拆书家主持的微行动学习环节，讨论出这类问题的解决方案）\u003cbr>\u003c/p>\u003cp>【互动提问】\u003c/p>\u003cp>大家觉得，在“主动应战”的三个步骤里，哪一步最难？\u003c/p>\u003cp>学习者的回答：第二步最难（提前做两种或两种以上的准备最难）\u003c/p>\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>1.\u003c/strong>\u003cstrong>明确问题】\u003c/strong>\u003c/p>\u003cp>大家觉得第二步：提前做两种或两种以上的准备最难，对吗？\u003c/p>\u003cp>学习者：（纷纷点头）对的。\u003c/p>\u003cp>【重述并明确问题】\u003c/p>\u003cp>好的，大家都觉得提前做两种或两种以上的准备最难。\u003c/p>\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>2.\u003c/strong>\u003cstrong>引导分组讨论问题的本质】\u003c/strong>\u003c/p>\u003cp>现在请大家以小组为单位，讨论一下为什么这一步特别难？产生这个问题的本质原因是什么？大家可以结合过往经验，尝试相互追问，深入的探讨一下。给大家6分钟的时间，组长帮忙记录一下小组讨论结果。\u003c/p>\u003cp>（讨论ing）\u003c/p>\u003cp>好，小伙伴讨论的非常热烈。现在我们请小组长分享一下讨论的结论。\u003c/p>\u003cp>组长1：经验不足、自己太懒\u003c/p>\u003cp>组长2：经验不足、了解不深（了解不深也是经验不足）\u003c/p>\u003cp>组长3：懒、惯性思维\u003c/p>\u003cp>拆书家：好的，谢谢各位组长，大家都讨论了很多，最后发现这一步特别难主要有两个原因，一个是经验不足，不知道要怎么做准备，另一个是因为懒，不愿意去多做准备。\u003c/p>\u003cp>一个是认知不足，一个是执行力不足。那你们觉得哪个才是问题的本质？\u003c/p>\u003cp>学习者（异口同声）：认知不足。\u003c/p>\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>3.\u003c/strong>\u003cstrong>明确问题的本质】\u003c/strong>\u003c/p>\u003cp>那大家讨论出来的问题本质是，认知不足，大家认同吗？\u003c/p>\u003cp>学习者：认同。\u003c/p>\u003cp>（确认）：好的，经过大家的一致认可，提前做两种或两种以上的准备最难的本质原因是认知不足。\u003c/p>\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>4.\u003c/strong>\u003cstrong>引导分组讨论解决方案】\u003c/strong>\u003c/p>\u003cp>现在我们已经清楚了问题的本质，那么接下来，就探讨一下怎么解决这个问题吧。\u003c/p>\u003cp>在讨论之前，有个问题想先跟大家明确下：\u003c/p>\u003cp>这个问题我们解决到什么程度就算满意了？也就是讨论的目标是什么？\u003c/p>\u003cp>学习者：讨论出一些提升认知的方法，让自己知道怎么提前做两种以上准备。\u003c/p>\u003cp>拆书家：好，那我们接下来要解决的目标就清晰了，就是讨论出一些提升认知方法，让自己知道怎么提前做两种以上准备，大家同意吗？\u003c/p>\u003cp>学习者：同意。\u003c/p>\u003cp>接下来请大家讨论一下，要达到这个目标该如何行动？\u003c/p>\u003cp>给大家6分钟时间，稍后我们请每个小组来分享一下讨论的成果。\u003c/p>\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>5.\u003c/strong>\u003cstrong>请各组代表讲解自己组的成果】\u003c/strong>\u003c/p>\u003cp>学习者分享：\u003c/p>\u003cp>组长1：\u003c/p>\u003cp>1、通过学习来提高（向专家/网络/书籍学习）\u003c/p>\u003cp>2、通过实践来提升（自己多经历，在做事中提炼）\u003c/p>\u003cp>组长2:\u003c/p>\u003cp>1、 学习他人的经验\u003c/p>\u003cp>2、 总结好的行动步骤\u003c/p>\u003cp>组长3:\u003c/p>\u003cp>我们只有一点补充：复盘。\u003c/p>\u003cp>【拆书家回应&amp;反馈】\u003c/p>\u003cp>非常感谢小伙伴们的分享，你们非常棒，我现在来总结一下，主要是以下三步：\u003c/p>\u003cp>1.&nbsp;&nbsp;&nbsp;&nbsp; 学习他人的经验——朋友/专家/网络/书籍等\u003c/p>\u003cp>2.&nbsp;&nbsp;&nbsp;&nbsp; 提炼可用的行动步骤—— 学到的东西很多，但哪些可以用呢？这个需要我们提炼出来，刚开始的时候，这一步如果难以做到也要向有经验的人学习。\u003c/p>\u003cp>3.&nbsp;&nbsp;&nbsp;&nbsp; 复盘总结出自己的经验——行动之后发现不足的地方我们可以在复盘时标记，下次就不会犯同样的错误了。\u003c/p>\u003cp>大家同意这三步吗？（同意）\u003c/p>\u003cp>【总结】\u003c/p>\u003cp>最后再总结下，在“主动应战”的三个步骤里，大家觉得最难的是第二步——“提前做两种或两种以上的准备”，产生这个问题的本质原因是：认知有限。\u003c/p>\u003cp>解决方法有三步：\u003c/p>\u003cp>1.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 学习他人的经验\u003c/p>\u003cp>2.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 提炼可用的行动步骤\u003c/p>\u003cp>3.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 复盘总结出自己的经验\u003c/p>\u003cp>【回应与反馈】\u003c/p>\u003cp>谢谢大家的积极参与，在大家的努力下，我们不仅探寻到了本质，还想到了解决之道，good job！\u003c/p>\u003cp>【A2】催化应用\u003c/p>\u003cp>&nbsp;拆书家提问设计：时间要求：1分钟\u003c/p>\u003cp>（技能点：【A2】环节指令清晰，学习者可以根据指令，写出自己未来的一个具体要做应用（比如：某个特定任务、和人分享、事后复盘或找人陪练））\u003cbr> 即使今天我们学习了这个拆页，你知道了在做事前该做些什么，但由于这不是你的习惯性思维模式，你可能并不会马上用起来。所以，请在接下来的日子里，试着跟身边的朋友分享，当你打算做一件什么事情的时候，你会怎么开始。请写下你的行动计划，包含具体时间和场景。1分钟后请一位小伙伴分享。\u003c/p>\u003cp>【学习者案例记录】\u003c/p>\u003cp>小蚊子：我去年暑假想要做兼职，结果去年暑假宿舍不给学生留校住宿，最后没办法我就回家了，在家混日子过得挺不开心的。今年暑假我还是想要做兼职，我会提前做两个准备：\u003c/p>\u003cp>1.&nbsp;问一下师兄师姐他们暑假兼职时是怎么安排住宿的？参照他们的经验做一个安排\u003c/p>\u003cp>2.请关系好的老师帮忙找一些提供住宿的兼职。\u003c/p>\u003cp>在兼职结束之后，我也会写一篇暑假兼职的复盘，总结出我的经验。\u003c/p>\u003cp>结语：\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 好的，谢谢小蚊子的分享。通过今天一个小时的学习，很高兴看到大家有所收获，希望在以后的生活和工作中，在遇到阻碍时，能用“目标-障碍改进法”，找到最可能的障碍，避免无用功。在没有遇到阻碍时，能通过主动应战，提前做准备，解决可能产生的问题。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1557363450000,"updated_at":1559988524000,"ria":true},{"id":7026,"topic":"MVP，最低可行性产品","learn_goal":"学会分析拆解自己的工作生活的目标，拆解出“最低可行性产品”","remark":"","level":"TF2-2","duration":20,"status":29,"type":0,"chaishujia":{"username":"叶子","city":""},"club":{"name":"上海羊角村分舵","city":"上海市"},"prologue":"大家好，我是叶子，今天很高兴和大家一起拆书，今天我要拆的是《精要主义》，要拆的级别是2-2。","ratings_count":1,"texts":[{"id":10403,"quote":"\u003cp>\u003cstrong>在硅谷流行着“完成比完美更重要”的理念\u003c/strong>。这并不是让大家去制造垃圾。其中的思想，在我看来是不要在不重要的事情上虚掷光阴，而是要把事情做成。在企业界，这种想法被描述为创作一种“最低可行性产品”（MVP Minimal Viable Product）。它指的是“对目标客户有用而且有价值的尽可能简单的产品是什么？”\u003c/p>\u003cp>同样，我们也可以采取“最低可行性进步”（Minimal Viable Progress）的方法。问问自己：“对于我们努力要完成的重要任务，有用且有价值的最小进步是什么？”我在本书的写作中就采用了这种方法。比如，当我还在探索阶段的时候，在动笔（或敲打键盘）之前，我会在Twitter 上面分享一个小小的想法（我的最低可行性产品）。如果能够在那上面引起共鸣，我就会给《哈佛商业评论》写一篇博客文章。通过这种只需要花费很少精力的迭代过程，我能够知道应该在什么地方搭建一座桥梁，让自己所思考的事情和同别人生活最相关的事情之间建立起联系。\u003c/p>\u003cp>皮克斯动画工作室把这个方法用在了他们的电影中。这些电影的创作不是开始与脚本，而是开始于情节串联图版，或者叫做连环漫画版电影。他们尝试各种想法，并观察哪些有效，在小范围内进行数百次实验。然后，做出一个影片放映给小规模人群看，以便提前获得反馈。这样，他们就可以用尽可能少的投入，获得尽可能快的长进。皮克斯动画工作室的首席创意官、迪士尼幻想攻错的首席创意顾问约翰·拉塞特（John Lasseter）说：“实际上，我们不是在完成电影，而是在发行电影。”\u003c/p>","explains":"\u003cp>开场：\u003c/p>\u003cp> F特征：这本《精要主义》讲的是如何让我们的应对拥挤不堪的工作和生活，如果不能自己安排生活的优先次序，就只能任由别人替你安排。\u003c/p>\u003cp>\u003cbr> A优势：这本书不是简单的口号，让我们精简和抓住重要的事情，而是一步一步带我们去完成这样的方法，书中从探索/排除和执行三个步骤来带领我们进入精要主义的生活。道理简单易懂、方法易行。\u003c/p>\u003cp>\u003cbr> B利益：你有没有许多事情因为工作量/方案太大而迟迟不敢下手，或者有花了很多资源去做事情后面发现其实没有必要的情况，这些问题在今天拆页里都有答案。\u003c/p>\u003cp>\u003cstrong>I\u003c/strong>\u003cstrong>。\u003c/strong>2-2要求：有举例子说明；有提到学习者可能产生的异议，并给与了预防性的讲解。\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003cbr>\u003c/p>\u003cp>这个片段就讲了3个单词，MVP，Minimal Viable Product，最低可行性产品。三个要素缺一不可，有用有价值，尽可能简单，得是个产品。\u003c/p>\u003cp>文章举了几个例子，第一个是作者写书的例子，可以看到作者的第一个MVP是作者会在twitter上先写一个想法，然后根据反馈，开始第二个MVP，给《哈佛商业评论》写一篇博客文章但最后会开始动笔写书。第二个例子是皮克斯动画工作室做电影的过程，第一个MVP是连环漫画版电影，然后根据反馈再开始第二个MVP，做一个影片小样。最后面才是我们大家看到的成片。\u003c/p>\u003cp>\u003cstrong>预防可能的异议：\u003c/strong>\u003c/p>\u003cp>可能有小伙伴会问，我们为什么要这么做啊？多复杂呀？我们可不可以一开始就写一本书了？可不可以直接拍一个电影呀？\u003c/p>\u003cp>可以吗？当然可以。但是我们更推荐MVP，这样做有几个好处。\u003c/p>\u003cp>1. 用最少的资源验证你的产品。 通过写一个博客文章可以通过点击量、阅读量和留言的问题，看看大家是不是对这个话题感兴趣，大家是不是对这个有共鸣，又会对哪些部分特别关心和在意。你可以提前获得反馈，并且是用最小的资源。\u003c/p>\u003cp>2. 可以让你告别拖延症，迈出行动的第一步。正如文章所说“完成比完美更重要”，我们会被一本书这样的大工程所吓到，没关系，想想你能MVP是什么，是不是可以先写一篇文章或者先写一个主题了。\u003c/p>\u003cp>那我们怎么做了？\u003c/p>\u003cp>第一步&nbsp;拆解\u003c/p>\u003cp> 你开始拆解这些关键部分或者关键节点，先做这些关键部分，先搭架子。我们先让这个事情动起来。\u003c/p>\u003cp>第二步 做\u003c/p>\u003cp>&nbsp;我们先开始做，然后在迭代。\u003c/p>\u003cp>\u003cstrong>举例说明：\u003c/strong>\u003c/p>\u003cp>我最近有特别喜欢一个公众号叫多抓鱼，它是一个二手书买卖平台。前几天有看到一篇文章，讲多抓鱼是怎么在一年多的时间内快速成长，目前已经完成腾讯领投的B轮。在最开始决定创业时，鱼助他们有很多担心，比如这个一折收书三折卖能赚钱吗？比如收到书的品相能好吗？等等很多疑问。这个时候他们是怎么开始的？他们的MVP是什么？他们拉了一个微信群，把认识的爱看书的人拉在一个群里，群主是多抓鱼的运营。有人想卖书就at群主，群主收到书后更新excel表格再at&nbsp;所有人，我们更新了。就这样开始运营。通过一张excel+微信群，这样一个MVP，他关心的这些答案都有了，收到书品相很好，一折收三折卖能赚钱。然后，他们慢慢迭代了。不在是个微信群，在微信里面搞了一个公众号，在这个里面微信公众号里面买卖二手书。注意哦，他们至今也没有开发一个app，他们就是在微信公众号里面做。这个就是他们这个阶段的MVP。\u003c/p>\u003cp>说说我自己的两个故事吧。\u003c/p>\u003cp>&nbsp; &nbsp;我想在朋友圈分享读书笔记，我常常觉得写的太差就不写不分享了，那对于读书笔记来说我的最小可行性产品是什么，恩，我可以在锤子便签上先写一小段感悟分享出来；\u003c/p>\u003cp>&nbsp; &nbsp;我一直想打造一个小花园，可又担心买那么多花架、花盆和植物，如果都养死了怎么办这些钱不都浪费了吗，所以一直没有行动。那么在这个事情上我的最小可行性产品又是什么了？我可以先把家里闲置的书架找出来凑合当个花架，然后把长的茂盛的吊兰进行分盆，这样我就可以不花什么钱先开始打造小花园计划了。\u003c/p>","interaction":"\u003cp>□2-2要求：分步催化中，提问中包括情境或场景，有学习者受启发联系到自己的具体应用场景。\u003c/p>\u003cp>□2-2要求：分步催化中指令清晰，有学习者根据指令，规划出了以后可以如何做的具体计划。\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>分步催化1【2分钟】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>请大家想一想，在自己接下来的生活中，有那个方面是你决定要去提升的？或者是要去尝试做出一个小产品的？比如你想做一个收费的咨询师？再比如你是一个app软件开发？又或者你要筹备一场活动？\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>请拿便签纸写下你想要提升的事情。\u003c/p>\u003cp>Morica：想做一个绘本推广，扩大自己的客户群。\u003c/p>\u003cp>\u003cstrong>分部催化2【8分钟】\u003c/strong>\u003c/p>\u003cp>好，请大家看着自己写下的便签，对照我们今天学习的“MVP最小可行性产品”的方法，按照每个步骤设计出接下来要做的方案。\u003c/p>\u003cp>现在我们来分个组，给大家七分钟的时间讨论，一会儿请小伙伴分享。\u003c/p>\u003cp>Mornica：\u003c/p>\u003cp>第一个MVP：类似上次年会的儿童趣味拆书的形式，在小区内推广，大概二周一次。\u003c/p>\u003cp>第二个MVP：找一个合作伙伴。我们俩都非常的爱孩子，对儿童绘本方面也都非常有兴趣有想法。\u003c/p>\u003cp>第三是：我报了一下课程，关于儿童教育方面的，课程推动我来做，不然这个学费就白费了。学习和实践互相作为补充。\u003c/p>\u003cp>结束语： 今天说了这么多，就是希望大家以后由这种MVP的意识，不再指望憋大招，不再想一口吃成大胖子，而是先做最小可行性产品，然后不断迭代，小步快跑。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1547296101000,"updated_at":1547296101000,"ria":true},{"id":6518,"topic":"三步扫除“最慢进行者”","learn_goal":"通过改变惯性思维，学会做“减法”，来解决前进道路上的**障碍","remark":"","level":"TF1-1","duration":15,"status":0,"type":0,"chaishujia":{"username":"涂毓敏","city":"武汉"},"club":{"name":"武汉珞珈分舵","city":"武汉"},"prologue":"\u003cp>【自我介绍】\u003c/p>\u003cp>大家好我是猛兔，勇猛的猛，兔子的兔。职业是一名自媒体写手，也是一名全职妈妈。\u003c/p>\u003cp>未来的人才必备的通用技能：是写作和演讲。\u003c/p>\u003cp>我希望能将这两项通用技能融会贯通，从拆书帮这个集体，吸取演讲技能的养分，预备在通往拆书家、升级打怪的过程中，与大家分享我写作技能的果实，顺便吐槽一些，与我儿子，4岁小男孩斗智斗勇的故事。\u003c/p>\u003cp>【拆书和拆书帮介绍】\u003c/p>\u003cp>在正式开拆之前，先给大家介绍一下拆书和拆书帮。\u003c/p>\u003cp>\u003cstrong>拆书\u003c/strong>，不是要把书本拆掉，而是将书本原有的知识拆一部分出来，吸收一部分有价值的精华，拆为己用，内化、应用。\u003c/p>\u003cp>我们会用到\u003cstrong>RIA拆书法\u003c/strong>来提升学习效率，这是一种借助便签工具的成人学习方法。\u003c/p>\u003cp>r是阅读原文，i是复述原文，a是联系自身经验。学生时代的学习方式强调的是以，书本知识 ，为中心，但这种ria学习法是以学习者为中心。\u003c/p>\u003cp>拆书法又分为两种形式：\u003c/p>\u003cp>一个是供\u003cstrong>个人学习\u003c/strong>的便签学习法，在家里，一个人运用便签法就可以学习，其效果不亚于一场主题培训，\u003c/p>\u003cp>另一种，是提供组织学习的（由拆书家带领的）现场学习法，就像我们现在围坐在一起，由一位拆书家引领我们学习。拆书家相当于培训师，带着大家把一本30块钱的书读出30000块的效果。\u003c/p>\u003cp>拆书帮，就是基于拆书学习法的，非营利性、青年自组织。目前，拆书帮分舵，遍布全国各大中小城市，这里集合了一批有正能量的小伙伴，他们说来到这里拆书学习，能感受到温暖，而且人也变得积极阳光。拆书帮的使命是帮助更多爱学习的人成为拆书家，让更多的人从拆书过程中受益。\u003c/p>","ratings_count":0,"texts":[{"id":9838,"quote":"\u003cp>\u003cstrong>三步扫除“最慢行进者”\u003c/strong>\u003c/p>\u003cp>人们很少花时间认真考虑什么样的努力会产生成效，什么样的不会。但就算我们认真考虑了，也很容易认为执行意味着加法而不是减法。如果我们想要出售更多的产品，那么我们会增加销售人员。如果我们想要生产更多的产品，那么我们就会扩大生产。这种方法可以找到清晰的证据支持。然而，要改善效果，还有其他思路可循。\u003cstrong>精要主义者不关注需要增加哪些精力和资源，而是关注哪些限制和障碍需要连根拔起。\u003c/strong>那么，他们是怎么做的呢?\u003c/p>\u003cp>\u003cstrong>1.弄清核心目标\u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 只有弄清了要达到的结果是什么，我们才能知道应该扫除的障碍是什么。如果不知道自己真正想要实现什么，所有的改变都是武断妄为。因此，不如向问自己:“如何知道自己已经成功了?”在本章，让我们假定你的目标是，在本周四下午2点之前，准备好份15页的报告草案，并用电子邮件发给客户。注意:这结果非常精确，一点儿都不含糊。\u003c/p>\u003cp>\u003cstrong>2.锁定障碍\u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 不要仓促上马,三思而后行。向问自己:“在我完成任务的道路上有哪些障碍?”&nbsp; “是什么阻碍着我完成任务?”把这些障碍列一一个清单。 它们可能包括:缺乏必要的信息、精力不足、追求完美。“哪 一个障碍扫除之后，其余的障碍会立刻消失?”根据这个问题，来给所有的障碍排列优先顺序。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 在锁定你的“最慢行进者”时，需要记住的关键一点是:即便是一些“有成效的”事情，比如为了获取信息而进行研究或者给别人发电子邮件，或是修改报告以求第一稿就达到完美， 这些都可能是障碍。记住，要达成的目标是完成报告的草案。任何延缓此目标执行的活动都是值得怀疑的。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 妨碍重要目标实现的障碍多种多样。然而，在任何一个特定的时间， 有且只有一个头等要事，如果主要障碍岿然不动的话，盲目扫除障碍不会产生任何效果。以我们的任务为例，如果获取信息是你的主要障碍，你可以雇人替你做些研究，但前述报告的起草依然没有获得进展。因此，正如艾利克斯最先修理了效率最低的那台机器，紧接着修理效率倒数第二低的那台，然后依此类推一样，不要试图一下子修好所有的机器，我们也应该一个一个地消除障碍物。\u003c/p>\u003cp>\u003cstrong>3.扫除障碍\u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 如果你的“最慢行进者”是你追求报告的完美性，你有很多很多的想法能让报告更完善，但是在现在的情况下，你的核心目标是交上初稿。因此，要扫除障碍，你必须考虑“\u003cstrong>完成比完美更重要\u003c/strong>”， 忘记“这报告必须完美”。允许自己不用对第一稿进行润色。 主要障碍一扫除， 这项工作的任何其他方面都会变得更容易。\u003c/p>","explains":"\u003cp>\u003cstrong>why为什么要选这个拆页呢，\u003c/strong>\u003c/p>\u003cp>\u003cstrong>因为在以往\u003c/strong>，我习惯用做加法的思维来解决问题。\u003c/p>\u003cp>比如减肥这件事，就会去网上搜减肥方法、减肥动作，\u003c/p>\u003cp>或者制定健康餐计划、运动计划等等。\u003c/p>\u003cp>这就是在做加法。\u003c/p>\u003cp>做加法的思维方式，看起来，好像是能更快达到减肥的目的，\u003c/p>\u003cp>但是，饮食习惯突然改变，让我更加想吃，而且，当健身计划，无法按时按量完成时，倍感压力。这些出现的新问题更容易减肥失败。\u003c/p>\u003cp>\u003cstrong>然而现在，\u003c/strong>这份拆页提供了一个新的，解决问题的思考方式，不再做加法，而是做减法，精要主义者，不需要增加精力和资源去解决更多出现的问题，而是将精力集中，解决现有的障碍。\u003c/p>\u003cp>只要找到拖垮目标的“最慢进行者”，用这三步就可以扫除，大大提升进程。\u003c/p>\u003cp>\u003cstrong>what什么是最慢进行者？\u003c/strong>\u003c/p>\u003cp>可以理解为：在达到目标过程中，拖垮整个进程的最大障碍。\u003c/p>\u003cp>\u003cstrong>how，\u003c/strong>那么，扫除时，要注意什么呢？\u003c/p>\u003cp>第一步，将目标数字化。\u003c/p>\u003cp>因为数字比文字更精准。数字可以有清晰的期限，过去和未来的比较，效果更容易呈现。\u003c/p>\u003cp>第二点，将障碍锁定。\u003c/p>\u003cp>列成清单，排出优先级，只解决最重要的一个。\u003c/p>\u003cp>第三步，将指令动作化。\u003c/p>\u003cp>可以避免喊口号。\u003c/p>\u003cp>举例，\u003c/p>\u003cp>还是减肥这件事，\u003c/p>\u003cp>首先，减肥，要变瘦，要健康，是一个模糊的文字化的目标。\u003c/p>\u003cp>现在我们把它数字化，\u003c/p>\u003cp>可以说：几个月内，从原来的多少斤，减到多少斤。\u003c/p>\u003cp>当然这里要注意，这个数字化之后的目标，是你踮踮脚就能达到的。不可能定下一个“3天，从160减到90斤”的目标，这几乎是不可能的。\u003c/p>\u003cp>然后，什么是你减肥之路的阻碍呢？\u003c/p>\u003cp>可以列出原因，可能是贪吃，可能是没运动，\u003c/p>\u003cp>列出来以后，只抓住一个你觉得最重要的，来解决掉\u003c/p>\u003cp>最后，如果你觉得最大障碍是缺乏运动，\u003c/p>\u003cp>那么就给自己下达动词化的指令：\u003c/p>\u003cp>铺上瑜伽垫，\u003c/p>\u003cp>打开keep app，\u003c/p>\u003cp>点开一个教程，\u003c/p>\u003cp>模仿教练的动作。\u003c/p>\u003cp>这就是在做减法，如果减肥的道路上，是因为动的太少，只要动起来就已经是很大的进步了。\u003c/p>\u003cp>举这个减肥的例子是帮助大家理解拆页的内容，接下来，给大家分享一段我亲身失败的经历。\u003c/p>","interaction":"\u003cp>【分享A1便签】\u003c/p>\u003cp>在今年三月份，我最初接触写作的时候，为了尽快成为一名，新媒体写手，我在同一时期，报了5个线上写作课，花了近万元学费，每天工作20个小时，学习新媒体的套路。给自己定了日计划、周计划、月计划，排的满满的，感觉每天都有忙不完的事，好像一旦停下来，就停止了进步。\u003c/p>\u003cp>每天只睡4个小时，持续一个月。导致我大病了一场，被确诊为心肌缺血。\u003c/p>\u003cp>我反思自己，\u003cstrong>以前\u003c/strong>都是运用的加法思维在工作，花了大量时间在搜集素材和金句上，耽误交初稿的时间。而且即使交了，结果还是被要求修改。有的时候还错过了热点的最佳发表时限。\u003c/p>\u003cp>看了这个拆页，我发现，如果运用减法的精要主义思维，不再做过多的搜集工作，只专注在写稿这个目标上，找出最大障碍予以排除，是不是会提升交初稿的效率呢？不管它多么粗糙，交出初稿，我才能和甲方进行下一个环节，可以再讨论再完善。\u003c/p>\u003cp>【分享A2便签】\u003c/p>\u003cp>学习这份拆页以后，我计划从明天早上八点开始，运用这个三步骤，重新规划我的工作，提升工作效率。\u003c/p>\u003cp>1、重新审视一下“写初稿”这个模糊的目标，将它数字化，变为“2小时写出2000字初稿”。\u003c/p>\u003cp>2、列出写稿子拖慢进程的障碍，至少找出三条，并排列优先级，只抓住一个，最慢进行者进行扫除。\u003c/p>\u003cp>3、扫除障碍时，注意运用动词下达行动指令\u003c/p>\u003cp>大家可以用这三步骤来试验一下，定一个减肥的减法计划。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1542626350000,"updated_at":1542626373000,"ria":true},{"id":4268,"topic":"创造全新的刺激事件来触发重要常规的执行","learn_goal":"学能够帮助他人找到一个刺激事件，能够很好的执行重要常规","remark":"大家是否还记得2008年北京获得8枚金牌的菲儿普斯吗？为何菲儿普斯能看似毫不费力地创造出这些惊人的运动奇迹呢？除了艰苦的训练之外，还有一个重要的因素，就是在训练时，教练为他设计了一些正确的常规，在菲儿普斯获得金牌前的几年里，他在每一次比赛中都遵循着同样的常规，这个常规，使得他的每一份努力都产生了事半功倍的效果。如果你想像菲儿普斯一样，每天能更轻松，有效的处理重要事务，而不被非重要事务挤得没有余地。那你就来听一下本次的拆书吧，拆书家王丽将带你拆解怎样设计一个可执行的重要常规习惯的方法。","level":"TF2-3","duration":20,"status":30,"type":0,"chaishujia":{"username":"王丽","city":"北京市"},"club":{"name":"北京宇宙中心分舵","city":"北京市"},"prologue":"大家好，我叫王丽，我的三个标签是：基督徒、建筑设计师、半新半熟的拆书家。又到年末了，大家今年定的目标都实现了吗？前不久，我看了一下自己年初定下的“2017年目标清单”，54个目标只实现了9个。没有实现的目标中有一个很重要的目标是“练习手绘”，但是我发现今年一次都没有练习，总是被发朋友圈，聊微信等其他的不重要事情挤掉。不知道大家有没有像我一样面对某件重要事情总是无法或很少去做的经历呢？请一个小伙伴分享一个自己的经历。\r\n学习者案例记录\r\n赵德祝分享：自己有一件特别重要的事情“打卡”要去做，但是发现自己经常会去看小说，玩游戏等，以至于没有时间去做“打卡”这件事。","ratings_count":1,"texts":[{"id":7253,"quote":"\u003cp>如果要让行为有新的变化，就不能局限于现有的刺激事件，\u003cstrong>我们可以创造全新的刺激事件来触发重要常规的执行\u003c/strong>。我用这种方法培养了写日记的常规习惯，它给我带来了神奇的功效。在很长一段时间里，我不过是三天打鱼，两天晒网地随便写写。一整天都拖着不写，然后到了晚上，我就会给自己找借口明早再写。但是，到了第二天早上我肯定又不会写，拖到晚上就有两天的东西要写，工作量太大了。因此，我再次拖延，就这样一天天地拖下去。后来，我听某人说，他养成了每天在固定时间写下寥寥数行的习惯。这听上去很容易，但我知道自己需要某种刺激物来提醒自己要在每天的特定时间内写作，否则我还是会像以前那样拖延。因此，我开始把日记本放在包里，紧挨着电话。这样一来，每天晚上当我把手机从包里拿出来充电（这个习惯我已经坚持得很好了）时，我就会看到日记本，它会提醒我在上面写东西。现在，写日记已经成了我的一种本能，仿佛自然天生，我甚至还对它心怀期待。我已经坚持写了10年，几乎一天都未落过。\u003c/p>","explains":"\u003cp>\u003cstrong>&lt;学习目标&gt;\u003c/strong>\u003c/p>\u003cp>在跟随我完成本次RIA现场学习后，学习者可以通过创造一个刺激事件，从而使得一件一直无法或很少去做的重要事件变成一件很容易执行的事件。\u003c/p>\u003cp>\u003cstrong>&lt;图书介绍&gt;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>B2：\u003c/strong>相信很多的小伙伴跟我们一样，明明知道有重要的事情要做，却老是去做其他的事情，导致没有时间去做重要的事。其实做重要的事情并不难，是否决定去做这件事才是让人头疼的事，那么今天，我将介绍给大家一个好的方法，就是将这件事发展为一种习惯，使其处于默认状态，让你做起来很轻松。这个方法来自于一本书—《精要主义》。\u003cstrong>F：\u003c/strong>这本书的作者格雷戈.麦吉沃思被誉为“21世纪的史蒂芬.柯维”,是精要主义的提出者，倡导者和领导者。这本书的核心价值观是让我们把有限的时间和精力投入到重要的事情上。\u003cstrong>A\u003c/strong>这本书与《断舍离》都是倡导精简的生活，不过《断舍离》侧重的是对物品的精简，这本书侧重的是对工作和生活的精简，对于现在应接不暇的选择和拥挤不堪的人生是十分必要的。\u003cstrong>B1：\u003c/strong>这本书提供了很多确实可行的方法，可以帮助我们专注于做少量重要的事，从而可以达到事半功倍的效果。\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&lt;What&gt;\u003c/strong>\u003c/p>\u003cp>大家先看一下我在片段中加粗的那句话-\u003cstrong>创造全新的刺激事件来触发重要常规的执行\u003c/strong>，这句话中的刺激和常规两个词大家可能不太懂，我给大家解释一下。\u003c/p>\u003cp>刺激：相当于是一种暗示，它是一个触发器，指示你的大脑进入某种自动行为模式，它就像开关一样，只要你打开它，习惯就会自然发生。\u003c/p>\u003cp>常规：就是惯常行为/习惯做法，是一种经常发生的，下意识的，忍不住去重复的行为。\u003c/p>\u003cp>\u003cstrong>&lt;举例说明&gt;\u003c/strong>\u003c/p>\u003cp>（现场进行一个实验-在现场喊“师父，超超师父”，师父会“抬头看我，并且问我怎么啦？”，这个实验中的“师父”就是刺激，“抬头看我，并问怎么啦”就是常规）\u003c/p>\u003cp>重要常规：就是完成重要事情的惯常行为/习惯做法。\u003c/p>\u003cp>\u003cstrong>&lt;How&gt;\u003c/strong>\u003c/p>\u003cp>为了让大家更加理解原文片段的步骤，那么我们来看一下片段中所提到的例子，作者是怎么把一件曾经无法完成的重要事情变为习惯的呢？大家可以带着下面的问题去阅读原文片段。\u003c/p>\u003cp>作者想要做的重要事情是？写日记\u003c/p>\u003cp>作者听到的成功方法是？在每天的固定时间写下寥寥数行的习惯 。\u003c/p>\u003cp>作者的做法是什么？\u003c/p>\u003cp>1.把日记本放在包里，紧挨着电话\u003c/p>\u003cp>2.每天晚上会把手机从包里拿出来充电\u003c/p>\u003cp>3.充电时会看到日记本，从而提醒自己写日记\u003c/p>\u003cp>\u003cstrong>&lt;细化行动步骤&gt;\u003c/strong>\u003c/p>\u003cp>通过研究作者的做法，我把书中提到的方法细化为下面几个步骤：\u003c/p>\u003cp>\u003cstrong>一、确定重要常规：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>1.选择重要事件：\u003c/strong>&nbsp;只选择一件你一直想要去做，但是一直未做或很少做的事件。（例如：写日记，跑步等）\u003c/p>\u003cp>\u003cstrong>2.制定实施方案：\u003c/strong>为重要事情设定频次和时长。例如：每天写几行/10分钟。\u003c/p>\u003cp>\u003cstrong>二、创造刺激事件：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>1.匹配习惯：\u003c/strong>根据重要事情的频次和时长，找到一个相对应的自己已经养成的好习惯，注意这个习惯一般是一个轻松的，不需要付出多少努力和意志力的习惯。（例如：每天坐地铁上班/出门拿钥匙/固定时间听休闲型音乐。）\u003c/p>\u003cp>\u003cstrong>2.设计或寻找暗示：\u003c/strong>这个暗示一定要和重要事件相关联。（例如：写日记-笔记本，听音乐-耳机，跑步-跑鞋/运动衣）\u003c/p>\u003cp>\u003cstrong>3.“绑定”暗示与匹配习惯：\u003c/strong>将暗示和匹配习惯建立关系，能达到当匹配习惯发生时（前、后），暗示就出现的效果。（例如：拿手机时，日记本就出现了。）\u003c/p>\u003cp>\u003cstrong>三、执行：\u003c/strong>当自己创造的刺激事件发生时，就执行重要常规。（拿出手机充电时，看到日记本，就写日记。）\u003c/p>\u003cp> &nbsp; &nbsp; &nbsp;\u003cstrong>&lt;自己的A2&gt;\u003c/strong>\u003c/p>\u003cp>看到这个方法，不禁又想到了自己的年初目标“练习手绘”，这个目标依然是我2018年一个重要目标，运用这个方法，我要怎么做呢？\u003c/p>\u003cp>\u003cstrong>一、确定重要常规：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>1.选择重要事件：\u003c/strong>练习手绘。\u003c/p>\u003cp>\u003cstrong>2.制定实施方案：\u003c/strong>每天晚上练习10分钟。\u003c/p>\u003cp>\u003cstrong>二、创造刺激事件：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>1.匹配习惯：\u003c/strong>我每天晚上回到家，都会把包放在桌子的一个固定位置上。\u003c/p>\u003cp>\u003cstrong>2.设计或寻找暗示：\u003c/strong>速写本。\u003c/p>\u003cp>\u003cstrong>3.“绑定”暗示与匹配习惯：\u003c/strong>把速写本放在我每天晚上放包的地方。\u003c/p>\u003cp>\u003cstrong>三、执行：\u003c/strong>当我晚上回家放包时，看到速写本，就可以练习10分钟的手绘。\u003c/p>","interaction":"\u003cp>\u003cstrong>&lt;\u003c/strong>\u003cstrong>促动学习者现场演练\u003c/strong>\u003cstrong>&gt;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家\u003c/strong>\u003cstrong>场景\u003c/strong>\u003cstrong>设计\u003c/strong>\u003cstrong>：\u003c/strong>\u003c/p>\u003cp>小王：是一个闲不住的人，他总是喜欢把自己的时间安排的满满的，他不仅工作特别的忙，还参加各种社群活动：比如行动派，攀登读书会，易效能时间管理等，最近他发现自己把一件最重要的事情忽略了，就是锻炼身体(年初的时候，为了能锻炼身体，还特意买了跑鞋，运动服，甚至还买了一个跑步机放在客厅里，希望自己每天可以跑步)。\u003c/p>\u003cp>小李：是小王的好朋友，刚刚学习完今天的方法，并且他知道小王有一些很好的习惯（1.每天早上6:00钟起床后会听30分钟的古典音乐休闲一下；2.每天晚上回家后都会充一杯柠檬茶喝；3.每天晚上回家后一进门就会换上拖鞋；4.每天晚上回家后一进门就会把包挂在门后的挂衣架上）。\u003c/p>\u003cp>有一天，小王请小李到家里吃饭，吃饭时小王向小李诉苦说感觉自己每天都在瞎忙，做了很多事，但是自己一直想要在跑步机上跑步这件事却没有做，不知道怎么来改变这个现状。小李一听，心里想这不正好可以用我前段时间学习的”创造全新的刺激事件来触发重要常规的执行“的方法吗？\u003c/p>\u003cp>请大家分别扮演小王和小李，请小李根据今天所学到的知识帮助一下小王。给大家7分钟的时间。\u003c/p>\u003cp>\u003cstrong>学习者\u003c/strong>\u003cstrong>演练\u003c/strong>\u003cstrong>记录：\u003c/strong>\u003c/p>\u003cp>小王：小李，我最近有一件特别苦恼的事，我觉得我现在每天特别忙，每天做了很多事，但是到了晚上想一想呢，不知道自己做了些啥，其实我真正想做的事是每天可以坚持跑步。（\u003cstrong>确定重要常规\u003c/strong>）\u003c/p>\u003cp>小李：看不出来啊，你真是太谦虚，客气了，看你每天朋友圈里都会分享早上起来听古典音乐啊，你这个习惯真的是挺好的。\u003c/p>\u003cp>小王：可能是每天做的事情，太多太杂啦，老想不起来跑步。\u003c/p>\u003cp>小李：哦，是这样啊，我想到自己最近正好看了一本书叫《精要主义》，里面有一个方法就是把我们想要做的重要事情和我们已经养成的习惯做一个关联，你想一想你想要跑步的这件事情跟你已经养成的习惯，看看能不能建立什么关联，比如说你晚上回家一进门就会换鞋，那你是不是可以放一双运动鞋，一件运动衣在门后提醒自己。\u003c/p>\u003cp>小王：你提醒我了，我回家时习惯一进家门就换上拖鞋，然后把包挂起来，那我现在可以在拖鞋旁边放一双运动鞋，以后我每天回到家就可以先换上运动鞋。（\u003cstrong>创造刺激事件\u003c/strong>）\u003c/p>\u003cp>小李：那你这样就可以在回到家后的第一时间跑步了，跑完步再把拖鞋换回来。（\u003cstrong>执行\u003c/strong>）\u003c/p>\u003cp>小王：你帮我梳理了一下，非常好，你的这个方法对我帮助很大。\u003c/p>\u003cp>小李：以后你要多请我吃饭啊。\u003c/p>\u003cp>小王：对了，我每天跑多长时间合适？\u003c/p>\u003cp>小李：看你的适应量，先慢慢来，先少跑点。\u003c/p>\u003cp>小王：那我先从跑30分钟开始吧？\u003c/p>\u003cp>\u003cstrong>学习者\u003c/strong>\u003cstrong>演练中采用到的方法梳理\u003c/strong>\u003cstrong>：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>一、确定重要常规：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>1.选择重要事件：\u003c/strong>在跑步机上跑步。\u003c/p>\u003cp>\u003cstrong>2.制定实施方案：\u003c/strong>每天晚上跑30分钟。\u003c/p>\u003cp>\u003cstrong>二、创造刺激事件：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>1.匹配习惯：\u003c/strong>每天晚上回家，会换上拖鞋，把包挂在门后。\u003c/p>\u003cp>\u003cstrong>2.设计或寻找暗示：\u003c/strong>运动鞋。\u003c/p>\u003cp>\u003cstrong>3.“绑定”暗示与匹配习惯：\u003c/strong>把运动鞋放在拖鞋旁边，每天晚上回家后，准备换鞋时就可以看到运动鞋。\u003c/p>\u003cp>\u003cstrong>三、执行：\u003c/strong>回家后，先换上运动鞋，在跑步机上跑30分钟。\u003c/p>\u003cp>\u003cstrong>&nbsp; &nbsp; &nbsp; &nbsp;&lt;结语\u003c/strong>\u003cstrong>&gt;\u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 最后，我总结一下今天的内容，今天所讲的这个方法，是一个主动去把重要事情变得简单并容易执行的方法，这种方法可以让你选择的重要事件沿着默认的路径实现，就像一个自动驾驶仪一样。希望你可以使用这个方法，让自己的重要事件执行的更容易。谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1513517377000,"updated_at":1513517377000,"ria":true},{"id":4012,"topic":"禀赋效应陷阱-放弃就是最大的赢","learn_goal":"学会应对拥挤不堪的工作与生活","remark":"大家都知道沉没成本，对不对？其实除了沉没成本还有一些常见的陷阱和对应的贴士。今天由榕冰为你解析其中的一个陷阱：禀赋效应及相应的对策。学会这一招，跳出禀赋效应陷阱，自律地追求“更少,但更好”。你就会以最少的代价从拥挤不堪中解救自己！\r\n","level":"TF1-1","duration":15,"status":0,"type":0,"chaishujia":{"username":"张溶冰","city":"北京市"},"club":{"name":"北京翰林分舵","city":"北京市"},"prologue":"【自我介绍】1分钟\r\n大家好，我叫榕冰，很多人会以为我的名字取自光荣的士兵，其实不然，是冰雪融化的榕冰，希望我能够做到温暖自己、温暖他人。下面介绍一下我的三个标签。第一个标签是冥想，在学习冥想之后，我开始试着利用工作的间歇冥想几分钟，发现确实能够起到好好休息的效果，为自己带来充沛的精力；第二个标签是8月轮值主席，这个月由我组织翰林周三国贸场的拆书活动，在现场为大家服务，如果有任何建议和问题，欢迎和我私下交流。第三个标签是早睡早起社群组长，早睡早起坚持了8个月；上个月是我第一次当组长，为14个小伙伴提供了贴心的服务，据统计，我们小组续报人数10个人，留存率达到71%，做的还不错。8月份我将继续留任。有想参加早睡早起活动的小伙伴，可以和我私聊哦.\r\n【拆书帮介绍】\r\n大家对拆书了解吗？今天现场有新来的小伙伴，我来为他们解释一下，请了解的小伙伴也加深一下印象哈。拆书是一种读书方法，拆书帮的帮主赵周出版了一本书：这样读书就够了，他在书里详细介绍了这种方法。拆书法并不是要把书拆了，而是将阅读书籍这一个过程变成RIA三个明确的步骤，更加适用于成人学习。首先R是对书本的某一片段进行阅读，I是用自","ratings_count":0,"texts":[{"id":6968,"quote":"\u003cp>主题：如何避开禀赋效应陷阱\u003c/p>\u003cp>书籍：精要主义\u003c/p>\u003cp>页数：165~166\u003c/p>\u003cp>\u003cstrong>陷阱一，禀赋效应\u003c/strong>\u003c/p>\u003cp>主人翁意识效力非凡。就像一句谚语所说的那样，世上从来就没有人会洗租赁的车，这是禀赋效应在作祟，也就是当一个人没有某件物品时，他就倾向于低估这件物品的价值，而当他一旦拥有该物品，就会倾向于高估它的价值。\u003c/p>\u003cp>在一项证实禀赋效应作用力的研究中，诺贝尔经济学奖获得者，丹尼尔卡尼曼，及其同事做了一项实验，他们把被试随机分成两组，并只给第一组每人发放了一个咖啡杯，然后问第一组人，这个咖啡杯，他们想要卖多少钱？问第二组人，他们愿意花多少钱来买这个杯子，结果，“拥有”杯子的人表示，低于5.25美元不卖，而没有杯子的人只愿花2.25~2.75美元来买这个杯子。换句话说，仅仅是因为拥有的缘故，就让这些杯子的主人们，高估了杯子的价值，并且更加不愿舍弃它们。\u003c/p>\u003cp>在你的生活中，我相信你一定可以想到这样的东西，一旦你想要放弃它们的时候，它们就会显得更加有价值。想象一下，一本闲置在书架上多年未翻的书，一个仍未开封的厨房用具，或者一件从米尔德里德银妈那里买的但从未穿过的运动衫，不管他们是否对你有用，或者让你高兴过，它们属于你这个事实，都会让你觉得它们比不属于你的时候更有价值。\u003c/p>\u003cp>遗憾的是，对于不重要的事情以及不重要的物品，我们都有这样的偏见。如果自己是团队主管，一向毫无进展的工作项目就会显得格外要紧。如果自己是募捐活动的召集人，那么不参加志愿糕点售卖活动就会难上加难。当我们感到自己是某项活动的“主人”时，就倍加欲罢不能。但是，这里有一个有用的小窍门。\u003c/p>\u003cp>\u003cstrong>对策一，假装你还不曾拥有它\u003c/strong>\u003c/p>\u003cp>汤姆斯塔福德，描述了一种简单的克服禀赋效应的方法。不要问：“这件物品我估值多少？”而是问：“如果手头没有，我愿意花多少钱来得到它？”对于机会和义务，也应该采取同样的方法。不要问：“如果错过了这个机会，我会有怎样的感受？”而是要问：“如果我没有这个机会，我愿意花多大的代价去得到它？”同样我们也可以问：“如果我不是已经参与了这个项目，我愿意费多大的劲儿来参与其中？”\u003c/p>","explains":"\u003cp>\u003cstrong>【分享I便签】\u003c/strong>\u003c/p>\u003cp>这个片段讲的是禀赋效应和对策。首先，什么是禀赋呢？这个词看起来文绉绉的，其实很好理解。简单的说就是人或组织所拥有的素质能力，也可以指所拥有的东西；和禀赋效应相对应，有个成语：敝帚自珍。还有一句俗语：破家值万贯，都有禀赋效应的影子，解释的很贴切。\u003c/p>\u003cp>这种情况确实很常见。举个例子，虽然我骑共享单车次数不多，但还是时不时就会遇到扫码开锁后，要么脚蹬坏了，要么车座无法调整，要么蹬起来咯咯作响的情况，最绝的一次是我在自认为已经很有经验，迅速检查确认刹车、车座、脚蹬都完好后，开心地扫码解锁，骑上车就准备走了，结果猛蹬几圈后，车居然停在原地纹丝不动，差点儿摔倒，把我惊着了。赶紧下车，才发现共享单车的链条竟然被卸下来了！没有链条的自行车，怎么骑？真是无语了。所以说共享单车虽然为大家提供了便利，解决了短距离的出行问题。但和自己家的自行车相比，却更容易被损坏，这就是禀赋效应的破坏力哇。\u003c/p>\u003cp>禀赋效应威力如此之大，难道就没有对策吗？世界是很奇妙的，有矛就有盾。它的对策其实很简单：当你要舍弃一个东西的时候，不要把它当成是自己的。而当你应该珍惜它的时候，一定要把它当成是自己的。\u003c/p>","interaction":"\u003cp>\u003cstrong>【分享A1便签】\u003c/strong>\u003c/p>\u003cp>想起来以前家里大扫除的时候，因为书架上的书大部分都是我的，所以理所当然就由我来整理书架。我妈叮嘱我，让我把不需要的书整理出来卖掉或送人。老实讲，平时那些书我并不看的，但是每当这个时候，我就会一边整理一边阅读。说是整理书架，实际上就是看了半天书，哪本也不舍得仍，效率很低，经常被我妈嘲笑：不就是把不要的书挑出来嘛，看把你难的，至于吗？而我却觉得这些书都很好啊，还没怎么看，扔掉多可惜啊。但其实我们俩都知道，这些书留下来我也不看的。母女俩经常为此拌嘴，我们都没有意识到，这就是禀赋效应在作怪啊。\u003c/p>\u003cp>那么我们应该怎么做才能高效的收拾整理书籍，避开这个坑呢？方法就像上面提到的那样简单而有效：那就是假装它不是你的。当我第一次读到这儿的时候，正好坐在堆满书的房间里，其实自己也觉得这个环境很不舒服了。我立刻进行了尝试，把书房想象成一家书店，我拿起书架上、书桌上的每本书，就会问自己一个问题：这本书到底有多好？值得你花这么多钱把它买回家吗？如果值得，我就把它放在书架上整理好；如果不值得，我就把它扔进箱子里。就这样，用这种方法我迅速的过了一遍书房，果真挑出了很多过时的、无用的书，堆放在箱子里，战果超级显著，书房终于显得很整齐了，自己看着对自己都很满意。\u003c/p>\u003cp>\u003cstrong>【分享A2便签】\u003c/strong>\u003c/p>\u003cp>在收拾好书房后，我就觉得其它房间有些辣眼睛了，太乱，不想看。我们的家是温暖的港湾，应当被打理的整洁干净温馨。但是刚开始的整洁，在居住了几年之后，就被我买买买的塞满了很多东西，显得拥挤不堪，收拾起来也是有心无力。在我收拾利索书架后，我打算使用这个方法帮助我收拾其它房间：我先假设房间里的东西都不属于我，我会怎么收拾整理呢？会把这些东西都留下来吗？只要在脑海里想像房间在我的努力下将会变得多么优雅整洁，我就忍不住要开始行动，不再是茫然发愁、不知所措，留下一堆东西，无处可放。\u003c/p>\u003cp>想法改变，人的行动就会随之变化。躲开禀赋效应陷阱的对策，对我们的工作也是大有帮助的，小伙伴们可以观察自己并践行，比如你所做的项目是否真正有必要继续？用这个对策，想象这是一个尚且不属于你的项目，问问你自己，是否还希望它进行下去吗？\u003c/p>\u003cp>希望小伙伴们能够熟悉这个对策，运用它避开禀赋效应陷阱，更好的工作和生活。\u003c/p>\u003cp>我今天的拆解到此结束。谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1510624274000,"updated_at":1510657201000,"ria":true},{"id":3575,"topic":"怎样设置工作与生活的界限，免受他人事务烦扰","learn_goal":"怎样设置工作与生活的界限，免受他人事务烦扰","remark":"","level":"TF2-4","duration":60,"status":0,"type":0,"chaishujia":{"username":"胡奇伟","city":"郑州"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"本次拆书学习目标1：通过本次拆书学习，我们能学会在遇到打扰自己的事项时纪录那些事件，并从这些事件中找到自己的界限，从别人的干扰和繁忙中解脱出来，让自己的个人价值最大化。目标2:通过本片的的学习，学习者可以学会通过制定“优先事项”就界线问题提前达成共识，从而避免浪费彼此的时间，提升合作效率。 F：本次拆书的片段节选自《精要主义》，作者是格雷戈•麦吉沃恩，他被誉为“21世纪的史蒂芬•柯维”，作为一名精要主义的提出者、倡导者和领导者，致力于帮助个人和企业摒弃琐碎，直抵精要。作为世界经济论坛全球青年领袖，他的思想影响了多国政要和众多知名企业家。 A：这本书作为一本致用类图书，豆瓣评分7.9分，整本书理论和实例相结合，层层递进，紧凑而不枯燥地向你讲述如何精简自己的工作和生活状态，读过本书你能轻松地将书中呈现的知识学以致用。 B：如果你现在觉得自己生活和工作拥挤不堪，每天都有忙不完的事儿，而自己的价值却没有突出，那么这本书就是为你准备的，正如副标题所说，应对拥挤拥挤不堪的生活，达到个人价值巅峰！同时，如果你在工作中总是被人打扰，让你不胜其烦，那么今天我们的学习就是专门解决这个问题的！","ratings_count":0,"texts":[{"id":6467,"quote":"\u003cp>当我让领导者们确定自己的界线时，他们几乎都做不到。他们知道自己是有一些界线的，但就是不能用语言表达出来。一个简单的事实是：如果你不能和自己、和别人说清楚这些界线，那么你期待别人能够尊重或者找到你的界线，恐怕也是不现实的。\u003c/p>\u003cp>想想那个总是把你从精要道路上拉出去的人，列一个坏事者清单——这个人提出的各种要求和行为，你都拒绝，除非它们正好和你自己的优先要事或者事项安排有交叉重叠之处。\u003c/p>\u003cp>找到你的坏事者的另一种快速测试方法就是，每一次你感到别人的要求冒犯了你或欺骗了你，你都要记下来。你无需通过某种极端的方法就能注意到它。即使是一个令你不快的小小的“刺痛”（我觉得这种描述有助于形容你的界线所受到的那种微小侵犯），不管是来自于一个你不想得到的邀请，还是一个不请自来的“机会”，抑或是一种帮个小忙的请求，都是你发现自己隐藏的界线的线索。\u003c/p>","explains":"\u003cp>大家都读完了，这个片段说的是如何确定自己的界线，让自己保持在精要道路上\u003cstrong>。（适用边界）\u003c/strong>毕竟，如果你不能和自己、和别人说清楚这些界线，那么就会有人把他们的问题当成我们的问题，要求我们牺牲自己的时间来解决他们的问题，这样的话我们的时间和精力就被榨取了，服务的是他们的事务而不是我们的，这样做会直接导致我们偏离自己的目标，无法完成自己的任务。\u003c/p>\u003cp>我们来看原文拆页：\u003c/p>\u003cp>\u003cstrong>（细化步骤）\u003c/strong>明确边界的具体的方法可以细化为：\u003c/p>\u003cp>一、找出那个总是把你从精要道路上拉出去的人，列一个“坏事者”清单。\u003c/p>\u003cp>二、明确你自己的优先要事或者你的to-do-list。\u003c/p>\u003cp>三、“坏事者”清单里的人提出的各种要求和行为，除非跟你的要事或to-do-list有交叉重叠之处，否则都拒绝掉。\u003c/p>\u003cp>四、记录下来其他人提出的让你有些小不爽的请求或者行为。\u003c/p>\u003cp>五、整理以上清单，明确自己的界线。\u003c/p>\u003cp>\u003cstrong>（不那么做的坏处）\u003c/strong>大家可能会觉得，我们不是应该帮助他人吗？别人开口请求帮助怎么好意思拒绝？我们当然应该提供帮助，关爱他人，使他人的生活有所改变。但是如果别人把他们的问题变成我们的问题，那么我们就不是在帮助他们，而是在纵容他们，除非它们正好和你自己的优先要事或者事项安排有交叉重叠之处，否则我们的任务不仅无法很好完成，同时也会剥夺他们解决问题的能力。\u003c/p>\u003cp>我们校区有一个老师，就喜欢把自己的事情或者问题让别人帮她解决。写方案不知道怎么写，就直接各种问你到最后，哪怕网上或者之前做的有方案可以参考，也是这样。跟会员家长沟通本来是老师的职责，却以不知道怎么跟家长说，怕沟通不好为由让领导帮她做这些事情等等。这就是一个典型的“坏事者”，而我的工作职责是做外联、安排试听课、促进报名、处理家长意见及学前班事宜。刚开始的时候我也是觉得，都是一个校区的同事，挺不好意思拒绝的，可是有好几次因为帮她做方案耽误了我安排试听课的工作，而她对于策划方面仍然是一副“小白”的样子，我才意识到，这事儿不能再继续了。\u003c/p>\u003cp>后来我通过这个拆页学会了在明确我的优先要事和to-do-list的前提下，除非她的要求和我的工作职责有交叉，比如家长有意向转介绍，一般我都会提醒她多思考怎么处理这些事，先做做试试，从而拒绝她的其他要求。这样我才能做好我的本职工作，而她也试着开始自己写方案、与家长沟通了。对于其他老师的一些要求，比如让我帮忙准备教具、去别的校区拿资料等，也是一些让我感到略微“刺痛”的请求，这时就需要把这些事情记录下来，除非顺路、和我的职责有交叉或者我处于空闲状态，一般都会让他们知道这是我的界线。\u003c/p>","interaction":"\u003cp>\u003cstrong>A1\u003c/strong>\u003cstrong>（显像提问）：\u003c/strong>现在请大家回想一下，在你的工作和生活中，有哪些人经常让你帮他做一些与你的工作内容无关的事情或者有哪些请求让你感觉不舒服？回想好的伙伴请举手发言。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 丽芳：前两天公司里的测试提出来一个问题，说研发总是指派给他们一些不属于测试的工作，但是研发觉得我们是一个项目组的，为了我们的项目，你们测试应该帮我们做一些工作\u003c/p>\u003cp>&nbsp; &nbsp;&nbsp;（\u003cstrong>反馈\u003c/strong>）你的例子非常贴切的展示了我们设置自己界线的必要性，因为研发把自己的工作职责推给别人了\u003c/p>\u003cp>\u003cstrong>A1+\u003c/strong>\u003cstrong>（反思加工经验）：\u003c/strong>我们刚才已经回顾了自己遇到的各种与“坏事者”有关的经历，我相信，明确我们的界线是我们精益工作的开始。那根据我们拆页中的建议，再结合我们刚才说的经历，我们要通过哪些步骤来明确自己的界线呢？请大家详细说明。\u003c/p>\u003cp>丽芳：我们之前开会的时候给领导提这个问题了，领导在开会的时候问测试都做了什么事情的时候，他说不出来，因为比较琐碎。通过今天的学习我可以给测试人员提这样一个建议：他可以列出来自己都做了什么，向领导据实汇报。并把自己的职责再强调一遍，明确自己要做哪些，那些自己不做，因为来面试的时候领导已经给他说过测试的职责范围了，同时也可以向大家说明，近期他的工作目标是什么，把他的计划和内容跟大家说明一下\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":6468,"quote":"\u003cp>我曾与一位同事搭档工作，他处理项目的方法与我截然相反。因此，有人预测我们之间会闹得不可开交。然而，我们的工作关系却十分融洽。这是为什么呢？因为从合作一开始，我就郑重其事地亮出了自己的优先事项，说明了在项目存续期间哪些额外的工作我乐意做，哪些不乐意做。“让我们说好我们想得到什么，”我开门见山说道，“以下这些事情对我来说很重要……”而且，我让他也这么做。\u003c/p>\u003cp>这样，我们就完成了一个“社会契约”，这与本章开篇故事中金永和他老板定的那个可不一样。就双方真正要着力实现的目标提前达成共识，互相了解对方的界线，这让我们避免了浪费彼此的时间，不去给对方提出徒增烦恼的要求，也不去分散对方的注意力，使其无法专注于要紧之事。结果，我们都在这个项目上实现了个人贡献峰值，而且尽管也有意见不同，但在整个工作过程中，我们相处的十分融洽。\u003c/p>\u003cp>通过不断练习，你会发现，设定界线会变得越来越容易。\u003c/p>","explains":"\u003cp>这个片段说的是在明确自己的界线后，怎样与同事相处时使用界线，学习完这个片段，我们能学会如何在别人提出要求之前就能知道你的界限，知道你会做哪些，不会做哪些工作，从而不打扰你；同时你也能尊重对方的界限，使得双方的贡献最大化。\u003c/p>\u003cp>\u003cstrong>在操作时，我们可以这样做：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>一、就大家要着力完成的目标/事项提前达成共识\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp; &nbsp; &nbsp; &nbsp;\u003c/strong> 二\u003cstrong>、明确亮出自己的优先事项或者to-do-list\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp; &nbsp; &nbsp;&nbsp; 三、说明自己的界线，确定哪些额外事情可以做，哪些不乐意做\u003c/strong>\u003c/p>\u003cp>\u003cstrong>四、让对方明确他的优先事项，了解他的界线\u003c/strong>\u003c/p>\u003cp>\u003cstrong>五、相互不给对方提出徒增烦恼的要求，不去分散对方的注意力\u003c/strong>\u003c/p>\u003cp>&nbsp;（\u003cstrong>预防\u003c/strong>\u003cstrong>异议\u003c/strong>）大家可能会觉得，话虽如此，可大家都是同事，设置这么多条条框框的不好相处啊。。然而，不说明你的界线代价会更高——你会失去选择做最重要事情的能力，这样也就失去了实现你个人价值最大化的机会。同时，如果你能把自己的价值最大化，即便你看起来有些“不近人情”，可是你最终将赢得大家的尊重。\u003c/p>\u003cp>&nbsp; （疑问）大家都挺熟的，感觉直接跟对方说自己的界线感觉开不开口怎么办？\u003cbr>\u003c/p>\u003cp>&nbsp; （\u003cstrong>回应\u003c/strong>）大家是否都有这样的感觉？有的话我们可以简单讨论下（1、我觉得话说到前头挺好的；2、我觉得贴一个告示很醒目，且不伤和气）\u003c/p>\u003cp>&nbsp; （\u003cstrong>举例\u003c/strong>）我自己在学习完这些内容之后，最近公司正在搞招生大pk，所以我们的共同目标就是在这两个月内尽量多的完成招生。我近期的目标是尽量多的邀约试听课，准备课后报告会，所以在我们校区的例会上我就直截了当的说出我的优先事项：邀约意向客户，准备课后报告会，完成订单。并明确了我的界线——在一周内，我会在周二、周四、周五邀约客户和准备报告会，为了我们校区的业绩，在此期间，一切与此无关的事情我都不会接受，除非你是给我提供意向客户或者有好的建议给我。受此影响，我们的一个老师也明确了她的优先事项和界限：准备要进行的试听课教耗材、备课，除了给她报备需要安插的试听课学生让她多准备教具外，她不希望被打扰。大家都明确了彼此的最重要目标和界线，相互之间都尊重彼此的优先事项和界线，不去给对方提其他要求，所以大家的效率非常的高，仅本周就完成本月的业绩目标的一半要求。\u003c/p>","interaction":"\u003cp>刚才我们学习了明确自己的界线及制定社会契约，我相信通过这些操作能使我们的价值最大化，下面我们来玩儿一个角色扮演，通过演习来熟悉这些过程。\u003c/p>\u003cp>\u003cstrong>A3\u003c/strong>\u003cstrong>：\u003c/strong>设想一下，你们部门准备上马一个新项目，你（A）负责方案设计，这关系着项目的成功与否，思路的流畅和连续性对你来说非常重要！你需要整块的时间来琢磨方案的问题。你的同事B负责对外连接，经常需要出去跟客户对接，可是他这个人有些随意性太大，虽然有前台人员，但是他跟你比较熟，以前经常会让你帮他看一些数据，帮他找一些资料拍给他，甚至让你帮忙拿快递。现在请大家进行小组内角色扮演，根据刚学习的内容，明确自己的界线，并与对方制定社会契约，使双方的价值最大化。现在请大家小组内讨论预演6分钟，6分钟后，每组选出两个人，一个扮演A，一个扮演B，以话剧的形式进行现场展示分享。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;好的，时间到，大家讨论演练的怎么样了？哪一组先来？\u003c/p>\u003cp>丽芳：我是旁白，冯颖是A，文静是B\u003c/p>\u003cp>旁白：A和B关系挺不错的，而且B因为业务原因经常在外面跑，所以B经常给A打电话寻求帮忙，但是A最近在做一个项目的方案，方案还很重要，需要整块的时间和流畅的思路\u003c/p>\u003cp>B：在忙吗？我有一些事情需要你帮我一下，是关于一些数据和客户资料的，我下周要出差，你看能不能帮帮我整理一下？\u003c/p>\u003cp>A：我现在在做咱们公司的新项目方案，正在理思路，时间比较紧急，你说说看是哪些数据和资料，如果和我的这个方案有重合或者辅助支撑的地方，我可以帮你找找，因为我不希望思路被打断，请理解。。你还有其他事情吗？\u003c/p>\u003cp>B：还有就是我下周有几个快件希望你能帮我发一下，还有就是我做外联需要拍照和一些简单的文案，你能帮我弄一下吗？\u003c/p>\u003cp>A：这些事情虽然不大，但是会打断我做方案的思路，如果是休息时间我可以帮你收发快件，如果要做拍照的话花费时间应该不会短，因为我现在做的这个项目的方案要花费大块的时间和其他小组的人一起协作，我没办法帮你做，你看能不能找一下咱们前台的工作人员抽时间帮你做一下吧\u003c/p>\u003cp>B：嗯，好的\u003c/p>\u003cp>（\u003cstrong>反馈\u003c/strong>）大家掌声鼓励一下！这个演练体现出了设置界限以及说明界限，非常好！\u003c/p>\u003cstrong>A2[分步催化1]\u003c/strong>：试想一下，你有个报告要出，只剩半小时时间了，正在拼命赶工，结果有个同事找你让你帮忙，这时候你会不会觉得很抓狂？那我们再想想\u003cstrong>未来一周内\u003c/strong>会不会出现这种情况：有同事在你工作的时候让你帮忙，打断你的思路、推迟你的工作进度而让你觉得不胜其扰？也请想一下你会不会有可能打断别人的工作？给大家2分钟时间思考，等下请小伙伴分享一下。\u003cbr>\u003cbr>丽芳：我们公司每周五下午2点半要开周例会，在开会前我需要准备本周的项目情况资料。准备这个资料需要一上午的时间，这样一来，周五上午基本上都不能分心。结果有一次，有个同事打电话说，有个版本需要我发给现场，但是原本这个工作不属于我的份内，但碍于情面我还是同意了。当然特别着急，还得联系现场的人还得找SVN库里的版本资料。导致我中午吃饭也没去，生气又懊恼。我觉得如果我不采取措施，这种情况还会发生。\u003cbr>\u003cbr>（\u003cstrong>反馈\u003c/strong>）芳姐说的这个情况非常贴切的说明了我们被打扰的状况，我相信大家都有可能会遇到。\u003cbr>\u003cstrong>A2[分步催化2]\u003c/strong>：请结合刚才大家想到的被打扰的情况，思考一下今天咱们拆书学习的明确界限和制定社会契约，你要如何做，才能在以后的工作中避免被别人打扰，或者打扰别人，请在小组内分享你的应用丽芳：嗯，我会整理我一周的工作内容，把工作内容按照优先级列出来。抽空和这个同事沟通，给他看看我周五的工作内容，说明例会资料的重要性（公司副总和各个项目经理都要参加）。也建议他按照这样做，最后一块沟通一下什么时间可以提供帮助，然后我们一块把工作做好。\u003cbr>（\u003cstrong>反馈\u003c/strong>）规划应用直接有效，能观测到，马上就能应用！\u003cp>\u003cstrong>结语：\u003c/strong>相信大家已经学会了明确界线和制定社会契约，希望大家可以经常使用，早日走向个人价值巅峰！谢谢大家的参与和配合！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1504433274000,"updated_at":1504530449000,"ria":true},{"id":3574,"topic":"通过低风险的方法排除不重要的事件，精简自己的工作和生活","learn_goal":"通过低风险的方法排除不重要的事件，精简自己的工作和生活","remark":"","level":"TF2-3","duration":25,"status":0,"type":0,"chaishujia":{"username":"胡奇伟","city":"郑州"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好，我是一级拆书家胡奇伟，今天准备过TF2-3，非常感谢大家的支持！为了方便一会儿的拆书环节，现在请大家三人一组进行分组。 本次拆书的主题是逆向试行，通过本次拆书学习，我们能学会如何通过低风险的方法来排除工作和生活中不重要的东西，精简自己的工作和生活。 F：本次拆书的片段节选自《精要主义》，副标题是“如何应对拥挤不堪的工作和生活”，作者是格雷戈•麦吉沃恩，他被誉为“21世纪的史蒂芬•柯维”，作为一名精要主义的提出者、倡导者和领导者，致力于帮助个人和企业摒弃琐碎，直抵精要。作为世界经济论坛全球青年领袖，他的思想影响了多国政要和众多知名企业家。 A：这本书作为一本致用类图书，豆瓣评分7.9分，也算相当不错了，整本书理论和实例相结合，层层递进，紧凑而不枯燥地向你讲述如何精简自己的工作和生活状态，读过本书你能轻松地将书中呈现的知识学以致用。 B：如果你现在觉得自己生活和工作拥挤不堪，每天都有忙不完的事儿，而自己的价值却没有突出，那么这本书就是为你准备的，正如副标题所说，应对拥挤拥挤不堪的生活，达到个人价值巅峰！","ratings_count":0,"texts":[{"id":6466,"quote":"\u003cp>近年来，“原型法”理念在商界很流行。构建一种原型或者大尺度模型，可以让一家公司试运行一种理念或产品，而不用预先进行大规模投资。同样的理念可以被反向运用，以一种相对而言低风险的方法排除不重要的东西，领英的董事长丹尼尔·夏皮罗称这种方法为“逆向试行”。\u003c/p>\u003cp>在逆向试行中，你可以检验取消一项尝试或活动是否会产生负面效应。例如，我合作的一位领导者在公司里担任了一个新的高管职务，他接手了其前任费了很大力气实施的一项工作：每周为其他领导者写一份大篇幅、非常直观的、涉及多个主题的报告。这极大地消耗了他团队的精力。他假设这个报告并未给公司带来太多价值。为了检验这个假设是够正确，他进行了一次逆向试行。他停止了报告的发布，等着看会出现什么样的反应。他发现没有人对这个报告流露出想念的意思，几个星期以后，甚至都没人提到这个报告。结果他提出结论：此报告对公司并无重要意义，可以取消。\u003c/p>\u003cp>在我们的社交活动中，也可以进行类似的逆向试行。你是不是经常会对客户、同事、朋友或者家庭成员做出一些承诺？你总是觉得这些能给他们带来重要影响，但实际上他们可能根本没有注意到？悄悄地取消或者至少把一个活动缩减几天或几周，你大概就能评估出它是否真的重要或者是否真的没人在乎。\u003c/p>\u003cp>就算用上了这些技巧，“不履行承诺”还是比从一开始就不承诺要难。要对已经承诺的事或人说“不”，是会让人深感愧疚，但我们也得直面它，没有人愿意违背自己说过的话。不过，学会这样做，以自己的勇气、专注和自律赢得尊重，是成为精要主义者的关键所在。\u003c/p>","explains":"\u003cp>大家都读完了，原文并不复杂，说的是如何通过逆向试行来排除一些自己承诺过的但别人并不在乎或者并无重要意义的事情，从而给自己做减法，用排除这些事情节省的时间去做更有意义的事情，向精益主义者更进一步。\u003c/p>\u003cp>\u003cstrong>（意译案例）\u003c/strong>有小伙伴知道，近期我们校区接手了一个学前班，刚接手的那段时间简直忙的不可开交，不仅是上课和课间的事情，还有就是从他们之前的学校带过来的习惯，就是接送孩子：每天早上和中午上学的时候要有一个专门的人下楼接孩子，放学的时候要把孩子送下去。当然我们也继续了这个习惯。这对于本来人手就不多的我们校区来说简直就是火上浇油，因为每天都要有一个老师负责接送孩子。而且孩子家长到校时间还不一定，从30分钟到1个小时不等，这就造成了很大的人力和精力浪费。后来我们发现只有两三个家长是在早上上班的时候在固定时间开车把孩子送到楼下，不方便上楼，之后中午和下午都是老人来接送，其他家长都是全职妈妈或者老人，每天悠哉悠哉的把孩子送过来，再悠哉悠哉的回去，于是我们就假设除了开车不方便上楼的家长外，其他人对于下楼接送孩子这件事并不在乎，为了检测这个假设是否正确，我们只在早上7点半到7点50之间下楼接开车送过来的孩子，剩下的时间就在教室带孩子进行早读，前台老师负责给孩子接水，迎接晚来的孩子。中午跟下午老师不下楼接送孩子，只在校区前台等着跟上楼的家长交流孩子的近况，就这样试行了两个多星期，发现没有家长对下楼接孩子的事情提出任何意见，相反，他们对我们就孩子的表现和他们进行交流这件事表达了感激，因为他们觉得我们比他们之前的老师对孩子的观察更仔细、更认真负责……所以我们得出结论，只要在早上固定的时间接开车送孩子不方便上楼的家长就行，其他孩子可以由家长自行送上楼，以此来调整老师们的时间，老师们也能喘口气，去做更多自己的事情。\u003c/p>\u003cp>&nbsp; \u003cstrong>（细化步骤）\u003c/strong>这就是逆向试行的一般步骤：一、发现工作和生活中有哪些你觉得耗费精力又不确定其价值但还在做的事情；二、假设这些事并不能给公司、同事或者朋友带来太多价值；三、验证假设，停止这些事情一段时间，等着看会出现什么样的反应；四、得出结论，这件事不重要（或重要），可以取消（或者继续）。\u003c/p>","interaction":"\u003cp>A3：我们刚学习了用“逆向试行”的方法来精简自己的工作和生活。现在一起来做一个演练，\u003cstrong>（场景设计）\u003c/strong>场景是这样的，小胡所在的集团有三四十家直营校区，每周五上午所有校长人都要早上九点钟到总部去开会。这个会议说的都是一些杂七杂八的事情，就是各个校区提出的遇到的情况以及一些需要解决的问题，每次开会都要就一些事情大家七嘴八舌讨论很久出不来答案，比方说关于工装的问题已经讨论了两个月了还没结果。开会时间从早上九点到下午两点，关键是还解决不了问题，而小胡作为一名新来的大区市场主管，与校区运营方面关系不大，为了开会也耽误不少小胡的其他事情。\u003cstrong>（小组讨论）\u003c/strong>现在我们来做一个演练，每组出两个人，一个人是小胡，一个人是小胡的领导，大家来演练一下怎样通过我们刚才学习的逆向试行来试着精简这个问题，请演练两个结果，一个成功精简的，一个无法精简的。请大家注意，在现实中我们有很多种方法来解决这个问题，今天我们演练的目的是通过逆向试行来精简自己的工作。现在开始排练，5分钟之后我们小组内派人来演练一下。\u003cstrong>（现场分享）\u003c/strong>请排练好的小组来演练一下自己组的排练结果\u003c/p>\u003cp>丽芳：我演小胡\u003cbr>\u003c/p>\u003cp>冯盈：我演小胡的领导\u003c/p>\u003cp>开始\u003c/p>\u003cp>丽芳：领导，有客户约我本周五上午见面谈一下咱们合作的事情，我周五上午的会议就参加不了了，您看……\u003c/p>\u003cp>冯盈：嗯，你既然负责市场，开会主要谈的是校区方面的事，那你就先跟客户谈吧\u003c/p>\u003cp>第二周\u003c/p>\u003cp>丽芳：领导，我这周五又参加不了了，咱们的一个合作单位有些事情已经跟我说了好几次，我想今天去处理一下\u003c/p>\u003cp>冯盈：那好吧，有问题解决问题，注意谈话态度\u003c/p>\u003cp>丽芳：好的！\u003c/p>\u003cp>（这是成功精简的情况）\u003c/p>\u003cp>丽芳：；领导，有客户约我本周五上午见面谈一下咱们合作的事情，我周五上午的会议就参加不了了，您看……\u003c/p>\u003cp>冯盈：咱们这是全体主管级别的会议，你能跟客户说一下换个时间谈吗？\u003c/p>\u003cp>丽芳：好吧，我跟客户说一下\u003c/p>\u003cp>（这是无法精简的情况）\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1504432450000,"updated_at":1504528392000,"ria":true},{"id":3305,"topic":"精要主义者如何轻松应对工作与生活呢？","learn_goal":"学会精要主义者养成的技巧","remark":"你是否也觉得无情的压力正在碾压生活中那些美好的东西？\r\n你是否经常感到疲惫异常却又没有发挥所能？\r\n你是否发现自己只擅长做琐碎小事？\r\n你是否感到自己总是忙忙碌碌却效率低下？\r\n你是否觉得自己的时间总是被别人的安排打乱？\r\n你是否觉得自己一直在奔波，却总是到不了任何地方？\r\n若想要最大限度成就真正重要之事，切忌贪多求全，事事应允。如果答案不是一个确定的YES,就是一个肯定的NO。只有摒弃琐碎而无足轻重的生活，才能过真正重要而有意义的人生。\r\n\r\n\r\n","level":"TF2-1","duration":19,"status":0,"type":0,"chaishujia":{"username":"果莉","city":"上海市"},"club":{"name":"上海喜乐分舵","city":"上海市"},"prologue":"自我介绍：\r\n大家好，我先介绍一下我自己，我叫果莉。我有三个标签： 第1个：我是一名财务工作者，如果大家有公司财税，个税，理财相关问题的，大家可以加我微信，也许可以帮助到你。第2个：我是一名新进的拆书家，同时也是喜乐分舵的财务官。大家有关于入会相关事宜，也可以咨询我哈!第3个：兴趣爱好是读书和跑步，一生唯有读书和跑步不能辜负。","ratings_count":0,"texts":[{"id":6152,"quote":"\u003cp>\u003cstrong>（2分钟）【R】\u003c/strong>\u003c/p>\u003cp>非精要主义者凡事都答应，是因为感觉到了那种社交尴尬和压力。他们常常为了追求取悦别人之后那种兴冲冲的感觉而自动说“Yes”，根本不假思索。但是，精要主义者知道，在这种兴冲冲的感觉过去之后，随即而来的就是懊悔的折磨。他们知道，如果这样做，自己很快就会感觉到受了欺负，因而愤恨不满。最后，他们会清醒地认识到自己将面临一种不愉快的现实：为了应许新的承诺，自己现在不得不牺牲更重要的东西。当然，关键不在于对所有要求都全盘拒绝，而是在于拒绝不重要的事情，以便应承真正重要的事情。我们怎样才能学会优雅地说“不”呢？下面就是一些基本的原则和具体的方案，教你怎样来优雅地说“不”。\u003c/p>\u003cp>1.把决定和关系分开来\u003c/p>\u003cp>当别人让我们去做什么的时候，我们往往会把这个要求和自己同他们的关系搅和在一起。有时候，它们看上去是如此的相互关联，以至于让我们忘记了拒绝这个要求并不等同于否定这个人。只有当人们把决定和关系分开来的时候，才能做出一个明确的决定，然后另行找到勇气和同情来传达它。\u003c/p>\u003cp>2.优雅地说“不”并不代表必须使用“No”\u003c/p>\u003cp>精要主义者更多地选择“不”，而不是说“不”。可能在某个时候，说“不”最优雅的方式就是直言不讳地说“不”。但是，“您能想到我，真让我受宠若惊，但我恐怕爱莫能助”，或者是“我非常愿意，可是我已经力不从心了”，这样清楚并且礼貌地拒绝别人、却不使用“不”字的方法很多很多。\u003c/p>\u003cp>3.关注权衡取舍\u003c/p>\u003cp>在答应的时候，对自己将要牺牲什么考虑得越多，拒绝就会变得越容易。不能清晰地认识到机会成本——也就是我们所放弃的东西的价值，那么我们就很容易跌进非陷阱，自欺欺人地告诉自己我们可以搞定一切。\u003c/p>","explains":"\u003cp>\u003cstrong>【I】（4分钟）\u003c/strong>\u003cstrong>TF\u003c/strong>\u003cstrong>（2-1）要求： what,why,how,适用边界\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>图书介绍\u003c/strong>\u003c/p>\u003cp>我今天要分享的这本书是《精要主义》,\u003cbr>\u003c/p>\u003cp>\u003cstrong>F\u003c/strong>\u003cstrong>（特征核心是书）:\u003c/strong>《精要主义》这本书作者是【英】 格雷戈.麦格沃恩，这本书最大的特点是讲了精要主义者的核心思维，精要主义者养成的技巧。使读者知道怎样才能设计自己的精要人生，不在琐碎中无足轻重，放弃“我什么都能做”的妄想。重拾对工作和生活的掌控，生命要浪费在美好的事情上，过真正有意义的人生。\u003c/p>\u003cp>\u003cstrong>A\u003c/strong>\u003cstrong>（优势比较建立安全感）\u003c/strong>: 这本书得到金立手机副总裁，猎聘网创始人、《非你莫属》制片人，股神巴菲特等大咖为其做精要代言。作者曾用这本书帮助苹果，GOOGLE,FACEBOOK多家世界顶尖公司摒弃琐碎，直抵精要，影响力之大。\u003c/p>\u003cp>\u003cstrong>B\u003c/strong>\u003cstrong>（利益）\u003c/strong>你有没有觉得自己的时间总是被别人的安排打乱？你有没有觉得自己总是忙忙碌碌却效率低下？你有没有觉得无法应对拥挤不堪的工作和生活？如果答案是肯定的，那么本书可以帮你对抗这些问题，帮助你重新掌控自己的工作和生活，做一个精要主义者。这也是本书最大的好处。\u003c/p>\u003cp>学习目标：在跟随我完成本次RIA现场学习后，学习者能够具备精要主义者养成的技巧之一优雅的说“不“。\u003c/p>\u003cp>下面进行I的环节，用自己的语言复述原文内容：\u003cstrong>what\u003c/strong>\u003cstrong>:\u003c/strong>我们的生活中每一天都面临着各种各样的事情，令我们的工作和生活拥挤不堪。精要主义并不每件事情都去做，每件事情都答应的。而是敢于坚定地，决绝地，优雅地说：“不”\u003cstrong>Why\u003c/strong>\u003cstrong>:\u003c/strong>而非精要主义者一般都是凭感觉，避免社交尴尬和压力而不说：“不”，应承一切事情。不加思考的直接回答，而随之而来的就是懊悔的折磨，也让别人认为你特别的不靠谱。\u003cstrong>How\u003c/strong>\u003cstrong>：\u003c/strong>所以赶紧培养你精要主义吧，优雅的说“不”。\u003cstrong>具体方案是：1，把决定和关系分开来。2，优雅地说“不”并不代表必须使用“No”3，关注权衡取舍\u003c/strong>.（视觉卡，讲解时拿出，有助于学习者理解）\u003c/p>\u003cp>我举个例子:我在初入职场时，办公室任何人都可以指使我做各种各样的事情。比如同事着急要去开会议，请我帮她买咖啡，复印，打印。同事家里有事，请我代她核对数据。。。。。。就是大家俗称“便利贴女生”，大家可以呼之即来挥之即去的。同事请我帮忙时即使自己已经忙不过来，但担心拒绝同事，会影响同事之间的关系，勉强答应。当然这不是我主要的工作，只是做决定和关系没有分开来。不敢说”NO”。难道不帮助他们做这些事情，就会影响你们之间的关系吗？往往是导致做了这些便利贴女生做的事情，而对于自己重要的事情反而没有做。没有关注权衡取舍。优雅地说“不”并不代表必须使用“No”，优雅地说“不”也并不代表会破坏同事关系。你也可以清楚礼貌的拒绝说：“我非常愿意帮你，但我现在已经力不从心了”。精要主义者并不是任何时侯都适用优雅的说“不”，他有一个\u003cstrong>适用的边际\u003c/strong>，比如我确定我有一件重要的事情，我可以这样优雅表达“不”。但在我比较有时间的情况下，我还是可以答应别人的要求的。\u003c/p>\u003cp>如果你\u003cstrong>不那么做的坏处\u003c/strong>就是任何人，任何事你都答应下来，由于你没有更多的时间来做好这些事情，也耽误了同事拜托你的事情，使同事抱怨你。自己本职工作的事情也没有完成，造成老板对你不好印象。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1】（3分钟）激活经验\u003c/strong>TF（2-1）要求：显像提问，相应的情境和画面，更快的激活经验。你有没有遇到过.....在小组内分享。\u003c/p>\u003cp>下面是A1环节，请认真听一下以下词汇和句子，哪一个是在你身边发生的？拒绝,害怕、失望。 大家可以想像一个情境：你的老板今天让你写一个很重要的计划书，必须今天完成。而你正在认真写计划时一位同事请你帮忙订个会议室，或是向你请教一个问题？拒绝,害怕、失望，哪一个能描述你当时的感受？\u003c/p>\u003cp>在便签上写下自己的这个词，是什么时侯，什么事情让你想到了这个词？\u003c/p>\u003cp>请一位小伙伴分享一下自己的便签。\u003c/p>\u003cp>学习者1：我是做网络的，我们是集团公司，其他分公司的同事，都坐在同一楼层里。其他分公司的同事，时不时会找我做一些除部门领导安排外的网络维护工作。这让我很为难，答应了他们吧，领导安排我的事情就会做不完。我当时的感受就是碍于情面，不好意思拒绝他们，也担心他们会失望。\u003c/p>\u003cp>学习者2：我在好几天前就答应儿子周六带他去看电影。到了周六那天，一位老同学突然打电话过来说是他已经到上海了，希望和我碰个面，我们聚聚。我当时很纠节，我是很想陪儿子的，因为作为家长说话要算话，不能食言，不然就会给孩子做了不好的榜样。对于突然来访的老同学，又不知道怎么拒绝他的邀请。如果拒绝他了，害怕他会不开心，友谊的小船说翻就翻了。只能勉强答应同学，结果整个聚会，我是坐立不安，也没有心情聊天。\u003c/p>\u003cp>\u003cstrong>【A1+】（7分钟）\u003c/strong>TF（2-1）要求：\u003c/p>\u003cp>下次再遇到这样的情况，你怎么用刚才学的精要主义的优雅说“不”的技巧去对待你生活中发生的事情呢？给大家每个人1-2分钟的时间在小组内分享一下，每个人都尽量表达一下。\u003c/p>\u003cp>\u003cbr>学习者1：我可能就不会像以前那样，勉强答应他们了。我会优雅的跟他们说“不”。我拿出来自己的待办清单，给他看1，2，3，4都还没有处理，实在是脱不开身，非常抱歉。你看你们是否能请个外包，或是跟我们领导说说。这样他看了我的待办清单，还有那么多事情，也不是直接拒绝他，我想他会理解的，也能把事情处理好。我也不用担心完不成领导交代的事情，受批评，影响在领导中的印象了。\u003c/p>\u003cp>学习者2：我之前认为，只要拒绝别人就会影响我和他的关系。其实我的朋友突然来访，邀请和我聚聚，我权衡了一下，觉得孩子的教育问题是个大事情。就打了电话，问了朋友说是会在周日晚上回去。我就跟他商量了一下，你看我已经答应了孩子周六陪他看电影，如果我爽约了，孩子会非常伤心，也会让我成为一个说话不算话的家长。你看你这里周日回去，那我们周日中午能不能再聚聚。我想我这样跟老同学说，他也会同意的。这就圆满解决问题了。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}}],"created_at":1501122392000,"updated_at":1504662647000,"ria":true},{"id":3183,"topic":"逆向试行","learn_goal":"学会通过低风险的方法来排除不重要的东西，精简自己的工作和生活","remark":"","level":"TF2-3","duration":30,"status":0,"type":0,"chaishujia":{"username":"胡奇伟","city":"郑州"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好，我是一级拆书家胡奇伟，今天准备过TF2-3，非常感谢大家的支持！为了方便一会儿的拆书环节，现在请大家三人一组进行分组。\r\n本次拆书的主题是逆向试行，通过本次拆书学习，我们能学会如何通过低风险的方法来排除工作和生活中不重要的东西，精简自己的工作和生活。\r\nF：本次拆书的片段节选自《精要主义》，副标题是“如何应对拥挤不堪的工作和生活”，作者是格雷戈•麦吉沃恩，他被誉为“21世纪的史蒂芬•柯维”，作为一名精要主义的提出者、倡导者和领导者，致力于帮助个人和企业摒弃琐碎，直抵精要。作为世界经济论坛全球青年领袖，他的思想影响了多国政要和众多知名企业家。\r\nA：这本书作为一本致用类图书，豆瓣评分7.9分，也算相当不错了，整本书理论和实例相结合，层层递进，紧凑而不枯燥地向你讲述如何精简自己的工作和生活状态，读过本书你能轻松地将书中呈现的知识学以致用。\r\nB：如果你现在觉得自己生活和工作拥挤不堪，每天都有忙不完的事儿，而自己的价值却没有突出，那么这本书就是为你准备的，正如副标题所说，应对拥挤拥挤不堪的生活，达到个人价值巅峰！","ratings_count":0,"texts":[{"id":6009,"quote":"\u003cp>近年来，“原型法”理念在商界很流行。构建一种原型或者大尺度模型，可以让一家公司试运行一种理念或产品，而不用预先进行大规模投资。同样的理念可以被反向运用，以一种相对而言低风险的方法排除不重要的东西，领英的董事长丹尼尔·夏皮罗称这种方法为“逆向试行”。\u003c/p>\u003cp>在逆向试行中，你可以检验取消一项尝试或活动是否会产生负面效应。例如，我合作的一位领导者在公司里担任了一个新的高管职务，他接手了其前任费了很大力气实施的一项工作：每周为其他领导者写一份大篇幅、非常直观的、涉及多个主题的报告。这极大地消耗了他团队的精力。他假设这个报告并未给公司带来太多价值。为了检验这个假设是够正确，他进行了一次逆向试行。他停止了报告的发布，等着看会出现什么样的反应。他发现没有人对这个报告流露出想念的意思，几个星期以后，甚至都没人提到这个报告。结果他提出结论：此报告对公司并无重要意义，可以取消。\u003c/p>\u003cp>在我们的社交活动中，也可以进行类似的逆向试行。你是不是经常会对客户、同事、朋友或者家庭成员做出一些承诺？你总是觉得这些能给他们带来重要影响，但实际上他们可能根本没有注意到？悄悄地取消或者至少把一个活动缩减几天或几周，你大概就能评估出它是否真的重要或者是否真的没人在乎。\u003c/p>\u003cp>就算用上了这些技巧，“不履行承诺”还是比从一开始就不承诺要难。要对已经承诺的事或人说“不”，是会让人深感愧疚，但我们也得直面它，没有人愿意违背自己说过的话。不过，学会这样做，以自己的勇气、专注和自律赢得尊重，是成为精要主义者的关键所在。\u003c/p>","explains":"\u003cp>大家都读完了，原文并不复杂，说的是如何通过逆向试行来排除一些自己承诺过的但别人并不在乎或者并无重要意义的事情，从而给自己做减法，用排除这些事情节省的时间去做更有意义的事情，向精益主义者更进一步。\u003c/p>\u003cp>\u003cstrong>（意译案例）\u003c/strong>有小伙伴知道，近期我们校区接手了一个学前班，刚接手的那段时间简直忙的不可开交，不仅是上课和课间的事情，还有就是从他们之前的学校带过来的习惯，就是接送孩子：每天早上和中午上学的时候要有一个专门的人下楼接孩子，放学的时候要把孩子送下去。当然我们也继续了这个习惯。这对于本来人手就不多的我们校区来说简直就是火上浇油，因为每天都要有一个老师负责接送孩子。而且孩子家长到校时间还不一定，从30分钟到1个小时不等，这就造成了很大的人力和精力浪费。后来我们发现只有两三个家长是在早上上班的时候在固定时间开车把孩子送到楼下，不方便上楼，之后中午和下午都是老人来接送，其他家长都是全职妈妈或者老人，每天悠哉悠哉的把孩子送过来，再悠哉悠哉的回去，于是我们就假设除了开车不方便上楼的家长外，其他人对于下楼接送孩子这件事并不在乎，为了检测这个假设是否正确，我们只在早上7点半到7点50之间下楼接开车送过来的孩子，剩下的时间就在教室带孩子进行早读，前台老师负责给孩子接水，迎接晚来的孩子。中午跟下午老师不下楼接送孩子，只在校区前台等着跟上楼的家长交流孩子的近况，就这样试行了两个多星期，发现没有家长对下楼接孩子的事情提出任何意见，相反，他们对我们就孩子的表现和他们进行交流这件事表达了感激，因为他们觉得我们比他们之前的老师对孩子的观察更仔细、更认真负责……所以我们得出结论，只要在早上固定的时间接开车送孩子不方便上楼的家长就行，其他孩子可以由家长自行送上楼，以此来调整老师们的时间，老师们也能喘口气，去做更多自己的事情。\u003c/p>\u003cp>&nbsp; &nbsp; \u003cstrong>（细化步骤）\u003c/strong>这就是逆向试行的一般步骤：一、发现工作和生活中有哪些你觉得耗费精力又不确定其价值但还在做的事情；二、假设这些事并不能给公司、同事或者朋友带来太多价值；三、验证假设，停止这些事情一段时间，等着看会出现什么样的反应；四、得出结论，这件事不重要（或重要），可以取消（或者继续）。\u003c/p>","interaction":"\u003cp>A3：我们刚学习了用“逆向试行”的方法来精简自己的工作和生活。现在一起来做一个演练，场景是这样的，我们集团有三四十家直营校区，每周五上午所有校长人都要早上九点钟到总部去开会。这个会议说的都是一些杂七杂八的事情，就是各个校区提出的遇到的情况以及一些需要解决的问题，每次开会都要就一些事情大家七嘴八舌讨论很久出不来答案，比方说关于工装的问题已经讨论了两个月了还没结果。开会时间从早上九点到下午两点，关键是还解决不了问题，而我是一名新来的大区市场主管，与校区管理方面关系不大，为了开会也耽误不少我的其他事情。现在我们来做一个演练，每组出两个人，一个人是我，一个人是我们领导，大家来演练一下怎样通过我们刚才学习的逆向试行来试着精简这个问题，请演练两个结果，一个成功精简的，一个无法精简的。请大家注意，在现实中我们有很多种方法来解决这个问题，今天我们演练的目的是通过逆向试行来精简自己的工作。现在开始排练，5分钟之后我们小组内派人来演练一下。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1499931236000,"updated_at":1504528019000,"ria":true},{"id":2924,"topic":"怎样设置工作与生活的界线，从而免受他人事务烦扰","learn_goal":"怎样设置工作与生活的界线，从而免受他人事务烦扰","remark":"","level":"TF2-4","duration":50,"status":0,"type":0,"chaishujia":{"username":"胡奇伟","city":"郑州"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"本次拆书的主题是：怎样设置工作与生活的界线，从而免受他人事务烦扰。目标：通过本次拆书学习，再遇到别人无休止的“任务分派”时，我们能学会设置工作和生活的界线，精简自己的时间和精力，从别人的干扰和繁忙中解脱出来，让自己的个人价值最大化。\r\nF：本次拆书的片段节选自《精要主义》，副标题是“如何应对拥挤不堪的工作和生活”，作者是格雷戈·麦吉沃恩，他被誉为“21世纪的史蒂芬·柯维”，作为一名精要主义的提出者、倡导者和领导者，致力于帮助个人和企业摒弃琐碎，直抵精要。服务的客户包括Apple、Google、Facebook、Twitter、Adobe等多家世界顶尖公司。 作为世界经济论坛全球青年领袖，他的思想影响了多国政要和众多知名企业家。\r\nA：这本书作为一本致用类图书，豆瓣评分7.9分，也算相当不错了，整本书理论和实例相结合，层层递进，紧凑而不枯燥地向你讲述如何精简自己的工作和生活状态，达到个人巅峰。\r\nB：如果你现在觉得自己生活和工作拥挤不堪，每天都有忙不完的事儿，而自己的价值却没有突出，那么这本书就是为你准备的，正如副标题所说，应对拥挤不堪的工作和生活，达到个人价值巅峰！","ratings_count":0,"texts":[{"id":5712,"quote":"\u003cp>当我让领导者们确定自己的界线时，他们几乎都做不到。他们知道自己是有一些界线的，但就是不能用语言表达出来。一个简单的事实是：如果你不能和自己、和别人说清楚这些界线，那么你期待别人能够尊重或者找到你的界线，恐怕也是不现实的。\u003c/p>\u003cp>想想那个总是把你从精要道路上拉出去的人，列一个坏事者清单——这个人提出的各种要求和行为，你都拒绝，除非它们正好和你自己的优先要事或者事项安排有交叉重叠之处。\u003c/p>\u003cp>找到你的坏事者的另一种快速测试方法就是，每一次你感到别人的要求冒犯了你或欺骗了你，你都要记下来。你无需通过某种极端的方法就能注意到它。即使是一个令你不快的小小的“刺痛”（我觉得这种描述有助于形容你的界线所受到的那种微小侵犯），不管是来自于一个你不想得到的邀请，还是一个不请自来的“机会”，抑或是一种帮个小忙的请求，都是你发现自己隐藏的界线的线索。\u003c/p>","explains":"\u003cp>大家都读完了，这个片段说的是如何确定自己的界线，让自己保持在精要道路上。（适用边界）毕竟，如果你不能和自己、和别人说清楚这些界线，那么就会有人把他们的问题当成我们的问题，要求我们牺牲自己的时间来解决他们的问题，这样的话我们的时间和精力就被榨取了，服务的是他们的事务而不是我们的，这样做会直接导致我们偏离自己的目标，无法完成自己的任务。\u003c/p>\u003cp>（预防异议）大家可能会问，我们不是应该帮助他人吗？我们当然应该提供帮助，关爱他人，使他人的生活有所改变。但是如果别人把他们的问题变成我们的问题，那么我们就不是在帮助他们，而是在纵容他们，除非它们正好和你自己的优先要事或者事项安排有交叉重叠之处，否则我们的任务不仅无法很好完成，同时也会剥夺他们解决问题的能力。\u003c/p>\u003cp>明确边界的具体的方法可以细化为：\u003c/p>\u003cp>一、找出那个总是把你从精要道路上拉出去的人，列一个“坏事者”清单。\u003c/p>\u003cp>二、明确你自己的优先要事或者你的to-do-list。\u003c/p>\u003cp>三、“坏事者”清单里的人提出的各种要求和行为，除非跟你的要事或to-do-list有交叉重叠之处，否则都拒绝掉。\u003c/p>\u003cp>四、记录下来其他人提出的让你有些小不爽的请求或者行为。\u003c/p>\u003cp>五、整理以上清单，明确自己的界线。\u003c/p>\u003cp>我们校区有一个老师，就喜欢把自己的事情或者问题让别人帮她解决。写方案不知道怎么写，就直接各种问你到最后，哪怕网上或者之前做的有方案可以参考，也是这样。跟会员家长沟通本来是老师的职责，却以不知道怎么跟家长说，怕沟通不好为由让领导帮她做这些事情等等。这就是一个典型的“坏事者”，而我的工作职责是做外联、安排试听课、促进报名、处理家长意见及学前班事宜。在明确我的优先要事和to-do-list的前提下，除非她的要求和我的工作职责有交叉，比如家长有意向转介绍，一般我都会提醒她多思考怎么处理这些事，先做做试试，从而拒绝她的其他要求。对于其他老师的一些要求，比如让我帮忙准备教具、去别的校区拿资料等，也是一些让我感到略微“刺痛”的请求，这时就需要把这些事情记录下来，除非顺路、和我的职责有交叉或者我处于空闲状态，一般都会让他们知道这是我的界线。\u003c/p>","interaction":"\u003cp>\u003cstrong>A1\u003c/strong>\u003cstrong>（显像提问）：\u003c/strong>现在请大家回想一下，在你的工作和生活中，有哪些人经常让你帮他做一些与你的工作内容无关的事情或者有哪些请求让你感觉不舒服？回想好的伙伴请举手发言。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 丽芳：前两天公司里的测试提出来一个问题，说研发总是指派给他们一些不属于测试的工作，但是研发觉得我们是一个项目组的，为了我们的项目，你们测试应该帮我们做一些工作\u003c/p>\u003cp>&nbsp; &nbsp;&nbsp;（\u003cstrong>反馈\u003c/strong>）你的例子非常贴切的展示了我们设置自己界线的必要性，因为研发把自己的工作职责推给别人了\u003c/p>\u003cp>\u003cstrong>A1+\u003c/strong>\u003cstrong>（反思加工经验）：\u003c/strong>我们刚才已经回顾了自己遇到的各种与“坏事者”有关的经历，我相信，明确我们的界线是我们精益工作的开始。那根据我们拆页中的建议，再结合我们刚才说的经历，我们要通过哪些步骤来明确自己的界线呢？请大家详细说明。\u003c/p>\u003cp>丽芳：我们之前开会的时候给领导提这个问题了，领导在开会的时候问测试都做了什么事情的时候，他说不出来，因为比较琐碎。通过今天的学习我可以给测试人员提这样一个建议：他可以列出来自己都做了什么，向领导据实汇报。并把自己的职责再强调一遍，明确自己要做哪些，那些自己不做，因为来面试的时候领导已经给他说过测试的职责范围了，同时也可以向大家说明，近期他的工作目标是什么，把他的计划和内容跟大家说明一下\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":5714,"quote":"\u003cp>\u003cstrong>R\u003c/strong>\u003cstrong>：\u003c/strong>我曾与一位同事搭档工作，他处理项目的方法与我截然相反。因此，有人预测我们之间会闹得不可开交。然而，我们的工作关系却十分融洽。这是为什么呢？因为从合作一开始，我就郑重其事地亮出了自己的优先事项，说明了在项目存续期间哪些额外的工作我乐意做，哪些不乐意做。“让我们说好我们想得到什么，”我开门见山说道，“以下这些事情对我来说很重要……”而且，我让他也这么做。\u003c/p>\u003cp>这样，我们就完成了一个“社会契约”，这与本章开篇故事中金永和他老板定的那个可不一样。就双方真正要着力实现的目标提前达成共识，互相了解对方的界线，这让我们避免了浪费彼此的时间，不去给对方提出徒增烦恼的要求，也不去分散对方的注意力，使其无法专注于要紧之事。结果，我们都在这个项目上实现了个人贡献峰值，而且尽管也有意见不同，但在整个工作过程中，我们相处的十分融洽。\u003c/p>\u003cp>通过不断练习，你会发现，设定界线会变得越来越容易。\u003c/p>","explains":"\u003cp>这个片段说的是在明确自己的界线后，怎样与同事相处时使用界线，学习完这个片段，我们能学会如何在别人提出要求之前就能知道你的界限，知道你会做哪些，不会做哪些工作，从而不打扰你；同时你也能尊重对方的界限，使得双方的贡献最大化。\u003c/p>\u003cp>\u003cstrong>在操作时，我们可以这样做：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>一、就大家要着力完成的目标/事项提前达成共识\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;&nbsp;二、明确亮出自己的优先事项或者to-do-list\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;&nbsp;三、说明自己的界线，确定哪些额外事情可以做，哪些不乐意做\u003c/strong>\u003c/p>\u003cp>\u003cstrong>四、让对方明确他的优先事项，了解他的界线\u003c/strong>\u003c/p>\u003cp>\u003cstrong>五、相互不给对方提出徒增烦恼的要求，不去分散对方的注意力\u003c/strong>\u003c/p>\u003cp>&nbsp;（\u003cstrong>预防\u003c/strong>\u003cstrong>异议\u003c/strong>）大家可能会觉得，话虽如此，可大家都是同事，设置这么多条条框框的不好相处啊。。然而，不说明你的界线代价会更高——你会失去选择做最重要事情的能力，这样也就失去了实现你个人价值最大化的机会。同时，如果你能把自己的价值最大化，即便你看起来有些“不近人情”，可是你最终将赢得大家的尊重。\u003c/p>\u003cp>&nbsp; （疑问）大家都挺熟的，感觉直接跟对方说自己的界线感觉开不开口怎么办？\u003cbr>\u003c/p>\u003cp>&nbsp; （\u003cstrong>回应\u003c/strong>）大家是否都有这样的感觉？有的话我们可以简单讨论下（1、我觉得话说到前头挺好的；2、我觉得贴一个告示很醒目，且不伤和气）\u003c/p>\u003cp>&nbsp; （\u003cstrong>举例\u003c/strong>）我自己在学习完这些内容之后，最近公司正在搞招生大pk，所以我们的共同目标就是在这两个月内尽量多的完成招生。我近期的目标是尽量多的邀约试听课，准备课后报告会，所以在我们校区的例会上我就直截了当的说出我的优先事项：邀约意向客户，准备课后报告会，完成订单。并明确了我的界线——在一周内，我会在周二、周四、周五邀约客户和准备报告会，为了我们校区的业绩，在此期间，一切与此无关的事情我都不会接受，除非你是给我提供意向客户或者有好的建议给我。受此影响，我们的一个老师也明确了她的优先事项和界限：准备要进行的试听课教耗材、备课，除了给她报备需要安插的试听课学生让她多准备教具外，她不希望被打扰。大家都明确了彼此的最重要目标和界线，相互之间都尊重彼此的优先事项和界线，不去给对方提其他要求，所以大家的效率非常的高，仅本周就完成本月的业绩目标的一半要求。\u003c/p>","interaction":"\u003cp>&nbsp;刚才我们学习了明确自己的界线及制定社会契约，我相信通过这些操作能使我们的价值最大化，下面我们来玩儿一个角色扮演，通过演习来熟悉这些过程。\u003c/p>\u003cp>\u003cstrong>A3\u003c/strong>\u003cstrong>：\u003c/strong>设想一下，你们部门准备上马一个新项目，你（A）负责方案设计，这关系着项目的成功与否，思路的流畅和连续性对你来说非常重要！你需要整块的时间来琢磨方案的问题。你的同事B负责对外连接，经常需要出去跟客户对接，可是他这个人有些随意性太大，虽然有前台人员，但是他跟你比较熟，以前经常会让你帮他看一些数据，帮他找一些资料拍给他，甚至让你帮忙拿快递。现在请大家进行小组内角色扮演，根据刚学习的内容，明确自己的界线，并与对方制定社会契约，使双方的价值最大化。现在请大家小组内讨论预演6分钟，6分钟后，每组选出两个人，一个扮演A，一个扮演B，以话剧的形式进行现场展示分享。\u003c/p>\u003cp>&nbsp;&nbsp; 好的，时间到，大家讨论演练的怎么样了？哪一组先来？\u003c/p>\u003cp>丽芳：我是旁白，冯颖是A，文静是B\u003c/p>\u003cp>旁白：A和B关系挺不错的，而且B因为业务原因经常在外面跑，所以B经常给A打电话寻求帮忙，但是A最近在做一个项目的方案，方案还很重要，需要整块的时间和流畅的思路\u003c/p>\u003cp>B：在忙吗？我有一些事情需要你帮我一下，是关于一些数据和客户资料的，我下周要出差，你看能不能帮帮我整理一下？\u003c/p>\u003cp>A：我现在在做咱们公司的新项目方案，正在理思路，时间比较紧急，你说说看是哪些数据和资料，如果和我的这个方案有重合或者辅助支撑的地方，我可以帮你找找，因为我不希望思路被打断，请理解。。你还有其他事情吗？\u003c/p>\u003cp>B：还有就是我下周有几个快件希望你能帮我发一下，还有就是我做外联需要拍照和一些简单的文案，你能帮我弄一下吗？\u003c/p>\u003cp>A：这些事情虽然不大，但是会打断我做方案的思路，如果是休息时间我可以帮你收发快件，如果要做拍照的话花费时间应该不会短，因为我现在做的这个项目的方案要花费大块的时间和其他小组的人一起协作，我没办法帮你做，你看能不能找一下咱们前台的工作人员抽时间帮你做一下吧\u003c/p>\u003cp>B：嗯，好的\u003c/p>\u003cp>（\u003cstrong>反馈\u003c/strong>）大家掌声鼓励一下！这个演练体现出了设置界限以及说明界限，非常好！\u003c/p>\u003cstrong>A2[分步催化1]\u003c/strong>：试想一下，你有个报告要出，只剩半小时时间了，正在拼命赶工，结果有个同事找你让你帮忙，这时候你会不会觉得很抓狂？那我们再想想近期有没有同事在你工作的时候让你帮忙，打断你的思路、推迟你的工作进度而让你觉得不胜其扰？也回想一下你有没有打断别人的工作？给大家2分钟时间思考，等下请小伙伴分享一下。\u003cbr>丽芳：我们公司每周五下午2点半要开周例会，在开会前我需要准备本周的项目情况资料。准备这个资料需要一上午的时间，这样一来，周五上午基本上都不能分心。结果有一次，有个同事打电话说，有个版本需要我发给现场，但是原本这个工作不属于我的份内，但碍于情面我还是同意了。当然特别着急，还得联系现场的人还得找SVN库里的版本资料。导致我中午吃饭也没去，生气又懊恼。\u003cbr>\u003cbr>（\u003cstrong>反馈\u003c/strong>）芳姐说的这个情况非常贴切的说明了我们被打扰的状况，我相信大家都遇到过。\u003cbr>\u003cstrong>A2[分步催化2]\u003c/strong>：请结合刚才大家想到的被打扰的情况，思考一下今天咱们拆书学习的明确界限和制定社会契约，你要如何做，才能在以后的工作中避免被别人打扰，或者打扰别人，请在小组内分享你的应用丽芳：嗯，我会整理我一周的工作内容，把工作内容按照优先级列出来。抽空和这个同事沟通，给他看看我周五的工作内容，说明例会资料的重要性（公司副总和各个项目经理都要参加）。也建议他按照这样做，最后一块沟通一下什么时间可以提供帮助，然后我们一块把工作做好。\u003cbr>（\u003cstrong>反馈\u003c/strong>）规划应用直接有效，能观测到，马上就能应用！\u003cp>\u003cstrong>结语：\u003c/strong>经过我们今天的学习，相信大家对明确界线和制定社会契约的作用和使用方法有所认识，希望大家可以经常使用，早日走向个人价值巅峰！谢谢大家的参与和配合！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1497422212000,"updated_at":1497450359000,"ria":true},{"id":2699,"topic":"设置缓冲期的窍门","learn_goal":"学习在不可预测情况下设置缓冲器","remark":"我们生活的世界无法预知，像饥荒这样的极端事件自不待说，意料之外的事情更是比比皆是。\r\n谁能知道交通状况是畅通无阻还是拥堵不堪？谁能预知自己要搭乘的航班将会晚点或是被取消？谁能料到自己明天会否在光滑的路面上滑倒摔伤手腕？同理，在公司里，我们无法预先知道供应商会迟到，同事会出错，或者客户会在最后一刻变卦等。\r\n无法预料却是我们唯一可以预料的（确定无疑）。既然如此，我们应该怎么办呢？一起学习设置缓冲期的窍门灵活应对吧\r\n","level":"TF1-1","duration":15,"status":0,"type":0,"chaishujia":{"username":"木年槿","city":"北京市"},"club":{"name":"北京宇宙中心分舵","city":"北京市"},"prologue":"大家好\r\n我是木年槿， 朋友给我的两个标签和一个我给自己的标签\r\n首先，朋友给我的两个标签\r\n第一个，灵活的胖子，灵活，这个嘛，我很喜欢打篮球，也是我们院队的主力；我跑800米3分10秒，我们班第一；至于胖子，显而易见啦~一身的肥肉是吧~ \r\n第二个，我是一个很不会整理东西的girl,从初中到大学，只要有我的寝室就从来不会被评为最佳寝室，然后我就安慰自己伟大的设计师，艺术家都是这样，太整齐影响我正常发挥~爱整理的小伙伴可以和我分享分享经验\r\n我给自己的标签， 我是一个典型的非精要主义者，所以前几天再我的书堆李翻出不知道什么时候就买了但是没有看的《精要主义》，慢慢学习","ratings_count":0,"texts":[{"id":5445,"quote":"\u003cp>\u003cstrong>&nbsp;设置缓冲期的窍门\u003c/strong>\u003c/p>\u003cp>2.比预计时间多留50%\u003c/p>\u003cp>&nbsp;&nbsp;我认识一个人，她总以为自己到商店只要5分钟就行，因为她有一回真的只用5分钟就到了那里。但实际上，没有10～15分钟根本就不够。这件事本身没什么大不了的，但不幸的是，她对于生活中的绝大多数事情都是这么估计的。结果，迟到便成了家常便饭。更糟糕的是，她总是处于压力之下，这让她感到内疚不已。在这样一种循环之中生活久了，她甚至都意识不到自己正处于一种常态化的压力之下。这种状况还影响了她的健康。然而，她依旧固执己见，认为只要5分钟就能到达商店，只要半小时就能完成电话会议，一星期就能写完重要报告，或者任何其他事情她都可以完成——这些她的确偶尔可以做到。但是这让她和她周围的人付出了很大代价。其实她只需要准备一些缓冲，就可以把那些仓促完成的事情做得更好。 &nbsp;\u003c/p>\u003cp>&nbsp;&nbsp;你是否也曾低估过完成任务所需的时间？如果是，那么你就和很多人同病相怜了。这种现象被称作“规划谬误”（Planning Fallacy）。这一术语由丹尼尔·卡尼曼于1979年提出，它指的是人们倾向于低估任务任务完成所需的时间，即便是在以前已经承担过相同任务的情况下也是如此。在一项研究中，37名学生被问到他们认为自己需要多长时间才能完成毕业论文。当这些学生被要求在“一切尽可能顺利”的前提下估计论文完成时间时，他们的平均估算值是27.4天。而当他们被问到如果“一切情况糟得不能再糟”，那么完成论文需要多长时间时，他们的平均估算值是48.6天。最后，这些学生实际完成毕业论文的时间平均为55.5天，只有30%的学生在他们估算的时间里完成了任务。令人不解的是，人们一方面承认自己有低估的倾向，但与此同时又总是相信自己当前所作的估计是准确的。\u003c/p>\u003cp>&nbsp;&nbsp;在关于人们为何会低估任务完成时间的诸多解释中，我认为“社会压力说”是最有意思的一种。一项研究发现，如果人们以匿名的方式估计任务完成所需的时间，那么他们就不会对规划谬误感到愧疚。这意味着，通常我们实际上知道自己无法在给定的期限里完成任务，但是我们不愿意向别人承认。\u003c/p>\u003cp>&nbsp;&nbsp;不管原因如何，结果都无外乎当我们做到时往往已经晚于自己预先所说的时间：开会迟到，工作迟交，账单迟结，等等。这样，本来可以顺利完成的任务，执行起来却变得阻力重重，令人沮丧不已。\u003c/p>\u003cp>&nbsp;&nbsp;要避免出现这样的情况，方法很简单，只需在我们估算的任务或项目完成所需的时间上加50%的缓冲量即可（如果觉得50%的缓冲量太过奢侈，那就想想实际完成时间比预计时间多50%的情况是多么常见吧）。如果你为一个电话会议留了一小时的时间，那么就再额外增加30分钟吧。如果你估计带儿子去参加足球训练需要10分钟，那么就在练习开始前15分钟离开家吧。这样做不仅有助于缓解担心自己会迟到时感受到的压力（想象一下，如果我们时间充裕，那么堵车时就大可不必大可不必着急心慌），而且如果发现任务比预想的完成得更快、更轻松（不过对于绝大多数人来说这种事情发生的概率很小），那么这多出来的时间就让人感觉像是得了一笔奖金一样。\u003c/p>","explains":"\u003cp>&nbsp;其实呢， 大家别看这个片段很长，其实它就是在说“规划谬误”这一现象，那什么是“规划谬误”呢？\u003c/p>\u003cp>&nbsp;人们总是低估完成一项特定的任务所需要的时间。“我肯定能在今天做完一分钟心理学”，最后却只能把这么丑的图放出来… 　　\u003c/p>\u003cp>世上最大的谎言：一个星期内看完一本书 　　一个月之后我要减20斤 　　三天内把方案做完 　　每天跟妈妈聊电话 　　...... 　\u003c/p>\u003cp>　为什么会发生？&nbsp;通常，我们作的计划都是所期望的理想状态：希望只需这么短的时间去完成。所以其实我们人类对未来的规划是不那么现实的。 我们还会否认意外事件的发生，认为意外不会有，也不会影响进程等等。 “这段时间里，我怎么可能淘宝、怎么可能刷微博、怎可能被朋友勾搭去吃一顿、怎么可能去取快递。一切都在我掌控之中。”&nbsp;那我们应该怎么做计划呢？怎么样避免“规划谬误”呢？\u003c/p>\u003cp>方法很简单，我们在开始或是接到一个项目时，都应该会有一个deadline,或者是自己也会估算一下大概的完成时间，这个方法呢，就是在预定的时间上再加上50%的缓冲量，比如你为一个电话会议留了一个小时的时间，那么再加上30分钟会更好。这样子不仅仅有助于缓解担心时间不够用，而且如果任务完成的早，自己也有时间准备下一项任务。\u003c/p>","interaction":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>&nbsp;接下来，说一个我的例子吧。\u003c/p>\u003cp>上周五我们学校运动会放假，我借着周五没有课，就和ABA英语培训机构的人事部约好周五中午14:00去面试（面试暑假兼职英语老师），地点是中关村文化大厦，也就是海淀黄庄站下车，我查了一下路线，大概1小时40分钟就到了，所以我就12:00出发，然而14:00的时候我还差一站才到海淀黄庄，而那个负责人已经打电话来问我到了没？最后我过了15分钟才到，虽然我一个劲的解释，但是感觉并没有什么用，我匆匆的参加笔试，然后面试，面试的第一个问题是：“如果你成为我们这的老师，遇到刚刚类似的迟到情况，你会怎么办？”原谅我脑洞不够大，我当时就傻了，结果我当然是没有通过面试。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>&nbsp;以后我会怎么运用呢？\u003c/p>\u003cp>1.当接到一个项目或者是要开始某一件事时，我借助一些外部工具或者是自己的一些经验，估算出自己完成这一任务所需要的时间\u003c/p>\u003cp>2.然后，在这个时间上再加上50%的缓冲时间。\u003c/p>\u003cp>例如，我明天下午1:30要考金融学，但是我还没有复习，其实老师已经给我们他要考什么了，虽然也是开卷考，但是我一直觉得开卷考更难，根据平时的学习，我觉得我应该 3个小时就复习的差不多了，明天早上只有两节课，加上早起，应该够了，刚好3个小时，但是学习了给自己留50%的缓冲期，所以我就现学现用，再给自己家1.5小时，所以我只能对各位说抱歉了，我待会儿就走了。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1495556862000,"updated_at":1495556862000,"ria":true},{"id":2559,"topic":"警惕！你的大部分时间也许都在瞎忙！","learn_goal":"让听众远离瞎忙。","remark":"乐于助人是中华民族的传统美德。所以无私的帮助他人是好事，关爱家长、朋友，为他们服务也没有问题。但是，如果别人把他们的问题变成我们的问题，那么就会榨干你的时间和精力，却丝毫没有益处。那么该如何解决这个问题呢？","level":"TF3-1","duration":15,"status":0,"type":0,"chaishujia":{"username":"陈宏玉","city":"北京市"},"club":{"name":"北京翰林分舵","city":"北京市"},"prologue":"自我介绍：2min\r\n大家好，我是今晚的拆书家宏玉，我的三个标签是拆书家、加班狗、新媒体运营。最近天天加班到晚上八九点，所以上两周都没有过来，好想念大家。都说运营狗，运营狗，我也是很不幸，踏入了运营行列，如果有小伙伴也跟我一样不幸，我们可以私下勾搭，交流经验，一起吐槽。","ratings_count":0,"texts":[{"id":5277,"quote":"\u003cp>场景法介绍图书:2min\u003c/p>\u003cp>好啦，言归正传，今天我给大家带来的书籍叫做《精要主义》，听书名大家也可能猜到主要讲的是对自己的生活进行规划和精简，要事第一。但是生活中呢，相信很多人都有过这样的经历，老板突然甩手给你扔过来个任务；同事希望你能为她自己都无暇完善的报告贡献智慧；要好的朋友打电话跟你喋喋不休的讲述着最近虐心的恋爱经历，而你正要去参加一个重要的会议，准备一项重要的工作。\u003c/p>\u003cp>大家遇到这类事情，都是怎么处理的呢？是不敢违背老板意愿，加班加点完成工作吗？是怕得罪同事，抽出时间帮助她完善报告吗？是不忍拒绝朋友电话，三心二意的听完吗？也有人可能是考虑到自己的事情紧急，拒绝了，但是心里还是很不好意思，觉得拒绝意味着不讲人情，心想下次再给他补回来吧。\u003c/p>\u003cp>生活中类似的这些事情在不断的榨取着我们的时间和精力。如果我们不加以重视和作出改变，那我们将没有时间处理的自己的核心事务，没有时间实现自己的目标。我们将被囚于别人替我们设置的限制之中。\u003c/p>\u003cp>（现场语速放慢，着重强调。）\u003c/p>\u003cp>今天我给大家带来的主题是当问题出现时，学会了解清楚问题所有者是谁。不要把别人的问题当成自己的问题。\u003c/p>\u003cp>我们接下来看一下拆页。\u003c/p>\u003cp>R：\u003c/p>\u003cp>作家亨利·克劳德在《界线》（boundaries）一书中讲了一个故事，说的就是这种情况。有一次，一对父母过来看他，希望他能“治好”他们那位25岁的儿子。他就问：“为什么孩子没有一起来?” 这对父母说:“他不觉得自己有问题。” 在听了他们的讲述之后，克劳德得出结论，这结论让这对父母很吃惊：“我觉得你们的儿子是对的。他没有问题…有问题的是你们……你们付钱，你们焦急，你们担心，你们计划，你们费尽心力让他继续这样下去。那么，他就没有问题了，因为你们已经从他那里把问题接过去了。”&nbsp;\u003c/p>\u003cp>然后，克劳德给他们打了个比方。想象一个邻居，他从来不给他家的草坪浇水，但是只要你打开你的洒水器，水就洒到了他家的草坪上。你的草地渐渐变黄并行将枯死，但是邻居看了看他家的青青绿草，暗自思忖：“我家的院子不错呀。”于是，所有的人都是输家：你的努力白费了，邻居也从没有养成给草地洒水的习惯。怎么解决？正如克劳德说的：“你必须筑起篱笆，让他的问题离开你的院子，待在它们该待的地方。\u003c/p>","explains":"\u003cp>I : 3-4min\u003c/p>\u003cp>看到大多数小伙伴都看完了，接下来是拆书家讲解引导部分。\u003c/p>\u003cp>文中讲述的是孩子的父母大包大揽，将孩子成长的问题都揽在自己身上，并寻求问题可以得到解决，孩子可以做出改变。但是他们没有意识到的是，孩子的问题已经变成了他们的问题，他们已经剥夺了孩子自己解决问题的能力。那怎么能不把别人的问题当成自己的问题呢？\u003c/p>\u003cp>首先，找到问题的所有者是谁，我们回到原文，在原文中作家问：“为什么孩子没有一起来?” 这对父母说:“他不觉得自己有问题。父母想帮助孩子解决问题，父母认为孩子有问题，但是孩子却没有意识到 。因为父母已经把问题接过去了。\u003c/p>\u003cp>第二步，确定自己的界限，把问题还给对方。原文中举了个给草坪浇水的例子，并描述了解决之道，“你必须筑起篱笆，让他的问题离开你的院子，待在它们该待的地方。也就是划清界限，把问题还给对方。\u003c/p>\u003cp>”\u003c/p>\u003cp>那有的小伙伴可能问，这个拆页是只针对父母嘛？其实生活中的我们在某个时刻何尝又不是那对父母呢？你不顾自己的时间和精力，答应了领导的任务、答应了同事的请求、答应了朋友的电话粥。你承接了他们的问题，却失去了自己选择的自由。有的人也可能会说，我总不能那么没人情味，就把问题抛给对方不管不顾吧。这里想跟大家澄清一下的是，我不是说我们不应该帮助别人，为别人服务，而是要确定自己的优先事项和自己的界限，管理好自己的精力和时间。况且迫使这些人自己解决自己的问题，不仅于你有利，于他们也有益。\u003c/p>\u003cp>给大家讲个最近的事，我们领导有一天问我旁边一个同事，说你能不能帮我写个策划案，这个同事是这样回答的，好啊，我很乐意完成这个工作，但是我目前在做这个官网文案的优化，如果我再承担一项，我将无法把工作做得好到令自己满意。然后领导收回了这个任务，并没有不高兴，因为他不想打扰这位高效工作的员工。\u003c/p>","interaction":"\u003cp>A2:10min&nbsp; &nbsp;\u003c/p>\u003cp>下面到了拆为己用的环节，大家联系生活实际，编写一段剧本，内容可以是工作中老板同事提出的额外要求，并不是职务内的事情，可能是私事。也可以是生活中朋友、另一半的请求，你内心并不想做。剧本中需要明确1.问题是什么&nbsp; 2.谁是问题所有者并还给对方。这个剧本有两个角色，一方提额外的要求，另一方思考思考问题所有者是，并把问题还给对方。我们以小组形式进行讨论，时间为五分钟。五分钟后我们请小伙伴来分享他的剧本。\u003c/p>\u003cp>分享者1:\u003c/p>\u003cp>很多孩子适龄的时候就会讲话了，但是有孩子也会晚一些，而这个阶段的父母呢，感觉孩子饿了就给他吃饭，渴了就给他水，孩子自己提出要求之前，孩子都不需要说话，语言能力比较弱，这个问题的所有者属于父母，父母应该把主动权还给孩子。让孩子自己提出要求。\u003c/p>\u003cp>分享者2:\u003c/p>\u003cp>王总：小李啊，今天我有一个特别重要的会议，但是我的孩子病了，我的回家带她看病，你看你时主管，您能代替我参加吗？\u003c/p>\u003cp>小李：王总我也很想去，但是您还记得周一的时候分配了战略规划和部门调整，这个事情关系到咱们公司的利益情况，董事会要批准同意的，明天是截止日期，今天我要做个汇总，特别重要，大概有十项。\u003c/p>\u003cp>王总：行，那我在找别人吧，我找老韩吧。\u003c/p>\u003cp>总结：当问题出现时，首先要思考问题所有者是谁，不要把别人的问题当成自己的问题，把问题还给对方，迫使这些人自己解决自己的问题，我们才有更多的时间和精力，专注于自己的事情，彼此获得成长和自由。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1494076012000,"updated_at":1494076320000,"ria":true},{"id":2397,"topic":"学会优雅的说“不”","learn_goal":"练习使用三种方法，对生活的重不重要的事优雅说不","remark":"我们经常无法坚持去拒绝生活和工作中那些不重要的事，而其中一个重要原因就是我们害怕拒绝他人。\r\n但是其实说“不”并不会带来很严重的社交问题。而且如果你能优雅的说“不”，还会为你赢得他人的尊重，最终为你带来成功。\r\n如何优雅的说”不“呢？请跟随Lizzy一起学习优雅的说“不”。","level":"TF2-4","duration":60,"status":0,"type":0,"chaishujia":{"username":"Lizzy","city":"北京市"},"club":{"name":"北京宇宙中心分舵","city":"北京市"},"prologue":"大家好我是今天的拆书家Lizzy。在接下来的一个小时时间里我会和大家探讨如何说不这个问题。","ratings_count":0,"texts":[{"id":5094,"quote":"\u003cp>为何在当下，大胆选择重要的事情，放弃不重要的事情，是如此的艰难? 这其中的一个原因其实再简单不过，无非就是我们内心对社交尴尬畏首畏尾。 &nbsp; 我们对群体对我们期望的服从，心理学家称之为规范性从众，虽然如今这种服从已经不再是生死攸关之事，但那种渴求却始终深深地根植于我们的头脑中。这就是为什么，不管是一个老朋友邀请你去吃饭，或是你的老板让你负责一项重要的、备受瞩目的项目，抑或是一个邻居拜托你帮忙参加家长会的糕点义卖活动时，哪怕是一个拒绝的念头都会给人带来身体上不舒服的感觉。我们觉得内疚，我们不想让别人失望，我们害怕破坏关系。但是，这些情绪会让明确性变得混乱不堪，会分散人的注意力，导致人们认识不到事实就是要么拒绝，然后遗憾几分钟；要么答应，换来几天、几周、几个月，甚至几年的后悔。要摆脱这样的困境，唯一的出路就是学会说“不”，坚决地，决绝地，却很优雅地说“不”。因为一旦我们这样做，就会发现自己对打击别人和惹怒别人的担心其实是被夸大的，而且还会发现人们实际上会更加尊重我们。自从成为精要主义者以来，我发现人们普遍都尊重和羡慕那些有着坚定信念勇于说“不”的人。\u003c/p>","explains":"\u003cp>学习目标：在跟随我完成本次RIA现场学习后，学习者知道为什么要说“不”以及在什么情况下要说“不”\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>F: &nbsp; 这本《精要主义》的作者是McKeown。他在本书中提出了“精要主义者应该遵循的思维模式”以摆脱无意义的多数，专注于有意义的少数“。在书中，他将这种模式转化为一整套的程序，非常利于执行。\u003c/td>\u003c/tr>\u003ctr>\u003ctd>A: &nbsp; 《精要主义》这本书非常畅销。他在豆瓣上也得到了7.9的高分，要知道采铜的《精进》的豆瓣评分也才只有7.7。书中提出的思想影响了多国的政要和众多的知名企业家。\u003cbr> &nbsp; &nbsp; &nbsp; 企业家成功的秘诀在于，以恰当的方式，在适宜的时候，对合适的项目说“Yes”。要做到这一点，他们必须善于对自己的其他想法说“No”。如何确定极为重要的事，如何将自己的精力分配给终能带来大回报的事务上，精要主义为此提供了简洁而富有说服力的建议。——里德.霍夫曼 &nbsp; LinkedIn创始人\u003cbr> &nbsp; &nbsp;\u003c/td>\u003c/tr>\u003ctr>\u003ctd>B: &nbsp; 快节奏的北京，庞大的社交圈，大家有没有觉得有太多事情要做而力不从心？从《精要主义》这本书里，你能够得到知识去判断生活中到底有哪些事情是你真的要去做的。这本书帮助我重新找回了对生活的控制感。所以推荐给大家也去看一看。\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>做个小调查请大家回答一下问题：&nbsp;\u003c/p>\u003cp>同事要求你帮助解决一个你工作范围以外的问题（对你来说是不重要的事儿）但你有很多自己的本职工作还没做完，你最终会去帮助同事吗？\u003c/p>\u003cp>这就是对群体希望的服从 &gt; 我们都担心因为拒绝别人而感到内疚，而破坏和别人关系，而让别人失望 &gt;\u003c/p>\u003cp>但一旦我们无条件的接受所有的这些不重要的事情，我们的生活就会变得混乱不堪 &gt;\u003c/p>\u003cp>事实的真相是，要么我们拒绝然后遗憾几分钟；要么我们答应，然后换来长久的后悔 &gt; 对打击和惹怒别人的担心是被夸大了的 &gt;而且如果你说&quot;不“， 你会赢得别人的尊重&nbsp;\u003c/p>\u003cp>因此，要大胆的对不重要的事情说”不“，这样可以帮你拒绝不重要的事情，让你集中精力处理重要的事情。同时，说”不“并不会对你的社交产生负面影响，反而会为你赢得大家的尊重。\u003c/p>\u003cp>现在总结一下：\u003c/p>\u003cp>在什么情况下我们要说“不”呢？当别人对你有一些希望，但这些希望却会让我们的生活变得混乱不堪而没有帮助的时候 &gt; 即这些事情是不重要的事情的时候 --&gt; 我们要考虑说“不”\u003c/p>\u003cp>为什么要说“不”呢？拒绝不重要的事儿，把精力专注在重要的事情上，控制自己的生活\u003c/p>\u003cp>不那么做的坏处：\u003c/p>\u003cp>一想到会让自己敬重、喜欢的人失望，我们就无法忍受。但这些都不足以让我们成为坏人。这是人性的一部分。然而，尽管拒绝别人是如此艰难，但如果不这样做，我们就会错过重要得多的东西。你会为了去赴约，满足同事和老板的额外要求，而错过了在你生命中更重要的事情：陪伴家人，发展自己的事业，不断学习成长。\u003c/p>","interaction":"\u003cp>重要的事充斥在我们每个人的生命中，无论是工作中同事对你提出的一些额外的帮助要求，还是朋友邀请你近一个月以来的第N次聚餐，或是邻居组织的&quot;小区嘉年华“。现在请大家分组讨论一下，去探索和发现，那些在你的生活中，本来可以说”不“的却因为害怕决绝他人而做的”不重要“的事儿。\u003c/p>\u003cp>实录：\u003c/p>\u003cp>宝仲：我有一个邻居朋友，经常会晚上约我聊天吃饭。一吃饭就还会喝点儿酒啊什么的。这样每周有个两三次。弄得我没法散步，跑步，还经常吃多。其实我很想用这个时间做点儿别的事情。而不是浪费在这种没有意义的吃饭上。但是又不知道怎么拒绝朋友。\u003c/p>\u003cp>莲莲：周末想单独去旅行，enjoy自己一个人的时光。但是朋友硬要跟你一起去。虽然朋友的陪伴很好，但是对于我来说独处更重要。弄得我不好意思拒绝。\u003c/p>\u003cp>回应和反馈：谢谢宝仲和莲莲的分享。总是被邀请去吃饭，被朋友要求一起出去玩儿，但这些事情其实并不是我们认为的重要的事儿，可我们不知道如何拒绝。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":5095,"quote":"\u003cp>方法一:“我需要先看一下日程表，然后再答复您。”&nbsp;\u003c/p>\u003cp>我认识一个领导人，她觉得自己整天的时间都被别人操纵了。她是一个典型的非精要主义者，虽然聪明能干，但却不会说“不”，结果很快就成了一个“万事帮”类型的人。人们常来找她，问她：“你能不能帮我完成X项目？”为了当一个好公民，她答应了。但是，这些五花八门的工作事项很快就让她感到不堪重负。后来，她学会了用一种新的措辞来答复请求：“我需要先看一下日程表，然后再答复您。”这才让她的境况得到了改观。这种措辞让她有时间先停顿一下，好好想一想，最后答复别人：很遗憾，我无法提供帮助。这种措辞也让她能够重新获得对自己决定的控制权，而不是别人一提出要求，就仓促答应。\u003c/p>\u003cp>方法二：“ 好的。那么我要取消的是什么？”&nbsp;\u003c/p>\u003cp>在很多人看来，对单位的高层领导说“不”，这几乎是无法想象的，甚至是可笑的。然而，如果说“YES”，会导致你无法集中精力完成自己的工作，那么此时，说“不”也是你的职责所在。在这种情况下，说“不”不仅是合情合理的，也是至关重要的。为达到这个目的，一种有效的方法是提醒你的上级，如果你答应做这件事，那么你将无法做其他事，就让他们来解决这个取舍问题吧。比如，经理来找你，问你能不能做X事项，你可以答复说：“好的，我很乐意优先完成这项工作。但是，为了集中精力在这个新项目上，我应该把哪些项目先放一放？”或者就说：“我很想把这个工作做好，但是考虑到我还有其他的任务，如果我再承这一项，我将无法把工作做得好到令自己满意。”我认识一位领导，他的一名下属就是这样答复他的。他一点儿也不想干扰这位工作高效、做事有条理的员工，于是他收回了这项并不太重要的任务，派给了一个做事不那么有条理的员工！\u003c/p>\u003cp>方法三：“ 这个我做不了，但是X可能对此感兴趣。”&nbsp;\u003c/p>\u003cp>很多人都倾向于认为自己的帮助具有无可比拟的价值，但是人们在提出要求的时候，通常并不在乎帮助他们的究竟是不是我们，只要有人帮忙就行。\u003c/p>","explains":"\u003cp>学习目标：在跟随我完成本次RIA现场学习后，学习者能够学会优雅的说不的方法\u003c/p>\u003cp>为了避免不重要的事情对我们工作和生活的打扰，我们要学会说”不“。但是对别人说不有时候真的很难。室友要求你帮忙，你怎么说不？同事要求你一起出席一个会议，你怎么说不？\u003c/p>\u003cp>那么怎样才能把说”不“对别人的打击和伤害降到最低，使说不为我们赢得尊重和成功呢？答案是我们要优雅的说”不“。 优雅的说就是要婉转的说，要有礼貌的说”不“。虽然，”不“本身很生硬，但是我们可以优雅的把”不“的意思表达出来。\u003c/p>\u003cp>在学习了为什么说不，什么情况下说不以后。现在让我们来学习如何优雅的说不。\u003cbr>\u003c/p>\u003cp>预防异议：\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>可能有的朋友会问，今天的这些方法对有些说”不“的场景应该不太适用吧？比如，老板跟我谈加薪，我对薪水的涨幅不满意。我要怎么和老板说”不“？ &nbsp; 首先我要明确一下，今天我们讨论的是对那些别人对我们提出的对我们个人来说是不重要的期望如何优雅的说”不“。 &nbsp; 至于其他的我们需要拒绝说不的场景，今天我们不涉及讨论。\u003cbr> &nbsp; &nbsp; \u003cbr> &nbsp; &nbsp; &nbsp; 另外，也许有的小伙伴认为，在他的人生中维持关系是最重要的，因此他认为所有别人的请求都是重要的事儿。这样也是OK的。每个人的情况都不相同，我们今天讨论的是拒绝那些我们认为”不重要“的请求。如果你认为，朋友，同事的所有请求都很重要你当然可以不去决绝。但每个人的精力都有限，我想在你的人生中总有你顾及不到的来自他人的对你来说“不重要”的请求吧。\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>首先，我简单为大家抽象罗列出生活中那些别人请求的对我们来说不重要的事儿的重要几种：&nbsp;\u003c/p>\u003cp>1. 承担额外的不重要的责任\u003c/p>\u003cp>2. 参与不重要的会议/活动\u003c/p>\u003cp>3. ”各种“帮助别人 &gt;&gt; &quot;各种” --&gt; 超出职责的，无休止的帮助\u003c/p>\u003cp>怎么优雅的对这些请求说”不“呢？让我们来看看片段二的这三个方法。\u003c/p>\u003cp>方法一：我把这个方法总结成三个字“没时间”\u003c/p>\u003cp>我们来看一下原文片段。“我要先看一下日程表，然后答复您”。原文片段是怎么应用的呢？最一开始你需要先告诉人家“我要开一下日程表”，然后留给自己时间去确认是否真要答应他人的请求，如果认为事情不重要，就回绝人家，告诉人家“我的日程表满了”。这是原文片段给出的解释。对于很难拒绝别人的重症患者，在最一开始可以按照这个步骤的第一步做，告诉别人我要查一查，然后让自己冷静冷静，再慢慢拒绝。但是在实际生活中如果我们真的把这件事情分解成这三个步骤就会感觉很生硬了。从另一个层面看，这本书是外国人写的，他说“查日程表“”很遗憾不能参加“这些话，都有些不太像我们中国人说的话。那我们要怎样自然的应用这个方法呢？我为大家总结出了三个小步骤。第一步：告诉对方我没时间。第二步，解释自己不能参加的原因。第三步，告诉对方无法答应请求。注意这些动作最好连续完成。\u003c/p>\u003cp>给大家举一个例子。周六我准备参加拆书帮的活动，大学的一个好哥们说大家一起聚聚，这个时候我就很为难的说，我周六有参加拆书活动没办法参加，好哥们一听说，你拆书活动天天参加，少一次又不会死人，我们同学都一年没聚了，叫你来一次这么难？你要是觉得和我们聚会没意思，就直说。\u003c/p>\u003cp>怎么应用这个方法去决绝呢？\u003c/p>\u003cp>“哎呀，哥们儿，咱们聚会那个时间正好赶上我带拆啊。如果我去参加咱们的聚会，我们舵这次的活动就黄了，因为如果带拆的人不在，活动就没法进行啊。我是1个多月以前就答应这次带拆的了。而咱们说周末聚会的事儿是才知道的。要是早知道咱们周末聚会我就不答应带拆了。 我真的很想参加咱们的同学聚会啊。我很想和你们见面聊聊啊。等这次活动结束以后，我一定找机会约你们出来聚聚。”\u003c/p>\u003cp>方法二：这个方法很适合拒绝比自己权利更大的领导\u003c/p>\u003cp>一般老板提出要求你做某事，你是不好意思告诉他我没时间的。那么怎么办？方法二帮到你。你可以告诉老板，如果我做了这个事儿，那么别的事儿我就做不成了。这种说法很婉转。比如例子里面指出的，老板让你做一些事情，你要告诉老板如果我做了这个事儿，那么我现在处理的重要事情就要被耽搁了。这样老板自然会掂量掂量，重新考虑是否真的需要你的帮助，以此来达到说“不”的效果。这样你既避免了直接拒绝老板的尴尬，又达到了不做“不重要”事情的目的。\u003c/p>\u003cp>方法三：我将方法三总结成“去找别人帮忙吧”\u003c/p>\u003cp>当别人请求帮忙而你想说“不”的时候，给对方提供替代你的方案往往是一个一举两得的方法。这样一来，你达到了说“不”的目的，同时对方的事情也有人帮忙了。\u003c/p>","interaction":"\u003cp>Amy是公司基层的项目管理人员。最近她特别忙碌，每天都超负荷的工作。但是她静下来仔细分析自己的工作内容后，竟然发现她的很多工作对于她来说都不是那么的重要。请结合今天片段里面介绍的优雅的说“不”的方法，帮助Amy想办法优雅的对同事说“不”，来拒绝这些在她看来并不重要的事情。\u003c/p>\u003cp>我们两两一组来进行角色扮演，一个人扮演Amy,另一个人扮演向Amy提出要求的同事和老板。其中扮演Amy的人，请应用我们今天介绍的优雅的说“不”中的一个或多个方法来想办法拒绝同事或者老板对她提出的请求，而扮演另外一个角色的小伙伴就可以自由发挥了。待会儿我们分组讨论完以后，我将需要小伙伴们来和大家分享你们的讨论。\u003c/p>\u003cp>实录一：\u003c/p>\u003cp>存在（扮演老板）：Amy啊，远在印度的团队需要管理上的支持，你是我们公司技术最好的一定能成功。你能不能帮忙管理一下印度项目？\u003c/p>\u003cp>黑石（扮演Amy): 没问题，没问题。哎呀，我最近在忙美国的项目，忙的是不可开交啊。时间上有些冲突。我现在也在惆怅该去怎么处理这种时间上的冲突。（方法二）\u003c/p>\u003cp>存在：这个我早就考虑到了，你可以加班解决这个问题。\u003c/p>\u003cp>黑石：老板，咱们公司老王，我观察他挺棒而且最近没事儿，我觉得如果他来做这个事儿肯定成。（方法三）\u003c/p>\u003cp>存在：你说的我早就考虑到了，老王技术不成，他来做项目会黄的。\u003c/p>\u003cp>黑石：老板，你说的对。但是，有件事儿我一直没告诉你。我老婆最近怀孕了。我得下班去照顾他。我得下班去照顾她。实在是不好意思。（方法一）\u003c/p>\u003cp>存在：我们这周末代表公司去看望一下你老婆。但是印度项目还是要你带。\u003c/p>\u003cp>实录二：\u003c/p>\u003cp>小燕（同事）： Amy我有一个技术上的难题，必须要你来帮助啊\u003c/p>\u003cp>木木兔（Amy）：嗯，其实这事儿老王可以帮到你的，他技术很好的，一定会帮你解决问题的。\u003c/p>\u003cp>我们刚刚帮助Amy找到了方法以便她对工作中不重要的事情优雅的说”不“。小伙伴们有没有冲动想要把优雅的说”不“的方法同样运用到自己的生活和工作中呢？下次老板再给你增加工作内容的时候你要怎么说？下次同事再让你额外帮忙的时候你要怎么做？下次闺蜜再让你陪她买衣服吃饭喝咖啡时候你要怎么做？\u003c/p>\u003cp>实录一：\u003c/p>\u003cp>小伙伴说：老板要求小伙伴来当药店店长。小伙伴直接拒绝“我可能不成”。场面顿时就特别的尴尬。其实可以更优雅的说不：“这个事情，不是我不想做，但是我觉得应该让其他更有才的人来做这个事儿。比如老赵。公益活动我还是可以参加的。”\u003c/p>\u003cp>实录二：\u003c/p>\u003cp>妈妈周末要出门参加活动但是女儿不愿意。妈妈怎么拒绝女儿呢？\u003c/p>\u003cp>方法一：女儿，妈妈很久前就答应叔叔阿姨今天去参加活动了。如果不去就属于违反约定了。而且这个活动对妈妈来说很重要。希望你支持妈妈让妈妈做这件重要的事儿。妈妈办完事儿回来就陪你玩儿。\u003c/p>\u003cp>方法二：女儿，虽然妈妈今天没办法陪你玩，但是爸爸可以陪你玩儿啊。你和爸爸一起过一个超级爸爸日吧。\u003c/p>\u003cp>回应与反馈：感谢大家的分享。我们用到了今天我们介绍的所有的方法来去拒绝老板和女儿的要求。感觉酷酷的。\u003c/p>\u003cp>结语：\u003cbr>我们经常无法坚持去拒绝生活和工作中的那些不重要的事，而重要原因之一就是我们害怕决绝他人。但是其实说“不”并不会带来很严重的社交问题，而且如果处理得当还会为你赢得他人的尊重，并且帮助你集中精力专注在最重要的事情上，最终为你带来成功。优雅的说”不“有很多的方法，今天为大家介绍了3种比较实用的小技巧。希望大家能够觉得有帮助，并且应用到实际的生活和工作中。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1492491861000,"updated_at":1492491861000,"ria":true},{"id":2395,"topic":"改变坏习惯","learn_goal":"改变坏习惯，建立新习惯","remark":"你有没有在忍受坏习惯的困扰？你的生活是否在被一些不好的习惯不断的侵蚀？你是否在自责花费了太多时间刷朋友圈、刷微博？又是否在一边呐喊要早睡一边继续熬夜？为什么你一次又一次的决心，换来的却是一次又一次的放弃？一年之计在于春，花都开了，你的这些习惯改掉了吗？如何轻松改掉坏习惯呢？请和Lizzy一起找出坏习惯的触发器，建立新习惯。\r\n","level":"TF2-3","duration":25,"status":0,"type":0,"chaishujia":{"username":"Lizzy","city":"北京市"},"club":{"name":"北京宇宙中心分舵","city":"北京市"},"prologue":"一年之计在于春，春节也过了，放假是没什么指望了。大家对新的一年有没有什么计划？想改掉些什么坏习惯吗？今天我和大家分享一个简单的小技巧来帮助大家改掉坏习惯。","ratings_count":0,"texts":[{"id":5092,"quote":"\u003cp>科学家们解释了每一个习惯都是由刺激、常规和激励组成。这个刺激就是一个触发器，指示你的大脑进入一种自动模式，以及选择要使用的习惯。然后就是常规活动，即行为本身，它可以是身体的，精神的，或者情绪的活动。最后是激励，它将帮助你的大脑弄清这个习惯是否值得记住。久而久之，这个循环——刺激、常规和激励，将会因为刺激和激励神经性地相互交织而变得更加无意识。”这就意味着，如果想改变自己的常规，你并不需要真的去改变行为。你需要找到引发非精要活动和行为的刺激事件，并设法让这个刺激事件与确属精要的事情相关联。比如，如果下班回家路上的那家面包店是导致你买甜甜圈的触发器，下一次路过时，你就要让它提醒你去街对面的熟食店买一份沙拉。很快，你将会下意识地、自动地执行新的常规.\u003c/p>","explains":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>F\u003c/td>\u003ctd>这本《精要主义》的作者是McKeown。他在本书中提出了“精要主义者应该遵循的思维模式”以摆脱无意义的多数，专注于有意义的少数“。在书中，他将这种模式转化为一整套的程序，非常利于执行。\u003c/td>\u003c/tr>\u003ctr>\u003ctd>A\u003c/td>\u003ctd>《精要主义》这本书非常畅销。他在豆瓣上也得到了7.9的高分，要知道采铜的《精进》的豆瓣评分也才只有7.7。书中提出的思想影响了多国的政要和众多的知名企业家。\u003c/td>\u003c/tr>\u003ctr>\u003ctd>B\u003c/td>\u003ctd>&nbsp;你是否也觉得无情的压力在碾压生活中哪些美好的东西？你是否经常感到疲惫异常却没有发挥所能？对于想要重新掌控自己的健康，幸福与快乐的人，我推荐大家读一读这本《精要主义》。\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>片段里面提及了3个概念，我们先逐一解释一下。\u003c/p>\u003cp>刺激：刺激能够触发常规行为和人们对激励的渴求，它就像多米诺骨牌的第一张牌，只要我们一碰到它，习惯就会自动发生。刺激几乎涵盖所有事物，某一个特别的时间、特别的地点、或者什么关键的人物、情绪和之前紧挨着的动作。比如每天晚上下班路过的面包店。\u003c/p>\u003cp>常规： 它比较显而易见，是一种经常发生的、下意识的、我们忍不住去重复的行为。比如，吃饭后立即睡觉，晚上睡前不洗澡…&nbsp;\u003c/p>\u003cp>激励: 激励是在常规行为发生后，一种我们可以立刻得到的、让我们感觉很爽的东西或感受。可以是物质上的，也可以是精神上的，总之它能够给我们带来舒服、安心和满足的感觉。比如吃饱了直接睡的那种满满的幸福感。\u003c/p>\u003cp>正如片段里面所说的那个例子，常规行为是下班路上买面包，刺激是路过面包房，在不改变刺激的前提下，我们只需要把买面包的旧行为替换成买沙拉的新行为就可以了，而新行为的激励就是健康的生活。&nbsp;\u003c/p>\u003cp>因此我们就有了改变旧有坏习惯的5个小步骤：\u003c/p>\u003cp>第一步，找出坏习惯\u003c/p>\u003cp>第二步，确定改变坏习惯的激励\u003c/p>\u003cp>第三步，找出旧有常规行为，也就是你想要改变的行为。\u003c/p>\u003cp>第四步，找出诱发常规行为的刺激。有的时候刺激很明显，比如回家路过面包房所以就买面包，这个里面刺激就是路过的面包房。但有的时候，刺激会隐藏起来不好找。今天我们的拆书时间有限，对于如何寻找隐藏起来的刺激我们就先不涉及。如果有兴趣我们以后可以再拆，去学习如何发现隐藏的刺激。\u003c/p>\u003cp>第五步，用新常规行为替换旧常规行为。\u003c/p>\u003cp>再举个例子具体应用一下，比如我每天晚上吃晚饭收拾完厨房就总是习惯性的躺倒在沙发上看电视玩儿手机。如何改掉这个坏习惯呢？&nbsp;\u003c/p>\u003cp>第一步，确定坏习惯是吃完晚饭收拾完厨房后会躺在沙发上看电视玩手机\u003c/p>\u003cp>第二步，确定要改变这个坏习惯的激励就是不躺着就可以减肥至少不会增重，而且最好可以利用这段时间照顾孩子\u003c/p>\u003cp>第三步，找出旧有常规行为，吃晚饭后躺着玩儿手机\u003c/p>\u003cp>第四步，找出诱发常规行为的刺激。吃晚饭规制完厨房\u003c/p>\u003cp>第五步，用新常规行为替换旧常规行为。受到吃晚饭规制完厨房的刺激后，带儿子出门遛弯\u003c/p>","interaction":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>场景1：俗话说的好，春天不减肥，夏天徒伤悲。Amy最近很烦恼，去年冬天积攒下来的肥膘要在夏天来临之前减下去，可是怎样减肥呢？她每天的生活很简单，两点一线，公司和家。每天早上为了不迟到她都会在路过公司门口的早点摊儿时候买个鸡蛋灌饼。中午她会和同事吃公司的食堂。食堂的饭难吃啊。。。所以每天下班时候她都会饿的厉害，正巧下班路上有个面包店，于是她经常光顾那里去吃个面包再回家。回到家，吃完妈妈做的饭，她还会习惯性的躺在沙发上玩手机，看电视。\u003cbr> &nbsp; &nbsp; 场景2：Allen最近心情不太好，工作生活都不太顺利。他新近的工作职责有所变化，随之而来的是巨大的压力。每天他都被各种会议和投死电话忙得不可开交，他最近养成一个新毛病，每处理完一个投诉电话他都会去公司楼下抽根烟以缓解压力。在生活方面，女朋友最近经常对他各种不满，两个人在一起没多久就开始闹变扭最后不欢而散。一般情况下遇到这种情况，他都会把自己的哥们儿叫出来陪着他醉酒浇愁。\u003cbr> &nbsp; &nbsp; &nbsp; Amy和Allen都想改掉她们目前身上的一些坏习惯以此来达成减肥和更健康生活的目的（新行为的激励）。结合今天学习的拆页片段，如何帮助Amy和Allen改掉他们旧有的常规行为呢？请找到Amy和Allen现有的一些需要改变的常规行为，发现刺激（触发器），并找到新行为来替换就行为。\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>小伙伴分享：\u003c/p>\u003cp>Amy的坏习惯是上班路上吃鸡蛋灌饼。\u003c/p>\u003cp>新行为的激励是减肥。\u003c/p>\u003cp>常规行为是在上班路上吃鸡蛋灌饼。\u003c/p>\u003cp>触发条件是上班路上路过。\u003c/p>\u003cp>新行为是买粥来替换吃鸡蛋灌饼。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1492490342000,"updated_at":1492490342000,"ria":true},{"id":2394,"topic":"克服禀赋效应","learn_goal":"了解禀赋效应，正确评估该放弃的东西/机会以作出正确的决策","remark":"一个前景黯淡的项目，一个从未使用过的电饭锅或是一本多年未翻的书，他们到底有多少价值？是否应该继续持有？跟随Lizzy一起了解禀赋效应，帮你正确评估该放弃的东西/机会以作出正确的决策。","level":"TF2-2","duration":15,"status":0,"type":0,"chaishujia":{"username":"Lizzy","city":"北京市"},"club":{"name":"北京宇宙中心分舵","city":"北京市"},"prologue":"你是否也觉得无情的压力正在碾压生活中那些美好的东西？\r\n你是否经常感到疲惫异常却又没有发挥所能？\r\n你是否发现自己只擅长做琐碎小事？\r\n你是否感到自己总是忙忙碌碌却效率低下？\r\n你是否觉得自己的时间总是被别人的安排打乱？\r\n你是否觉得自己一直在奔波，却总是到不了任何地方？\r\n对于那些想要重新掌控自己的健康、幸福与快乐的人来说，这是一本必读之作。","ratings_count":0,"texts":[{"id":5091,"quote":"\u003cp>就像一句谚语所说的那样，世上从来就没有人会洗租赁的车！这是禀赋效应在作祟，也就是当一个人没有某件物品时，他就倾向于低估这件物品的价值，而当他一旦拥有该物品，就会倾向于高估它的价值。在一项证实禀赋效应作用力的研究中，诺贝尔经济学奖获得者丹尼尔·卡尼曼及其同事做了一项实验。他们把被试随机分成两组，并只给第一组每人发放了一个咖啡杯。然后问第一组人，这个咖啡杯他们想要卖多少钱。问第二组人，他们愿意花多少钱来买这个杯子。结果，“拥有”杯子的人表示低于5.25美元不卖，而没有杯子的人只愿花2.25～2.75美元来买这个杯子。换句话说，仅仅是因为拥有的缘故，就让这些杯子的主人们高估了杯子的价值，并且更加不愿舍弃它们。\u003c/p>\u003cp>这里有一个有用的小窍门：假装你还不曾拥有它\u003c/p>\u003cp>不要问：“这件物品我估值多少？”而是问：“如果手头没有，我愿意花多少钱来得到它？”对于机会和义务，也应该采取同样的方法。不要问：“ 如果错过了这个机会，我会有怎样的感受？” 而是要问：“ 如果我没有这个机会，我愿意花多大的代价去得到它？” 同样，我们也可以问：“ 如果我不是已经参与了这个项目，我愿意费多大的劲儿来参与其中？”\u003c/p>","explains":"\u003cp>学习目标：&nbsp;在跟随我完成本次RIA现场学习后，学习者能够掌握克服禀赋效应的方法，能够正确评估该放弃的东西/机会以作出正确的决策\u003c/p>\u003cp>图书介绍：\u003c/p>\u003cp>F:这本《精要主义》的作者是有被誉为“21世纪的史蒂芬.科维”之称的麦基沃恩。他在本书中介绍了精要主义者的思维模式，并将这种模式转化为一种系统化的程序，助你摆脱无意义的多数，专注有意义的少数，成就有意义、有目的的人生。\u003c/p>\u003cp>A:荣获800-CEO-READ商业书籍大奖，《华尔街日报》畅销书，《纽约时报》畅销书。\u003c/p>\u003cp>B: 你是否也觉得无情的压力正在碾压生活中那些美好的东西？\u003c/p>\u003cp>你是否经常感到疲惫异常却又没有发挥所能？\u003c/p>\u003cp>你是否发现自己只擅长做琐碎小事？\u003c/p>\u003cp>你是否感到自己总是忙忙碌碌却效率低下？\u003c/p>\u003cp>你是否觉得自己的时间总是被别人的安排打乱？\u003c/p>\u003cp>你是否觉得自己一直在奔波，却总是到不了任何地方？\u003c/p>\u003cp>对于那些想要重新掌控自己的健康、幸福与快乐的人来说，这是一本必读之作。\u003c/p>\u003cp>今天给大家介绍怎样克服禀赋效应。\u003c/p>\u003cp>首先说，什么是禀赋效应呢？大家在原文片段中能找到答案吗？禀赋效应：当一个人没有某件物品时，他就倾向于低估这件物品的价值，而当他一旦拥有该物品时，就会倾向于高估它的价值。片段里面给的例子很清晰的说明了这个概念。两组被试，一组人只是因为拥有杯子就会估高杯子的价值；而另外一组人没有杯子他们就会把杯子的价格估低。这就是禀赋效应了。\u003c/p>\u003cp>给大家举个我的例子，我最近要处理掉我儿子小时候用的童车。于是我就跑去“转转”发布广告。这车是我几年前从美国花了4000多人民币海淘回来的。我想着至少得1500才肯转手。结果，等了很久都没人理睬我，偶尔有人留言也是问我600能成交吗。很显然，因为我拥有这个童车我就认为他的价值是1500，但有意向买我这个二手童车的人却认为它的价值是600。这就是典型的禀赋效应。\u003c/p>\u003cp>片段给出了关于克服禀赋效应的方法。&nbsp;\u003c/p>\u003cp>1. 如果是要买卖物品，就“不要问物品的估值” 而是“问如果手头没有，我愿意花多少钱买”\u003c/p>\u003cp>2. 如果是对于机会，就“不要问，如果我错过了机会我会有怎样的感受”而是要问”如果我没有这个机会，我愿意花多大的代价去得到他“\u003c/p>\u003cp>也就是说问自己： 如果我没有X,我愿意花多少精力或者钱去获得X\u003c/p>\u003cp>那么我怎样应用这个客服禀赋效应的方法到我卖童车的事情上呢？ 改变提问的方式，就会得到完全不同的结果。\u003c/p>","interaction":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>A2：催化应用\u003cbr> &nbsp; &nbsp; （分步催化1 - 激活应用场景）\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>提问\u003c/td>\u003ctd>现在请大家想一想，在你的生活中，有没有这样的东西，一旦你想要放弃它们的时候，它们就会显得更加有价值？比如，一本闲置在书架上多年未翻的书，一个仍未开封的厨房用具，或者一件从GAP那里买的但从未穿过的运动衫。不管它们是否对你有用或者让你高兴过，它们属于你这个事实，都会让你觉得它们比不属于你的时候更有价值。请大家分组讨论一下，分享给大家你的那个”一旦想放弃就会让你觉得更有价值的“东西。\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cbr>\u003c/td>\u003ctd>实录\u003c/td>\u003ctd>桃子：一直在教育行业里工做。最近想换行业。可是又认为教育行业所积累的经验很有价值，不愿意放弃。\u003cbr> &nbsp; &nbsp; 德柱：做了很久的程序员。最近想换到产品经理。可是又认为Code的经验很有价值，不愿放弃。\u003c/td>\u003c/tr>\u003ctr>\u003ctd>A2：催化应用\u003cbr> &nbsp; &nbsp; （分步催化2 - 规划行动步骤）\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>提问\u003c/td>\u003ctd>因为拥有，所以认为东西的价值更高而不愿意轻易放弃。刚才我们找到了我们各自不愿意轻易放弃的东西。现在请大家讨论一下，你们打算如何运用今天我们拆页片段介绍的”克服禀赋效应“的方法来帮助自己正确评估该放弃的那个东西以作出正确的决策呢？\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cbr>\u003c/td>\u003ctd>实录\u003c/td>\u003ctd>建斌：超市结账时候给的20块钱的券，可以用38元兑换原价58元的葡萄酒。总是很纠结是否要真的去兑换这个券去买葡萄酒。不兑换就觉得亏。利用今天学到的知识，转换提问方式：如果我没有20块钱的优惠劵，我是否愿意花38块钱去买这个葡萄酒？答案是否定的。因此我以后再也不会被这个优惠券所烦恼。\u003cbr> &nbsp; &nbsp; &nbsp; 超哥：最近在考虑是否留在北京。他假设自己没有在北京，问自己愿意花多少代价留在北京。结果他发现自己“身在福中不知福”。原来留在北京要花费很大的代价，他以前一直嘀咕了留在北京的客观价值。\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1492489751000,"updated_at":1492489751000,"ria":true},{"id":1662,"topic":"面对目标，如何迈出第一步，并坚持下去","learn_goal":"把目标一口一口的吃下去","remark":"痛苦的年终总结又开始了，你有没有发现年初定的\"大目标\"\"小计划\"都还在很远处冲你招手挑衅？\r\n是目标太高冷？是计划太缥缈？\r\n其实只是你没有学会如何迈出正确的第一步。\r\n就让我们一起学习如何把目标一口一口的吃掉吧！","level":"TF2-2","duration":20,"status":0,"type":0,"chaishujia":{"username":"抗抗","city":"北京市"},"club":{"name":"北京翰林分舵","city":"北京市"},"prologue":"大家好，我是抗抗，抗日战争的那个抗抗。\r\n我有3个标签，第一个标签，我是一名建筑师，第二个标签，感悟，我一直觉得我们听到什么，看到什么都远远没有感悟到什么重要，所以感悟是我对自己的要求。第三个标签，是不自洽。这就是我，一个不自洽的感悟型建筑师。\r\n今天我想推荐给大家的书叫做：《精要主义》，副标题是：如何应对拥挤不堪的工作与生活。\r\nF特征:它的作者是格雷戈，这本书主要介绍了精要主义的思维模式，并将其转变为一种行动机制。\r\nA优势:它曾经长期占据美国亚马逊时间管理类图书第一名，作者也因此被誉为“21世纪的史蒂芬•柯维”。股神巴菲特，LinkedIn创始人里德•霍夫曼，甚至是张绍刚都推荐过这本书。相较其他致用类书籍它更加强调思想的转变而非仅仅流于表面的行为建议。\r\nB利益:正如书籍副标题中提到的，这本书能够告诉我们如何用“更好，但更好”的思维方式去处理拥挤不堪的工作与生活。这种方式能够解决我们总是忙忙碌碌却效率低下的困扰，能够让我们不再纠结于应付一些琐碎小事，而留出更多精力与完成大事要事。通过这本书的学习，能让我们摆脱无意义的多数，专注有意义的少数，成就令人羡慕的多彩人生。","ratings_count":0,"texts":[{"id":4223,"quote":"\u003cp>\u003cstrong>【主题】\u003c/strong>\u003cstrong>&nbsp; \u003c/strong>\u003cstrong>三种方式，满足需求\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【图书】\u003c/strong>\u003cstrong>&nbsp; \u003c/strong>\u003cstrong>《精要主义》\u003c/strong>\u003c/p>\u003cp>当初只不过投入了一点点努力来建设一种机制，而现在它顺利无阻地发挥着效用。在家里和在工作中，我们都可以建立这样的机制。关键在于，要从小处着手，鼓励进步，庆祝小胜。以下是一些技巧。\u003c/p>\u003cp>\u003cstrong>1.&nbsp; \u003c/strong>\u003cstrong>关注最低可行性进步\u003c/strong>\u003c/p>\u003cp>在硅谷流行着“完成比完美更重要”的理念。这并不是让大家去制造垃圾。其中的思想，在我看来就是不要在不重要的事情上虚掷光阴，而是要把事情做成。在企业界，这种想法被表述为创造一种“最低可行性产品”（Minimal ViableProduct）。它指的是：“对目标客户有用且有价值的尽可能简单的产品是什么？同样，我们也可以采取“最低可行性进步”（Minimal Viable Progress）的方法。问问自己：“对于我们努力要完成的重要任务，有用且有价值的最小进步是什么？”\u003c/p>\u003cp>\u003cstrong>2.&nbsp; \u003c/strong>\u003cstrong>做最低可行性准备\u003c/strong>\u003c/p>\u003cp>应对一个重要目标或一个最后期限，有两种截然对立的方法。一种是早动手，小步前进；另一种是晚动手，一日千里。“晚而大”意味着要在最后一刻完成全部，通宵加班，把它做完。“早而小”意味着以尽可能少的时间投入，尽可能早地开始。\u003c/p>\u003cp>你只要在一个项目或任务到期前两周仅仅投入10分钟时间，就不用在最后时刻花大把时间焦头烂额地仓促赶工了。\u003c/p>\u003cp>\u003cstrong>3.&nbsp; \u003c/strong>\u003cstrong>直观地嘉奖进步\u003c/strong>\u003c/p>\u003cp>相较于设定庞大的、高远的和不现实的目标，从小处着手，奖励进步，才能成就更多。作为一种额外奖励，这种明确地强化成功的行为，能让我们在过程中收获更多的快乐和满足。\u003c/p>","explains":"\u003cp>现在大家都看完这个片段了，可能觉得有些晦涩难懂，接下来我来分享一下我对这个片段的理解。大家都还记得年初给自己定的那些目标吗？现在距离16年结束还有不到20天，大家的目标完成的怎么样呢？是不是发现有些目标是个硬骨头很难开始很难坚持？这个片段就告诉我们，可以锻炼一种机制，来一步一步实现那些很难的目标。这个机制分3步：\u003c/p>\u003cp>第一步：完成对目标有用的一点点工作，并取得进步，此处不能纠结，不能求完美。\u003cstrong>（举例子）例如我要在今年完成一次马拉松，那就先从跑5公里开始。\u003c/strong>\u003c/p>\u003cp>第二步：做一点点有用的准备，例如要完成马拉松，先买上一双适合的跑鞋，\u003cstrong>（举例子）\u003c/strong>例如我今年要准备去欧洲来一次自由行，那就先咨询咨询旅行社，确定具体去哪个国家。\u003c/p>\u003cp>第三步：给自己的进步一点点奖励，今天跑完5公里，就奖励自己一条新裙子，下周跑完10公里，就奖励自己一件新毛衣。估计等马拉松跑完，咱们一身行头都换新的了。\u003c/p>\u003cp>最后，也是最重要的，就是这个机制要是不断坚持，循环往复的，不停地完成工作，不停地做准备，然后不停地奖励自己。\u003c/p>\u003cp>\u003cstrong>（预防性的讲解）大家可能会说：哎呀，这太简单了，简单为什么你们之前就没有坚持下去呢？其实是你没有抓住机制内在的运作逻辑，先说做，要实现目标，做工作是最直接有效的，其次是准备，只有准备了才知道下一步做什么，这是对做的引导，也避免了不知道做什么的情况。最后，完成了工作，进行了准备，从而得到了奖励，然后我们就尝到了甜头，会继续做工作做准备。这是一整套相互推动，无限循环的运作机制。欠缺了每一环，都失去了他的魅力。是不是没有看上去那么简单？\u003c/strong>\u003c/p>","interaction":"\u003cp>\u003cstrong>催化步骤一：\u003c/strong>大家都来想想你们曾经雄心勃勃的立下的目标吧，哪些现在还没什么起色呢？比如年初立下今年读书100本的同学们。比如好多小伙伴会希望今年能通过自己专业的技能考试。再比如好多人今年都想要跑一次马拉松。\u003c/p>\u003cp>下面给大家1分钟时间，在原文的空白处写下一个自己那些制定了很久，可一直没什么起色的目标。然后我想请小伙伴来给大家做个简短的分享。\u003c/p>\u003cp>分享者1：我想考法语3级的翻译证书。\u003c/p>\u003cp>\u003cstrong>催化步骤二：\u003c/strong>好，小伙伴说出了自己很难办的目标，那么学习了今天的这个机制，面对自己的目标，大家又会怎么做呢？我先举个例子，例如想要通过技能考试的小伙伴，可以先尝试报名专业辅导班，然后把考试大纲的辅导教材买回家，每天如果坚持复习两小时就奖励自己玩游戏10分钟。咱们也来个复习两小时，充电10分钟。\u003c/p>\u003cp>给大家4分钟时间，在组内分享一下自己的目标，以及参照今天的这个机制，如何一步一步完成目标。然后我会请小伙伴做分享。\u003c/p>\u003cp>分享者1：我17年还是想考法语3级的翻译证书，我目前可以做的一点点准备是报了网上辅导班，安排了复习时间，找了老师。一点点工作是每天上30分钟的网课，是3节课。一点点的奖励可以是：坚持一周每天上课，周六休息一天。还可以把看法国电影作为奖励。此外还可以给自己买天使爱美丽电影的周边。\u003c/p>\u003cp>感谢小伙伴的分享，我来总结一下，今天我给大家分享了对于难啃的硬骨头目标，怎么慢慢把它它吃掉！这是一种神秘而有效的机制，叫做三个一点点，一点点的功课，一点点的准备，一点点的奖励。最后再有很多很多的坚持，你的目标一定会实现。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1482397638000,"updated_at":1488360074000,"ria":true},{"id":1581,"topic":"关注当下，从最重要的开始","learn_goal":"了解当下此刻什么是最重要的，从最重要的开始做起","remark":"在当今忙碌快节奏的时代，有时候我们恨不得把自己会分身术，因为身边有太多的事情需要处理，比如查看电子邮件、听微信留言、读一本必须要读的书，这些时常使我们感到焦虑和紧张，不知如何下手。\r\n此刻我们唯一能所的事情，就是停下来，投入到当下，了解此刻最重要的事情是什么？\r\n只有了解了what's important now？才能真正地win。","level":"TF1-1","duration":15,"status":0,"type":0,"chaishujia":{"username":"钱彩虹","city":"武汉"},"club":{"name":"武汉珞珈分舵","city":"武汉"},"prologue":"大家好！我是钱彩虹。\r\n我是一名大学老师，也经常给企业做礼仪培训工作。\r\n平时在工作和生活中，因为自我管理能力比较的弱，导致拖延症比较严重，同时，家事、工作任务等琐事也比较多，导致想学习却总觉得没有时间，即使有时间也学不进去，书本是看过就忘。偶然的机会，参加了May老师的一次现场拆书活动。觉得这种方法很新颖、很适合我。后来就找到了拆书帮在武汉的分舵，上周也参加了RIA训练营，通过实践练习有了更深刻的认识。今天正式开始升级打怪的历程。\r\n拆书是一种读书方法论。根据成人的学习特点，由“拆书人”通过将一本书的某个片段拆出来进行引申，贯彻到自己今后的思考和行动中。\r\n拆书实践过程中常用到的方法包括：便签法、现场拆解、俱乐部活动。\r\n其中便签法主要应用于个人学习，通过R（阅读片段）、I（用自己的话重述知识）、A1（描述自己的相关经验）和A2（以后我怎么应用）几个步骤，让个人读书能达到同主题培训的效果；\r\n现场拆解由一位拆书家选取出一些片段，组织一场现场学习，引导和促进一群人把知识拆为己用；\r\n拆书帮俱乐部活动是在拆书帮便签读书法的基础上，由一群热爱学习的小伙伴组成的互相式学习型青年自组织，是拆书","ratings_count":0,"texts":[{"id":4120,"quote":"\u003cp>活在当下的三个技巧：\u003c/p>\u003cp>1.想清楚当下最重要的是什么\u003c/p>\u003cp>同一时刻很多事情都争着抢着要被优先完成的这种压力，对我再熟悉不过了。焦虑和紧张让我停了下来。我跪下、闭上眼睛，问自己：当下重要的是什么？沉思片刻后，我明白了，在知道当下重要的是什么之前，重要的事搞清楚：“当下重要的是什么这个理念。”\u003c/p>\u003cp>我站了起来，开始整理，我把所有散乱的堆在我身边的东西收了起来，放到该放的位置上去，免得他们分散我的注意力，也免得我每次经过时，他们迫使我按他们的吩咐去做，我关掉了手机，没人给我发短信，让我如释重负。我打开笔记本记录下这一天，就让我收起了心，用铅笔给脑海中出现的所有事情列一个清单。&nbsp;\u003c/p>\u003cp>当你面临很多很多任务，以至于不知该从何下手收拾，停下来，深呼吸，投入到当下，问问自己此时此刻最重要的是什么——不是明天最重要的是什么，甚至不是一小时后最重要的是什么？如果不确定，那就把所有征求你注意力的事情都列出来，然后换掉所有此时此刻不重要的事情。&nbsp;\u003c/p>\u003cp>2.专注在当下，把未来清除出去。&nbsp;\u003c/p>\u003cp>我采取的下一步措施是坐下来，给那些可能这样的事情列一个清单，不是针对当下的，这个清单不是用来记录确定承诺的，它只不过是用来把这些想法从脑子里清除出去，留在本子上而已，这样做有两个目的，第一它保证了我不会忘了这些想法，他们也许将来会被证明有用，第二，它减轻了我必须现在就实行它们那种压迫感和身心的危险。&nbsp;\u003c/p>\u003cp>3.给每个清单排列优先顺序\u003c/p>\u003cp>接下来，我给每个清单都排列的先后顺序，然后，我开始做当下重要的是什么这个清单上所列的事情，一次一件，我冷静地完成着，清单事项，每完成一件，就从清单上划掉。到了睡觉时间，我不但做完了所有需要在当时完成的事情，而且还因为认真专注而更出色，更高效的完成任务。\u003c/p>","explains":"\u003cp>《精要主义》是英国作家格雷格.麦吉沃恩的著作，他是一名精要主义的提出者、倡导者和领导者。这本书就是帮助我们摒弃生活和工作中的琐碎、直抵精要，从而从容应对拥挤不堪的工作和生活。\u003c/p>\u003cp>每天我们是不是觉得有很多事情要争着抢着完成，从而紧张焦虑？解决这种焦虑的方法之一就是专注于当下，充分投入于当下，共有三个技巧可用，分别是：想清楚当下最重要的是什么、专注当下把未来清除出去、给每一个清单列先后顺序。具体实施步骤如下：\u003c/p>\u003cp>1.坐下来，深呼吸，将分散注意力的事情先清除，如手机关机。\u003c/p>\u003cp>2.打开笔记本，记下脑海中出现的所有事情，列一个清单\u003c/p>\u003cp>3.区分“当下最重要的事”和“可能未来重要的事”，把未来重要的事写在另一页\u003c/p>\u003cp>4.给每个清单上的事情排列一个先后顺序\u003c/p>\u003cp>5.按照清单上重要顺序开始做，一次做一件。\u003c/p>\u003cp>6.每完成一件，就从清单上划掉，直至完成。\u003c/p>","interaction":"\u003cp>A1：每天早上我定了3个闹钟，但是总是拖到最后一分钟才不得不起床。要么匆忙收拾出门，不上班时觉得应该有很多事情要做却又不知道做什么。\u003c/p>\u003cp>每天上班时间除了按部就班地完成工作，再就是领导安排的临时任务，或者突然想起来的一些琐事。如果想不起来空闲时间都用来刷手机。\u003c/p>\u003cp>一天过完，感觉好像什么也没做，懊悔不已。\u003c/p>\u003cp>A2：如果第二天要出差，一般是我最焦虑的时候，因为要安排行李、行程、家务、孩子等等很多的事情，生怕有遗漏。此时，运用此方法应该是比较有效的。\u003c/p>\u003cp>1.找一个没有干扰的时间，坐下来好好捋一捋要做的事情。\u003c/p>\u003cp>2.用笔记本简要记下需要安排的所有要做的事\u003c/p>\u003cp>3.将事情分类：出差物品清单+出差行程安排（重要）、孩子的学习安排（次重要）、家务其他安排（可委托）。\u003c/p>\u003cp>4.将所有事情按重要性和紧急性排一个顺序，其中提前确定行程，包括票务等信息一定要确认清楚是最重要的。\u003c/p>\u003cp>5.将分好类的清单，用手机APP记录下来。\u003c/p>\u003cp>6.按照重要性和紧急性先后顺序一件一件开始做，完成的就划掉\u003c/p>\u003cp>7.有些需要在事后提醒的，调好闹钟\u003c/p>\u003cp>8.最后，再按清单检查一遍，确保无误\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1481517199000,"updated_at":1481517514000,"ria":true},{"id":1509,"topic":"在工作和生活中，从小处着手，鼓励进步，庆祝小胜","learn_goal":"在工作和生活中，从小处着手，鼓励进步，庆祝小胜","remark":"《精要主义》如何应对拥挤不堪的工作与生活！\r\n主张只做该做的事情。它向“我可以拥有一切”和“我可以做好一切”的主流论断发起攻击，倡导“在合适的时机，以恰当的方式，追求合适的事情”。它旨在让人们重新掌控自己的选择权，自主决定如何支配宝贵的时间和精力——而不再是许可他人替我们作出选择。\r\n“21世纪的史蒂芬·柯维”麦吉沃恩诚意之作，摒弃琐碎而无足轻重的生活，过真正重要而有意义的人生！","level":"TF1-2","duration":15,"status":0,"type":0,"chaishujia":{"username":"潇潇","city":"上海市"},"club":{"name":"上海申活分舵","city":"上海市"},"prologue":"大家好，我是潇潇。我们本次的学习主题是在工作和生活中，从小处着手，鼓励进步，庆祝小胜。希望学习者跟我学习过后，能够将任务目标分解，先从小处着手，鼓励小胜。","ratings_count":0,"texts":[{"id":4039,"quote":"\u003cp>\u003cstrong>《精要主义》\u003c/strong>\u003c/p>\u003cp>\u003cstrong>1、 \u003c/strong>\u003cstrong>关注最低可行性进步\u003c/strong>\u003c/p>\u003cp>在硅谷流行着“完成比完美更重要”的理念。这并不是让大家去制造垃圾。其中的思想，在我看来就是不要在不重要的事情上虚掷光阴，而是要把事情做成。在企业界，这种想法被表述为创造一种“最低可行性产品”（Minimal Viable Product）。它指的是：“对目标客户有用有价值的尽可能简单的产品是什么？”\u003c/p>\u003cp>同样，我们也可以采取“最低可行性进步”（Minimal Viable Progress）的方法。问问自己：“对于我们努力要完成的重要任务，有用有价值的最小进步是什么？”我在本书的写作中就采用了这种方法。比如，当我还在探索阶段的时候，在动笔（或敲打键盘）之前，我会在Twitter 上面分享一个小小的想法（我的最低可行性产品）。如果能够在那上面引起共鸣，我就会给《哈佛商业评论》写一篇博客文章。通过这种只需要花费很少精力的迭代过程，我能够知道应该在什么地方搭建一座桥梁，让自己所思考的事情和同别人生活最相关的事情之间建立起联系。\u003c/p>\u003cp>皮克斯动画工作室把这个方法用在了他们的电影中。这些电影的创作不是开始与脚本，而是开始于情节串联图版，或者叫做连环漫画版电影。他们尝试各种想法，并观察哪些有效，在小范围内进行数百次实验。然后，做出一个影片放映给小规模人群看，以便提前获得反馈。这样，他们就可以用尽可能少的投入，获得尽可能快的长进。皮克斯动画工作室的首席创意官、迪士尼幻想攻错的首席创意顾问约翰·拉塞特（John Lasseter）说：“实际上，我们不是在完成电影，而是在发行电影。”\u003c/p>\u003cp>\u003cstrong>2、&nbsp;&nbsp; \u003c/strong>\u003cstrong>做最低可行性准备\u003c/strong>\u003c/p>\u003cp>应对一个重要目标或者一个最后期限，有两种截然对立的方法。一种是早动手，小步前进；另一种是晚动手，一日千里。“晚而大”意味着要在最后一刻完成全部，通宵加班，把它做完。“早而小”意味着以尽可能少的时间投入，尽可能早地开始。\u003c/p>\u003cp>你只要在一个项目或任务到期前两周仅仅投入10分钟时间，就不用在最后时刻花大把时间焦头烂额地仓促赶工了。有了目标或者期限，就问问自己：“我此刻能够做的最低可行性准备是什么？”\u003c/p>\u003cp>有一位领导，他非常善于发表激动人心的演说。他解释说自己的秘诀就是在演说的6个月前就开始为这些鸿篇阔论做准备。不是准备整个讲稿，只是开始而已。如果未来几个星期或几个月内你有一个重大报告要做，那么你现在就打开文件，花4分钟，想到什么就写什么。然后，关闭文件。不要超过4分钟。开始就够了。\u003c/p>\u003cp>一位在纽约的同事有一种很简单的方法：任何时候她安排了会议或者有电话要打，就会很精确地花15秒钟备忘一下那个会议的主题。这样在开会那天早上，当她坐下来准备发言要点的时候，可以参考这个备忘录。她不需要规划整个会议的议程，只要花几秒钟提前准备，就会大有收益。\u003c/p>\u003cp>\u003cstrong>3、&nbsp;&nbsp; \u003c/strong>\u003cstrong>直观地嘉奖进步\u003c/strong>\u003c/p>\u003cp>你记不记得，在你5岁的时候，学校组织了一场募捐活动？你记得那个用来直观地展示学校向目标迈进的大温度计吗？你是否记得，看到温度计一天天上升时，心情多么激动，多么欢欣鼓舞？或者，你的父母给你准备了一个星形图，每次你吃了菠菜，或按时睡觉，或打扫了房间，你就能得到一颗星星，然后很快你就不用什么激励物也在做这些事情了。\u003c/p>\u003cp>直观地看到自己正在朝着目标进步，会产生一种巨大的力量。不管是在家里，还是在单位里，不要不屑于把这样的方法运用到你自己的重要目标上。\u003c/p>\u003cp>相较于设定庞大的、高远的和不现实的目标，从小处着手，奖励进步，才能成就更多。作为一种额外奖励，这种明确地强化成功的行为，能让我们在过程中收获更多的快乐和满足。\u003c/p>","explains":"\u003cp>\u003cstrong>【自我介绍】\u003c/strong>大家好，我是潇潇。下面我来先做一个自我介绍。我有三个便签：阅读+运动+育儿。我喜欢阅读，现在基本上每周至少看两本书，我乐意将书中学到的知识与自己的实际生活相结合，成为一个更好的自己；其次我热爱运动，现在每天运动或者锻炼的形式有Keep或者冥想，以后会根据自己的情况逐步定期拓展其他的运动项目；最后一个标签是育儿，我家里有个21个月的宝宝，我立志成为一个和蔼可亲的好妈妈，教育好我的孩子。\u003c/p>\u003cp>\u003cstrong>【书籍介绍】\u003c/strong>今天我拆解的书籍是《精要主义》（格雷戈·麦吉沃恩著，Greg Mckeown）。这本书的理念是，若想要最大限度成就真正重要之事，切忌贪多求全，事事应允。如果答案不是一个确定的Yes，就是一个肯定的No。只有摒弃琐碎而无足轻重的生活，才能过真正重要而有意义的人生。\u003c/p>\u003cp>\u003cstrong>【学习目标】\u003c/strong>今天我们的学习目标是从小处着手，鼓励进步，庆祝小胜。下面我把拆页发给大家，给大家2分钟的时间阅读原文。\u003c/p>\u003cp>\u003cstrong>【I】\u003c/strong>\u003c/p>\u003cp>【Why】很多时候人们在碰到一项任务时，倾向于拖延或者离截止时间很近了才开始行动。但如果在项目开始的时候，仅仅花很少的时间投入，你就不用在最后时刻花大把的时间焦头烂额的仓促赶工了。\u003c/p>\u003cp>【How】所以经常问自己这么两个问题：1、对于我们努力要完成的重要任务，有用有价值的最小进步是什么？2、为了完成这个最小的进步，我此刻能够做的最低可行性准备是什么？除此之外，对于每一次小的进步，设定一种嘉奖的方式，让自己能明确地看到进步，这种明确强化成功的行为，能让我们在过程中收获更多的快乐和满足。\u003c/p>\u003cp>【案例】下面讲讲发生在我自己身上的案例。我有件事情一直都拖延着没有做，抄写李笑来得到专栏《通向财富自由之路》，因为抄写的时候可以让我做到“只字不落的阅读”，每一次抄写整理思想上都会有不同的认识。抄写了几篇并留言之后，一直都没有多余的时间再做这件事情。那么为了把我想做的事情坚持下去，第一步设定我的最小进步：写一篇已发布文章的总结，对整个专栏有一个更深入的印象，了解大致的框架；第二步：最低可行性的准备：先花10分钟的时间，把所有的已发布文章的标题列出来；第三步：设定嘉奖，设置一个打卡文件，每完成一篇打一个√，如果我坚持把前面落下的抄写完成后，奖励自己学习秋叶的系列课程《轻松手绘：用简笔画提升你的竞争力》。\u003c/p>\u003cp>【分组】\u003c/p>\u003cp>一会儿我们需要分组讨论下，所以我先给大家分组，从我左边开始，三人一组。\u003c/p>","interaction":"\u003cp>A1\u003c/p>\u003cp>现在进入A环节，那么，请大家先想想自己过去有没有过去一直都拖延着没有做的事情？我给大家3分钟时间请大家在小组内分享。\u003c/p>\u003cp>下面我们有请一位小伙伴分享下自己的案例，有谁自愿分享的请举下手。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;学习者案例：以前我想做100个俯卧撑，现在我从20个开始，然后逐步加到30个、40个，最后实现自己的目标。我觉得这就是能达到自己力所能及的小目标。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;A2：\u003cbr>\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;我们读过这个拆页，了解到对于一项任务可以从小处着手，奖励自己，鼓励自己的进步。大的目标是一天一天从小的目标积累过来的，关注自己最小的可行行动，设定嘉奖，会让自己行动的过程更满足。那么我们可以针对自己拖延的事情，先设定第一步最小进步是什么？第二步为了完成这个最小进步，我们可以做的最低可行性准备是什么？第三步给自己的奖励是什么？下面花1分钟的时间写一下自己的便签。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;学习者案例：我健身减肥这个事情拖了很长时间，我设定的最小进步是从明天开始每天做完一个keep的2级的训练，在每天送完孩子上学回到家就马上铺上垫子开始做，完成后给自己一个士力架。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1480671542000,"updated_at":1480671542000,"ria":true},{"id":1508,"topic":"设置缓冲区使自己保持头脑理智清醒","learn_goal":"学习者学会比预计时间多留50%","remark":"《精要主义》如何应对拥挤不堪的工作与生活！\r\n主张只做该做的事情。它向“我可以拥有一切”和“我可以做好一切”的主流论断发起攻击，倡导“在合适的时机，以恰当的方式，追求合适的事情”。它旨在让人们重新掌控自己的选择权，自主决定如何支配宝贵的时间和精力——而不再是许可他人替我们作出选择。\r\n“21世纪的史蒂芬·柯维”麦吉沃恩诚意之作，摒弃琐碎而无足轻重的生活，过真正重要而有意义的人生！","level":"TF1-1","duration":10,"status":0,"type":0,"chaishujia":{"username":"潇潇","city":"上海市"},"club":{"name":"上海申活分舵","city":"上海市"},"prologue":"大家好，我是潇潇。今天我们的学习目标是设置缓冲区使自己保持头脑理智清醒，希望大家跟着我学习之后可以学会比预计时间多留50%的方法。","ratings_count":0,"texts":[{"id":4035,"quote":null,"explains":null,"interaction":null,"flags":{"r":false,"i":false,"a":false,"a1":false,"a2":false,"a3":false}},{"id":4036,"quote":null,"explains":null,"interaction":null,"flags":{"r":false,"i":false,"a":false,"a1":false,"a2":false,"a3":false}},{"id":4037,"quote":null,"explains":null,"interaction":null,"flags":{"r":false,"i":false,"a":false,"a1":false,"a2":false,"a3":false}},{"id":4038,"quote":"\u003cp>\u003cstrong>《精要主义》P205~206\u003c/strong>\u003c/p>\u003cp>2. 比预计时间多留50%\u003c/p>\u003cp>我认识一个人，她总以为自己到商店只要5分钟就行，因为她有一回真的只用5分钟就到了那里。但实际上，没有10~15分钟根本就不够。这件事本身没有什么大不了的，但不幸的是，她对于生活中的绝大多数事情都是这么估计的。结果，迟到便成了家常便饭。更糟糕的是，她总是处于压力之下，这让她感到内疚不已。在这样一种循环之中生活久了，她甚至都意识不到自己正处于一种常态化的压力之下。这种状况还影响了她的健康。然而，她依旧固执已见，认为只要5分钟就能到达商店，只要半小时就能完成电话会议，一星期就能写完重要报告，或者任何其他事情她都可以完成——这些她的确偶尔可以做到。但是这让她和她周围的人付出了很大代价。其实她只需要准备一些缓冲，就可以把那些仓促完成的事情做得更好。\u003cbr> 你是否也曾低估过完成任务所需的时间？如果是，那么你就和很多人同病相怜了。这种现象被称作“规划谬误”（Planning Fallacy）。这一术语由丹尼尔·卡尼曼于1979年提出，它指的是人们倾向于低估任务完成所需的时间，即便是在以前已经承担过相同任务的情况下也是如此。在一项研究中，37名学生被问到他们认为自己需要多长时间才能完成毕业论文。当这些学生被要求在“一切尽可能顺利”的前提下估计论文完成时间时，他们的平均估算值是27.4天。而当他们被问到如果“一切情况糟的不能再遭”，那么完成论文需要多长时间时，他们的平均估算值是48.6天。最后，这些学生实际完成毕业论文的时间平均55.5天，只有30%的学生在他们估计的时间里完成了任务。令人不解的是，人们一方面承认自己有低估的倾向，但与此同时又总是相信自己当前所作的估计是准确的。\u003cbr> 在关于人们为何会低估任务完成时间的诸多解释中，我认为“社会压力说”是最有意思的一种。一项研究发现，如果人们以匿名的方式估计任务完成所需的时间，那么他们就不会对规划谬误感到愧疚。这意味着，通常我们实际上知道自己无法在给定的期限里完成任务，但是我们不愿意向别人承认。\u003cbr> 不管原因如何，结果都无外乎当我们做到时往往已经晚于自己预先所说的时间：开会迟到，工作迟交，账单迟结，等等。这样，本来可以顺利完成的任务，执行起来却变得阻力重重，令人沮丧不已。\u003cbr> 要避免出现这样的情况，方法很简单，只需要在我们估算的任务或项目完成所需的时间上加50%的缓冲量即可（如果觉得50%的缓冲量太过奢侈，那就想想实际完成时间比预计时间多50%的情况是多么常见吧）。如果你为一个电话会议留了一小时的时间，那么就再额外增加30分钟吧。如果你估计带儿子去参加足球训练需要10分钟，那么就在联系开始前15分钟离开家吧。这样做不仅有助于缓解担心自己会迟到时感受到的压力（想象一下，如果我们时间充裕，那么堵车时就大可不必着急心慌），而且如果发现任务比预想的完成得更快、更轻松（不过对于绝大多数人来说这种事情发生的概率很小），那么这多出来的时间就让人感觉像是得了一笔奖金一样。\u003c/p>","explains":"\u003cp>自我介绍：\u003c/p>\u003cp>下面我来先做一个自我介绍。我有三个便签：阅读+运动+育儿。下面我来逐个解释一下，首先我喜欢阅读，现在基本上每周至少看两本书，我乐意将书中学到的知识与自己的实际生活相结合，希望成为更好的自己；其次我热爱运动，现在每天运动的形式有Keep或者冥想，以后会根据自己的情况逐步定期拓展其他的运动项目；最后一个标签是育儿，我家里有个21个月的宝宝，我希望成为一个和蔼可亲的好妈妈，教育好我的孩子。\u003c/p>\u003cp>拆书帮介绍：\u003cbr>\u003c/p>\u003cp>接下来我来介绍下拆书帮。现场有没有是第一次来的还不了解拆书帮的小伙伴请举下手？ \u003c/p>\u003cp>首先我们看下什么是拆书。“拆书”是一种学习方法论，用于以提升能力、解决问题为目标的成人学习，强调以学习者为中心而不是以知识为中心，要把知识关联学习者的经验、规划具体的运用。分为个人学习的拆书法和组织学习的拆书法：个人学习的应用是便签法，让人读一本书就能达到参加同主题培训的效果；组织学习的应用是一位拆书家拿一本书加工出一场现场学习，引导和促进一群人把知识拆为已用。\u003c/p>\u003cp>“拆书帮”是基于拆书法的学习爱好者社群，表现为各地的拆书帮分舵（也叫拆书帮俱乐部）。拆书帮分舵是公益性青年组织，其使命是帮助更多学习爱好者成长为拆书家。\u003c/p>\u003cp>\u003cstrong>“\u003c/strong>RIA便签读书法”：R就是Reading阅读的意思，I就是Interpretation解释，意思是用自己的话把原文复述一遍；A是Appropriation，意思是应用，这种应用有A1和A2。A1是联系自己过去的经验，A2是以后自己应该怎么去实践和运用。\u003c/p>\u003cp>书籍介绍：\u003c/p>\u003cp>《精要主义》（格雷戈·麦吉沃恩著，Greg Mckeown）\u003c/p>\u003cp>这本书的理念是，若想要最大限度成就真正重要之事，切忌贪多求全，事事应允。如果答案不是一个确定的Yes，就是一个肯定的No。只有摒弃琐碎而无足轻重的生活，才能过真正重要而有意义的人生。\u003c/p>\u003cp>那么下面大家花2分钟的时间把原文阅读一遍。\u003c/p>\u003cp>【I】\u003c/p>\u003cp>很多时候人们经常会低估完成任务所需要的时间，，即便是在以前你已经做过相同任务的情况下也是这样。通常我们实际上无法在给定的期限里完成任务，只是我们不愿意向别人承认。其实生活中突发事件是经常发生的，如果我们不给日常生活中要做的事情留足时间，很有可能会让自己陷入被动的情况。\u003c/p>\u003cp>要避免出现这样的情况，方法很简单，只需在我们估算的任务或项目完成所需的时间加上50%的缓冲量即可，多的时间算作是对自己的一个奖励。为了向大家说明50%其实也还是比较保守的，我以发生在我身上的一个例子作为说明。\u003c/p>","interaction":"\u003cp>A1\u003c/p>\u003cp>就我自己的经验来说，就经常发生预留时间比实际行动的时间要少很多的情况。上周末在我女儿玩手机的时候，不小心手机屏幕被她摔碎了，当时很心疼我的手机，当即决定要拿出去维修，出门的时间是11点半，平时我去维修店那边预计的时间是30分钟，估计修手机的时间是半个小时，所以来回时间应该是1个半小时，按计划刚好1点赶回来吃午餐。可是路上发生的事情我完全没有预料到。第一：周末在维修店所在的商区附近很难找到合适的停车位，找停车位浪费了很多时间；第二：因为第一次去维修店，所以在商场里找维修点也花了不少时间；第三：到了维修店，前面还有好多人，需要等待的时间也很长，并不是我预想的半小时就能搞定的。最终我办这件事情花了3个小时，比预想的整整多花了一倍的时间。\u003c/p>\u003cp>A2\u003c/p>\u003cp>我想以后做事的时候，也可以多预留50%的时间。把这个技巧用到拆书上，我可以这么做。\u003c/p>\u003cp>1、&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 我以后来拆书的路上可以多预留50%的时间，比如：如果是1个小时路程，我就提前一个半小时出发；如果需要2个小时路程，我就准备3个小时。\u003c/p>\u003cp>2、&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 现在基本上是提前一周预备拆书：a）挑选拆页（在平时阅读过程中选择，时间无法确定）；b）写便签（有感悟的片段2小时）；c）根据反馈修改便签（4小时）；d）提前演练（5小时）；总计11小时。\u003c/p>\u003cp>那么我的计划可以修改为提前一周半开始准备，写便签的时间修改为3小时，修改便签的时间调整为6小时，演练的时间修改为8小时。总计17个小时。\u003c/p>\u003cp>那么到这里，我今天的分享就结束了，谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1480670632000,"updated_at":1480671301000,"ria":true},{"id":1447,"topic":"面对机会，进行选择是应遵循的三条最低标准+三条极端标准","learn_goal":"在跟随我完成本次RIA现场学习后，学习者能够运用片段中的步骤","remark":"书籍的作者是格雷戈·麦吉沃恩 (Greg McKeown) ，被誉为“21世纪的史蒂芬·柯维”。这本书长期占据美国亚马逊时间管理类图书第一名，股神巴菲特，LinkedIn创始人里德·霍夫曼，甚至是张绍刚都推荐过这本书。\r\n书中主要阐述了“更少，但更好”的思维模式，当你感到自己总是忙忙碌碌却效率低下，当你纠结于应付一些琐碎小事，而大事却迟迟不见起色，这本书中所推荐的思维方式和处事态度就洽洽能把这些烦恼解决掉。通过这本书的学习，能让你摆脱无意义的多数，专注有意义的少数，成就有目的的人生。","level":"TF2-1","duration":20,"status":0,"type":0,"chaishujia":{"username":"抗抗","city":"北京市"},"club":{"name":"北京翰林分舵","city":"北京市"},"prologue":"大家好，我是抗抗，抗日战争的那个抗抗。\r\n我有3个标签：首先我是一名建筑师，其次，我是多样性的，我眼中的世界和我心中的世界都是多样的。最后，我最重要的一个标签是X，这个X会随时随地的变化，今天，这个X代表：我好忙\r\n今天我想推荐给大家的书叫做：《精要主义》，副标题是：如何应对拥挤不堪的工作与生活。它的作者是格雷戈·麦吉沃恩 (Greg McKeown) ，被誉为“21世纪的史蒂芬·柯维”。这本书长期占据美国亚马逊时间管理类图书第一名，股神巴菲特，LinkedIn创始人里德·霍夫曼，甚至是张绍刚都推荐过这本书。\r\n书中主要阐述了“更少，但更好”的思维模式，当你感到自己总是忙忙碌碌却效率低下，当你纠结于应付一些琐碎小事，而大事却迟迟不见起色，这本书中所推荐的思维方式和处事态度就洽洽能把这些烦恼解决掉。通过这本书的学习，能让你摆脱无意义的多数，专注有意义的少数，成就有目的的人生。\r\n在跟随我完成本次RIA现场学习后，学习者能够运用片段中的步骤，在机会到来时做出正确的选择。","ratings_count":0,"texts":[{"id":3955,"quote":"\u003cp>\u003cstrong>【主题】&nbsp;&nbsp;面对机会，应如何取舍\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【图书】&nbsp;&nbsp;《精要主义》\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【章节】&nbsp;&nbsp;第8章\u003c/strong>\u003c/p>\u003cp>R:&nbsp;&nbsp;&nbsp;\u003c/p>\u003cp>\u003cstrong>三条最低标准+三条极端标准\u003c/strong>\u003c/p>\u003cp>在决定自己应寻找什么样的机会时,精挑细选只是问题的一个方面，当机会自己找上门来的时候，问题就变得更复杂了。\u003c/p>\u003cp>对错过好事儿的担心会产生很大的影响。我们怎么能说“不”呢？机会就在那里，等着我们去拿。我们还可能曾经追求过这样的机会，但是现在要得到它简直易如反掌，而我们却瞻前顾后。但如果只是因为它容易得到而接受它，我们就会冒未来不得不拒绝另一个更有意义的机会的风险。\u003c/p>\u003cp>当机会向你走来时，不妨用以下这种简单、系统的流程来执行精挑细选的标准。\u003c/p>\u003cp>第一步，把机会写下来。\u003c/p>\u003cp>第二步，写下3条“最低标准”，如果这个机会要进入考虑范围的话，就必须达到这3条标准。\u003c/p>\u003cp>第三步，写下3条理想或“极端标准”，如果这个机会要被考虑的话，也必须满足这3条标准。\u003c/p>\u003cp>按照这个流程，一旦这个机会不能满足第一组标准，那么答案很显然就是No。但是如果它不满足3条极端标准中的2条，答案依然是No。﻿\u003c/p>","explains":"\u003cp>\u003cstrong>I环节，用自己的话讲解原文知识点\u003c/strong>\u003cstrong>（2分钟）\u003c/strong>\u003c/p>\u003cp>每天我们都会遇到各种机会，大的，小的，期待许久的，不经意而来的，那么面对扑面而来的机会，如何评判，如何取舍呢？\u003c/p>\u003cp>\u003cstrong>\u003cstrong>（负面一般做法+这样做的坏处）\u003c/strong>回想双11时面对商家的疯狂打折，你是怎么应对这个机会的呢？是不是脑子一热，无原则，无判断，买了一堆不那么需要，不那么喜欢的东西，最后损失了银子，没准儿还造成了家庭矛盾呢？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>(\u003c/strong>\u003cstrong>失败案例)\u003c/strong>\u003cstrong>当我看到这个片段，除了反思双十一我的剁手行为之外，我还回想到之前工作中的一次失败经历。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>年初，有个项目摆在我面前，规模不大，而且与我的专业不对口，但是有好处是短频快，而且甲方之前与我们没有合作过。我当时只是觉得专业不对口，就草草选择了放弃这个机会。于是项目部就把这个项目委托给了B，谁知小项目结束后，这个甲方就继续与B合作了一个专业非常对口，且规模更大的项目，那个不对口的小项目只是之后的大项目的预热，我后悔莫及，由于我没有充分的判断，一个很好的机会就这样失去了。\u003c/strong>\u003c/p>\u003cp>今天的片段就是告诉大家如何用理性的方式来评判一个机会的优劣好坏。这个方法是可以量化的，可以打分的。判断的方法一共分为4步：大家可以看看原文下面的表格。\u003c/p>\u003cp>1.&nbsp;&nbsp; 首先，把机会写下来，简短明确一目了然。\u003c/p>\u003cp>2.&nbsp;&nbsp; 之后，罗列出这个机会我们应该抓住所需要的最低标准，3个就够了。比如面对一件打折的衣服，1价格足够低，能买得起，2尺寸合适，能穿的进去，3穿着基本舒适，就是最低标准。\u003c/p>\u003cp>3.&nbsp;&nbsp; 同样的，也列出3个最高，最理想标准，就是指抓住这个机会我们能够得到的三个好处。还是对于打折衣服吗，1穿着美观，体现气质，2能穿着一段时间，不会过时，3能与其他衣服至少2-3件衣服进行搭配，就是最高标准。\u003c/p>\u003cp>4.&nbsp;&nbsp; 最后就是评判环节，如果我们要抓住这个机会，就必须满足3个最低标准，同时满足2个最高标准。也就是3-2的评判标准。\u003c/p>\u003cp>有了这4步，就能准确地抓住好的机会，而把坏的机会一脚踢开。\u003c/p>\u003cp>\u003cstrong>（ 负面例子变成正面例子）如果再回看我之前的失败案例我会怎么做呢？我会列出面对新项目的3个最低标准：1，能独立完成；2，不会拖很久；3，能计入工作量。三个最高标准：1，对专业发展有帮助；2，能展现我的工作能力；3，客户有潜力。可见3个最高标准只有第一个不能满足，可见在学习了片段的4个步骤之后，依据3-2的机会评判标准，我应该选择接受这个项目。\u003c/strong>\u003c/p>","interaction":"\u003cp>大家有没有这样的情况，有一个新的工作机会来了，可能与自己的专业不对口，或者与自己预设的成长目标有差距，但是又有一笔非常不错的薪酬，这时应该如何取舍呢？\u003c/p>\u003cp>也许例如超超小伙伴今天的真实经历，下午有个的拆书帮活动，是个好机会，但是要是参加就必须把单位的活动推掉。但是拆书活动又能带给我们新的知识，结识新的朋友。\u003c/p>\u003cp>还例如燕子姐给孩子报辅导班，也许口碑很好的辅导班价格很高，报名时间非常短，就放弃了，最后可能其他上了辅导班的孩子英语上或绘画上会有提高，自己的孩子进步的慢一些。\u003c/p>\u003cp>也许我们都会遇到这种情况，因为机会来了，我们由于没有恰当的评判方式，结果做了错误选择，最后造成损失。\u003c/p>\u003cp>接下来我想请大家回想一下，之前是不是有类似情况：当一个机会摆在我的面前，就像至尊宝，没有抓住他，给大家一分钟的时间，请大家把自己情况写在原文下的框子里面，然后我会请一个小伙伴来分享一下他自己的一次错过的机会，一次评判的不够准确的机会。\u003c/p>\u003cp>\u003cstrong>分享者1：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>考大学时候报专业，当时太小了，爸妈也不太管，我就按自己想法来的，最后报的不合适，直接被调剂，这个事儿对我影响挺大的。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>引导部分：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家：那有没有想过，如果再给你一次机会，我们能不能尝试用这四步：首先写下这个机会，之后罗列3个最低标准，再罗列3个最高标准，最后按照3-2的原则来进行评判。我们应该如何做呢？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>分享者1：我高考报志愿这个机会，首先我要先选择学校的位置，城市很重要，第二，学的专业应该我喜欢，第三，分数能报上。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家：那极端的三个标准呢？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>分享者1：首先专业应该是学校的重点专业，第二，选择对未来发展有促进作用的，长久发展的可能。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家：3个最低标准：城市、专业要喜欢、分数能满足；3个最高标准：这位小伙伴罗列了2个，对他来说最极端的，首先是专业自身的发展前景，之后是专业在学校中的地位，学习是不是更重视这个专业，最后，我想是不是还有别的极端标准：就是这个专业在这个学习有1-2位老师，是我们之前所仰慕的，这样如果我们今后考虑考研、读博就可以选择这位导师。按照这样的方法，如果我们再次进行专业的选择，就有章可循了。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>接下来请大家在想想刚才自己写下来的机会，如果再给我们一个复盘的机会，我们应该如何选择？也可以是当下我们所面临的机会，如果我们按照这个方法进行选择，回是什么结果？\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>分享者2：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>我发现我写完这个表格，我对于这个机会的选择基本有了一个明确的放向。这个机会是这样的，有人可以把一个免费的场地给我用来开书坊，我是否要接受。最低标准：费用低；场地面积够用；房东变化不大，现在答应，以后会不会变卦。极端标准：我想把这个书坊建成一个活动中心；能否支持书坊转型，书坊只提供样书，购买在网上；能否有足够的客源，把这个做火。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>总结（\u003c/strong>\u003cstrong>1分钟\u003c/strong>\u003cstrong>）\u003c/strong>\u003c/p>\u003cp>今天学到的方法，既可以用在很大的事情上面，例如选专业，又可以用在很小的事情上，例如挑选衣服、买吃的时候打折了要不要买。今天我们学习到了面对机会，进行选择的理智方法，首先写下这个机会，之后罗列3个最低标准，再罗列3个最高标准，最后按照3-2的原则，也就是必须满足3个最低标准，同时满足2个最高标准，如果这样，这个机会我们就抓住它，如果不满足这个3-2的标准，那这个机会我们就放弃。\u003c/p>\u003cp>最后，谢谢大家的倾听！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1480170110000,"updated_at":1491029161000,"ria":true},{"id":1255,"topic":"关注真正重要的事情","learn_goal":"教会大家抓住容易忽略的那些关键信息","remark":"我们听到的信息中，最大的那个声音就是最有用的内容吗？有没有可能得到的是错误的信息？如果这时你急于作出反应，能抓到要领吗？如何通过逻辑思维，抓住容易忽略的那些关键信息？\r\n本周拆书，我们来聊一聊问题背后的那些事儿。","level":"TF3-3","duration":60,"status":0,"type":0,"chaishujia":{"username":"Emma","city":"北京市"},"club":{"name":"北京紫禁之巅分舵","city":"北京市"},"prologue":"【学习目标】（第一个RIA）在跟随我完成本次现场学习后，学习者能够明确目标，权衡取舍，选择做对目标最有利的事。（第二个RIA）在跟随我完成本次现场学习后，学习者能够在解决问题时，先探究问题的本质，再确定问题的解决目标，根据目标制定行动方案。\r\n【自我介绍】大家好，我是Emma。我的本职工作是在建筑行业做弱电工程师。与其他的拆书家比起来，我的嗓门比较大，所以后面的朋友，如果听不清的话，朝我挥挥手，我会努力让你们都听到的。听过我拆书的人，给我的反馈是，（男）学习的效率提高了，（女）同事说听特喜欢听我夸她，（男）带下属变得容易了，（女）我老公都说我变漂亮了~ 前边儿都是我分享过的内容，最后这个可能真跟我没什么关系，也许只是因为双11快到了，他就那么一说，为了让你少花点钱~\r\n 【学习者场景法介绍图书】最近我同事很苦恼，本来已经答应了女朋友去爬香山，结果领导告诉他周末要加班，他希望两件事都别耽误，问我有什么办法？\r\n在同一时间里，同时有几件事要做，大家遇到过类似的场景吗？你会怎么做？\r\n有人说：我可以两者兼顾，带着随身Wi-Fi去香山加班嘛。请问，女朋友和领导谁会满意？如果不考虑取舍，","ratings_count":0,"texts":[{"id":3560,"quote":null,"explains":"\u003cp>原文讲了关于取舍的两个故事。\u003c/p>\u003cp>第一个故事，雷曼兄弟前任CFO，因为不懂得取舍，模糊了工作和生活的界限，最后她的生活中只有工作。\u003c/p>\u003cp>第二个故事，培养儿子读哈佛的父母，因为目标明确，就是让孩子进哈佛，懂得取舍，不让孩子做对实现目标来说不重要的那些事，这是舍，孩子才有机会进读哈佛读书，这是取。\u003c/p>\u003cp>这两个故事告诉我们，有所取，必有所舍。\u003c/p>\u003cp>可能有人说，那个CFO也有取舍啊，她取了工作舍了生活嘛？\u003c/p>\u003cp>问题是：她追求的是只有工作的生活吗？到底是她主动的舍了生活？还是被动地被工作填满了生活？大家请看第一段第二行最后一个词：牺牲，由此可以推测出作者认为她是被动地。相比之下，案例中的父母，从是一开始就明确了目标，以此作为权衡的标准，主动地进行取舍。\u003c/p>\u003cp>那怎么取舍呢？书中给出的方法是“强迫自己权衡两者，战略性地选择那个对自己最有利的”，换成我自己的话说就是，\u003c/p>\u003cp>首先，要明确目标。因为目标是我们的战略，是我们权衡做什么不做什么的标准。如果你的目标不够明确，试着问自己这样两个问题：\u003cem>“什么是最重要的事？”“我要大干一场的是什么？”\u003c/em>；\u003c/p>\u003cp>其次，权衡做什么、不做什么。有了目标，就有了权衡的标准，主动地进行取舍；\u003c/p>\u003cp>最后，选择做对目标最有利的事。什么叫“战略性地选择”？战略就是从全局考虑，实现全局目标的规划，“战略性地选择”也就是对全局、对实现目标最有利的选择，因为这样的选择增加了实现目标的机会。\u003c/p>\u003cp>可能有人不赞成书中的观点，认为我就是可以两者兼顾啊，不用考虑取舍啊。\u003c/p>\u003cp>让我们来问个问题自测一下：如果你只能在一件事情上做到出类拔萃，那将会是一件什么事？\u003c/p>\u003cp>如果你有答案，说明你已经在进行取舍了。\u003c/p>\u003cp>如果没有答案，这个方法就不适用了。因为没有目标，就没有权衡的标准，也就不存在取舍了。\u003c/p>","interaction":"\u003cp>【A2】\u003c/p>\u003cp>请自己编一个小故事，设计一段人物角色的对话，其中部分对话使用运用“明确目标-&gt;权衡取舍-&gt;做出战略性选择”的方法，使人物对问题的回应产生情节变化（有起因、经过、结果）。\u003c/p>\u003cp>故事灵感可以来源于你经历过的两难的选择，你当时是怎样取舍的，结合今天的知识点，把它改写成一个故事。\u003c/p>\u003cp>可以参照示范的故事结构，使用第二页的空白表格，写下一段对话。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>微光的分享\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>事件背景\u003c/p>\u003cp>&amp;\u003c/p>\u003cp>人物设置\u003c/p>\u003c/td>\u003ctd>\u003cp>朋友有了调岗的机会。新的岗位有晋升的机会，但是人际关系比较复杂，工作量也很大。现在的岗位，发展空间有限，人际关系简单，但是工作比较清闲。在此之前，她一直坚持写文章。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>人物对话\u003c/p>\u003c/td>\u003ctd>\u003cp>朋友\u003c/p>\u003c/td>\u003ctd>\u003cp>我\u003c/p>\u003c/td>\u003ctd>\u003cp>情节发展\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>现在的上班都没什么事，感觉太荒废了，最近不是开放了一个新的岗位吗，我想申请过去，没准儿还有晋升的机会。\u003c/p>\u003c/td>\u003ctd>\u003cp>你的目标到底是什么呢？\u003c/p>\u003cp>只是因为厌倦了现在的工作环境，想换个新的环境？还是想在工作上创造一番成就，赶快晋升？\u003c/p>\u003c/td>\u003ctd>\u003cp>起因\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>可能两方面的因素都有吧，我知道那个新的岗位很适合我，我经常会写一些文章发在简书啊豆瓣啊这些社交平台上，读者也很多，比较符合我的兴趣。\u003c/p>\u003c/td>\u003ctd>\u003cp>你的性格适合那个岗位吗？那里人际关系比较复杂，你能处理好上下级关系吗？再说，对你来说最重要的事是什么，是写文章还是晋升？\u003c/p>\u003c/td>\u003ctd>\u003cp>经过\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>嗯，我的性格好像是不太适合那个环境。我得明确一下我的目标。目前来说，还是写文章对我来说更重要，我想建立自己的个人IP，需要充足的空闲时间来写文章。新岗位那么忙，不是我想要的。\u003c/p>\u003c/td>\u003ctd>\u003cp>是啊，不过没关系。毕竟你现阶段的目标是建立IP，你专注了对你来说最重要的事，有取必有舍嘛，只要你选择了对达成目标最重要的事就好。\u003c/p>\u003c/td>\u003ctd>\u003cp>结果\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>\u003cbr>【总结过渡】我们明确目标、权衡取舍、作出战略性选择的意义，在于当我们遇到两难的选择时，能够权衡该做什么，不做什么，知道什么才是我们应该重点关注的内容，为学习如何关注真正重要的事打好基础。\u003c/p>","flags":{"r":false,"i":true,"a":true,"a1":false,"a2":true,"a3":false}},{"id":3561,"quote":"\u003cp>在阅读拆页之前，先来做一个简单的测试，完成自测题，并统计总分。\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>请仔细阅读以下5个题目中的每句话，根据自己当前的实际情况按照1~5的程度打分，1表示完全不符合，5表示非常符合。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>看新闻的时候，我读完内容后，还会进一步思考这些内容意味着什么。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>我遇到问题的第一反应，是先寻找关键所在，再采取行动着手解决。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>面对各种要求，我不会犯晕，而是能够清晰辨别哪个重要，哪个不重要。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>解决问题时，我擅长聚焦于最重要的细节。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","explains":"\u003cp>了解自己是否关注真正重要的事情时的思维表现\u003c/p>\u003cp>得分低于8分，说明你对问题的认识流于表象，缺少深度分析，对问题的解决办法缺乏头绪；\u003c/p>\u003cp>得分在8~16分之间，可能你局限于对事实或者细节做出反应，没有关注问题的本质是什么，抓不住要领；\u003c/p>\u003cp>得分高于16分，说明你能够认清问题的本质，关注真正重要的事情。\u003c/p>","interaction":null,"flags":{"r":true,"i":true,"a":false,"a1":false,"a2":false,"a3":false}},{"id":3562,"quote":null,"explains":"\u003cp>原文一开始，设计学校的这个课程给他们的挑战是什么？\u003cstrong>（设计低成本的保温箱）\u003c/strong>所以他们面对的问题是 “如何将保温箱的成本降低到1%”。\u003c/p>\u003cp>第二段一开始，简的团队把这个项目仅仅看作是一个成本问题了吗？\u003cstrong>（没有）\u003c/strong>\u003c/p>\u003cp>他们上来就着手制造便宜的塑料保温箱了吗？\u003cstrong>（没有）\u003c/strong>\u003c/p>\u003cp>他们没有这么做，而是煞费苦心地干什么呢？\u003cstrong>（去实地探索，寻找问题的关键所在）\u003c/strong>\u003c/p>\u003cp>问题的关键所在意味着问题的本质。只有明确了问题的本质，才关注到了真正重要的事情，才能从根本上解决问题。\u003c/p>\u003cp>他们明确了问题的本质是什么呢？\u003cstrong>（农村缺电，无法使用现有的保温箱）\u003c/strong>\u003c/p>\u003cp>问题的本质是缺电。只有解决了保温箱不用电的问题，才能从根本上解决的问题。如果简的团队一开始就上手解决成本问题，就算做出了便宜的但是需要用电的保温箱，尼泊尔的农村家庭会用吗？\u003cstrong>（显然不会。）\u003c/strong>\u003c/p>\u003cp>现在团队真正的挑战就变得十分明确了，他们的解决目标是什么？\u003cstrong>（创造不用电的低成本保温箱）\u003c/strong>\u003c/p>\u003cp>有了这种关键性的认识，他们开始解决手头的问题，制定了达成目标的行动方案，最终设计出了真正实用的保温箱。\u003c/p>\u003cp>我们再来回顾一下，简的团队是怎么行动的？\u003c/p>\u003cp>首先，充分研究问题，设计一个便宜的保温箱，并不等于，用最便宜的材料；\u003c/p>\u003cp>然后，进一步认清问题的本质，这个箱子用在发展中国家，尤其是农村，缺电才是问题的关键所在；\u003c/p>\u003cp>所以，真正的解决目标应该是，设计一个便宜的不用电的保温箱；而不只是一开始想的那样，换一种便宜的材料那么简单；\u003c/p>\u003cp>最后，制定行动方案，聚焦于最重要的细节，找到一种便宜的不用电的保温材料，最终使问题得到圆满解决。\u003c/p>\u003cp>我把行动步骤写在了第三页的左侧，请大家看一下，这就是我们待会儿要讨论和练习的方法。\u003c/p>\u003cp>这个方法适合于解决实际的应用问题，而不适用于应试的问题。\u003c/p>\u003cp>比如说，考试问你线性代数的问题，不需要挖掘什么问题的本质，因为标准答案只有一个，填上就完了。\u003c/p>\u003cp>我们都经历过应试教育，所以有时候面对问题，第一反应就想填个答案，而现实生活的问题往往有着复杂的原因和情况，不像应试那样填个答案就能解决，需要我们挖掘一下问题的本质，找到真正需要解决的问题，根据解决目标，制定行动方案。\u003c/p>","interaction":"\u003cp>【A3】接下来，是我们的分组讨论时间。\u003c/p>\u003cp>请阅读我给出案例场景，\u003c/p>\u003cp>11.11快到了，曾经好好的一个“光棍节”，现在活生生被绑架成了一个“抢”节。你是否也曾跟风消费，被忽悠着买了一大堆有的没的，有划算的，也有后悔的。下周又到双十一了，看着满屏的优惠活动，你有点儿心动了……\u003c/p>\u003cp>请大家分组讨论一下 “今年的双十一买不买？”这个问题。以小组为单位，一个人扮演“双十一潜在消费者”，其余的人通过深入追问的方式，明确问题的本质是什么，待会儿我们请一个组来分享一下你们的讨论出的问题的本质是什么。\u003c/p>\u003cp>我在明确一下接下来每一位学习者都要讨论的问题是：今年的双十一买不买？\u003c/p>\u003cp>学习者案例记录\u003c/p>\u003cp>小S所在的葫芦娃组分享问题的本质。\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>\u003c/p>\u003cp>在你的这个经历中，如何体现拆页中的明确问题的本质的呢？\u003c/p>\u003cp>\u003cstrong>小S：\u003c/strong>\u003c/p>\u003cp>我们组的剁手党是我，大家刚才深入追问的问题主要是这些……\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>我们明确了讨论的问题是\u003c/p>\u003c/td>\u003ctd>\u003cp>今年的双十一买不买？\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>为了探究问题的本质，我们提了这些问题来深入追问……\u003c/p>\u003c/td>\u003ctd>\u003cp>你买到的东西是不是确实是你需要的？\u003c/p>\u003cp>之前买过的东西是否现在还再用？\u003c/p>\u003cp>消费本身满足的是哪方面的需求，心理的还是有使用需求？\u003c/p>\u003cp>今年比去年购物车里的东西更多了还是精简了？\u003c/p>\u003cp>最后大家提了一个很刻薄的也刺到了我的痛楚的问题就是：\u003c/p>\u003cp>如果今年就是不买的话，你会怎么样？\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>问题的本质是什么？\u003c/p>\u003c/td>\u003ctd>\u003cp>综合以上问题，我发现我买的东西不全是我有使用需求的，更多的可能满足了我的心理需求。虽然我今年的购物车已经有所精简了，但是，不买的话我可能会有点空虚感。所以，我们认为问题的本质是享乐主义和满足物欲。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>\u003cstrong>拆书家：\u003c/strong>\u003c/p>\u003cp>好，谢谢小S的分享。其他组认同这个本质吗？谁还有不同的意见要分享？\u003c/p>\u003cp>其他组大都表示认同，有一个小组有补充。\u003c/p>\u003cp>馒头所在的豪华套餐组认为男性和女性的消费习惯不同，女生常年都在买买买，而男生一年只集中采购一次，不如就选在折扣力度最大的这一次。所以他们对问题的本质又补充了一点，就是享受折扣带来的成就感。\u003c/p>\u003cp>对这一点，其他组也表示认同。\u003c/p>\u003cp>好，现在大家把问题的本质集中到了“享乐主义”、“ 满足物欲”、“ 享受折扣带来的成就感”这三类问题上，请在此基础上，进一步讨论出解决目标是什么，也就是说，今年双十一，你认为自己做到什么样就算实现目标了，你对自己很满意。再讨论如何行动就能达成这个目标，最终形成一个解决方案，各组有一个人把你们的解决方案写下来。\u003c/p>\u003cp>学习者案例记录\u003c/p>\u003cp>梓瑄所在的小组分享解决目标和方案。\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>\u003c/p>\u003cp>在你们的讨论中，如何体现拆页中的明确解决目标的呢？以及为了达成目标，你们从哪些方面去考虑了行动方案？\u003c/p>\u003cp>\u003cstrong>梓瑄：\u003c/strong>\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>解决目标是什么？\u003c/p>\u003c/td>\u003ctd>\u003cp>我们的目标是做到在一定的限额内按需消费。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>为了达成目标，我们制定的行动计划是……\u003c/p>\u003c/td>\u003ctd>\u003cp>我们的的行动计划是：\u003c/p>\u003cp>1.&nbsp;&nbsp; &nbsp; 列一个购物清单。（从克服物欲的方面考虑）\u003c/p>\u003cp>这上面的东西都是最近一个月会用到的\u003c/p>\u003cp>2.&nbsp;&nbsp; &nbsp; 设定一个消费限额。（从克服享乐主义的方面考虑）\u003c/p>\u003cp>比如只能买￥1000块。这个是为了克服满足物欲。（学习者上钦补充：最好再设定一个浮动限额，来帮助自己适应这个过渡期，矫正消费习惯。）\u003c/p>\u003cp>3.&nbsp;&nbsp; &nbsp; 找一个人来监督自己。（从克服折扣成就感的方面考虑）\u003c/p>\u003cp>比如，我在提交订单之前，给家人看一下购物车，他会帮我审核一下，把把关。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>\u003cbr>\u003cbr>【A2】催化应用\u003c/p>\u003cp>即使你在理智上认同了“关注真正重要的事”的理念，也记住了行动步骤，但由于这不是往常你的思维习惯，遇到问题时，你可能第一时间还是不会去探究问题的本质。所以，事后复盘的方法可以帮助你更有效地把这个方法应用起来。\u003c/p>\u003cp>接下来的一周内，请你刻意留心面对问题，需要解决时，把你对问题的认识和思考记下来，然后试着用深究问题本质-&gt;明确解决目标-&gt;制定行动方案的方法，再分析一次，比较两次的差异在哪里？\u003c/p>\u003cp>学习者案例记录\u003c/p>\u003cp>淑意分享的未来要做的应用\u003c/p>\u003cp>我写的文章浏览量比较少，如果不用精要思维的方法，我就觉得是不是我写的东西大家不爱看，不够迎合大家的阅读口味，是不是应该写点吸引眼球的内容。用了精要思维的方法后，我分析“我如何建立自己的IP”的问题的本质，是应该提升自己的的价值和影响力，我的解决目标是成为高效阅读者、三级拆书家、简书签约作者，制定的行动计划是每周读本书、半年之内完成拆书所有晋级、每天在简书上输出1篇文章。\u003c/p>\u003cp>【总结】经过这么热烈的讨论，相信我们能够做到在权衡取舍的时候，关注最重要的问题，在解决问题的时候，不要一上来就盲目地行动，而是能深入地挖掘问题的本质，明确真正要解决的目标，再开始制定行动方案。今天的拆书就到这里，谢谢大家。\u003c/p>","flags":{"r":false,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1478246289000,"updated_at":1481770390000},{"id":799,"topic":"Get 精要，远离杂乱无章的人生！","learn_goal":"Get 精要，远离杂乱无章的人生！","remark":"你是否经常为了取悦别人或者避免麻烦而点头答应？\r\n你是否经常恨自己答应去做什么事，事后却疑惑不解地自问“我为什么要揽下这件事”？\r\n为此，你是否曾感到心力交瘁？你是否曾觉得自己只擅长做琐碎小事？你是否曾感到自己忙忙碌碌却又效率低下？\r\n如果你对上述任何一个问题的回答是肯定的，说明你的工作和生活还不够“精要”。精要主义拒绝接受我们能做所有事情的想法，而是要求我们进行真正的权衡取舍并作出艰难决定。具体怎么做呢？预知行动建议，欢迎本周四来西二旗，阿花现场带你了解精要的核心思维，帮你改善杂乱无章的人生。","level":"TF2-3","duration":25,"status":0,"type":0,"chaishujia":{"username":"阿花","city":"北京市"},"club":{"name":"北京紫禁之巅分舵","city":"北京市"},"prologue":"自我介绍、分组、图书介绍","ratings_count":0,"texts":[{"id":2523,"quote":"\u003cp>一个不争的事实是：我们生活的世界中几乎一起都是无价值的，仅有极少的事物例外。正如约翰•麦克斯韦尔（John Maxwell）所写：“几乎一切事情的次要性再怎么高估都不够。”\u003c/p>\u003cp>抛开1:1的逻辑，我们就开始认识到了追求精要的价值。我们发现，很多我们追求的好机会远不如极少数真正的契机有价值。一旦认识到这一点，\u003cstrong>我们就开始扫描环境，追寻那些重要的少数，并且急切地淘汰那些不重要的多数。\u003c/strong>只有这样，我们才能拒绝好机会，拥抱真正的契机。\u003c/p>\u003cp>这就解释了为何精要主义者要花费时间来探索自己的所有选项。这种额外的时间投资是值得的，因为有些东西实在是至关重要，它们会10倍地回报为找到它们所付出的努力。换句话说，\u003cstrong>精要主义者们用更多的时间来辨别，以便花更少的时间来做，正所谓磨刀不误砍柴工\u003c/strong>。\u003c/p>","explains":"\u003cp>这个片段讲的是精要主义者只把时间和精力花在有意义的事情上。片段开头强调了一个事实“我们生活的世界中几乎一切都是无价值的，仅有极少数的事物例外”，然后基于这个事实，作者分析了精要人生的践行步骤，我们可以从中提炼出三步。\u003c/p>\u003cp>【细化行动步骤】\u003c/p>\u003cp>第一步，探索：在行动前，扫描环境，对所有选项进行系统地探索，辨别出“重要的少数”与“不重要的多数”。\u003c/p>\u003cp>第二步，排除：勇敢说“不”，淘汰“不重要的多数”。\u003c/p>\u003cp>第三步，执行：花更少时间轻松自如地去做“重要的少数”。\u003c/p>\u003cp>【举例分析】\u003c/p>\u003cp>为了便于大家更好地理解，我给大家分享一个案例：\u003c/p>\u003cp>今天下午我的一个同学约我晚上逛街吃饭，可我想晚上追剧《小别离》，另外我还在犹豫要不要来西二旗参加拆书活动。那我晚上到底应该做什么呢？运用精要主义，第一步，我要探索所有选项：逛街吃饭、追剧、参加拆书活动，然后辨别“重要的少数”、“不重要的多数”，其中逛街吃饭可以下次再约，追剧呢看回放也可以，这两件属于“不重要的多数”，而参加拆书活动错过了就没法弥补了，属于“重要的少数”。第二步是勇敢拒绝，其中逛街吃饭，你可以对同学用委婉拒绝的方式，而追剧你可以用“直接放弃”的方式，以淘汰不重要的多数。第三步是执行，我把时间和精力都安排给晚上的拆书活动了，这样我就可以轻松去完成这件事了。（当然，因个人价值观、喜好不同，如果你也遇到我这种情况，你可能会选择去跟同学逛街吃饭或其他，这没有对错之分，只是你我在“重要性”的价值评判不一样。）\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; OK. 通过这个案例，我想大家已经理解了精要主义。提醒大家：精要主义适用于任何拥挤不堪的工作和生活场景。如果你想拥有精要人生，那就请尽情的使用精要主义吧。\u003c/p>","interaction":"\u003cp>现在我们一起来拆为己用，演练的场景为：作为M公司销售部的经理，小刘为人勤奋、关心下属、听从上司、力求做好所有的事情，结果没有时间陪伴家人，没有时间多读书和娱乐，感觉心力交悴，每天承受着无以言表的折磨。让我们来看看刘经理的一天：\u003c/p>\u003cp>8:30 部门例会\u003c/p>\u003cp>9:30 对报上来的文件等进行批示；处理邮件；阅读文件、报告、建议书等。中间不断有下属请示工作，刘经理的思路和时间被分割和耽误，工作一直延续到11:00。\u003c/p>\u003cp>11:00市场主管过来商讨下周就要实施的A商场的促销方案，刘经理亲自接待。\u003c/p>\u003cp>12:00匆匆吃过饭，看了会报纸，猛然想起上周销售总监交待的《销售渠道规划报告》还没完成，明天就要交了，顾不上休息，刘经理立马冲进办公室。\u003c/p>\u003cp>13:00 财务部经理过来要与他讨论销售部下个月的费用问题，顺便聊了一下个人的私事和公司最近的传闻。\u003c/p>\u003cp>13:40 接到大客户的投诉电话，处理客户的投诉问题。\u003c/p>\u003cp>14:30 替销售总监去开会，却忘了上午抽时间跟销售总监探讨汇报内容，结果会上一问三不知被总经理批评，要求他会后提交《7月份销售数据分析》。\u003c/p>\u003cp>15:30 刚要写《7月份销售数据分析》，一个下属又进来请示工作，直到16:30才提交。\u003c/p>\u003cp>16:30 开始写《销售渠道规划报告》，发现有好几个问题需要与市场部经理确认，去找市场部经理，一直持续到17:10。\u003c/p>\u003cp>17:30 下班时间到，报告才写了1页PPT，没办法，刘经理只好加班，一直到22:30。\u003c/p>\u003cp>23:30 回到家，老婆和儿子都已经睡着了，桌子上摆着饭菜和一块蛋糕，这时他才想起来今天是儿子的生日party。\u003c/p>\u003cp>刘经理的一天被各种工作任务占满了，为了做完所有的事情，忙得顾不上喝水、休息、吃晚饭和陪儿子过生日。刚刚你学习了“精要主义的三个践行步骤”，请运用这个方法试着给刘经理提供一个解决方案，帮助他改善任务繁多又杂乱无章的工作。请4人一组，先认真研究演练场景，然后组内讨论，每组讨论时间为8分钟。8分钟后，由1组分享讨论结果。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1472383092000,"updated_at":1472383102000,"ria":true},{"id":725,"topic":"放弃也是一种勇气，前进就是一种胜利","learn_goal":"放弃不再痛苦，前进也很轻松","remark":"你是否遇到过这样的情况：明明知道喜欢上了一个应该要放弃的人，但是还是舍不得？明明股票在大跌却还是不敢清仓？这次带你认识生活中的这些困扰，放弃该放弃的，让理性回归本身。\r\n在生活中是不是经常坚持力低下?总觉得自己没有动力，是不是每次有事情来了就会觉得无从下手，感觉完成整个事情实在是太困难了？这次让我们轻松行动起来，做自己想要去做的。","level":"TF2-4","duration":55,"status":0,"type":0,"chaishujia":{"username":"存在","city":"北京市"},"club":{"name":"北京宇宙中心分舵","city":"北京市"},"prologue":"F特征：这本《精要主义》讲的是如何让我们的应对拥挤不堪的工作和生活，如果不能自己安排生活的优先次序，就只能任由别人替你安排。\r\nA优势：这本书不是简单的口号，让我们精简和抓住重要的事情，而是一步一步带我们去完成这样的方法，书中从探索/排除和执行三个步骤来带领我们进入精要主义的生活。道理简单易懂、方法行而不难。\r\nB利益：你有没有许多不想做的事情，结果都到你身上来了？如何优雅的说不；你有没有明明知道不对，就是不知道为什么没有放手？沉没成本的陷阱；明明自己有一个震惊众人的想法，结果却一直不能执行？奖励自己的小胜。你是不是会觉得自己现在的生活不是自己想要的，却又感觉无所适从？选择，我们需要的力量。这本书里会找到这些问题的解释。相信在这本书里也会带给你新的思考，你是不是需要精要的人生。\r\n一个小测试：\r\n看看你怎么回答：\r\n为了奖励员工一年的努力，临近年末的时候，单位发给员工每人一张音乐会门票，位置在前排中间，价值800元。你本身对听音乐会颇为喜爱，拿到票子十分高兴。可是天公不作美，在开音乐会的那天突然来了一场暴风雪，这场突如其来的风雪导致路面积雪情况严重，所有公共交通工具都暂停使用，","ratings_count":0,"texts":[{"id":2321,"quote":"\u003cp>\u003cstrong>1. \u003c/strong>\u003cstrong>R:\u003c/strong>\u003cstrong>阅读原文拆页一（1分钟） \u003c/strong>\u003c/p>\u003cp>沉没成本指的是，由于已经投入其中的成本无法收回，而对某项已知的亏本生意继续投入时间、金钱或精力的倾向。毫无疑问，这很容易导致一种恶性循环：投入越多，就越想破釜沉舟坚持到底，直到投资获得回报。在某事上投入的越多，要从中抽离越困难。\u003c/p>\u003cp>&nbsp;个人很容易为沉没成本俘虏。为什么我们能忍受一场难看的电影而不中途退场，是因为我们已经为电影票花了钱。房子装修似乎永不见完工，但我们却总是不断的往里投钱，大概也是出于同样的原因。也正是受制于沉没成本，哪怕公交车或地铁迟迟不来，我们也会一直等着，而不去叫一辆出租车；明知道一段关系有害无益，我们也会精心维护，哪怕自己的努力只会让情况更糟。诸如此类的例子俯拾皆是。比如亨利·格瑞伯汉姆，他最近把自己的毕生全部积蓄，共计2600美元，都花在了一场狂欢节游戏上，结果却只赢得了一个大号香蕉娃娃。他花的越多，就越铁了心要赢回来。亨利说：’我一定要把钱赢回来‘的这个念头让人欲罢不能，但结果却适得其反。随着对这个毫无意义的活动投入的越多，他越无法从中脱身。\u003c/p>\u003cp>你是否也曾在无意义的事情上不断投入时间和努力，而不是斩仓止损？你是否也曾在成功无望的投资上越砸越多，而不是收手脱身？你是否也曾在没有前途的道路上一条道走到黑，因为不想承认从一开始就选错了方向？尽管已经深陷想补偿损失更多的怪圈，非精要主义者却依然不愿意迷途知返，冲破藩篱，挣脱陷阱。而精要主义者却又勇气和自信承认自己的错误并脱身抽离，忽略已经沉没的成本。\u003c/p>","explains":"\u003cp>\u003cstrong>1. \u003c/strong>\u003cstrong>拆页一的I 环节（预计用时4分钟）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>相信大家已经明白了这个片段的意思，那么接下来大家来看看这个片段中有哪些关键的词语需要我们关注？\u003c/p>\u003cp>已经投入、成本、无法收回、继续投入的倾向、投入越多，抽离越困难。这里面很关键的词语在：已经投入是过去的，而我们经常把过去的已经收回不了的成本，放在当下做判断，而避免沉没成本的方法应该是站在当下，来看待问题。\u003c/p>\u003cp>总结2个步骤方法：1、首先判断哪些是沉没成本 2、然后梳理当下我们做决策因素是什么？3、客观的做出理性判断。\u003c/p>\u003cp>说个最简单的例子，来运用这三个方法\u003c/p>\u003cp>设想你是一位电脑销售商，你几年前买进的100台单价为8000元/台的奔腾III电脑现在已经过时了，某学校愿意以4000元/台的价格买下，你会卖吗？\u003c/p>\u003cp>首先你完全不应当考虑这8000元的原价，它是已经成为过去式的沉没成本，这和你现在的决策毫无关系。其次你应当考虑的是将来你是否能以高于4000元的价格卖掉你的电脑（摩尔定律的知识基本上越来越不值钱）。如果不能，那么这4000元/台的价格是你最佳的卖出价，为什么不卖呢？\u003c/p>\u003cp>就像上面的例子，如果不清楚知道沉没成本的话，我们以为自己是在很努力的挽回损失，可能实际上已经走在错误的道路上了，又或者离我们的目标偏离了。\u003c/p>\u003cp>有许多小伙伴可能会说：过去的投入肯定会对当下带来影响，那怎么不考虑呢？说的很正确，我们用当下来看到问题，是看当下的情况作为我们的判断，过去投入的影响是当下判断的一个因素，但是过去的投入不是。比如你8块的股票，现在6块了，我们判断的依据是6块的当前股票是不是应该卖掉，而不是考虑这个股票当年是8块买的。\u003c/p>\u003cp>也有小伙伴说沉没成本的误区是不是总是不好呢？那也不一定，比如有时候有些事情你坚持不了，沉没成本可能是让你坚持下来的动力。\u003c/p>\u003cp>相信大家看完这个片段过后，前面的小测试已经有了答案了。在生活中我们与许多沉没成本的问题。比如说我自己在生活中就有许多时候这样的纠结，比如我的衣柜里面有许多衣服其实都好久好久没穿过了，放在那每次搬家都会很麻烦，但是我又不舍得扔掉，还有书柜里面有许多书，都已经看过了，而且估计也很难再看了，但是我还是不愿意扔掉，总觉的什么时候就会用上。而这些事情在平时都没什么，只是在当我搬家的时候做决策他就变成了沉没成本，已经花出去的钱回不来了，而且也用不到了。\u003c/p>","interaction":"\u003cp>\u003cstrong>1. \u003c/strong>\u003cstrong>拆页一的A1（预计用时4分钟）\u003c/strong>\u003c/p>\u003cp>俗话说：学以致用，我都爆出了自己那么多糗事，那么接下来小伙伴是不是也得爆料一点呢？比如说下饭馆吃饭，吃饱了过后发现还是有自己喜欢吃的菜在那里，结果因为觉得不迟太浪费，然后有吃了，让自己撑到了？ \u003c/p>\u003cp>\u003cstrong>2. \u003c/strong>\u003cstrong>拆页一的A2（预计用时4分钟）\u003c/strong>\u003c/p>\u003cp>那么遇到这样的事情我们应该怎么做？首先哪些是沉默成本已经回不来了？那么接下来从当下做出理性判断。&nbsp;\u003c/p>\u003cp>\u003cstrong>学习者案例：\u003c/strong>\u003c/p>\u003cp>小新：\u003cbr>\u003c/p>\u003cp>之前去饭店吃饭，总是一不小心就点多了，然后就说不能浪费，就撑着把吃完了，结果经常吃的太多不舒服，原来点过的菜已经变成沉没成本，不应该是决定我们继续不继续吃下去的因素，是否继续吃，应该是根据是否饥饿来说的。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":2322,"quote":"\u003cp>\u003cstrong>1. \u003c/strong>\u003cstrong>R:\u003c/strong>\u003cstrong>阅读原文拆页二（预计用时2分钟）：\u003c/strong>\u003c/p>\u003cp>我们可以选择。我们既可以下功夫建设一种制度，让执行精要知识不费力气，也可以听命一种制度，哪怕实际上只会让执行要事变得困难重重。\u003c/p>\u003cp>1、关注最低可行性进步\u003c/p>\u003cp>在硅谷流行着“完成比完美更重要”的理念。这并不是让大家去制造垃圾。其中的思想，在我看来是不要在不重要的事情上虚掷光阴，而是要把事情做成。在企业界，这种想法被描述为：最低可行性产品（MVP Minimal Viable Product）。\u003c/p>\u003cp>同样，我们也可以采取“最低可行性进步”（MVP Minimal Viable Progress）的方法问自己：“对于我们要努力完成的任务，有用且最有价值的任务是什么？”\u003c/p>\u003cp>2、做最低可行性准备\u003c/p>\u003cp>应对一个重要目标或者一个最后期限，有两种截然对立的方法。一种是早动手，小步前进；另一种是晚动手一日千里。“晚而大”意味着要在最后一个完成全部，通宵加班，把他做完。“早而小”意味着以尽可能少的时间投入，尽可能早的开始。\u003c/p>\u003cp>你只要在一个任务或者项目到期前两周仅仅投入10分钟时间，就不用在最后一刻花大把时间焦头烂额的仓促赶工了。有了目标或者期限，就问问自己：我此刻最低可行性准备是什么？\u003c/p>\u003cp>3、直观嘉奖进步\u003c/p>\u003cp>你记不记得，你父母给准备了一个星星图案，每次你吃了菠菜，或按时睡觉，或打扫了房间，你就能得到一颗星星，然后很快你就不用什么激励物也能做这些事情了。\u003c/p>\u003cp>直观的看着自己朝着目标进步，会产生一种巨大的力量。不管是在家里，还是在单位里，不要不屑于把这样的方法运用到你自己重要的目标上。\u003c/p>\u003cp>相较于设定庞大的、高远和不现实的目标，从小处着手，奖励进步，才能成就更多。作为一种奖励，这种明确的强化成功的行为，能让我们在过程中收获更多的快乐和满足。\u003c/p>","explains":"\u003cp>\u003cstrong>1. \u003c/strong>\u003cstrong>拆页二的I（预计用时5分钟）\u003c/strong>\u003c/p>\u003cp>在这个片段中大家已经看清楚了，一共有3个方法：第一个是关注最低可行性进步，第二个是做最低可行性准备,第三个是直观嘉奖进步。接下来我将会带领大家一步一步去理解这三个方法步骤\u003c/p>\u003cp>MVP这个词语估计大家都听过，这个在软件开发里经常可以听到，但是今天是多MVP不太一样是最低可行性进步。大家肯定都有许多梦想那么我今天就以自己曾经做的个人感觉还算牛逼的事情来说一下我当时怎么做的。14年我去骑行的川藏线，天天介绍都说了，那么我是如何去实现这个梦想的呢？第一个最低可行性准备：既然决定了，我就要准备点什么吧，比如攻略啊、注意啊，加个群啊，反正没事就做一点小这方面的。一段时间了解过后发现：川藏线全程2000+公里翻越14座山，当时看到了这个我就觉得压力山大，感觉这好像太难了，然后我就想，能不能完成我不知道，不过我可以先锻炼一下，骑个百八十公里试试。于是就买了车，从住的地方骑行到十三陵，然后在骑回来。当时晚上还约了个妹子说我骑行回来一起看一个即兴喜剧的表演，直观的嘉奖进步（有了在约美女的动力，还说了我骑行回来）过后，发现在虽然第一次骑行80公里累的很，但是还是在下午3点钟就回来了，晚上顺利和妹纸约会看表演。在骑回来过后发现自己的体力还是有待提高，于是接下来3周，每周都开始跑步，跑完了发个朋友圈，让小伙伴点赞，感觉很爽。最后在6月底就出发了，7月1日开始骑行，每天骑行完了，发朋友圈让小伙伴点赞。\u003c/p>\u003cp>在这个过程中，遇到了许多问题，比如说坚持还是放弃，我就会告诉自己我都骑了这么多了，现在放弃亏大了（沉没成本的好处来了。）比如说下一次晚上睡觉前先把早上要用的东西方好（最小的准备），路上告诉自己骑行5公里就可以休息一次，然后刷下朋友圈看多少人点赞。等等，最终还是坚持下来了，这里还是要谢谢在我朋友圈点赞的小伙伴。\u003c/p>\u003cp>那么在刚刚的例子中，小伙伴能告诉我使用了哪些步骤吗？\u003c/p>\u003cp>对，比如自己先骑一次百八十公里，就是一个可行性的进步，比如骑完了约个美女去看演出，就是一个奖励。还有朋友圈点赞的奖励，还有在网上查资料，找队友的最小可行性准备。\u003c/p>\u003cp>用习惯了过后许多事情都可以这样做了，比如去年我骑行海南岛，也是这样完成的。\u003c/p>","interaction":"\u003cp>\u003cstrong>1. \u003c/strong>\u003cstrong>A3\u003c/strong>\u003cstrong>（10分钟）：5分钟讨论。\u003c/strong>\u003c/p>\u003cp>那么接下来，我们想象一下，有如下场景任选一个，大家看看怎么去用着三个方法去一步一步的执行我们的目标。\u003c/p>\u003cp>场景1：\u003c/p>\u003cp>小明一直想出去旅游，他对塞班岛非常向往，想那里的碧海蓝天，可以通透的看到整个海底。可是他觉得这个对自己太遥远了，又要花钱，还要花很多时间，还要准备一大堆东西，然后想想就觉得，这实在太困难了。结果到今天也没有去成。\u003c/p>\u003cp>场景2：\u003c/p>\u003cp>小花一直想去提升一下自己的演讲能力，可是他发现自己站在讲台上就很难说话，最近他发现有一个拆书帮的组织，非常锻炼人的培训和演讲能力，可是听说成为三级拆书家需要过五关斩六将，还听说有一个拆书家2-4拆了5次还没过，想想都觉得可怕，结果虽然已经来参加很多次活动了，但是还只是参加活动。\u003c/p>\u003cp>A3：5分钟分享\u003c/p>\u003cp>\u003cstrong>1. \u003c/strong>\u003cstrong>A2\u003c/strong>\u003cstrong>（14分钟）：7分钟讨论\u003c/strong>\u003c/p>\u003cp>刚刚大家讨论的很激烈，场景中也有许多东西，那么接下来是不是要做点实在的了？在第二段开始前大家写下来今年下半年的目标，那么如果运用这三个办法去执行该如何去做呢？接下来问问自己：我此刻最低可行性准备是什么，是查找一下行动的方法？还是约个有经验的小伙伴聊聊？\u003c/p>\u003cp>再要问问自己：什么样的可行性进步能让我目标可以更容易达到呢，一次体能训练？一个小技能的学习？\u003c/p>\u003cp>当然，更重要的是，不要忘了给自己的奖励是什么，一次约会？一个想了好久的礼物，还是小伙伴的赞？\u003c/p>\u003cp>A2：7分钟分享\u003c/p>\u003cp>\u003cstrong>学习者案例：\u003c/strong>\u003c/p>\u003cp>叶子：\u003c/p>\u003cp>准备计划去旅行，首先做一个最低可行性准备，去旅行的最小行为是准备、预定、游玩、回来，那么进行最小可行性准备需要做点准备，去贴吧上面查看攻略、了解旅行的一些注意事项，把攻略准备好，最小可行性计划就是收集可行性攻略，如果攻略做好了，那么奖励自己大吃一顿，然后接着继续做。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1470918494000,"updated_at":1470918494000,"ria":true}]};